    /**
     * Creates a new bank account
     */
    public void createBankAccount(BankAccount bAccount) {
        EdsUser user = userManager.getUser();
        EdsBankAccount bankAccount = null;
        EdsAccount account;
        if (bAccount.getObjectId() != null) {
            bankAccount = bankAccountManager.get(bAccount.getObjectId());
            account = bankAccount.getAccount();
        } else {
            account = new EdsAccount();
        }
        account.setAccountType(accountingManager.getAccountTypeByCode(EdsAccountType.BANK));
        account.setAccountCode(bAccount.getCode());
        account.setCodeString(bAccount.getCode());
        account.setKey(EdsAccount.BANK);
        account.setName(bAccount.getName());
        account.setEnablePayments(true);
        account.setBankAccountActive(bAccount.isActive());

        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        account.setCurrency((bAccount.getCurrency() != null && bAccount.getCurrency().getId() != null)
                ? currencyManager.get(bAccount.getCurrency().getId())
                : baseCurrency);
        account.setForeignAccount(!baseCurrency.getObjectID().equals(account.getCurrency().getObjectID()));

        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsBankAccount.class.getSimpleName());
        if (account.getObjectID() == null) {
            account.setCreator(user);
            account.setCreationTime(new Date());
            accountingManager.create(account);
            kpiLog.setActionType(KpiLog.ActionType.ADD);
            kpiLog.setEntityId(account.getObjectID());
            ServerUtils.kpiLog(log, kpiLog, "Add Bank Account");
        } else {
            account.setUpdater(user);
            account.setLastUpdateTime(new Date());
            accountingManager.update(account);
            kpiLog.setActionType(KpiLog.ActionType.UPDATE);
            kpiLog.setEntityId(account.getObjectID());
            ServerUtils.kpiLog(log, kpiLog, "Update Bank Account");
        }
        try {
            chartOfAccountSolrComponent.index(account);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        if (bankAccount == null) {
            bankAccount = new EdsBankAccount();
        }
        bankAccount.setExchangeRate(bAccount.getExchangeRate());
        bankAccount.setAccount(account);
        bankAccount.setAccountNumber(bAccount.getAccountNumber());
        bankAccount.setAccauntName(bAccount.getAccauntName());
        bankAccount.setBankBranch(bAccount.getBankBranch());
        bankAccount.setBankAddress(bAccount.getBankAddress());
        bankAccount.setSwiftCode(bAccount.getSwiftCode());
        bankAccount.setIbanCode(bAccount.getIbanCode());
        bankAccount.setSortCode(bAccount.getSortCode());
        bankAccount.setAbaCode(bAccount.getAbaCode());
        bankAccount.setAgentID(bAccount.getAgentID());
        bankAccount.setBic(bAccount.getBig());
        bankAccount.setActive(bAccount.isActive());

        bankAccount.setStreetAddress(bAccount.getStreetAddress());
        bankAccount.setCity(bAccount.getCity());
        if (bAccount.getCountryId() != null) {
            bankAccount.setCountry(countryManager.get(bAccount.getCountryId()));
        } else {
            bankAccount.setCountry(null);
        }
        if (bAccount.getStateId() != null) {
            bankAccount.setState(regionManager.get(bAccount.getStateId()));
        } else {
            bankAccount.setState(null);
        }
        bankAccount.setPhoneNumber(bAccount.getPhoneNumber());
        bankAccount.setPostCode(bAccount.getPostCode());

        bankAccount.setOpeningDate(bAccount.getOpeningDate() != null
                ? bAccount.getOpeningDate().getNonConvertedDate()
                : null);
        bankAccount.setOpeningAmount(bAccount.getOpeningAmount());
        bankAccount.setCustomFields(createBankAccountCustomFields(bankAccount.getCustomFields(), bAccount.getCustomFieldItems()));

        List<EdsUser> owners = new ArrayList<>();

        bankAccount.getOwners().clear();
        if (bAccount.getSelectedOwners() != null && !bAccount.getSelectedOwners().isEmpty()) {
            bAccount.getSelectedOwners().forEach(owner -> owners.add(userManager.get(owner.getId())));
            bankAccount.setOwners(owners);
        }

        if (bankAccount.getObjectID() == null) {
            bankAccountManager.create(bankAccount);
            baseEventPostProcessor.registerEvent(BankAccountEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_ADD, bankAccount, userManager.getUser());
        } else {
            bankAccountManager.update(bankAccount);
            baseEventPostProcessor.registerEvent(BankAccountEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_EDIT, bankAccount, userManager.getUser());
        }
        if (bAccount.getAttachments() != null && bAccount.getAttachments().length > 0) {
            attachmentUtilsManager.saveAttachments(F_BANK_ACCOUNT, bankAccount.getObjectID(), bankAccount.getObjectID(), bAccount.getAttachments());
        }
        createOrUpdateBankAccountOpeningBalanceTransaction(bankAccount);
    }

    @Transactional
    public EdsBankAccountCustomFields createBankAccountCustomFields(EdsBankAccountCustomFields edsBankAccountCustomFields, ArrayList<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            if (edsBankAccountCustomFields == null) {
                boolean isEmpty = true;
                for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                    if ((fieldItem.getFieldStringValue() != null && !"".equals(fieldItem.getFieldStringValue()))
                            || fieldItem.getFieldDateNonConvertedValue() != null
                            || (fieldItem.getAttachments() != null && fieldItem.getAttachments().length > 0)
                            || (fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty())) {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty) {
                    return null;
                }
                edsBankAccountCustomFields = new EdsBankAccountCustomFields();
                bankAccountCFManager.create(edsBankAccountCustomFields);
            }
            CustomFieldsUtils.setDomenObjectCustomFields(edsBankAccountCustomFields, customFieldItems);
            return edsBankAccountCustomFields;
        }
        return null;
    }

    private void createOrUpdateBankAccountOpeningBalanceTransaction(EdsBankAccount bankAccount) {
        EdsUser user = transactionManager.getUser();
        Integer calculationScale = financialSettingsManager.getFinancialSettings().getAccountingCalculationScale();
        EdsBankTransaction openingBalanceTransaction = transactionManager.getBankAccountOpeningBalanceTransaction(bankAccount.getObjectID());

        if (bankAccount.getOpeningAmount() != null && bankAccount.getOpeningDate() != null && bankAccount.getOpeningAmount().setScale(calculationScale, RoundingMode.HALF_UP).compareTo(ZERO) != 0) {
            if (openingBalanceTransaction != null) {
                transactionManager.deleteTransactionItems(openingBalanceTransaction.getObjectID());
                openingBalanceTransaction.setDeleted(false);
            } else {
                openingBalanceTransaction = new EdsBankTransaction(); //creating new transaction
                openingBalanceTransaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
            }
            openingBalanceTransaction.setName(bankAccount.getAccount().getName() + " Opening Balance");

            openingBalanceTransaction.setBankAccount(bankAccount);
            openingBalanceTransaction.setJournalDate(bankAccount.getOpeningDate());
            openingBalanceTransaction.setPostedBy(user);
            openingBalanceTransaction.setPostedDate(user.getUserDate());

            boolean isForeignAccount = bankAccount.getAccount().isForeignAccount();
            BigDecimal amountInBase, amountInForeign = bankAccount.getOpeningAmount().setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            if (isForeignAccount) {
                amountInBase = amountInForeign.divide(bankAccount.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            } else {
                amountInBase = amountInForeign;
            }

            Set<EdsTransactionItem> transactionItemList = new HashSet<>();

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            transactionItem.setTransaction(openingBalanceTransaction);
            transactionItem.setAccount(bankAccount.getAccount());
            if (amountInBase.compareTo(BigDecimal.ZERO) >= 0) {
                transactionItem.setDebit(amountInBase);
                if (isForeignAccount) {
                    transactionItem.setForeignDebit(amountInForeign);
                }
            } else {
                transactionItem.setCredit(amountInBase.abs());
                if (isForeignAccount) {
                    transactionItem.setForeignCredit(amountInForeign.abs());
                }
            }
            transactionItemList.add(transactionItem);

            transactionItem = new EdsTransactionItem();
            transactionItem.setTransaction(openingBalanceTransaction);
            transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.OPENING_BALANCE));
            if (amountInBase.compareTo(BigDecimal.ZERO) >= 0) {
                transactionItem.setCredit(amountInBase);
                if (isForeignAccount) {
                    transactionItem.setForeignCredit(amountInForeign);
                }
            } else {
                transactionItem.setDebit(amountInBase.abs());
                if (isForeignAccount) {
                    transactionItem.setForeignDebit(amountInForeign.abs());
                }
            }
            transactionItemList.add(transactionItem);

            openingBalanceTransaction.setTransactionItems(transactionItemList);

            transactionManager.createOrUpdate(openingBalanceTransaction);

        } else if (openingBalanceTransaction != null) {
            openingBalanceTransaction.setDeleted(true);
            transactionManager.update(openingBalanceTransaction);
        }
    }


    private void createCompanyAccounts(EdsCurrency currency) {
        if (accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_RECEIVABLE) != null) {
            return;
        }

        createAccount(currency, EdsAccountType.CURRENT_ASSET, EdsAccount.ACCOUNTS_RECEIVABLE, "Accounts Receivable", "Invoices the business has issued but has not yet collected payment on");
        createAccount(currency, EdsAccountType.CURRENT_ASSET, EdsAccount.VAT_INPUT, "Input VAT", "The balance in this account represents VAT from the TAX Authority.");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.ACCOUNTS_PAYABLE, "Accounts Payable", "Invoices the company has received from suppliers but have not made payment on");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.UNPAID_EXPENSE_CLAIMS, "Unpaid Expense Claims", "Expense claims typically made by employees/shareholder employees which the business has not made payment on");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.VAT_PAYABLE, "VAT Payable", "The balance in this account represents VAT owing to the TAX Authority.");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.VAT_OUTPUT, "Output VAT", "The balance in this account represents VAT owing to the TAX Authority.");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.HISTORICAL_ADJUSTMENT, "Historical Adjustment", "For accountant adjustments");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.PENDING_GOODS_RECEIVED_NOTES, "Pending Goods Received Notes", "For Goods Received Transactions");
        createAccount(currency, EdsAccountType.EQUITY, EdsAccount.OPENING_BALANCE, "Opening Balance", "For Inventory item");
        createAccount(currency, EdsAccountType.CURRENT_LIABILITY, EdsAccount.SALARIES_PAYABLE, "Salaries Payable", "For Salaries Payable");

        EdsFloatingAccount floatingAccount = new EdsFloatingAccount();
        floatingAccount.setAccountType(accountingManager.getAccountTypeByCode(OTHER_INCOME));
        floatingAccount.setAccountCode(String.valueOf(EdsAccount.EXCHANGE_VARIANCE));
        floatingAccount.setCodeString(String.valueOf(EdsAccount.EXCHANGE_VARIANCE));
        floatingAccount.setKey(EdsAccount.EXCHANGE_VARIANCE);
        floatingAccount.setDebitType(accountingManager.getAccountTypeByCode(OVERHEAD));
        floatingAccount.setCreditType(accountingManager.getAccountTypeByCode(OTHER_INCOME));
        floatingAccount.setName("Exchange rate gain/loss");
        floatingAccount.setDescription("For registering gain and loss cost by exchange rate difference");
        accountingManager.create(floatingAccount);
    }

    private void createAccount(EdsCurrency currency, String accountType, int accountCode, String name, String description) {
        EdsUser user = userManager.getUser();
        EdsAccount account = new EdsAccount();

        EdsAccount existAccount = accountingManager.getAccountByCode(String.valueOf(accountCode));
        if (existAccount != null && existAccount.getObjectID() != null) {
            return;
        }

        account.setCurrency(currency);
        account.setAccountType(accountingManager.getAccountTypeByCode(accountType));
        account.setAccountCode(String.valueOf(accountCode));
        account.setCodeString(String.valueOf(accountCode));
        account.setKey(accountCode);
        account.setName(name);
        account.setDescription(description);
        account.setCreationTime(new Date());
        account.setLastUpdatedDate(new Date());
        account.setCreator(user);
        account.setUpdater(user);
        accountingManager.create(account);

        try {
            chartOfAccountSolrComponent.index(account);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private void createKPIDefaultAccounts(EdsCurrency currency) {
        List<Integer> deleteGLAccountIds = accountingManager.getGLAccountsInattendedInInvoices();
//        accountingManager.deleteGLAccountsInattendedInInvoices();
        List<EdsAccountTemplate> accountsTemplate = accountTemplateManager.getAccountsFromTemplate();
        List<EdsAccount> list = Lists.newArrayList();
        for (EdsAccountTemplate at : accountsTemplate) {
            EdsAccount account = accountingManager.getAccountByCode(String.valueOf(at.getCode()));
            if (account == null) {
                account = new EdsAccount();
                accountingManager.create(account);
            }
            account.setAccountType(at.getAccountType());
            account.setKey(at.getKey());
            if (at.getCode() != null) {
                account.setAccountCode(String.valueOf(at.getCode()));
                account.setCodeString(at.getCode().toString());
            }
            account.setDescription(at.getDescription());
            account.setName(accountingLocalizer.localize(at.getCodeString(), at.getName()));
            account.setTax(at.getTax());
            account.setShowInExpense(at.getShowInExpense());
            account.setEnablePayments(at.getEnablePayments());
            account.setCurrency(currency);
            list.add(account);
        }

        if (!list.isEmpty()) {
            try {
                chartOfAccountSolrComponent.indexes(list);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        if (deleteGLAccountIds != null && !deleteGLAccountIds.isEmpty()) {
            try {
                solrManager.removeChartOfAccountByIds(deleteGLAccountIds.toArray(new Integer[0]));
            } catch (SolrServerException | IOException e) {
                e.printStackTrace();
            }
        }
    }

    public void createWorkforcetrackDefaultAndCompanyAccounts(EdsCurrency currency) {
        createCompanyAccounts(currency);
        createKPIDefaultAccounts(currency);
    }

    public void createDefaultAccountingParametersForMobile() {
        EdsCompany company = accountingManager.getUser().getCompany();

        if (!company.getAccountingSetup()) {

            /*-----Saving Financial Settings Start-----*/
            FinancialSettingsItem fsi = new FinancialSettingsItem();
            Calendar endOfYear = new GregorianCalendar();
            endOfYear.set(Calendar.MONTH, 12);
            endOfYear.set(Calendar.DAY_OF_MONTH, endOfYear.getActualMaximum(Calendar.MONTH));
            ServerUtils.setEndOfTheDay(endOfYear);
            fsi.setFinYearEnd(new DateNonConvertable(endOfYear.getTime()));

            EdsCountry country = company.getCountryZone().getCountry();
            if (financialSettingsManager.getFinancialSettings().getCurrency() != null) {
                fsi.setCurrencyId(financialSettingsManager.getFinancialSettings().getCurrency().getObjectID());
            } else if (country.getCurrency() != null) {
                fsi.setCurrencyId(country.getCurrency().getObjectID());
            } else {
                fsi.setCurrencyId(currencyManager.getCurrency(CurrencyManager.USD).getObjectID());
            }
            EdsFinancialSettings financialSettings = saveFinancialSettingsNew(fsi);
            financialSettings.setConversionDate(new Date());
            /*-----Saving Financial Settings End-----*/

            createAccountingExtraDefaultParameters();

            //Create Default Invoice Settings
            createDefaultInvoiceSettings(company);
            //Creating Default Accounts
            createWorkforcetrackDefaultAndCompanyAccounts(currencyManager.get(fsi.getCurrencyId()));

            company.setAccountingSetup(true);
        }
    }

