    public AccountItem createAccount(AddAccountItem accountItem) {
        EdsUser user = userManager.getUser();
        EdsAccount account = new EdsAccount();
        if (accountItem.getAccountTypeId() != null) {
            account.setAccountType(accountingManager.getAccountType(accountItem.getAccountTypeId()));
        } else if (accountItem.getAccountTypeCode() != null && !accountItem.getAccountTypeCode().isEmpty()) {
            account.setAccountType(accountingManager.getAccountTypeByCode(accountItem.getAccountTypeCode()));
        }

        if (accountItem.getTaxItem() != null && accountItem.getTaxItem().getId() != null) {
            account.setTax(vatManager.get(accountItem.getTaxItem().getId()));
        }
        account.setName(accountItem.getName());
        account.setDescription(accountItem.getDescription());
        account.setAccountCode(accountItem.getCode());
        if (accountItem.getParentAccount() != null && accountItem.getParentAccount().getId() != null) {
            EdsAccount parentAccount = accountingManager.get(accountItem.getParentAccount().getId());
            account.setParent(parentAccount);
        } else {
            account.setParent(null);
        }
        Integer accountKey = account.getKey() != null ? account.getKey() : account.getGroupKey();
        if (accountKey != null && (accountKey.equals(EdsAccount.ACCOUNTS_RECEIVABLE) || accountKey.equals(EdsAccount.ACCOUNTS_PAYABLE))) {
            accountingManager.clearDefaultAccount(accountKey);
            account.setIsDefaultAccount(accountItem.getIsDefaultAccount());
        } else {
            account.setIsDefaultAccount(false);
        }

        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        account.setCurrency(accountItem.getCurrencyID() != null
                ? currencyManager.get(accountItem.getCurrencyID())
                : baseCurrency);
        account.setForeignAccount(!baseCurrency.getObjectID().equals(account.getCurrency().getObjectID()));

        account.setCodeString(accountItem.getCode());
        account.setShowInExpense(accountItem.isShowInExpense());
        account.setActive(accountItem.isActive());
        account.setShow(accountItem.isShowInLookUp());

        account.setEnablePayments(accountItem.isEnablePayments());
        account.setQBAccountID(accountItem.getQBAccountID());
        account.setLastUpdatedDate(new Date());
        account.setGroupKey(account.findGroupKey());
        account.setCustomFields(createAccountCustomFields(account.getCustomFields(), accountItem.getCustomFieldItems()));

        account.setCreationTime(new Date());
        account.setLastUpdatedDate(new Date());
        account.setCreator(user);
        account.setUpdater(user);

        accountingManager.create(account);

        if (account.getAccountType() != null && EdsAccountType.BANK.equals(account.getAccountType().getCode())) {
            EdsBankAccount bankAcount = createBankAcount(account, accountItem);
            account.setBankAccountActive(bankAcount.isActive());
        } else {
            account.setBankAccountActive(true);
        }

        try {
            chartOfAccountSolrComponent.index(account);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        baseEventPostProcessor.registerEvent(ChartOfAccountEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_ADD, account, userManager.getUser());
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsAccount.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.ADD);
        kpiLog.setEntityId(account.getObjectID());
        ServerUtils.kpiLog(log, kpiLog, "Added new Account");

        return new AccountItem(account.getObjectID(), account.getCodeString(), account.getName(), account.getShowInExpense());
    }

    private EdsBankAccount createBankAcount(EdsAccount account, AddAccountItem accountItem) {
        EdsBankAccount bankAccount = bankAccountManager.getBankAccountByAccountID(account.getObjectID());
        if (bankAccount == null) {
            bankAccount = new EdsBankAccount();
        }
        bankAccount.setOpeningAmount(accountItem.getOpeningAmount());
        bankAccount.setOpeningDate(accountItem.getOpeningDate());
        bankAccount.setAccount(account);
        bankAccountManager.createOrUpdate(bankAccount);
        createOrUpdateBankAccountOpeningBalanceTransaction(bankAccount);

        return bankAccount;
    }

    @Override
    public void createAccounts(ArrayList<AddAccountItem> accountItems) {
        if (accountItems != null && !accountItems.isEmpty()) {
            for (AddAccountItem accountItem : accountItems) {
                createAccount(accountItem);
                accountingManager.flushAndClear();
            }
        }
    }

