    public ListResult<BankAccount> getBankAccounts(ListingFilterParameter filterParametrs) {
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsBankAccount.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.LIST);
        ServerUtils.kpiLog(log, kpiLog, "Get Bank Accounts list");

        ListPanelToolRpc panelTools = filterParametrs.getListPanelTool();
        if (panelTools.isCustomFieldsShown()) {
            filterParametrs.setCustomFieldsShown(panelTools.isCustomFieldsShown());
            filterParametrs.setCustomFieldsShown(true);
            panelTools.setListViewCustomFields(commonService.getCompanyCustomFieldsForListView(ViewName.BankAccounts));
            filterParametrs.setColumnsOfListing(panelTools.getColumnCodeName());
        }

        List<EdsBankAccount> bankAccounts = accountingManager.getBankAccountList(filterParametrs);
        Integer totalCount = accountingManager.getBankAccountListCount(filterParametrs);

        baseEventPostProcessor.registerEvent(AccountsEventListenerImpl.TYPE, AccountsEventListenerImpl.EVENT_ACCOUNT_CALCULATE_ACCOUNT_BALANCE, null, userManager.getUser());

        CurrencyItem baseCurrency = invoiceCircularResolver.getBaseCurrency();

        ArrayList<BankAccount> bankAccountList = new ArrayList<>();
        for (EdsBankAccount ba : bankAccounts) {

            BankAccount bankAccount = new BankAccount();
            bankAccount.setObjectId(ba.getObjectID());

            EdsAccount account = ba.getAccount();
            String code = account.getAccountCode();
            String name = account.getName();
            String accountNumber = ba.getAccountNumber();
            bankAccount.setCode(code);
            bankAccount.setName(name != null ? name : "");
            bankAccount.setAccountNumber(accountNumber != null ? accountNumber : "");
            bankAccount.setCurrency(account.getCurrency() != null
                    ? account.getCurrency().createCurrencyItem()
                    : baseCurrency);
            bankAccount.setActive(ba.isActive());

//            bankAccount.setReconcilationReportEnabled(bankStatementManager.getBankStatements(ba).size() > 0);
            bankAccount.setReconcilationReportEnabled(true);

            if (account.isForeignAccount()) {
//                if (account.isBalanceCalculated()) {
//                    bankAccount.setBalance(account.getForeignBalance() != null
//                                           ? account.getForeignBalance()
//                                           : BigDecimal.ZERO);
//                } else {
                bankAccount.setBalance(accountingManager.getAccountForeignBalance(account.getObjectID()));
//                }
            } else {
//                if (account.isBalanceCalculated()) {
//                    bankAccount.setBalance(account.getBalance() != null ? account.getBalance() : BigDecimal.ZERO);
//                } else {
                bankAccount.setBalance(accountingManager.getAccountBalance(account.getObjectID()));
//                }
            }

            bankAccount.setAccountId(account.getObjectID());
            if (ba.getCustomFields() != null && filterParametrs.isCustomFieldsShown()) {
                bankAccount.setCustomFieldsMap(CustomFieldsUtils.getRPCCustomFields(ba.getCustomFields(), filterParametrs.getColumnsOfListing()));
            }
            bankAccountList.add(bankAccount);
        }
        if (filterParametrs.getSortField() != null && BankAccount.AMOUNT_COLUMN.equals(filterParametrs.getSortField())) {
            if (filterParametrs.getSortDir() == 1) {
                bankAccountList.sort((o1, o2) -> {
                    BigDecimal balance1 = o1.getBalance() != null ? o1.getBalance() : BigDecimal.ZERO;
                    BigDecimal balance2 = o2.getBalance() != null ? o2.getBalance() : BigDecimal.ZERO;
                    return balance2.compareTo(balance1);
                });
            } else {
                bankAccountList.sort(Comparator.comparing(BankAccount::getBalance));
            }
        }
        return new ListResult<>(bankAccountList, totalCount);
    }

    @Override
    public BankAccountItem[] getBankAccountsForLookUp(ListingFilterParameter filterParametrs) {
        List<EdsBankAccount> bankAccounts = accountingManager.getBankAccountList(filterParametrs);
        BankAccountItem[] bAccountArray = new BankAccountItem[bankAccounts.size()];
        if (filterParametrs != null && filterParametrs.getLookUpBy() != null && Constants.BANK_ACCOUNT_NAME.equals(filterParametrs.getLookUpBy())) {
            int i = 0;
            for (EdsBankAccount account : bankAccounts) {
                bAccountArray[i++] = account.getBankAccountNameForLookup();
            }
            return bAccountArray;
        }
        if (filterParametrs != null && filterParametrs.getLookUpBy() != null && Constants.B_ACCOUNT_NUMBER.equals(filterParametrs.getLookUpBy())) {
            int i = 0;
            for (EdsBankAccount account : bankAccounts) {
                bAccountArray[i++] = account.getBankAccountNumberForLookup();
            }
            return bAccountArray;
        }
        if (filterParametrs != null && filterParametrs.getLookUpBy() != null && Constants.B_ACCOUNT_CODE.equals(filterParametrs.getLookUpBy())) {
            int i = 0;
            for (EdsBankAccount account : bankAccounts) {
                bAccountArray[i++] = account.getBankAccountCodeForLookup();
            }
            return bAccountArray;
        }
        CurrencyItem baseCurrency = invoiceCircularResolver.getBaseCurrency();
        if (filterParametrs != null && BankAccountTypeEnum.BANK.getCode().equals(filterParametrs.getAccountType())) {
            int i = 0;
            for (EdsBankAccount ba : bankAccounts) {
                bAccountArray[i] = ba.createBankItemForLookUp();
                if (bAccountArray[i].getCurrency() == null) {
                    bAccountArray[i].setCurrency(baseCurrency);
                }
                i++;
            }
            return bAccountArray;
        }
        int i = 0;
        for (EdsBankAccount ba : bankAccounts) {
            bAccountArray[i] = ba.createBankAccountItemForLookUp();
            if (bAccountArray[i].getCurrency() == null) {
                bAccountArray[i].setCurrency(baseCurrency);
            }
            i++;
        }
        return bAccountArray;
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public BankAccount getBankAccountForEdit(Integer objectID) {
        BankAccount accForTransfer = new BankAccount();
        accForTransfer.setCountryAndRegionItems(commonService.getCountriesAndRegions());

        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        SelectItem[] ownersList = crmServiceLocal.getOwnersListByPermission(PermissionConstants.ACCOUNTING_BANKACCOUNT_ASSIGNEE_LIST_VALUE);

        if (objectID != null) {
            EdsBankAccount bankAcc = bankAccountManager.get(objectID);
            accForTransfer.setObjectId(bankAcc.getObjectID());
            accForTransfer.setAccountId(bankAcc.getAccount().getObjectID());
            accForTransfer.setCode(bankAcc.getAccount().getCodeString());
            accForTransfer.setName(bankAcc.getAccount().getName());
            accForTransfer.setAccountNumber(bankAcc.getAccountNumber());
            accForTransfer.setAccauntName(bankAcc.getAccauntName());
            accForTransfer.setBankBranch(bankAcc.getBankBranch());
            accForTransfer.setBankAddress(bankAcc.getBankAddress());
            accForTransfer.setSwiftCode(bankAcc.getSwiftCode());
            accForTransfer.setIbanCode(bankAcc.getIbanCode());
            accForTransfer.setSortCode(bankAcc.getSortCode());
            accForTransfer.setAbaCode(bankAcc.getAbaCode());
            accForTransfer.setAgentID(bankAcc.getAgentID());
            accForTransfer.setBig(bankAcc.getBic());
            accForTransfer.setActive(bankAcc.isActive());
            accForTransfer.setStreetAddress(bankAcc.getStreetAddress());
            accForTransfer.setCity(bankAcc.getCity());
            if (bankAcc.getCountry() != null) {
                accForTransfer.setCountryId(bankAcc.getCountry().getObjectID());
                accForTransfer.setCountryName(countryLocalizer.localize(bankAcc.getCountry().getCode(), bankAcc.getCountry().getName()));
            }
            if (bankAcc.getState() != null) {
                accForTransfer.setStateId(bankAcc.getState().getObjectID());
                accForTransfer.setStateName(regionLocalizer.localize(bankAcc.getState().getCode(), bankAcc.getState().getName()));
            }
            accForTransfer.setPostCode(bankAcc.getPostCode());
            accForTransfer.setPhoneNumber(bankAcc.getPhoneNumber());
            if (bankAcc.getAccount().getCurrency() != null) {
                accForTransfer.setCurrency(bankAcc.getAccount().getCurrency().createCurrencyItem());
            }
            accForTransfer.setExchangeRate(bankAcc.getExchangeRate());

            if (bankAcc.getOpeningDate() != null) {
                accForTransfer.setOpeningDate(new DateNonConvertable(bankAcc.getOpeningDate()));
            }
            accForTransfer.setOpeningAmount(bankAcc.getOpeningAmount());
            accForTransfer.setUsedInSystem(bankAcc.isUsedInSystem() || bankAcc.getAccount().isUsedInSystem(true));

            ArrayList<CompanyCustomFieldItem> customFieldsItems = commonService.getCompanyCustomFields(ViewName.BankAccounts);
            accForTransfer.setCustomFieldItems(CustomFieldsUtils.setRPCCustomFieldItems(bankAcc.getCustomFields(), customFieldsItems));

            if (bankAcc.getOwners() != null && !bankAcc.getOwners().isEmpty()) {
                for (SelectItem owner : ownersList) {
                    owner.setSelected(bankAcc.getOwnersMap().containsKey(owner.getId()));
                }

                StringBuilder ownerNames = new StringBuilder();
                for (EdsUser owner : bankAcc.getOwners()) {
                    ownerNames.append(owner.getName()).append(",");
                }
                accForTransfer.setOwnerNames(ownerNames.substring(0, ownerNames.toString().length() - 1));
            }

        } else {
            accForTransfer.setCurrency(baseCurrency.createCurrencyItem());
        }

        accForTransfer.setOwnerItems(ownersList);

        return accForTransfer;
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public SelectItem[] getBankAccountItems() {
        List<EdsBankAccount> bankAccounts = accountingManager.getBankAccounts();
        SelectItem[] items = new SelectItem[bankAccounts != null ? bankAccounts.size() : 0];
        int i = 0;
        for (EdsBankAccount bAcc : bankAccounts) {
            if (bAcc.isActive()) {
                String codeString = bAcc.getAccount().getAccountCode();
                SelectItem item = new SelectItem(bAcc.getObjectID(), (codeString != null
                        ? codeString + " -> "
                        : "") + bAcc.getAccount().getName(), bAcc.getAgentID());
                item.setParam(bAcc.getAccount().getCurrency().getName());
                items[i] = item;
                i++;
            }
        }
        return items;
    }


