    public TaxItem saveTaxRate(TaxData data) {
        EdsVat edsTax;
        Integer taxRateScale = financialSettingsManager.getFinancialSettings().getTaxRateScale();
        BigDecimal taxPercent = AccountingConstants.ZERO, effectiveRateAsBigDecimal;
        BigDecimal totalRateWithoutCompound = BigDecimal.ZERO, compoundRate = BigDecimal.ZERO, effectiveTaxRate;

        String vatName;
        if (data.getObjectId() != null) {
            edsTax = vatManager.get(data.getObjectId());
        } else {
            edsTax = new EdsVat();
        }
        if (data.isSelectedByDefault()) {
            boolean existsDefaultTax = vatManager.existsDefaultTax();
            if (existsDefaultTax) {
                vatManager.removeDefaultTax();
            }
            edsTax.setSelectedByTaxDefault(true);
        } else {
            edsTax.setSelectedByTaxDefault(false);
        }
        edsTax.setName(data.getTaxName());
        edsTax.setVatAmount(data.getTaxRate() != null
                ? data.getTaxRate().setScale(taxRateScale, RoundingMode.HALF_UP)
                : null);
        edsTax.setTaxType(data.getTaxTypeId());
        edsTax.setUpdatedDate(new Date());
        edsTax.setGroupTax(data.isGroupTax());
        edsTax.setKey(data.getKey());
        edsTax.setPermissionType(data.getPermissionType());
        edsTax.setFaiId(data.getFaiId());
        edsTax.setFaiPurchaseId(data.getFaiPurchaseId());
        edsTax.setStatus(data.getStatus());
        edsTax.setFaiCategorieIds(data.getFaiCategoryIds());
        edsTax.setFaiPurchaseCategoryIds(data.getFaiPurchaseCategoryIds());
        vatManager.createOrUpdate(edsTax);

        taxComponentManager.deleteTaxComponents(edsTax.getObjectID());
        taxGroupItemManager.deleteGroupItems(edsTax.getObjectID());

        if (edsTax.getGroupTax()) {
            if (data.getGroupItems() != null && !data.getGroupItems().isEmpty()) {
                for (TaxItem taxItem : data.getGroupItems()) {
                    EdsVat edsTaxItem = vatManager.get(taxItem.getId());
                    EdsTaxGroupItem edsTaxGroupItem = new EdsTaxGroupItem();
                    edsTaxGroupItem.setItem(edsTaxItem);
                    edsTaxGroupItem.setTax(edsTax);
                    taxGroupItemManager.create(edsTaxGroupItem);
                    taxPercent = taxPercent.add(edsTaxItem.getEffectiveRateAsBigDecimal());
                }
            }
            vatName = data.getTaxName() + "(" + taxPercent.setScale(taxRateScale, RoundingMode.HALF_UP) + "%)";
            return new TaxItem(edsTax.getObjectID(), vatName, taxPercent, taxPercent, null);
        } else {
            if (data.getComponents() != null) {
                data.getComponents();
                for (TaxComponentData tcd : data.getComponents()) {
                    EdsTaxComponent component = new EdsTaxComponent();
                    component.setName(tcd.getName());
                    component.setCompound(tcd.isCompound());
                    component.setRate(tcd.getRate());
                    if (tcd.getAccount() != null && tcd.getAccount().getId() != null) {
                        component.setAccount(accountingManager.get(tcd.getAccount().getId()));
                    } else {
                        component.setAccount(null);
                    }
                    taxPercent = taxPercent.add(tcd.getRate());
                    component.setTax(edsTax);
                    if (tcd.isCompound()) {
                        compoundRate = tcd.getRate();
                    } else {
                        totalRateWithoutCompound = totalRateWithoutCompound.add(tcd.getRate());
                    }
                    taxComponentManager.create(component);
                }
            }
            vatName = data.getTaxName() + "(" + taxPercent.setScale(taxRateScale, RoundingMode.HALF_UP) + "%)";
            effectiveTaxRate = compoundRate.compareTo(BigDecimal.ZERO) > 0
                    ? ((totalRateWithoutCompound.divide(new BigDecimal(100), RoundingMode.HALF_UP).add(BigDecimal.ONE)).multiply(compoundRate).add(totalRateWithoutCompound))
                    : totalRateWithoutCompound;
            effectiveRateAsBigDecimal = effectiveTaxRate.setScale(taxRateScale, RoundingMode.HALF_UP);
            return new TaxItem(edsTax.getObjectID(), vatName, taxPercent, effectiveRateAsBigDecimal, data.getTaxTypeId());
        }
    }

    public Integer saveWarehouse(WarehouseItem warehouse) {
        EdsWarehouse edsWarehouse;
        boolean isNew = false;
        if (warehouse.getObjectID() != null) {
            edsWarehouse = warehouseManager.get(warehouse.getObjectID());
        } else {
            edsWarehouse = new EdsWarehouse();
            isNew = true;
        }

        edsWarehouse.setName(warehouse.getName());
        edsWarehouse.setNotes(warehouse.getNotes());
        edsWarehouse.setPrimaryContactID(warehouse.getPrimaryContactID());
        edsWarehouse.setCustomFields(createWarehouseCustomFields(edsWarehouse.getCustomFields(), warehouse.getCustomFieldItems()));

        List<EdsUser> owners = new ArrayList<>();
        if (warehouse.getSelectedOwners() != null && !warehouse.getSelectedOwners().isEmpty()) {
            warehouse.getSelectedOwners().forEach(owner -> owners.add(userManager.get(owner.getId())));
            edsWarehouse.setOwners(owners);
        }/* else {
            owners.add(userManager.getUser());
            edsWarehouse.setOwners(owners);
        }*/

        warehouseManager.createOrUpdate(edsWarehouse);
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsWarehouse.class.getSimpleName());
        kpiLog.setEntityId(edsWarehouse.getObjectID());
        if (isNew) {
            kpiLog.setActionType(KpiLog.ActionType.ADD);
            ServerUtils.kpiLog(log, kpiLog, "Add new warehouse");
        } else {
            kpiLog.setActionType(KpiLog.ActionType.UPDATE);
            ServerUtils.kpiLog(log, kpiLog, "Update warehouse");
        }
        return edsWarehouse.getObjectID();
    }

    private EdsWarehouseCustomFields createWarehouseCustomFields(EdsWarehouseCustomFields edsWarehouseCustomFields, List<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            if (edsWarehouseCustomFields == null) {
                boolean isEmpty = true;
                for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                    if ((fieldItem.getFieldStringValue() != null && !fieldItem.getFieldStringValue().isEmpty())
                            || fieldItem.getFieldDateNonConvertedValue() != null || (fieldItem.getAttachments() != null && fieldItem.getAttachments().length > 0)
                            || (fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty())) {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty) {
                    return null;
                }
                edsWarehouseCustomFields = new EdsWarehouseCustomFields();
                warehouseCFManager.create(edsWarehouseCustomFields);
            }
            CustomFieldsUtils.setDomenObjectCustomFields(edsWarehouseCustomFields, customFieldItems);
            return edsWarehouseCustomFields;
        }
        return null;
    }

