    public Integer saveProductCategory(ProductCategoryItem productCategoryItem) {
        if (productCategoryItem != null) {
            EdsProductCategory item = new EdsProductCategory();

            if (productCategoryItem.getId() != null) {
                item = productCategoryManager.get(productCategoryItem.getId());
            }

            EdsProductCategory existingCategory = productCategoryManager.getCategoryByName(productCategoryItem.getName());
            if (existingCategory != null && !existingCategory.equals(item)) {
                return 0;
            }

            item.setCode(productCategoryItem.getCode());
            item.setActive(productCategoryItem.isActive());
            item.setPrefix(productCategoryItem.getPrefix());
            item.setIntNumber(productCategoryItem.getIntNumber());
            item.setName(productCategoryItem.getName());
            item.setDescription(productCategoryItem.getDescription());
            item.setPrice(productCategoryItem.getPrice());
            item.setOrder(productCategoryItem.getOrder());
            item.setLastUpdateDate(new Date());
            item.setNameLocalize(WfmJsonUtils.objectConvertToJsonString(productCategoryItem.getNameLocalize()));
            item.setDescriptionLocalize(WfmJsonUtils.objectConvertToJsonString(productCategoryItem.getDescriptionLocalize()));
            if (productCategoryItem.getParentCategoryID() != null && productCategoryItem.getParentCategoryID() > 0) {
                item.setParent(productCategoryManager.get(productCategoryItem.getParentCategoryID()));
            } else {
                item.setParent(null);
            }

            item.setImageID(productCategoryItem.getImageID());

            if (productCategoryItem.getCustomFields() != null && !productCategoryItem.getCustomFields().isEmpty()) {
                StringBuilder changesBuilder = new StringBuilder();
                for (CompanyCustomFieldItem cit : productCategoryItem.getCustomFields()) {
                    changesBuilder.append(item.getCustomFields() != null && CustomFieldsUtils.getObjectValue(item.getCustomFields(), cit.getColumnCode()) != null ? getChanges(CustomFieldsUtils.getObjectValue(item.getCustomFields(), cit.getColumnCode()), cit) : (cit.getColumnCode() + ","));
                }
                String changes = changesBuilder.toString();
                if (!changes.isEmpty()) {
                    item.addCustomFieldChanges(changes);
                }
            }
            item.setCustomFields(saveCustomFields(item.getCustomFields(), productCategoryItem.getCustomFields()));
            EdsBusinessEvent productCategoryWorkflow = null;
            KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
            kpiLog.setEntityName(EdsProductCategory.class.getSimpleName());
            if (item.getObjectID() != null) {
                productCategoryManager.update(item);
                kpiLog.setActionType(KpiLog.ActionType.UPDATE);
                kpiLog.setEntityId(item.getObjectID());
                productCategoryWorkflow = baseEventPostProcessor.registerEvent(WorkflowActionDetectedEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_EDIT, item, userManager.getUser());
                productCategoryWorkflow.setEntityType(TYPE_PRODUCT_CATEGORY);
                baseEventPostProcessor.registerEvent(ProductCategoryEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_EDIT, item, userManager.getUser());
                ServerUtils.kpiLog(log, kpiLog, "Product category update");
            } else {
                productCategoryManager.create(item);
                kpiLog.setActionType(KpiLog.ActionType.ADD);
                kpiLog.setEntityId(item.getObjectID());
                productCategoryWorkflow = baseEventPostProcessor.registerEvent(WorkflowActionDetectedEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_ADD, item, userManager.getUser());
                productCategoryWorkflow.setEntityType(TYPE_PRODUCT_CATEGORY);
                baseEventPostProcessor.registerEvent(ProductCategoryEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_ADD, item, userManager.getUser());
                ServerUtils.kpiLog(log, kpiLog, "Add product category");
            }
//            productCategoryWorkflow.setEntityType(TYPE_PRODUCT_CATEGORY);
            if (productCategoryItem.isCopyCustomFieldsFromParent()) {
                copyCustomFieldsFromParent(item);
            }

            return item.getObjectID();
        }

        return 0;
    }

    private String getChanges(Object ob, CompanyCustomFieldItem item) {
        if (ob != null) {
            if (DATA_TYPE_TEXT.equals(item.getDataType())) {
                String text = (String) ob;
                return !text.equals(item.getFieldStringValue()) ? (item.getColumnCode() + ",") : "";
            } else if (DATA_TYPE_NUMBER.equals(item.getDataType())) {
                String s = String.valueOf(((Double) ob).intValue());
                return !s.equals(item.getFieldStringValue()) ? (item.getColumnCode() + ",") : "";
            } else if (DATA_TYPE_DATE.equals(item.getDataType())) {
                Date date = (Date) ob;
                return !date.equals(item.getFieldDateNonConvertedValue() != null ? item.getFieldDateNonConvertedValue().getNonConvertedDate() : null) ? (item.getColumnCode() + ",") : "";
            }
        }
        return "";
    }


    public Integer[] saveProductCategories(ProductCategoryList productCategoryList) {

        ProductCategoryItem[] productCategories = productCategoryList.getItems();

        if (productCategories != null) {
            Integer[] result = new Integer[productCategories.length];
            for (int i = 0; i < productCategories.length; i++) {
                EdsProductCategory item = new EdsProductCategory();

                item.setName(productCategories[i].getName());
                item.setDescription(productCategories[i].getDescription());
                item.setLastUpdateDate(new Date());
                productCategoryManager.create(item);

                result[i] = item.getObjectID();
            }
            return result;
        }
        return new Integer[0];
    }

