    public boolean deleteWarehouse(Integer warehouseId) {
        List<EdsProductWarehouseLocation> productLocations = itemManager.getProductLocationsByWarehouseID(warehouseId);
        if (productLocations != null && !productLocations.isEmpty()) {
            return false;
        }
        EdsWarehouse warehouse = warehouseManager.get(warehouseId);
        warehouse.getOwners().clear();
        warehouseManager.delete(warehouse);
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsWarehouse.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.DELETE);
        kpiLog.setEntityId(warehouseId);
        ServerUtils.kpiLog(log, kpiLog, "Delete warehouse");
        return true;
    }

    public HashMap<String, Integer> deleteUnitMeasurement(Integer unitMeasurementId) {
        EdsUnitMeasurement unitMeasurement = unitMeasurementManager.get(unitMeasurementId);
        HashMap<String, Integer> isUsed = unitMeasurementManager.isUnitMeasurementUsed(unitMeasurementId);
        if (isUsed == null || (!isUsed.containsKey(PRODUCT) && !isUsed.containsKey(INV_ITEM) && !isUsed.containsKey(QUOTE_ITEM) && !isUsed.containsKey(OPPORTUNITY_ITEM))) {
            isUsed = new HashMap<>();
            if (unitMeasurement != null) {
                unitMeasurement.setDeleted(true);
                unitMeasurementManager.update(unitMeasurement);
            }
        }
        return isUsed;
    }

    public boolean deleteProductCategory(Integer categoryId) {
        EdsProductCategory category = productCategoryManager.get(categoryId);

        List<EdsItem> products = itemManager.getProductsByCategoryID(categoryId, false);
        //destroy link with products
        for (EdsItem product : products) {
            product.setCategory(null);
            product.setLastUpdateTime(new Date());
            product.setUpdater(userManager.getUser());

            KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
            kpiLog.setActionType(KpiLog.ActionType.UPDATE);
            kpiLog.setEntityId(product.getObjectID());
            ServerUtils.kpiLog(log, kpiLog, "Product updated");
            itemManager.update(product);
            try {
                productsServicesSolrComponent.index(product);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsProductCategory.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.DELETE);
        kpiLog.setEntityId(category.getObjectID());
        ServerUtils.kpiLog(log, kpiLog, "Delete product category");
        productCategoryManager.deleteProductCategory(category.getObjectID());
        EdsBusinessEvent productCategoryWorkflow = null;
        productCategoryWorkflow = baseEventPostProcessor.registerEvent(WorkflowActionDetectedEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_DELETE, category, userManager.getUser());
        productCategoryWorkflow.setEntityType(TYPE_PRODUCT_CATEGORY);
        baseEventPostProcessor.registerEvent(ProductCategoryEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_DELETE, category, userManager.getUser());
        return true;
    }

