    @Override
    public boolean deleteShippingMedthod(Integer shippingMedthodId) {
        EdsShippingMethod shippingMethod = shippingMethodManager.get(shippingMedthodId);
        if (shippingMethod != null) {
            if (shippingMethod.getCustomers() != null && !shippingMethod.getCustomers().isEmpty()) {
                return false;
            }
            final int[] deletes = {0};
            if (shippingMethod.getQuotes() != null && !shippingMethod.getQuotes().isEmpty()) {
                shippingMethod.getQuotes().stream().filter(quote -> !quote.isDeleted()).forEach(quote -> deletes[0]++);
            }
            if (shippingMethod.getReservations() != null && !shippingMethod.getReservations().isEmpty()) {
                return false;
            }
            if (shippingMethod.getInvoices() != null && !shippingMethod.getInvoices().isEmpty()) {
                shippingMethod.getInvoices().stream().filter(invoice -> !invoice.isDeleted()).forEach(invoice -> deletes[0]++);
            }
            if (deletes[0] > 0) {
                return false;
            }

            shippingMethod.setDeleted(true);
            shippingMethodManager.update(shippingMethod);
            return true;
        } else {
            return false;
        }
    }

    @Transactional
    public void changeReconcileStatus(Integer transactionID, String status, Integer accountId) {
        EdsTransactionItem transactionItem = transactionItemManager.getByTransactionIdAndAccountId(transactionID, accountId);
        transactionItem.setReconcileStatus(status);
        transactionItemManager.update(transactionItem);
        EdsBankStatementItem bankStatementItem = transactionItem.getTransaction().getBankStatementItem();
        if (bankStatementItem != null) {
            if (!MARKED_AS_RECONCILED.equals(status)) {
                bankStatementItem.setReconciled(RECONCILED.equals(status));
                bankStatementItemManager.update(bankStatementItem);
            }
        }
    }

