    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ListResult<ProductLocationItem> getWarehouseProductsList(ListingFilterParameter filterParametrs) {
        EdsWarehouse warehouse = warehouseManager.get(filterParametrs.getWarehouseID());
        List<Object> warehouseProducts = productWarehouseLocationManager.getLocationsByWarehouseID(warehouse.getObjectID(), filterParametrs);
        ArrayList<ProductLocationItem> items = new ArrayList<>();
        List<Integer> ids = new ArrayList<>();
        int total = warehouseProducts.size();
        if (filterParametrs.getLimit() != null) {
            warehouseProducts = ListUtils.getSublist(warehouseProducts, filterParametrs.getStart(), filterParametrs.getLimit());
        }
        for (Object object : warehouseProducts) {
            Object[] product = (Object[]) object;
            ProductLocationItem item = new ProductLocationItem();
            item.setWarehouseID(warehouse.getObjectID());
            item.setWarehouseName(warehouse.getName());
            item.setObjectID(Integer.parseInt(String.valueOf(product[0])));
            item.setProductID(Integer.parseInt(String.valueOf(product[0])));
            item.setProductName(String.valueOf(product[1]));
            item.setProduct_number(String.valueOf(product[2]));
            item.setQty((BigDecimal) product[3]);
            item.setProductLocationDescription(String.valueOf((product[4])));
            item.setPickingNumber(String.valueOf((product[5]))); //TO DO


            items.add(item);

            ids.add(item.getObjectID());
        }
        HashMap<Integer, BigDecimal> averageCostMap = itemStockManager.getInventoryTransactionBalance(ids, warehouse.getObjectID());
        for (ProductLocationItem item : items) {
            item.setAverageCost(averageCostMap.get(item.getObjectID()));
        }
        return new ListResult<>(items, total);
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public WarehouseItem getWarehouse(Integer warehouseID) {
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsWarehouse.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.VIEW);
        kpiLog.setEntityId(warehouseID);
        ServerUtils.kpiLog(log, kpiLog, "get warehouse to view and edit");
        EdsWarehouse warehouse = warehouseManager.get(warehouseID);

        if (warehouse != null) {
            WarehouseItem item = warehouse.getRPC();

            if (item.getPrimaryContactID() != null) {
                EdsCrmContact contact = crmContactManager.get(item.getPrimaryContactID());

                item.setContactname(contact.getName());
                item.setPhone(contact.getPrimaryPhone());
                item.setEmail(contact.getPrimaryEmail());

                if (contact.getPrimaryAddressFromAll() != null && contact.getPrimaryAddressFromAll().getAddress() != null) {
                    item.setAddress(contact.getPrimaryAddressFromAll().getAddress());
                }
            }

            SelectItem[] ownersList = crmServiceLocal.getOwnersListByPermission(PermissionConstants.WAREHOUSE_OWNER);
            if (warehouse.getOwners().isEmpty()) {
                item.setOwnerItems(ownersList);
            } else {
                for (SelectItem owner : ownersList) {
                    owner.setSelected(warehouse.getOwnersMap().containsKey(owner.getId()));
                }
                item.setOwnerItems(ownersList);
            }

            ArrayList<CompanyCustomFieldItem> customFieldsItems = commonService.getCompanyCustomFields(ViewName.WareHouses);
            item.setCustomFieldItems(CustomFieldsUtils.setRPCCustomFieldItems(warehouse.getCustomFields(), customFieldsItems));
            item.setTemplates(getPdfTemplates(PdfReferenceCodeNameEnum.WARE_HOUSE_PRODUCT_LIST.name()).getItems());
            return item;
        }
        return null;
    }


