    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ProductCategoryItem getProductCategory(Integer categoryID) {

        ProductCategoryItem categoryItem = new ProductCategoryItem();
        categoryItem.setActive(true);
        if (categoryID != null) {
            EdsProductCategory category = productCategoryManager.get(categoryID);

            if (category != null) {
                categoryItem.setId(category.getObjectID());
                categoryItem.setActive(category.isActive());
                if (category.getCode() != null) {
                    categoryItem.setCode(category.getCode());
                    if (category.getPrefix() == null || category.getPrefix().isEmpty()) {
                        categoryItem.setPrefix(category.getCode().replace(EdsNumberingSettings.decimalFormat.format(category.getIntNumber()), ""));
                    } else {
                        categoryItem.setPrefix(category.getPrefix());
                    }
                    categoryItem.setIntNumber(category.getIntNumber());
                } else {
                    NumberData number = generateProductCategoryNumber();
                    categoryItem.setCode(number.getNumberString());
                    categoryItem.setPrefix(number.getFirstNumberString());
                    categoryItem.setIntNumber(number.getIntNumber());
                }
                if (genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ENABLE_ERP_TEXTILEFINDS_CUSTOMIZATION)) {
                    categoryItem.setName(buildHierarchyName(category));
                } else {
                    categoryItem.setName(category.getName());
                }
                categoryItem.setDescription(category.getDescription());
                categoryItem.setPrice(category.getPrice());
                categoryItem.setOrder(category.getOrder());
                if (category.getParent() != null) {
                    categoryItem.setParentCategoryID(category.getParent().getObjectID());
                    categoryItem.setParentCategoryName(category.getParent().getName());
                }

                if (category.getImageID() != null) {
                    categoryItem.setImageID(category.getImageID());
                    categoryItem.setImageUrl(uploadManager.getUploadFileUrl(category.getImageID()));
                }

                categoryItem.setCustomFields(CustomFieldsUtils.setRPCCustomFieldItems(category.getCustomFields(), commonService.getCompanyCustomFields(ViewName.ProductCategoryStoreFront)));

                categoryItem.setNameLocalize(WfmJsonUtils.jsonStringConvertToObject(category.getNameLocalize(), HashMap.class));
                categoryItem.setDescriptionLocalize(WfmJsonUtils.jsonStringConvertToObject(category.getDescriptionLocalize(), HashMap.class));
                ArrayList<CompanyCustomFieldItem> customFields = commonServiceLocal.getCompanyCustomFieldsByRelationship(ViewName.ProductCategory, categoryID, null);
                if (customFields != null && !customFields.isEmpty()) {
                    categoryItem.setCategoryCustomFields(customFields);
                }

            }
        } else {
            NumberData number = generateProductCategoryNumber();
            categoryItem.setCode(number.getNumberString());
            categoryItem.setPrefix(number.getFirstNumberString());
            categoryItem.setIntNumber(number.getIntNumber());
        }
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsProductCategory.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.VIEW);
        kpiLog.setEntityId(categoryID);
        ServerUtils.kpiLog(log, kpiLog, "View product category");

        return categoryItem;
    }


