    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public AccountItem[] getAccountsForInvoice(ListingFilterParameter fp, ArrayList<String> types) {
        if (fp == null) {
            fp = new ListingFilterParameter();
        }
        fp.setLookUp(true);

        CurrencyItem baseCurrency = invoiceCircularResolver.getBaseCurrency();

        List<EdsAccount> accounts = new ArrayList<>();
        if (types != null && !types.isEmpty()) {
            if (types.contains(Constants.REVENUE)
                    || types.contains(Constants.ASSETS)
                    || types.contains(Constants.EXPENSES)
                    || types.contains(Constants.EQUITY)
                    || types.contains(LIABILITIES)
                    || types.contains(NON_CURRENT_ASSET)) {
                accounts.addAll(getAccountsByCategory(types, fp, true));
            } else if (types.contains(RECEIVABLE)) {
                accounts.addAll(getAccountsByCategory(Lists.newArrayList(REVENUE, Constants.EQUITY, LIABILITIES), fp, false));
            } else if (types.contains(PAYABLE)) {
                fp.setAccountTypes(Lists.newArrayList(EXPENSES, Constants.EQUITY, Constants.ASSETS, LIABILITIES, NON_CURRENT_ASSET));
                List<EdsAccount> edsAccountList = accountingManager.getAccountsForPayableType(fp);
                accounts.addAll(edsAccountList);
            } else if (types.contains(FINANCED_BY)) {
                accounts.addAll(getAccountsByCategory(Lists.newArrayList(Constants.ASSETS, LIABILITIES, Constants.EQUITY), fp, true));
            } else if (types.contains(FIXED_ASSET)) {
                fp.setAccountCode(FIXED_ASSET);
                accounts = getAccountsByCategory(Lists.newArrayList(Constants.ASSETS, NON_CURRENT_ASSET), fp, true);
            } else if (types.contains("TAX")) {
                boolean isTaxAccountEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.TAX_ACCOUNT_ENABLED);
                if (isTaxAccountEnabled) {
                    accounts = accountingManager.getGroupAccounts(fp, Lists.newArrayList(EdsAccountType.CURRENT_LIABILITY, EdsAccountType.CURRENT_ASSET, EdsAccountType.DIRECT_EXPENSES, EdsAccountType.OVERHEAD, EdsAccountType.COST_OF_SALES));
                } else {
                    accounts = accountingManager.getGroupAccounts(fp, Lists.newArrayList(EdsAccountType.CURRENT_LIABILITY, EdsAccountType.CURRENT_ASSET));
                }
            } else if (types.contains(PREPAYMENT)) {
                fp.setSystem(true);
                fp.setAccountCode(AccountingConstants.CURRENT_ASSET);
                accounts.addAll(getAccountsByCategory(Lists.newArrayList(Constants.ASSETS), fp, true));

                fp.setAccountCode(null);
                accounts.addAll(getAccountsByCategory(Lists.newArrayList(LIABILITIES), fp, true));
            } else {
                accounts = accountingManager.getAllAccounts(fp);
            }
        } else {
            accounts = accountingManager.getAllAccounts(fp);
        }

        accounts = ListUtils.getSublistSmart(new ArrayList<>(accounts), fp.getStart(), fp.getLimit() > 0
                ? fp.getLimit()
                : DEFAULT_LIMIT);

        if ("MANUAL_ENTRY".equals(fp.getForm())) {
            if (baseCurrency.getId().equals(fp.getCurrencyID())) {
                accounts = accounts.stream()
                        .filter(a -> a.getCurrency().getObjectID().equals(baseCurrency.getId()))
                        .collect(Collectors.toList());
            } else {
                ListingFilterParameter finalFp = fp;
                accounts = accounts.stream()
                        .filter(a -> a.getCurrency().getObjectID().equals(finalFp.getCurrencyID()) || a.getCurrency().getObjectID().equals(baseCurrency.getId()))
                        .toList();
            }
        }

        AccountItem[] result = new AccountItem[accounts.size()];
        int i = 0;
        for (EdsAccount account : accounts) {
            result[i] = account.createAccountItem();
            if (result[i].getCurrencyID() == null) {
                result[i].setCurrencyID(baseCurrency.getId());
                result[i].setCurrencyCode(baseCurrency.getName());
            }
            i++;
        }

        return result;
    }

