    private AccountsByCategory objectToTransfer(List<EdsAccount> accounts) {
        List<AccountItem> assets = new ArrayList<>();
        List<AccountItem> liabilities = new ArrayList<>();
        List<AccountItem> equity = new ArrayList<>();
        List<AccountItem> expenses = new ArrayList<>();
        List<AccountItem> revenue = new ArrayList<>();
        List<AccountItem> overhead = new ArrayList<>();
        for (EdsAccount ac : accounts) {
            String category = ac.getAccountType().getCategory();
            AccountItem accountItem = ac.createAccountItem();
            if (EdsAccountType.ASSETS.equals(category)) {
                assets.add(accountItem);
            } else if (EdsAccountType.LIABILITIES.equals(category) || category.equals(EdsAccountType.CURRENT_LIABILITY)) {
                liabilities.add(accountItem);
            } else if (EdsAccountType.EQUITY.equals(category)) {
                equity.add(accountItem);
            } else if (EdsAccountType.EXPENSES.equals(category)) {
                expenses.add(accountItem);
            } else if (EdsAccountType.REVENUE.equals(category)) {
                revenue.add(accountItem);
            } else if (OVERHEAD.equals(category)) {
                overhead.add(accountItem);
            }
        }
        AccountsByCategory accountsByCategory = new AccountsByCategory();
        accountsByCategory.setAssets(sortAccountItems(assets).toArray(new AccountItem[]{}));
        accountsByCategory.setLiabilities(sortAccountItems(liabilities).toArray(new AccountItem[]{}));
        accountsByCategory.setEquity(sortAccountItems(equity).toArray(new AccountItem[]{}));
        accountsByCategory.setExpenses(sortAccountItems(expenses).toArray(new AccountItem[]{}));
        accountsByCategory.setRevenue(sortAccountItems(revenue).toArray(new AccountItem[]{}));
        accountsByCategory.setOverhead(sortAccountItems(overhead).toArray(new AccountItem[]{}));
        return accountsByCategory;
    }

    private List<AccountItem> sortAccountItems(List<AccountItem> items) {
        items.sort((o1, o2) -> {
            if (o1.getCode() == null) {
                return -1;
            }
            if (o2.getCode() == null) {
                return 1;
            }
            return o1.getCode().compareTo(o2.getCode());
        });
        return items;
    }

    public AccountTypesByCategory getAccountTypes() {
        List<EdsAccountType> accountTypes = accountingManager.getAccountTypes();
        List<SelectItem> assets = new ArrayList<>();
        List<SelectItem> liabilities = new ArrayList<>();
        List<SelectItem> equity = new ArrayList<>();
        List<SelectItem> expenses = new ArrayList<>();
        List<SelectItem> revenue = new ArrayList<>();
        List<SelectItem> creditCard = new ArrayList<>();

        SelectItem defaultAccount = null;

        for (EdsAccountType acType : accountTypes) {
            SelectItem acTypeSelect = new SelectItem(acType.getObjectID(), accountingLocalizer.localize(acType.getCode(), acType.getName()), acType.getCode());
            switch (acType.getCategory()) {
                case EdsAccountType.ASSETS -> assets.add(acTypeSelect);
                case EdsAccountType.LIABILITIES -> liabilities.add(acTypeSelect);
                case EdsAccountType.EQUITY -> equity.add(acTypeSelect);
                case EdsAccountType.EXPENSES -> {
                    expenses.add(acTypeSelect);
                    if (EdsAccountType.OVERHEAD.equals(acTypeSelect.getDescription())) {
                        defaultAccount = acTypeSelect;
                    }
                }
                case EdsAccountType.REVENUE -> revenue.add(acTypeSelect);
                case EdsAccountType.CREDIT_CARD -> creditCard.add(acTypeSelect);
            }
        }
        AccountTypesByCategory atCat = new AccountTypesByCategory();
        atCat.setAssets(assets.toArray(new SelectItem[]{}));
        atCat.setLiabilities(liabilities.toArray(new SelectItem[]{}));
        atCat.setEquity(equity.toArray(new SelectItem[]{}));
        atCat.setExpenses(expenses.toArray(new SelectItem[]{}));
        atCat.setRevenue(revenue.toArray(new SelectItem[]{}));
        atCat.setCreditCard(creditCard.toArray(new SelectItem[]{}));

        atCat.setDefaultAccount(defaultAccount);
        return atCat;
    }

    public Integer createTransactionsForInvoice(EdsInvoice invoice, EdsUser user) {
        if (!invoice.isFixedAssetRelated()) {
            Integer invoiceId = createTransactionsForInvoice1(invoice, user).getObjectID();

            if (invoice.getTotalInInvoiceCurrency() != null
                    && invoice.getTotalInInvoiceCurrency().compareTo(BigDecimal.ZERO) > 0
                    && invoice.getFullPayments() != null
                    && invoice.getTotalInInvoiceCurrency().compareTo(invoice.getFullPayments()) == 0) {
                invoice.setEntityStatus(referenceManager.findReference(Constants.INVOICE_STATUS, Constants.PAID));
                invoiceManager.update(invoice);

                try {
                    if (invoice instanceof EdsPurchaseInvoice) {
                        purchaseInvoiceSolrComponent.index((EdsPurchaseInvoice) invoice);
                    } else if (invoice instanceof EdsSaleInvoice) {
                        saleInvoiceSolrComponent.index((EdsSaleInvoice) invoice);
                    }
                } catch (final IOException | SolrServerException | InterruptedException e) {
                    e.printStackTrace();
                }
            }
            return invoiceId;
        }
        return null;
    }

    /**
     * Creates transaction after invoice is registered
     *
     * @param invoice created invoice
     * @return transaction to be created
     */
    private EdsInvoiceTransaction createTransactionsForInvoice1(EdsInvoice invoice, EdsUser user) {
        String invoiceType = invoice.getType(); //the type of invoice payable or receivable
        EdsInvoiceTransaction transaction = transactionManager.getTransactionByInvoice(invoice);
        if (transaction != null) {
            itemStockManager.deleteItemStocksByTransaction(transaction.getObjectID());
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsInvoiceTransaction(); //creating new transaction
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        }

        transaction.setInvoice(invoice);
        transaction.setJournalDate(invoice.getInvoiceDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getUserDate());

        transactionManager.createOrUpdate(transaction);

        //this list for the transaction items container
        List<EdsTransactionItem> transactionItemList = new ArrayList<>();
        Set<GenericSettingsEnum> genericSettingsEnums = genericSettingsManager.getEnabledGenericSettings();
        boolean isTaxAccountEnabled = genericSettingsEnums.contains(GenericSettingsEnum.TAX_ACCOUNT_ENABLED);
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        boolean isDiscountAccountEnabled = financialSettings.getEnableDiscountAccount();
        boolean isMultiWarehouseEnabled = financialSettings.getEnableMultiWarehouse();

        EdsAccount systemShippingAccount = accountingManager.getAccountByKey(EdsAccount.DISTRIBUTION_CARRIAGE);

        EdsWarehouse defaultWarehouse = warehouseManager.getDefaultWarehouse();
        EdsCurrency baseCurrency = financialSettings.getCurrency();

        EdsTransactionItem transactionItem = new EdsTransactionItem();
        //--------------------------------------RECEIVABLE------------------------------------//
        if (invoiceType.equals(RECEIVABLE)) {
            EdsAccount systemTaxAccount = accountingManager.getVatAccount(RECEIVABLE);
            EdsAccount systemDiscountAccount = accountingManager.getAccountByKey(EdsAccount.SALES_DISCOUNT);
            EdsBaseSaleInvoice saleInvoice = (EdsBaseSaleInvoice) invoice;
            transaction.setName(saleInvoice.getClient().getName());
            transaction.setClient(saleInvoice.getClient());

            {//# (A/R) transaction item logic depends on given currency
                if (invoice.getReceivablePayable() != null &&
                        (invoice.getCurrency().equals(invoice.getReceivablePayable().getCurrency())
                                || baseCurrency.equals(invoice.getReceivablePayable().getCurrency()))) {
                    transactionItem.setAccount(invoice.getReceivablePayable());
                } else {
                    transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_RECEIVABLE, invoice.getCurrency()));
                }
                if (invoice.getTotal().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setDebit(invoice.getTotal()); //accounts receivable always DEBIT when you add invoice
                } else {
                    transactionItem.setCredit(invoice.getTotal().abs()); //accounts receivable always DEBIT when you add invoice
                }
                if (transactionItem.getAccount().isForeignAccount()) {
                    if (invoice.getTotalInInvoiceCurrency().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setForeignDebit(invoice.getTotalInInvoiceCurrency());
                    } else {
                        transactionItem.setForeignCredit(invoice.getTotalInInvoiceCurrency().abs());
                    }
                }
                transactionItemList.add(transactionItem);
            }
            // For sales invoice system must not creagte billable expense transaction
            if (!(invoice instanceof EdsSaleInvoice)) {
                // All billable expenses logic here
                generateInvoiceBillableExpenseTransactionItems(invoice, transactionItemList, isTaxAccountEnabled, systemTaxAccount);
            }

            //Other things Equity, Liability, Assets, Expenses are CREDIT
            int i = 0;
            EdsTransactionItem lastTransactionItem = null;
            for (EdsInvoiceItem invoiceItem : saleInvoice.getInvoiceItems()) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(invoiceItem.isDeferredTransasctionItem() ? accountingManager.getAccountByKey(EdsAccount.DEFERRED_REVENUE) : invoiceItem.getAccount());
                transactionItem.setDepartment(invoiceItem.getDepartment());
                transactionItem.setProject(invoiceItem.getProject());
                transactionItem.setDescription(invoiceItem.getDescription());
                transactionItem.setItemId(invoiceItem.getObjectID());

                BigDecimal netAmount = ZERO;
                if (TAX_CALCULATION_INCLUSIVE.equals(invoice.getTaxCalculationType())) {
                    BigDecimal taxAmount = ZERO;
                    if (invoiceItem.getVat() != null) {
                        BigDecimal taxPercent = BigDecimal.valueOf(invoiceItem.getVat().getEffectiveTaxRate());
                        if (invoiceItem.getDoubleVat() != null) {
                            taxPercent = taxPercent.add(BigDecimal.valueOf(invoiceItem.getDoubleVat().getEffectiveTaxRate()));
                        }
                        taxAmount = invoiceItem.getNet().multiply(taxPercent).divide(HUNDRED.add(taxPercent), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    }
                    netAmount = invoiceItem.getNet().subtract(taxAmount).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                } else {
                    if (invoiceItem.getNet() != null) {
                        netAmount = invoiceItem.getNet().setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    } else {
                        netAmount = BigDecimal.ZERO;
                    }
                }

                if (isDiscountAccountEnabled) {
                    netAmount = netAmount.add(invoiceItem.getItemCalculatedDiscountAmount().divide(invoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                }

                if (netAmount.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(netAmount);
                } else {
                    transactionItem.setDebit(netAmount.abs());
                }

                transactionItemList.add(transactionItem);

                if (i == saleInvoice.getInvoiceItems().size() - 1) {
                    lastTransactionItem = transactionItem;
                }

                if (!isMultiWarehouseEnabled && invoiceItem.getWarehouse() == null) {
                    invoiceItem.setWarehouse(defaultWarehouse);
                }
                i++;
            }
            baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_SALES_INVOICE_TRANSACTION, saleInvoice, user);

            if (invoice.getTotalTaxes() != null && invoice.getTotalTaxes().compareTo(ZERO) != 0) {
                List<EdsInvoiceItem> edsInvoiceItemList = invoice.getInvoiceItems();
                if (isTaxAccountEnabled) {
                    for (EdsInvoiceItem edsInvoiceItem : edsInvoiceItemList) {
                        if (edsInvoiceItem.getVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setCredit(calculatedTax);//liability is a CREDIT when amount is positive
                                } else {
                                    transactionItem.setDebit(calculatedTax.abs());//liability is a DEBIT when amount is negative
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }

                        if (edsInvoiceItem.getDoubleVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getDoubleVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setCredit(calculatedTax);//liability is a CREDIT when amount is positive
                                } else {
                                    transactionItem.setDebit(calculatedTax.abs());//liability is a DEBIT when amount is negative
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }
                    }
                } else {
                    BigDecimal lineItemsTotalTaxes = BigDecimal.ZERO;
                    for (EdsInvoiceItem edsInvoiceItem : edsInvoiceItemList) {
                        if (edsInvoiceItem.getVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                lineItemsTotalTaxes = lineItemsTotalTaxes.add(accountTaxesMap.get(accountKey));//liability is a CREDIT when amount is positive
                            }
                        }
                        if (edsInvoiceItem.getDoubleVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getDoubleVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                lineItemsTotalTaxes = lineItemsTotalTaxes.add(accountTaxesMap.get(accountKey));//liability is a CREDIT when amount is positive
                            }
                        }
                    }
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(systemTaxAccount);
                    if (lineItemsTotalTaxes.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(lineItemsTotalTaxes);//liability is a CREDIT when amount is positive
                    } else {
                        transactionItem.setDebit(lineItemsTotalTaxes.abs());//liability is a DEBIT when amount is negative
                    }
                    transactionItemList.add(transactionItem);
                }
            }

            //Discount account calculation
            if (isDiscountAccountEnabled && invoice.getTotalDiscount() != null && invoice.getTotalDiscount().compareTo(ZERO) != 0) {
                BigDecimal discount = invoice.getTotalDiscount().divide(invoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                EdsTransactionItem discountItem = new EdsTransactionItem();
                discountItem.setAccount(systemDiscountAccount);

                if (discount.compareTo(BigDecimal.ZERO) >= 0) {
                    discountItem.setDebit(discount);
                } else {
                    discountItem.setCredit(discount.abs());
                }

                transactionItemList.add(discountItem);
            }

            if (saleInvoice.getShippingMethod() != null) {
                EdsShippingMethod shippingMethod = saleInvoice.getShippingMethod();
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(shippingMethod.getAccount() != null
                        ? shippingMethod.getAccount()
                        : systemShippingAccount);

                BigDecimal shippingAmount = saleInvoice.getShippingAmount().divide(saleInvoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                if (shippingAmount.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(shippingAmount);
                } else {
                    transactionItem.setDebit(shippingAmount.abs());
                }
                transactionItemList.add(transactionItem);
            }

            if (lastTransactionItem != null) {
                BigDecimal debCredDifference = transaction.getDebitCreditDiff(RECEIVABLE, transactionItemList);

                if (debCredDifference.compareTo(BigDecimal.ZERO) != 0) {

                    if (lastTransactionItem.getCredit() != null) {
                        lastTransactionItem.setCredit(lastTransactionItem.getCredit().add(debCredDifference));
                    } else if (lastTransactionItem.getDebit() != null) {
                        lastTransactionItem.setDebit(lastTransactionItem.getDebit().subtract(debCredDifference));
                    }
                }
            }

            //----------------------------------------------PAYABLE------------------------------------//
        } else if (invoiceType.equals(PAYABLE)) {
            EdsPurchaseInvoice purchaseInvoice = (EdsPurchaseInvoice) invoice;

            boolean isReverseCharge = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE)
                    && (invoice.getClientOrSupplier() != null && invoice.getClientOrSupplier().isReverseChargeApplicable() || purchaseInvoice.isReverseChargeApplicable());

            EdsAccount systemTaxAccount = accountingManager.getVatAccount(PAYABLE);
            EdsAccount systemDiscountAccount = accountingManager.getAccountByKey(EdsAccount.PURCHASE_DISCOUNT);
            transaction.setName(purchaseInvoice.getSupplier().getName());
            transaction.setSupplier(purchaseInvoice.getSupplier());
            EdsTransactionItem lastTransactionItem = null;

            BigDecimal invoiceTaxTotal = invoice.getTotalTaxes();
            if (invoice.getCurrency() != null && baseCurrency != null && !invoice.getCurrency().getObjectID().equals(baseCurrency)) {
                BigDecimal totalTaxAmount = BigDecimal.ZERO;
                List<EdsInvoiceItem> edsInvoiceItemList = invoice.getInvoiceItems();
                for (EdsInvoiceItem edsInvoiceItem : edsInvoiceItemList) {
                    if (edsInvoiceItem.getTaxAmount() != null) {
                        totalTaxAmount = totalTaxAmount.add(edsInvoiceItem.getTaxAmount());
                    }
                }
                invoiceTaxTotal = totalTaxAmount.divide(invoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            }

            {//# (A/R) transaction item logic depends on given currency
                if (invoice.getReceivablePayable() != null &&
                        (invoice.getCurrency().equals(invoice.getReceivablePayable().getCurrency())
                                || (invoice.getReceivablePayable() != null && baseCurrency.equals(invoice.getReceivablePayable().getCurrency())))) {

                    transactionItem.setAccount(invoice.getReceivablePayable());
                } else {
                    transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, invoice.getCurrency()));
                }
                if (invoice.getTotal().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(invoice.getTotal()); //accounts payable is CREDIT when amount is positive
                } else {
                    transactionItem.setDebit(invoice.getTotal().abs()); //accounts payable is DEBIT when amount is negative
                }
                if (transactionItem.getAccount().isForeignAccount()) {

                    if (invoice.getTotalInInvoiceCurrency().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setForeignCredit(invoice.getTotalInInvoiceCurrency());
                    } else {
                        transactionItem.setForeignDebit(invoice.getTotalInInvoiceCurrency().abs());
                    }
                }
                transactionItemList.add(transactionItem);
            }
            boolean isConvertedInvoice = invoice.getConvertedQuotes() != null && !invoice.getConvertedQuotes().isEmpty();

            if (isConvertedInvoice) {
                BigDecimal convertedItemsTotal = BigDecimal.ZERO;
                for (EdsInvoiceItem item : invoice.getInvoiceItems()) {

                    if (item.getQuoteItemId() == null) {
                        BigDecimal itemTotal = item.getNet().add(item.getTaxCalculationType() == 2 && item.getTaxAmount() != null
                                ? item.getTaxAmount()
                                : BigDecimal.ZERO);

                        if (isDiscountAccountEnabled) {
                            BigDecimal itemDiscount = item.getItemCalculatedDiscountAmount();
                            itemTotal = itemTotal.add(itemDiscount);
                        }

                        EdsTransactionItem invoiceItemTItem = new EdsTransactionItem();
                        invoiceItemTItem.setAccount(item.getAccount());
                        invoiceItemTItem.setDepartment(item.getDepartment());
                        invoiceItemTItem.setDescription(item.getDescription());
                        invoiceItemTItem.setProject(item.getProject());
                        invoiceItemTItem.setItemId(item.getObjectID());

                        convertedItemsTotal = convertedItemsTotal.add(itemTotal);
                        if (itemTotal.compareTo(BigDecimal.ZERO) >= 0) {
                            invoiceItemTItem.setDebit(itemTotal);
                        } else {
                            invoiceItemTItem.setCredit(itemTotal.abs());
                        }
                        transactionItemList.add(invoiceItemTItem);
                    }
                }
                EdsTransactionItem pendingGoodsTItem = new EdsTransactionItem();
                pendingGoodsTItem.setAccount(accountingManager.getAccountByKey(EdsAccount.PENDING_GOODS_RECEIVED_NOTES));
                BigDecimal pendingGoodsTotal = invoice.getTotal().subtract(convertedItemsTotal);

                //
                //This one is temporary solution for excluding VAT from GRN
                //After some period we'll delete this one
                //
                {
                    if (!isReverseCharge && invoice.getConvertedShippingData() != null && !invoice.getConvertedShippingData().isEmpty()) {
                        List<Integer> shippingDataIds = invoice.getConvertedShippingData().stream().filter(shd -> !shd.isDeleted()).map(EdsShippingData::getObjectID).collect(Collectors.toList());
                        BigDecimal grnVatTotal = transactionManager.getGrnVATTotal(shippingDataIds);
                        invoiceTaxTotal = invoiceTaxTotal.subtract(grnVatTotal);
                    }
                }
                if (!isReverseCharge) {
                    pendingGoodsTotal = pendingGoodsTotal.subtract(invoiceTaxTotal);
                }
                if (pendingGoodsTotal.compareTo(BigDecimal.ZERO) >= 0) {
                    pendingGoodsTItem.setDebit(pendingGoodsTotal);
                } else {
                    pendingGoodsTItem.setCredit(pendingGoodsTotal.abs());
                }
                lastTransactionItem = pendingGoodsTItem;
                transactionItemList.add(pendingGoodsTItem);
            } else {
                //Other things Equity, Liability, Assets, Expenses are DEBIT
                int i = 0;

                for (EdsInvoiceItem invoiceItem : purchaseInvoice.getInvoiceItems()) {
                    EdsTransactionItem invoiceItemTItem = new EdsTransactionItem();
                    invoiceItemTItem.setAccount(invoiceItem.isDeferredTransasctionItem() ? accountingManager.getAccountByKey(EdsAccount.DEFERRED_EXPENSE) : invoiceItem.getAccount());
                    invoiceItemTItem.setDepartment(invoiceItem.getDepartment());
                    invoiceItemTItem.setDescription(invoiceItem.getDescription());
                    invoiceItemTItem.setProject(invoiceItem.getProject());
                    invoiceItemTItem.setItemId(invoiceItem.getObjectID());

                    BigDecimal netAmount = ZERO;
                    if (TAX_CALCULATION_INCLUSIVE.equals(invoice.getTaxCalculationType())) {
                        BigDecimal taxAmount = ZERO;

                        if (invoiceItem.getVat() != null) {
                            BigDecimal taxPercent = BigDecimal.valueOf(invoiceItem.getVat().getEffectiveTaxRate());
                            if (invoiceItem.getDoubleVat() != null) {
                                taxPercent = taxPercent.add(BigDecimal.valueOf(invoiceItem.getDoubleVat().getEffectiveTaxRate()));
                            }
                            taxAmount = invoiceItem.getNet().multiply(taxPercent).divide(HUNDRED.add(taxPercent), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        }
                        netAmount = invoiceItem.getNet().subtract(taxAmount).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    } else {
                        netAmount = invoiceItem.getNet().setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    }

                    if (isDiscountAccountEnabled) {
                        netAmount = netAmount.add(invoiceItem.getItemCalculatedDiscountAmount().divide(invoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }

                    if (netAmount.compareTo(BigDecimal.ZERO) >= 0) {
                        invoiceItemTItem.setDebit(netAmount);
                    } else {
                        invoiceItemTItem.setCredit(netAmount.abs());
                    }

                    if (invoiceItemTItem.getAccount().isForeignAccount()) {
                        BigDecimal netAmountInvoiceCurrency = netAmount.multiply(invoice.getExchangeRate());
                        if (netAmountInvoiceCurrency.compareTo(BigDecimal.ZERO) >= 0) {
                            invoiceItemTItem.setForeignDebit(netAmountInvoiceCurrency);
                        } else {
                            invoiceItemTItem.setForeignCredit(netAmountInvoiceCurrency.abs());
                        }
                    }


                    //IMPORTANT: this one will use to asset cost
                    invoiceItem.setTransactionValue(netAmount);

                    transactionItemList.add(invoiceItemTItem);

                    if (i == purchaseInvoice.getInvoiceItems().size() - 1) {
                        lastTransactionItem = invoiceItemTItem;
                    }

                    EdsItem item = invoiceItem.getItem();
                    if (item != null && (item.getType().equals(INVENTORY_ITEM) || item.getType().equals(ASSEMBLY_ITEM) || item.getType().equals(PRODUCT_KIT))) {
                        //purchase invoice items apply to item stock (this is by Normurod)
                        if (!isMultiWarehouseEnabled && invoiceItem.getWarehouse() == null) {
                            invoiceItem.setWarehouse(defaultWarehouse);
                        }
                        applyPurchasesToItemStock(invoiceItem, transaction);
                    }

                    i++;
                }
                baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_PURCHASE_INVOICE_TRANSACTION, invoice, user);
            }

            if (!(isConvertedInvoice && isReverseCharge)
                    && invoiceTaxTotal != null
                    && invoiceTaxTotal.compareTo(ZERO) != 0) {

                if (isTaxAccountEnabled) {
                    List<EdsInvoiceItem> edsInvoiceItemList = invoice.getInvoiceItems();
                    for (EdsInvoiceItem edsInvoiceItem : edsInvoiceItemList) {

                        if (edsInvoiceItem.getVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                EdsTransactionItem accTaxTItem = new EdsTransactionItem();
                                accTaxTItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);

                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    accTaxTItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                                } else {
                                    accTaxTItem.setCredit(calculatedTax.abs());//liability is also a CREDIT in this case
                                }
                                transactionItemList.add(accTaxTItem);
                            }
                        }

                        if (edsInvoiceItem.getDoubleVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getDoubleVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                EdsTransactionItem accTaxTItem = new EdsTransactionItem();
                                accTaxTItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);

                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    accTaxTItem.setDebit(calculatedTax);//own VAT is also a DEBIT in this case
                                } else {
                                    accTaxTItem.setCredit(calculatedTax.abs());//own VAT is also a CREDIT in this case
                                }
                                transactionItemList.add(accTaxTItem);
                            }
                        }
                    }
                } else {
                    EdsTransactionItem sysTaxItem = new EdsTransactionItem();
                    sysTaxItem.setAccount(systemTaxAccount);

                    if (invoiceTaxTotal.compareTo(BigDecimal.ZERO) >= 0) {
                        sysTaxItem.setDebit(invoiceTaxTotal);//liability is also a DEBIT in this case
                    } else {
                        sysTaxItem.setCredit(invoiceTaxTotal.abs());//liability is also a CREDIT in this case
                    }
                    transactionItemList.add(sysTaxItem);

                    /*
                     * REVERSE CHARGE MODE
                     */
                    {
                        if (isReverseCharge) {
                            EdsTransactionItem outTaxItem = new EdsTransactionItem();
                            outTaxItem.setAccount(accountingManager.getVatAccount(RECEIVABLE));

                            if (invoiceTaxTotal.compareTo(BigDecimal.ZERO) >= 0) {
                                outTaxItem.setCredit(invoiceTaxTotal);
                            } else {
                                outTaxItem.setDebit(invoiceTaxTotal.abs());
                            }
                            transactionItemList.add(outTaxItem);
                        }
                    }
                }
            }

            //Discount account calculation
            if (isDiscountAccountEnabled && invoice.getTotalDiscount() != null && invoice.getTotalDiscount().compareTo(ZERO) != 0) {
                BigDecimal discount = invoice.getTotalDiscount().divide(invoice.getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                EdsTransactionItem discountItem = new EdsTransactionItem();
                discountItem.setAccount(systemDiscountAccount);

                if (discount.compareTo(BigDecimal.ZERO) >= 0) {
                    discountItem.setCredit(discount);
                } else {
                    discountItem.setDebit(discount.abs());
                }

                transactionItemList.add(discountItem);
            }

            if (lastTransactionItem != null) {
                BigDecimal credDebDifference = transaction.getDebitCreditDiff(PAYABLE, transactionItemList);
                if (credDebDifference.compareTo(BigDecimal.ZERO) != 0) {
                    if (lastTransactionItem.getDebit() != null) {
                        lastTransactionItem.setDebit(lastTransactionItem.getDebit().add(credDebDifference));
                    } else if (lastTransactionItem.getCredit() != null) {
                        lastTransactionItem.setCredit(lastTransactionItem.getCredit().subtract(credDebDifference));
                    }
                }
            }
        }

        //set transaction item list to transaction
        if (!transactionItemList.isEmpty()) {
            for (EdsTransactionItem ti : transactionItemList) {
                ti.setTransaction(transaction);
            }
        }
        transaction.getTransactionItems().addAll(transactionItemList);

        transactionManager.update(transaction);

        return transaction;
    }

    private void generateInvoiceBillableExpenseTransactionItems(EdsInvoice invoice, List<EdsTransactionItem> transactionItemList, boolean isTaxAccountEnabled, EdsAccount systemTaxAccount) {
        EdsTransactionItem transactionItem;

        List<EdsExpense> expList = expenseManager.getExpenseByInvoice(invoice.getObjectID());
        //transactionItem for billableExpense
        BigDecimal totalTaxes = ZERO;
        if (expList != null && !expList.isEmpty()) {
            for (EdsExpense exp : expList) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(exp.getAccount());

                if (exp.getNetAmountInBase().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(exp.getNetAmountInBase());
                } else {
                    transactionItem.setDebit(exp.getNetAmountInBase().abs());
                }

                transactionItemList.add(transactionItem);

                if (exp.getMarkupAccount() != null && exp.getMarkupAmount().compareTo(ZERO) > 0) {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(exp.getMarkupAccount());

                    if (exp.getMarkupAmount().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(exp.getMarkupAmount().divide(exp.getReport().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        transactionItem.setDebit(exp.getMarkupAmount().abs().divide(exp.getReport().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }
                    transactionItemList.add(transactionItem);
                }
                if (exp.getMarkupTax() != null && exp.getMarkupTaxAmount().compareTo(ZERO) > 0) {
                    totalTaxes = totalTaxes.add(exp.getMarkupTaxAmount().divide(exp.getReport().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                }
            }
        }

        //Purchase invoice items as billable expenses
        List<EdsInvoiceItem> invoiceItemListAsExpense = invoiceManager.getItemListAsExpenseByInvoice(invoice.getObjectID());
        if (invoiceItemListAsExpense != null && !invoiceItemListAsExpense.isEmpty()) {
            for (EdsInvoiceItem exp : invoiceItemListAsExpense) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(exp.getAccount());
                transactionItem.setDepartment(exp.getDepartment());
                transactionItem.setDescription(exp.getDescription());

                if (exp.getNet().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(exp.getNet());
                } else {
                    transactionItem.setDebit(exp.getNet().abs());
                }
                transactionItemList.add(transactionItem);

                if (exp.getMarkupAccount() != null && exp.getMarkupAmount().compareTo(ZERO) > 0) {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(exp.getMarkupAccount());

                    if (exp.getMarkupAmount().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(exp.getMarkupAmount().divide(exp.getInvoice().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        transactionItem.setDebit(exp.getMarkupAmount().abs().divide(exp.getInvoice().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }
                    transactionItemList.add(transactionItem);
                }
                if (exp.getMarkupTax() != null && exp.getMarkupTaxAmount().compareTo(ZERO) > 0) {
                    totalTaxes = totalTaxes.add(exp.getMarkupTaxAmount().divide(exp.getInvoice().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                }
            }
        }

        //Manual transaction items as billable expenses
        List<EdsManualJournalItem> mjItemListAsExpense = manualJournalItemManager.getItemListAsExpenseByInvoice(invoice.getObjectID());
        if (mjItemListAsExpense != null && !mjItemListAsExpense.isEmpty()) {
            for (EdsManualJournalItem exp : mjItemListAsExpense) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(exp.getAccount());
                transactionItem.setDepartment(exp.getDepartment());
                transactionItem.setDescription(exp.getDescription());

                if (exp.getDebit() != null && exp.getDebit().compareTo(BigDecimal.ZERO) > 0) {
                    transactionItem.setCredit(exp.getDebitInBase());
                } else {
                    transactionItem.setDebit(exp.getCreditInBase());
                }
                transactionItemList.add(transactionItem);

                if (exp.getMarkupAccount() != null && exp.getMarkupAmount().compareTo(ZERO) > 0) {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(exp.getMarkupAccount());

                    if (exp.getMarkupAmount().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(exp.getMarkupAmount().divide(exp.getManualTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        transactionItem.setDebit(exp.getMarkupAmount().abs().divide(exp.getManualTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }
                    transactionItemList.add(transactionItem);
                }
                if (exp.getMarkupTax() != null && exp.getMarkupTaxAmount().compareTo(ZERO) > 0) {
                    totalTaxes = totalTaxes.add(exp.getMarkupTaxAmount().divide(exp.getManualTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                }
            }
        }

        //Bank/Cash payment items as billable expenses
        List<EdsBankTransferItem> btItemListAsExpense = spendReceiveMoneyItemManager.getItemListAsExpenseByInvoice(invoice.getObjectID());
        if (btItemListAsExpense != null && !btItemListAsExpense.isEmpty()) {
            for (EdsBankTransferItem exp : btItemListAsExpense) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(exp.getAccount());
                transactionItem.setDepartment(exp.getDepartment());
                transactionItem.setDescription(exp.getDescription());

                if (exp.getAmount().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(exp.getAmountInBase());
                } else {
                    transactionItem.setDebit(exp.getAmountInBase().abs());
                }
                transactionItemList.add(transactionItem);

                if (exp.getMarkupAccount() != null && exp.getMarkupAmount().compareTo(ZERO) > 0) {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(exp.getMarkupAccount());

                    if (exp.getMarkupAmount().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(exp.getMarkupAmount().divide(exp.getMoneyTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        transactionItem.setDebit(exp.getMarkupAmount().abs().divide(exp.getMoneyTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }
                    transactionItemList.add(transactionItem);
                }
                if (exp.getMarkupTax() != null && exp.getMarkupTaxAmount().compareTo(ZERO) > 0) {
                    totalTaxes = totalTaxes.add(exp.getMarkupTaxAmount().divide(exp.getMoneyTransfer().getExchangeRate(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                }
            }
        }

        //Bank Chick items as billab expenses
        List<EdsBankCheckItem> chItemListAsExpense = bankCheckItemManager.getItemListAsExpenseByInvoice(invoice.getObjectID());
        if (chItemListAsExpense != null && !chItemListAsExpense.isEmpty()) {
            for (EdsBankCheckItem exp : chItemListAsExpense) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(exp.getAccount());
                transactionItem.setDescription(exp.getDescription());

                if (exp.getAmount().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(exp.getAmountInBase());
                } else {
                    transactionItem.setDebit(exp.getAmountInBase().abs());
                }
                transactionItemList.add(transactionItem);

                if (exp.getMarkupAccount() != null && exp.getMarkupAmount().compareTo(ZERO) > 0) {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(exp.getMarkupAccount());

                    BigDecimal markupInBase = Optional.ofNullable(exp.getMarkupAmount()).orElse(BigDecimal.ZERO)
                            .divide(Optional.ofNullable(exp.getBankCheck().getExchangeRate()).orElse(BigDecimal.ONE), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                    if (markupInBase.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(markupInBase);
                    } else {
                        transactionItem.setDebit(markupInBase.abs());
                    }
                    transactionItemList.add(transactionItem);
                }
                if (exp.getMarkupTax() != null && exp.getMarkupTaxAmount().compareTo(ZERO) > 0) {
                    totalTaxes = totalTaxes.add(exp.getMarkupTaxAmount());
                }
            }
        }

        if (totalTaxes.compareTo(ZERO) != 0) {
            if (isTaxAccountEnabled) {
                List<EdsInvoiceItem> edsInvoiceItemList = invoice.getInvoiceItems();
                for (EdsInvoiceItem edsInvoiceItem : edsInvoiceItemList) {
                    if (edsInvoiceItem.getVat() != null) {
                        HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                transactionItem.setCredit(calculatedTax);//liability is CREDIT when amount is positive
                            } else {
                                transactionItem.setDebit(calculatedTax.abs());//liability is DEBIT when amount is negative
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                    if (edsInvoiceItem.getDoubleVat() != null) {
                        HashMap<Integer, BigDecimal> accountTaxesMap = edsInvoiceItem.getDoubleVat().calculateAccountTaxes(edsInvoiceItem.getNet(), invoice.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                transactionItem.setCredit(calculatedTax);//liability is CREDIT when amount is positive
                            } else {
                                transactionItem.setDebit(calculatedTax.abs());//liability is DEBIT when amount is negative
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                }
            } else {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(systemTaxAccount);
                if (totalTaxes.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(totalTaxes);//liability is CREDIT when amount is positive
                } else {
                    transactionItem.setDebit(totalTaxes.abs());//liability is DEBIT when amount is negative
                }
                transactionItemList.add(transactionItem);
            }
        }
    }


    public Integer voidInvoiceTransactions(Integer invoiceID, DateNonConvertable voidDate) {
        EdsInvoice invoice = invoiceManager.get(invoiceID);
        EdsInvoiceTransaction invTransaction = transactionManager.getTransactionByInvoice(invoice);
        if (invTransaction != null) {
            EdsInvoiceTransaction transaction = new EdsInvoiceTransaction(); //creating new transaction
            transaction.setName(invoice.getClientOrSupplier().getName());
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);

            transaction.setJournalDate((voidDate != null && voidDate.getNonConvertedDate() != null)
                    ? voidDate.getNonConvertedDate()
                    : invoice.getInvoiceDate());
            transaction.setPostedBy(transactionManager.getUser());
            transaction.setPostedDate(transactionManager.getUser().getUserDate());
            transaction.setReversalTransaction(invTransaction);
            transaction.setInvoice(invTransaction.getInvoice());
            transaction.setClient(invTransaction.getClient());
            transaction.setSupplier(invTransaction.getSupplier());

            if (invTransaction.getTransactionItems() != null && !invTransaction.getTransactionItems().isEmpty()) {
                EdsTransactionItem item;
                for (EdsTransactionItem invTransItem : invTransaction.getTransactionItems()) {
                    item = new EdsTransactionItem();
                    item.setAccount(invTransItem.getAccount());
                    item.setDepartment(invTransItem.getDepartment());
                    item.setProject(invTransItem.getProject());
                    item.setDebit(invTransItem.getCredit());
                    item.setCredit(invTransItem.getDebit());
                    item.setForeignDebit(invTransItem.getForeignCredit());
                    item.setForeignCredit(invTransItem.getForeignDebit());
                    item.setCrmAccount(invTransItem.getCrmAccount());
                    transaction.addTransactionItem(item);
                }
            }
            transactionManager.create(transaction);

            //delete item stock by the invoice transaction
            itemStockManager.deleteItemStocksByTransaction(invTransaction.getObjectID());
            return transaction.getObjectID();
        }
        return -1;
    }

    /**
     * Creates transaction after payment is registered
     *
     * @param invoicePayment the bank payment for the certain invoice
     */
    public void createTransactionForPayment(EdsInvoicePayment invoicePayment) {//check if payable or receivable
        EdsUser user = accountingManager.getUser();
        if (user == null) {
            user = invoicePayment.getUser();
        }

        EdsInvoicePaymentTransaction transaction = transactionManager.getTransactionByPayment(invoicePayment);//get the transaction for this invoice payment
        if (transaction == null) {
            transaction = new EdsInvoicePaymentTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
        } else {
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        }
        transaction.setInvoicePayment(invoicePayment);
        transaction.setJournalDate(invoicePayment.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setReference(invoicePayment.getReference());

        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();

        String inOutType = invoicePayment.getInOutType(); //the type of invoice payable or receivable
        Integer systemAccountKey = invoicePayment.getSystemAccountKeyByType();
        EdsInvoicePayment applied = invoicePayment.getAppliedPayment();

        if ((RECEIVABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) ||
                PAYABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) ||
                RECEIVABLE_CREDIT_REFUND.equals(invoicePayment.getType()) ||
                PAYABLE_DEBIT_REFUND.equals(invoicePayment.getType()))
                && applied != null && applied.getReceivablePayable() != null
                && (AccountingConstants.RECEIVABLE_PREPAYMENT.equals(applied.getType()) || AccountingConstants.PAYABLE_SUPPLIER_CREDIT.equals(applied.getType()))) {

            invoicePayment.setReceivablePayable(applied.getReceivablePayable());
        }

        if (invoicePayment.getReceivablePayable() != null && invoicePayment.getReceivablePayable().getKey() != null && invoicePayment.getReceivablePayable().getKey() == EdsAccount.UNEARNED_REVENUE && (AccountingConstants.RECEIVABLE_PREPAYMENT.equals(invoicePayment.getType()) || RECEIVABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) && invoicePayment.getAppliedPayment() != null)) {
            systemAccountKey = EdsAccount.UNEARNED_REVENUE;
        } else if (invoicePayment.getReceivablePayable() != null && invoicePayment.getReceivablePayable().getKey() != null && invoicePayment.getReceivablePayable().getKey() == EdsAccount.PREPAID_EXPANSES && (AccountingConstants.PAYABLE_SUPPLIER_CREDIT.equals(invoicePayment.getType()) || PAYABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) && invoicePayment.getAppliedPayment() != null)) {
            systemAccountKey = EdsAccount.PREPAID_EXPANSES;
        }

        BigDecimal paymentExchangeRate = invoicePayment.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
        BigDecimal diff = ZERO, invoiceExchangeRate;
        if (VATRETURN_PAYMENT_RECEIVABLE.equals(invoicePayment.getType()) || VATRETURN_PAYMENT_PAYABLE.equals(invoicePayment.getType())) {
            invoiceExchangeRate = paymentExchangeRate;
            if (invoicePayment.getNote() != null && "".equals(invoicePayment.getNote())) {
                transaction.setName("Payment: " + invoicePayment.getNote());
            } else {
                transaction.setName("Payment: VAT Refund");
            }
        } else if (RECEIVABLE_PREPAYMENT.equals(invoicePayment.getType()) || PAYABLE_SUPPLIER_CREDIT.equals(invoicePayment.getType())) {
            invoiceExchangeRate = paymentExchangeRate;
            if (RECEIVABLE_PREPAYMENT.equals(invoicePayment.getType())) {
                transaction.setName("Prepayment: " + invoicePayment.getCrmAccount().getName() + (invoicePayment.getNumber() != null
                        ? " | " + invoicePayment.getNumber()
                        : ""));
                transaction.setClient(invoicePayment.getCrmAccount());
            } else {
                transaction.setName("Supplier Credit: " + invoicePayment.getCrmAccount().getName() + (invoicePayment.getNumber() != null
                        ? " | " + invoicePayment.getNumber()
                        : ""));
                transaction.setSupplier(invoicePayment.getCrmAccount());
            }
        } else if (RECEIVABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) || PAYABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) ||
                RECEIVABLE_CREDIT_REFUND.equals(invoicePayment.getType()) || PAYABLE_DEBIT_REFUND.equals(invoicePayment.getType())) {
            invoiceExchangeRate = paymentExchangeRate;
            if (RECEIVABLE_PREPAYMENT_REFUND.equals(invoicePayment.getType()) || RECEIVABLE_CREDIT_REFUND.equals(invoicePayment.getType())) {
                transaction.setName("Customer Refund: " + invoicePayment.getCrmAccount().getName() + (invoicePayment.getReference() != null
                        ? " | " + invoicePayment.getReference()
                        : ""));
                transaction.setClient(invoicePayment.getCrmAccount());
            } else {
                transaction.setName("Supplier Refund: " + invoicePayment.getCrmAccount().getName() + (invoicePayment.getReference() != null
                        ? " | " + invoicePayment.getReference()
                        : ""));
                transaction.setSupplier(invoicePayment.getCrmAccount());
            }
        } else if (RECEIVABLE_PREPAYMENT_SHARE.equals(invoicePayment.getType()) || RECEIVABLE_CRM_ACCOUNT_CREDIT.equals(invoicePayment.getType())
                || RECEIVABLE_MANUAL_CREDIT.equals(invoicePayment.getType()) || RECEIVABLE_BANKTRANSFER_CREDIT.equals(invoicePayment.getType())) {
            invoiceExchangeRate = paymentExchangeRate;
            transaction.setClient(invoicePayment.getCrmAccount());
            transaction.setName("Payment: " + invoicePayment.getCrmAccount().getName());

            if (invoicePayment.getAppliedPayment() != null && invoicePayment.getCurrencyID().equals(invoicePayment.getAppliedPayment().getCurrencyID())) {
                paymentExchangeRate = invoicePayment.getAppliedPayment().getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
            } else if (invoicePayment.getManualJournalID() != null) {
                EdsManualJournal mj = manualJournalManager.get(invoicePayment.getManualJournalID());

                if (invoicePayment.getCurrencyID().equals(mj.getCurrency().getObjectID())) {
                    paymentExchangeRate = mj.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                    diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
                }
            } else if (invoicePayment.getBankTransferID() != null) {
                EdsBankTransfer bt = spendReceiveMoneyManager.get(invoicePayment.getBankTransferID());

                if (invoicePayment.getCurrencyID().equals(bt.getCurrency().getObjectID())) {
                    paymentExchangeRate = bt.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                    diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
                }
            }
        } else if (PAYABLE_BANK_CHECK_SHARE.equals(invoicePayment.getType()) || PAYABLE_CRM_ACCOUNT_CREDIT.equals(invoicePayment.getType())
                || PAYABLE_MANUAL_CREDIT.equals(invoicePayment.getType()) || PAYABLE_SUPPLIER_CREDIT_SHARE.equals(invoicePayment.getType())
                || PAYABLE_BANKTRANSFER_CREDIT.equals(invoicePayment.getType())) {

            invoiceExchangeRate = paymentExchangeRate;
            transaction.setSupplier(invoicePayment.getCrmAccount());
            transaction.setName("Payment: " + invoicePayment.getCrmAccount().getName());

            if (invoicePayment.getAppliedPayment() != null && invoicePayment.getCurrencyID().equals(invoicePayment.getAppliedPayment().getCurrencyID())) {
                paymentExchangeRate = invoicePayment.getAppliedPayment().getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
            } else if (invoicePayment.getManualJournalID() != null) {
                EdsManualJournal mj = manualJournalManager.get(invoicePayment.getManualJournalID());

                if (invoicePayment.getCurrencyID().equals(mj.getCurrency().getObjectID())) {
                    paymentExchangeRate = mj.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                    diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
                }
            } else if (invoicePayment.getBankTransferID() != null) {
                EdsBankTransfer bt = spendReceiveMoneyManager.get(invoicePayment.getBankTransferID());

                if (invoicePayment.getCurrencyID().equals(bt.getCurrency().getObjectID())) {
                    paymentExchangeRate = bt.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                    diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
                }
            }
        } else {
            if (invoicePayment.getCurrencyID() != null && !invoicePayment.getCurrencyID().equals(invoicePayment.getInvoice().getCurrency().getObjectID())) {
                invoiceExchangeRate = paymentExchangeRate;
            } else {
                invoiceExchangeRate = invoicePayment.getInvoice().getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
            }
            transaction.setName("Payment: " + invoicePayment.getInvoice().getClientOrSupplier().getName());
            transaction.setTargetTransaction(transactionManager.getTransactionByInvoice(invoicePayment.getInvoice()));
            diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
            if (RECEIVABLE.equals(invoicePayment.getType())) {
                transaction.setClient(invoicePayment.getInvoice().getClientOrSupplier());
            } else if (PAYABLE.equals(invoicePayment.getType())) {
                transaction.setSupplier(invoicePayment.getInvoice().getClientOrSupplier());
            }
        }
        if (invoiceExchangeRate.compareTo(ZERO) == 0) {
            invoiceExchangeRate = new BigDecimal("1.00");
        }
        if (paymentExchangeRate.compareTo(ZERO) == 0) {
            paymentExchangeRate = new BigDecimal("1.00");
        }
        BigDecimal bankAmount = paymentExchangeRate.compareTo(BigDecimal.ONE) == 0 ? invoicePayment.getAmount() : (invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0
                ? invoicePayment.getAmountInInvoiceCurrency()
                : invoicePayment.getAmount()).divide(paymentExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        BigDecimal receivablePayable = invoiceExchangeRate.compareTo(BigDecimal.ONE) == 0 ? invoicePayment.getAmount() : (invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0
                ? invoicePayment.getAmountInInvoiceCurrency()
                : invoicePayment.getAmount()).divide(invoiceExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED) && (invoicePayment.getInvoice() != null || invoicePayment.getCurrencyID() != null);
        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();

        EdsCurrency paymentCurrency = null;
        if (invoicePayment.getInvoice() != null) {
            paymentCurrency = invoicePayment.getInvoice().getCurrency();
        } else if (invoicePayment.getCurrencyID() != null) {
            paymentCurrency = currencyManager.get(invoicePayment.getCurrencyID());
        }

        EdsAccount receivablePayableAccount = null;
        if (invoicePayment.getReceivablePayable() != null) {
            receivablePayableAccount = invoicePayment.getReceivablePayable();
        } else if (invoicePayment.getInvoice() != null && invoicePayment.getInvoice().getReceivablePayable() != null) {
            receivablePayableAccount = invoicePayment.getInvoice().getReceivablePayable();
        } else if (invoicePayment.getCreditNote() != null && invoicePayment.getCreditNote().getReceivablePayable() != null) {
            receivablePayableAccount = invoicePayment.getCreditNote().getReceivablePayable();
        }

        //if chosen account doesn't corresponding to the transaction currency then cancel the account
        if (receivablePayableAccount != null && !((invoicePayment.getInvoice() != null && invoicePayment.getInvoice().getReceivablePayable() != null && baseCurrency.equals(invoicePayment.getInvoice().getReceivablePayable().getCurrency()))
                || paymentCurrency.equals(receivablePayableAccount.getCurrency())
                || paymentCurrency.equals(baseCurrency))) {
            receivablePayableAccount = null;
        }

        //----------------------------------------------PAYABLE------------------------------------//
        if (inOutType.equals(PAYABLE)) {
            EdsTransactionItem transactionItem = new EdsTransactionItem();

            if (receivablePayableAccount != null) {
                transactionItem.setAccount(receivablePayableAccount);
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(systemAccountKey, paymentCurrency));
            }

            if (transactionItem.getAccount().isForeignAccount()) {
                if (invoicePayment.getForeignAccExRate() != null && invoicePayment.getCurrencyID().equals(baseCurrency.getObjectID())) {
                    transactionItem.setForeignCredit(invoicePayment.getAmount().multiply(invoicePayment.getForeignAccExRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else {
                    transactionItem.setForeignDebit(invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0 ? invoicePayment.getAmountInInvoiceCurrency() : invoicePayment.getAmount());
                }
            }
            transactionItem.setDebit(receivablePayable);
            transaction.addTransactionItem(transactionItem);

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(bankAmount).abs();
                if (paymentExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setDebit(variance);
                } else if (paymentExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setCredit(variance);
                }

                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }
            transactionItem = new EdsTransactionItem();
            EdsAccount paymentAccount = invoicePayment.getAccount();
            transactionItem.setAccount(paymentAccount);
            transactionItem.setCredit(bankAmount);

            if (transactionItem.getAccount().isForeignAccount()) {

                if (invoicePayment.getAppliedPayment() != null && !invoicePayment.getCurrencyID().equals(invoicePayment.getAppliedPayment().getCurrencyID())) {
                    transactionItem.setForeignCredit(bankAmount.multiply(invoicePayment.getAppliedPayment().getExchangeRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else if (invoicePayment.getForeignAccExRate() != null && invoicePayment.getCurrencyID().equals(baseCurrency.getObjectID())) {
                    transactionItem.setForeignCredit(bankAmount.multiply(invoicePayment.getForeignAccExRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else {
                    transactionItem.setForeignCredit(invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0
                            ? invoicePayment.getAmountInInvoiceCurrency()
                            : invoicePayment.getAmount());
                }
            }
            transaction.addTransactionItem(transactionItem);
            //--------------------------------------RECEIVABLE------------------------------------//
        } else if (inOutType.equals(RECEIVABLE)) {
            EdsTransactionItem transactionItem = new EdsTransactionItem();

            if (receivablePayableAccount != null) {
                transactionItem.setAccount(receivablePayableAccount);
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(systemAccountKey, paymentCurrency));
            }

            transactionItem.setCredit(receivablePayable);
            if (transactionItem.getAccount().isForeignAccount()) {
                if (invoicePayment.getForeignAccExRate() != null && invoicePayment.getCurrencyID().equals(baseCurrency.getObjectID())) {
                    transactionItem.setForeignCredit(invoicePayment.getAmount().multiply(invoicePayment.getForeignAccExRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else {
                    transactionItem.setForeignCredit(invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0 ?
                            invoicePayment.getAmountInInvoiceCurrency() : invoicePayment.getAmount());
                }
            }
            transaction.addTransactionItem(transactionItem);

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(bankAmount).abs();
                if (paymentExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setCredit(variance);
                } else if (paymentExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setDebit(variance);
                }
                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }

            transactionItem = new EdsTransactionItem();
            EdsAccount paymentAccount = invoicePayment.getAccount();
            transactionItem.setAccount(paymentAccount);
            transactionItem.setDebit(bankAmount);

            if (transactionItem.getAccount().isForeignAccount()) {

                if (invoicePayment.getAppliedPayment() != null && !invoicePayment.getCurrencyID().equals(invoicePayment.getAppliedPayment().getCurrencyID())) {
                    transactionItem.setForeignDebit(bankAmount.multiply(invoicePayment.getAppliedPayment().getExchangeRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else if (invoicePayment.getForeignAccExRate() != null && invoicePayment.getCurrencyID().equals(baseCurrency.getObjectID())) {
                    transactionItem.setForeignDebit(bankAmount.multiply(invoicePayment.getForeignAccExRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else {
                    transactionItem.setForeignDebit(invoicePayment.getAmountInInvoiceCurrency() != null && invoicePayment.getAmountInInvoiceCurrency().compareTo(BigDecimal.ZERO) != 0 ?
                            invoicePayment.getAmountInInvoiceCurrency() :
                            invoicePayment.getAmount().multiply(invoicePayment.getExchangeRate()));
                }
            }
            transaction.addTransactionItem(transactionItem);
        }
        transactionManager.createOrUpdate(transaction);
    }

    public void createTransactionForRefund(EdsInvoicePayment creditNoteRefund) {
        EdsUser user = accountingManager.getUser();

        String creditNoteType = creditNoteRefund.getCreditNote().getType(); //the type of credit note payable or receivable
        EdsInvoicePaymentTransaction transaction = new EdsInvoicePaymentTransaction();//get the transaction for this credit note
        transaction.setTargetTransaction(transactionManager.getTransactionByInvoice(creditNoteRefund.getCreditNote()));
        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
        transaction.setInvoicePayment(creditNoteRefund);
        transaction.setJournalDate(creditNoteRefund.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setName("Refund: " + creditNoteRefund.getCreditNote().getClientOrSupplier().getName());
        //----------------------------------------------PAYABLE------------------------------------//
        BigDecimal invoiceExchangeRate = creditNoteRefund.getCreditNote().getExchangeRate();
        BigDecimal paymentExchangeRate = creditNoteRefund.getExchangeRate();
        if (invoiceExchangeRate.compareTo(ZERO) == 0) {
            invoiceExchangeRate = new BigDecimal("1.00");
        }
        if (paymentExchangeRate.compareTo(ZERO) == 0) {
            paymentExchangeRate = new BigDecimal("1.00");
        }
        BigDecimal diff = paymentExchangeRate.subtract(invoiceExchangeRate).abs();
        BigDecimal bankAmount = creditNoteRefund.getAmount().divide(paymentExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        BigDecimal receivablePayable = creditNoteRefund.getAmount().divide(invoiceExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED) && creditNoteRefund.getCreditNote() != null;

        EdsAccount receivablePayableAccount = creditNoteRefund.getCreditNote().getReceivablePayable();

        if (creditNoteType.equals(PAYABLE)) {
            transaction.setSupplier(creditNoteRefund.getCreditNote().getClientOrSupplier());

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            if (isMultiCurrencyEnabled) {
                if (receivablePayableAccount != null) {
                    transactionItem.setAccount(receivablePayableAccount);
                } else {
                    transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, creditNoteRefund.getCreditNote().getCurrency()));
                }
                transactionItem.setCredit(receivablePayable);
                if (transactionItem.getAccount().isForeignAccount()) {
                    transactionItem.setForeignCredit(creditNoteRefund.getAmount());
                }
                transaction.addTransactionItem(transactionItem);
            } else {
                if (receivablePayableAccount != null) {
                    transactionItem.setAccount(receivablePayableAccount);
                } else {
                    transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_PAYABLE));
                }
                transactionItem.setCredit(receivablePayable);
                transaction.addTransactionItem(transactionItem);
            }

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(bankAmount).abs();
                if (paymentExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setCredit(variance);
                } else if (paymentExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setDebit(variance);
                }

                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }
            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(creditNoteRefund.getAccount());
            transactionItem.setDebit(bankAmount);
            if (transactionItem.getAccount().isForeignAccount()) {
                transactionItem.setForeignDebit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);
            //--------------------------------------RECEIVABLE------------------------------------//
        } else if (creditNoteType.equals(RECEIVABLE)) {
            transaction.setClient(creditNoteRefund.getCreditNote().getClientOrSupplier());

            EdsTransactionItem transactionItem = new EdsTransactionItem();

            if (isMultiCurrencyEnabled) {
                if (receivablePayableAccount != null) {
                    transactionItem.setAccount(receivablePayableAccount);
                } else {
                    transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_RECEIVABLE, creditNoteRefund.getCreditNote().getCurrency()));
                }
                transactionItem.setDebit(receivablePayable);
                if (transactionItem.getAccount().isForeignAccount()) {
                    transactionItem.setForeignDebit(creditNoteRefund.getAmount());
                }
                transaction.addTransactionItem(transactionItem);
            } else {
                if (receivablePayableAccount != null) {
                    transactionItem.setAccount(receivablePayableAccount);
                } else {
                    transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_RECEIVABLE));
                }
                transactionItem.setDebit(receivablePayable);
                transaction.addTransactionItem(transactionItem);
            }

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(bankAmount).abs();
                if (paymentExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setDebit(variance);
                } else if (paymentExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setCredit(variance);
                }

                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }

            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(creditNoteRefund.getAccount());
            transactionItem.setCredit(bankAmount);
            if (transactionItem.getAccount().isForeignAccount()) {
                transactionItem.setForeignCredit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);
        }
        transactionManager.create(transaction);
    }

    public void createTransactionForCreditedInvoice(EdsInvoicePayment creditNoteRefund) {
        EdsUser user = accountingManager.getUser();
        String creditNoteType = creditNoteRefund.getCreditNote().getType(); //the type of credit note payable or receivable
        EdsInvoicePaymentTransaction transaction = new EdsInvoicePaymentTransaction();//get the transaction for this credit note
        transaction.setTargetTransaction(transactionManager.getTransactionByInvoice(creditNoteRefund.getCreditNote()));
        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);

        transaction.setInvoicePayment(creditNoteRefund);
        transaction.setJournalDate(creditNoteRefund.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setName(creditNoteRefund.getCreditNote().getClientOrSupplier().getName());
        //----------------------------------------------PAYABLE------------------------------------//
        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();

        BigDecimal creditNoteExchangeRate = creditNoteRefund.getCreditNote().getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
        BigDecimal invoiceExchangeRate = creditNoteRefund.getInvoice().getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
        BigDecimal diff = creditNoteExchangeRate.subtract(invoiceExchangeRate).abs();

        BigDecimal receivablePayable = creditNoteRefund.getAmount().divide(creditNoteExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        BigDecimal invoiceAmount = creditNoteRefund.getAmount().divide(invoiceExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED);

        EdsAccount systemAccount;
        if (RECEIVABLE.equals(creditNoteType)) {
            transaction.setClient(creditNoteRefund.getCreditNote().getClientOrSupplier());
            if (isMultiCurrencyEnabled) {
                systemAccount = accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_RECEIVABLE, creditNoteRefund.getCreditNote().getCurrency());
            } else {
                systemAccount = accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_RECEIVABLE);
            }

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(systemAccount);
            transactionItem.setCredit(invoiceAmount);

            if (isMultiCurrencyEnabled && systemAccount.isForeignAccount()) {
                transactionItem.setForeignCredit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);

            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(systemAccount);
            transactionItem.setDebit(receivablePayable);

            if (isMultiCurrencyEnabled && systemAccount.isForeignAccount()) {
                transactionItem.setForeignDebit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(invoiceAmount).abs();

                if (creditNoteExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setCredit(variance);
                } else if (creditNoteExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setDebit(variance);
                }

                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }

        } else {
            transaction.setSupplier(creditNoteRefund.getCreditNote().getClientOrSupplier());
            if (isMultiCurrencyEnabled) {
                systemAccount = accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, creditNoteRefund.getCreditNote().getCurrency());
            } else {
                systemAccount = accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_PAYABLE);
            }

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(systemAccount);
            transactionItem.setDebit(invoiceAmount);

            if (isMultiCurrencyEnabled && systemAccount.isForeignAccount()) {
                transactionItem.setForeignDebit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);

            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(systemAccount);
            transactionItem.setCredit(receivablePayable);

            if (isMultiCurrencyEnabled && systemAccount.isForeignAccount()) {
                transactionItem.setForeignCredit(creditNoteRefund.getAmount());
            }
            transaction.addTransactionItem(transactionItem);

            if (diff.compareTo(BigDecimal.ZERO) > 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
                BigDecimal variance = receivablePayable.subtract(invoiceAmount).abs();

                if (creditNoteExchangeRate.compareTo(invoiceExchangeRate) < 0) {
                    transactionItem.setDebit(variance);
                } else if (creditNoteExchangeRate.compareTo(invoiceExchangeRate) > 0) {
                    transactionItem.setCredit(variance);
                }

                if (variance.compareTo(BigDecimal.ZERO) > 0) {
                    transaction.addTransactionItem(transactionItem);
                }
            }
        }

        transactionManager.create(transaction);
    }

    public Integer createTransactionsForCreditNote(EdsInvoice creditNote, Integer creditNoteInvoiceID) {
        EdsUser user = transactionManager.getUser();
        if (user == null) {
            user = creditNote.getCreator();
        }

        String creditNoteType = creditNote.getType(); //the type of credit note payable or receivable
        EdsInvoiceTransaction transaction = transactionManager.getTransactionByInvoice(creditNote);
        if (transaction != null) {
            itemStockManager.deleteItemStocksByTransaction(transaction.getObjectID());
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsInvoiceTransaction(); //creating new transaction
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(/*user.getCompany()*/null) + 1);
        }

        transaction.setInvoice(creditNote);//transaction belongs to credit note
        transaction.setJournalDate(creditNote.getInvoiceDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getUserDate());

        transactionManager.createOrUpdate(transaction);

        List<EdsInvoiceItem> creditNoteItems = creditNote.getInvoiceItems();
        Set<GenericSettingsEnum> genericSettingsEnums = genericSettingsManager.getEnabledGenericSettings();
        EdsWarehouse defaultWarehouse = warehouseManager.getDefaultWarehouse();
        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        Integer calculationScale = financialSettingsManager.getFinancialSettings().getAccountingCalculationScale();

        boolean isTaxAccountEnabled = genericSettingsEnums.contains(GenericSettingsEnum.TAX_ACCOUNT_ENABLED);

        //this list for the transaction items container
        List<EdsTransactionItem> transactionItemList = new ArrayList<>();

        EdsTransactionItem transactionItem = new EdsTransactionItem();
        //--------------------------------------RECEIVABLE------------------------------------//
        if (creditNoteType.equals(RECEIVABLE)) {
            EdsAccount systemTaxAccount = accountingManager.getVatAccount(RECEIVABLE);
            EdsSaleInvoice receivableCreditNote = (EdsSaleInvoice) creditNote;

            transaction.setName(receivableCreditNote.getClient().getName());
            transaction.setClient(receivableCreditNote.getClient());

            if (creditNote.getReceivablePayable() != null &&
                    (creditNote.getCurrency().equals(creditNote.getReceivablePayable().getCurrency())
                            || baseCurrency.equals(creditNote.getReceivablePayable().getCurrency()))) {
                transactionItem.setAccount(creditNote.getReceivablePayable());
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_RECEIVABLE, creditNote.getCurrency()));
            }
            if (creditNote.getTotal().compareTo(BigDecimal.ZERO) >= 0) {
                transactionItem.setCredit(creditNote.getTotal()); //accounts receivable always CREDIT when you add credit note
            } else {
                transactionItem.setDebit(creditNote.getTotal().abs()); //accounts receivable always DEBIT when you add credit note
            }
            if (transactionItem.getAccount().isForeignAccount()) {
                if (creditNote.getTotalInInvoiceCurrency().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setForeignCredit(creditNote.getTotalInInvoiceCurrency());
                } else {
                    transactionItem.setForeignDebit(creditNote.getTotalInInvoiceCurrency().abs());
                }
            }
            transactionItemList.add(transactionItem);

            //Other things Equity, Liability, Assets, Expenses are CREDIT
            int i = 0;
            EdsTransactionItem lastTransactionItem = null;
            for (EdsInvoiceItem credNoteItem : creditNoteItems) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(credNoteItem.getAccount());
                transactionItem.setDepartment(credNoteItem.getDepartment());
                transactionItem.setProject(credNoteItem.getProject());
                transactionItem.setDescription(credNoteItem.getDescription());

                if (TAX_CALCULATION_INCLUSIVE.equals(creditNote.getTaxCalculationType())) {
                    BigDecimal taxAmount = ZERO;
                    if (credNoteItem.getVat() != null) {
                        BigDecimal taxPercent = BigDecimal.valueOf(credNoteItem.getVat().getEffectiveTaxRate());
                        if (credNoteItem.getDoubleVat() != null) {
                            taxPercent = taxPercent.add(BigDecimal.valueOf(credNoteItem.getDoubleVat().getEffectiveTaxRate()));
                        }
                        taxAmount = credNoteItem.getNet().multiply(taxPercent).divide(HUNDRED.add(taxPercent), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    }
                    BigDecimal calculatedItemTotal = credNoteItem.getNet().subtract(taxAmount).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    System.out.println("Cal item total: " + calculatedItemTotal);
                    if (calculatedItemTotal.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setDebit(calculatedItemTotal);
                    } else {
                        transactionItem.setCredit(calculatedItemTotal.abs());
                    }
                } else {
                    BigDecimal netAmount = credNoteItem.getNet().setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    if (netAmount.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setDebit(netAmount);
                    } else {
                        transactionItem.setCredit(netAmount.abs());
                    }
                }
                transactionItemList.add(transactionItem);

                if (i == creditNoteItems.size() - 1) {
                    lastTransactionItem = transactionItem;
                }

                if (credNoteItem.getWarehouse() == null) {
                    credNoteItem.setWarehouse(defaultWarehouse);
                }
                cogsServices.getService().applyReturnedItemsToStock(credNoteItem, transaction);
                i++;
            }
            baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_CUSTOMER_CREDIT_NOTE_TRANSACTION, creditNote, user);

            if (creditNote.getTotalTaxes() != null && creditNote.getTotalTaxes().compareTo(ZERO) != 0) {
                if (isTaxAccountEnabled) {
                    List<EdsInvoiceItem> edsCNItemList = creditNote.getInvoiceItems();
                    for (EdsInvoiceItem edsCNItem : edsCNItemList) {
                        if (edsCNItem.getVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsCNItem.getVat().calculateAccountTaxes(edsCNItem.getNet(), creditNote.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                                } else {
                                    transactionItem.setCredit(calculatedTax.abs());//liability is also a CREDIT in this case
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }
                        if (edsCNItem.getDoubleVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsCNItem.getDoubleVat().calculateAccountTaxes(edsCNItem.getNet(), creditNote.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                                } else {
                                    transactionItem.setCredit(calculatedTax.abs());//liability is also a CREDIT in this case
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }
                    }
                } else {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(systemTaxAccount);
                    if (creditNote.getTotalTaxes().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setDebit(creditNote.getTotalTaxes());//liability is also a DEBIT in this case
                    } else {
                        transactionItem.setCredit(creditNote.getTotalTaxes().abs());//liability is also a CREDIT in this case
                    }
                    transactionItemList.add(transactionItem);
                }
            }

            if (lastTransactionItem != null) {
                BigDecimal credDebDifference = transaction.getDebitCreditDiff(PAYABLE, transactionItemList);
                System.out.println("Diff: " + credDebDifference);
                if (lastTransactionItem.getDebit() != null) {
                    lastTransactionItem.setDebit(lastTransactionItem.getDebit().add(credDebDifference));
                } else if (lastTransactionItem.getCredit() != null) {
                    lastTransactionItem.setCredit(lastTransactionItem.getCredit().subtract(credDebDifference));
                }
            }
            //----------------------------------------------PAYABLE------------------------------------//
        } else if (creditNoteType.equals(PAYABLE)) {
            boolean isReverseCharge = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE)
                    && (creditNote.getClientOrSupplier() != null && creditNote.getClientOrSupplier().isReverseChargeApplicable() || creditNote.isReverseChargeApplicable());

            EdsAccount systemTaxAccount = accountingManager.getVatAccount(PAYABLE);
            EdsPurchaseInvoice payableCreditNote = (EdsPurchaseInvoice) creditNote;

            transaction.setName(payableCreditNote.getSupplier().getName());
            transaction.setSupplier(payableCreditNote.getSupplier());

            if (creditNote.getReceivablePayable() != null &&
                    (creditNote.getCurrency().equals(creditNote.getReceivablePayable().getCurrency())
                            || baseCurrency.equals(creditNote.getReceivablePayable().getCurrency()))) {
                transactionItem.setAccount(creditNote.getReceivablePayable());
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, creditNote.getCurrency()));
            }
            if (creditNote.getTotal().compareTo(BigDecimal.ZERO) >= 0) {
                transactionItem.setDebit(creditNote.getTotal()); //accounts payable are always DEBIT when you add invoice
            } else {
                transactionItem.setCredit(creditNote.getTotal().abs()); //accounts payable are always CREDIT when you add invoice negative
            }
            if (transactionItem.getAccount().isForeignAccount()) {
                if (creditNote.getTotalInInvoiceCurrency().compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setForeignDebit(creditNote.getTotalInInvoiceCurrency());
                } else {
                    transactionItem.setForeignCredit(creditNote.getTotalInInvoiceCurrency().abs());
                }
            }
            transactionItemList.add(transactionItem);

            //Other things Equity, Liability, Assets, Expenses are DEBIT

            int i = 0;
            EdsTransactionItem lastTransactionItem = null;
            for (EdsInvoiceItem credNoteItem : creditNoteItems) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(credNoteItem.getAccount());
                transactionItem.setDepartment(credNoteItem.getDepartment());
                transactionItem.setProject(credNoteItem.getProject());

                if (TAX_CALCULATION_INCLUSIVE.equals(creditNote.getTaxCalculationType())) {
                    BigDecimal taxAmount = ZERO;

                    if (credNoteItem.getVat() != null) {
                        BigDecimal taxPercent = BigDecimal.valueOf(credNoteItem.getVat().getEffectiveTaxRate());
                        if (credNoteItem.getDoubleVat() != null) {
                            taxPercent = taxPercent.add(BigDecimal.valueOf(credNoteItem.getDoubleVat().getEffectiveTaxRate()));
                        }
                        taxAmount = credNoteItem.getNet().multiply(taxPercent).divide(HUNDRED.add(taxPercent), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    }
                    BigDecimal calculatedItemTotal = credNoteItem.getNet().subtract(taxAmount).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                    if (calculatedItemTotal.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(calculatedItemTotal);
                    } else {
                        transactionItem.setDebit(calculatedItemTotal.abs());
                    }
                } else {
                    BigDecimal netAmount = credNoteItem.getNet().setScale(calculationScale, RoundingMode.HALF_UP);

                    if (netAmount.compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(netAmount);
                    } else {
                        transactionItem.setDebit(netAmount.abs());
                    }
                }

                transactionItemList.add(transactionItem);

                if (i == creditNoteItems.size() - 1) {
                    lastTransactionItem = transactionItem;
                }
                if (credNoteItem.getWarehouse() == null) {
                    credNoteItem.setWarehouse(defaultWarehouse);
                }
                EdsItem item = credNoteItem.getItem();

                if (item != null && (INVENTORY_ITEM.equals(item.getType()) || ASSEMBLY_ITEM.equals(item.getType()))) {
                    transactionItem.setAccount(item.getCogsAccount());
                }
                i++;
            }
            baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_SUPPLIER_CREDIT_NOTE_TRANSACTION, creditNote, user);

            if (creditNote.getTotalTaxes().compareTo(ZERO) != 0) {
                if (isTaxAccountEnabled) {
                    List<EdsInvoiceItem> edsCNItemList = creditNote.getInvoiceItems();
                    for (EdsInvoiceItem edsCNItem : edsCNItemList) {
                        if (edsCNItem.getVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsCNItem.getVat().calculateAccountTaxes(edsCNItem.getNet(), creditNote.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);

                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setCredit(calculatedTax);//liability is also a CREDIT in this case
                                } else {
                                    transactionItem.setDebit(calculatedTax.abs());//liability is also a DEBIT in this case
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }

                        if (edsCNItem.getDoubleVat() != null) {
                            HashMap<Integer, BigDecimal> accountTaxesMap = edsCNItem.getDoubleVat().calculateAccountTaxes(edsCNItem.getNet(), creditNote.getTaxCalculationType());
                            for (Integer accountKey : accountTaxesMap.keySet()) {
                                BigDecimal calculatedTax = accountTaxesMap.get(accountKey);

                                transactionItem = new EdsTransactionItem();
                                transactionItem.setAccount(accountKey > 0
                                        ? accountingManager.get(accountKey)
                                        : systemTaxAccount);
                                if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                    transactionItem.setCredit(calculatedTax);//liability is also a CREDIT in this case
                                } else {
                                    transactionItem.setDebit(calculatedTax.abs());//liability is also a DEBIT in this case
                                }
                                transactionItemList.add(transactionItem);
                            }
                        }
                    }
                } else {
                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(systemTaxAccount);

                    if (creditNote.getTotalTaxes().compareTo(BigDecimal.ZERO) >= 0) {
                        transactionItem.setCredit(creditNote.getTotalTaxes());//liability is also a CREDIT in this case
                    } else {
                        transactionItem.setDebit(creditNote.getTotalTaxes().abs());//liability is also a DEBIT in this case
                    }
                    transactionItemList.add(transactionItem);

                    /*
                     * REVERSE CHARGE MODE
                     */
                    {
                        if (isReverseCharge) {
                            EdsTransactionItem outTaxItem = new EdsTransactionItem();
                            outTaxItem.setAccount(accountingManager.getVatAccount(RECEIVABLE));

                            if (creditNote.getTotalTaxes().compareTo(BigDecimal.ZERO) >= 0) {
                                outTaxItem.setDebit(creditNote.getTotalTaxes());//liability is also a DEBIT in this case
                            } else {
                                outTaxItem.setCredit(creditNote.getTotalTaxes());//liability is also a CREDIT in this case
                            }
                            transactionItemList.add(outTaxItem);
                        }
                    }
                }
            }
            if (lastTransactionItem != null) {
                BigDecimal debCredDifference = transaction.getDebitCreditDiff(RECEIVABLE, transactionItemList);
                if (debCredDifference.compareTo(BigDecimal.ZERO) != 0) {
                    if (lastTransactionItem.getCredit() != null) {
                        lastTransactionItem.setCredit(lastTransactionItem.getCredit().add(debCredDifference));
                    } else if (lastTransactionItem.getDebit() != null) {
                        lastTransactionItem.setDebit(lastTransactionItem.getDebit().subtract(debCredDifference));
                    }
                }
            }
        }

        if (!transactionItemList.isEmpty()) {
            for (EdsTransactionItem ti : transactionItemList) {
                ti.setTransaction(transaction);
            }
        }
        transaction.getTransactionItems().addAll(transactionItemList);
        transactionManager.update(transaction);
        return transaction.getObjectID();
    }

    public void createTransactionForPaymentRefundCloseAmount(EdsPaymentRefund paymentRefund, BigDecimal closedAmount, SelectItem account, PaymentData[] payments) {
        EdsUser user = accountingManager.getUser();
        if (user == null) {
            user = paymentRefund.getUser();
        }

        EdsPaymentRefundTransaction transaction = new EdsPaymentRefundTransaction();
        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);

        transaction.setPaymentRefund(paymentRefund);
        transaction.setJournalDate(paymentRefund.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setReference(paymentRefund.getReference());

        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();

        String inOutType = RECEIVABLE.equals(paymentRefund.getType()) ? PAYABLE : PAYABLE.equals(paymentRefund.getType()) ? RECEIVABLE : null;
        Integer systemAccountKey = RECEIVABLE.equals(paymentRefund.getType()) ? EdsAccount.ACCOUNTS_RECEIVABLE : PAYABLE.equals(paymentRefund.getType()) ? EdsAccount.ACCOUNTS_PAYABLE : null;

        BigDecimal paymentExchangeRate = paymentRefund.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
        if (RECEIVABLE.equals(paymentRefund.getType()) || PAYABLE.equals(paymentRefund.getType())) {
            if (RECEIVABLE.equals(paymentRefund.getType())) {
                transaction.setName("Customer Refund: " + paymentRefund.getCrmAccount().getName() + (paymentRefund.getNumber() != null
                        ? " | " + paymentRefund.getNumber()
                        : ""));
                transaction.setClient(paymentRefund.getCrmAccount());
            } else {
                transaction.setName("Supplier Refund: " + paymentRefund.getCrmAccount().getName() + (paymentRefund.getNumber() != null
                        ? " | " + paymentRefund.getNumber()
                        : ""));
                transaction.setSupplier(paymentRefund.getCrmAccount());
            }
        }

        if (paymentExchangeRate.compareTo(ZERO) == 0) {
            paymentExchangeRate = new BigDecimal("1.00");
        }

        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED) && paymentRefund.getCurrencyID() != null;

        //----------------------------------------------PAYABLE------------------------------------//
        if (inOutType.equals(PAYABLE)) {
            for (PaymentData payment : payments) {
                if (payment.getClosedAmount() != null && payment.isClosePrepayment() && payment.getPrepaymentID() != null) {
                    EdsInvoicePayment prepayment = invoicePaymentManager.get(payment.getPrepaymentID());
                    if (prepayment != null) {
                        EdsTransactionItem transactionItem = new EdsTransactionItem();
                        BigDecimal paymentRefundExchangeRate = paymentRefund.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                        BigDecimal receivablePayable = payment.getClosedAmount().multiply(paymentRefundExchangeRate);
                        transactionItem.setDebit(receivablePayable);
                        if (prepayment.getReceivablePayable() != null) {
                            transactionItem.setAccount(prepayment.getReceivablePayable());
                        } else {
                            if (isMultiCurrencyEnabled) {
                                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(systemAccountKey, currencyManager.get(paymentRefund.getCurrencyID())));

                                transactionItem.setDebit(receivablePayable);
                                if (transactionItem.getAccount().isForeignAccount()) {
                                    transactionItem.setForeignDebit(closedAmount);
                                }
                            } else {
                                transactionItem.setAccount(accountingManager.getAccountByKey(systemAccountKey));
                            }
                        }
                        transaction.addTransactionItem(transactionItem);
                    }
                }
            }

            BigDecimal paymentRefundExchangeRate = paymentRefund.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            EdsAccount paymentAccount = accountingManager.get(account.getId());
            if (isMultiCurrencyEnabled) {
                transactionItem.setAccount(paymentAccount);
                transactionItem.setCredit(closedAmount.multiply(paymentRefundExchangeRate));

                if (transactionItem.getAccount().isForeignAccount()) {
                    transactionItem.setForeignCredit(closedAmount);
                }
                transaction.addTransactionItem(transactionItem);
            } else {
                transactionItem.setAccount(paymentAccount);
                transactionItem.setCredit(closedAmount.multiply(paymentRefundExchangeRate));
                transaction.addTransactionItem(transactionItem);
            }
            //--------------------------------------RECEIVABLE------------------------------------//
        } else if (inOutType.equals(RECEIVABLE)) {
            for (PaymentData payment : payments) {
                if (payment.getClosedAmount() != null && payment.isClosePrepayment() && payment.getPrepaymentID() != null) {
                    EdsInvoicePayment prepayment = invoicePaymentManager.get(payment.getPrepaymentID());
                    if (prepayment != null) {
                        EdsTransactionItem transactionItem = new EdsTransactionItem();
                        BigDecimal paymentRefundExchangeRate = paymentRefund.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
                        BigDecimal receivablePayable = payment.getClosedAmount().multiply(paymentRefundExchangeRate);
                        transactionItem.setCredit(receivablePayable);
                        if (prepayment.getReceivablePayable() != null) {
                            transactionItem.setAccount(prepayment.getReceivablePayable());
                        } else {
                            if (isMultiCurrencyEnabled) {
                                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(systemAccountKey, currencyManager.get(paymentRefund.getCurrencyID())));

                                transactionItem.setCredit(receivablePayable);
                                if (transactionItem.getAccount().isForeignAccount()) {
                                    transactionItem.setForeignCredit(closedAmount);
                                }
                            } else {
                                transactionItem.setAccount(accountingManager.getAccountByKey(systemAccountKey));
                            }
                        }
                        transaction.addTransactionItem(transactionItem);
                    }
                }
            }

            BigDecimal paymentRefundExchangeRate = paymentRefund.getExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP);
            BigDecimal receivablePayable = closedAmount.multiply(paymentRefundExchangeRate);

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            EdsAccount paymentAccount = accountingManager.get(account.getId());
            if (isMultiCurrencyEnabled) {
                transactionItem.setAccount(paymentAccount);
                transactionItem.setDebit(receivablePayable);

                if (transactionItem.getAccount().isForeignAccount()) {
                    transactionItem.setForeignDebit(closedAmount);
                }
                transaction.addTransactionItem(transactionItem);
            } else {
                transactionItem.setAccount(paymentAccount);
                transactionItem.setDebit(receivablePayable);
                transaction.addTransactionItem(transactionItem);
            }
        }
        transactionManager.createOrUpdate(transaction);
    }

