            if (invoicePayment.getInvoice() != null | invoicePayment.getCreditNote() != null) {
                transaction.setTargetTransaction(transactionManager.getTransactionByInvoice(invoicePayment.getInvoice() != null
                        ? invoicePayment.getInvoice()
                        : invoicePayment.getCreditNote()));
            }
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
