    public void createOrUpdateTransactionForExpense(EdsExpenseReport expenseReport) {
        EdsUser user = accountingManager.getUser();
        boolean isCurrencyDiff = expenseReport.getCurrency() != null && expenseReport.getBaseCurrency() != null && !expenseReport.getCurrency().getObjectID().equals(expenseReport.getBaseCurrency().getObjectID()) && expenseReport.getExchangeRate() != null;
        boolean isReverseCharge = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE) && expenseReport.isReverseChargeApplicable();

        EdsExpenseTransaction transaction = transactionManager.getTransactionByExpense(expenseReport);
        if (transaction == null) {
            transaction = new EdsExpenseTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
            transaction.setExpenseReport(expenseReport);
        } else {
            transactionManager.deleteTransactionItems(transaction.getObjectID());
            transaction.setDeleted(false);
        }
        transaction.setJournalDate(expenseReport.getStartDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getUserDate());
        transaction.setName(expenseReport.getCurrentApprover() != null && expenseReport.getCurrentApprover().getExactEmployee() != null
                ? expenseReport.getCurrentApprover().getExactEmployee().getFullName()
                : null);//maybe different name
        transaction.setSupplier(expenseReport.getSupplier());

        transactionManager.createOrUpdate(transaction);

        List<EdsTransactionItem> transactionItemList = new ArrayList<>();
        EdsTransactionItem transactionItem = new EdsTransactionItem();
        EdsAccount expenseClaim = accountingManager.getAccountByKey(EdsAccount.UNPAID_EXPENSE_CLAIMS);
        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();

        if (expenseReport.getSupplier() != null && expenseReport.getSupplier().getObjectID() != null) {
            if (expenseReport.getPayableAccount() != null &&
                    (expenseReport.getCurrency().equals(expenseReport.getPayableAccount().getCurrency())
                            || (expenseReport.getPayableAccount() != null && baseCurrency.equals(expenseReport.getPayableAccount().getCurrency())))) {

                transactionItem.setAccount(expenseReport.getPayableAccount());
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, expenseReport.getCurrency()));
            }
        } else {
            transactionItem.setAccount(expenseClaim);
        }
        transactionItem.setDescription(expenseReport.getDescription());
        transactionItem.setCredit(expenseReport.getBaseTotal()); //accounts payable are always CREDIT when you add invoice
        if (isCurrencyDiff) {
            transactionItem.setForeignCredit(expenseReport.getTotal());
        }
        transactionItemList.add(transactionItem);

        //Employee Expense with suppier
        if (!expenseReport.isCompanyExpense() && expenseReport.getSupplier() != null) {
            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.UNPAID_EXPENSE_CLAIMS, expenseReport.getCurrency()));
            transactionItem.setDescription(expenseReport.getDescription());
            transactionItem.setCredit(expenseReport.getBaseTotal());
            if (isCurrencyDiff) {
                transactionItem.setForeignCredit(expenseReport.getTotal());
            }
            transactionItemList.add(transactionItem);


            transactionItem = new EdsTransactionItem();
//            transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, expenseReport.getCurrency()));
            transactionItem.setAccount(transactionItemList.get(0).getAccount());
            transactionItem.setDescription(expenseReport.getDescription());
            transactionItem.setDebit(expenseReport.getBaseTotal());
            if (isCurrencyDiff) {
                transactionItem.setForeignDebit(expenseReport.getTotal());
            }
            transactionItemList.add(transactionItem);
        }

        boolean isPurchaseOrderRelated = expenseReport.getPurchaseOrder() != null;
        EdsAccount landedCostAccount = accountingManager.getAccountByKey(EdsAccount.LANDED_COST);
        StringBuilder reference = new StringBuilder();

        BigDecimal totalTaxes = ZERO;

        EdsTransactionItem lastTransactionItem = null;
        //Other things Equity, Liability, Assets, Expenses are DEBIT
        for (EdsExpense expenseItem : expenseReport.getExpenses()) {
            transactionItem = new EdsTransactionItem();
            transactionItem.setDescription(expenseItem.getDescription());
            transactionItem.setDepartment(expenseItem.getDepartment());
            transactionItem.setProject(expenseItem.getProject());
            transactionItem.setItemId(expenseItem.getObjectID());

            if (isPurchaseOrderRelated || expenseItem.isAllocatedToPO()) {
                transactionItem.setAccount(landedCostAccount);
                reference.append((!reference.isEmpty() ? ", " : "") + expenseItem.getAccount().getName());
            } else {
                transactionItem.setAccount(expenseItem.getAccount());
            }
            if (TAX_CALCULATION_INCLUSIVE.equals(expenseReport.getTaxCalculationType())) {
                if (expenseItem.getTax() != null && expenseItem.getTax().getEffectiveRateAsBigDecimal().compareTo(ZERO) >= 0) {
                    totalTaxes = totalTaxes.add(expenseItem.getTaxAmountInBase(false));
                    transactionItem.setDebit(expenseItem.getNetAmountInBase().subtract(expenseItem.getTaxAmountInBase(false)).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else if (expenseItem.getDoubleTax() != null && expenseItem.getDoubleTax().getEffectiveRateAsBigDecimal().compareTo(ZERO) >= 0) {
                    totalTaxes = totalTaxes.add(expenseItem.getTaxAmountInBase(true));
                    transactionItem.setDebit(expenseItem.getNetAmountInBase().subtract(expenseItem.getTaxAmountInBase(true)).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                } else {
                    transactionItem.setDebit(expenseItem.getNetAmountInBase());
                }
            } else {
                if (expenseItem.getTax() != null && expenseItem.getTax().getEffectiveRateAsBigDecimal().compareTo(ZERO) >= 0) {
                    totalTaxes = totalTaxes.add(expenseItem.getTaxAmountInBase(false));
                }
                if (expenseItem.getDoubleTax() != null && expenseItem.getDoubleTax().getEffectiveRateAsBigDecimal().compareTo(ZERO) >= 0) {
                    totalTaxes = totalTaxes.add(expenseItem.getTaxAmountInBase(true));
                }
                transactionItem.setDebit(expenseItem.getNetAmountInBase());
            }
            if (isCurrencyDiff) {
                transactionItem.setForeignDebit(transactionItem.getDebit().multiply(expenseReport.getExchangeRate()));
            }
            lastTransactionItem = transactionItem;
            transactionItemList.add(transactionItem);
        }
        if (totalTaxes.compareTo(ZERO) != 0) {
            EdsAccount systemTaxAccount = accountingManager.getVatAccount(PAYABLE);
            boolean isTaxAccountEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.TAX_ACCOUNT_ENABLED);

            if (isTaxAccountEnabled) {
                List<EdsExpense> edsExpenseItemList = expenseReport.getExpenses();
                for (EdsExpense edsExpenseItem : edsExpenseItemList) {
                    if (edsExpenseItem.getTax() != null) {
                        HashMap<Integer, BigDecimal> accountTaxesMap = edsExpenseItem.getTax().calculateAccountTaxes(edsExpenseItem.getUnits().multiply(edsExpenseItem.getCostPerUnit()), expenseReport.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                            calculatedTax = calculatedTax.divide(expenseReport.getExchangeRate(), ServerUtils.getCalculationScale(), RoundingMode.HALF_UP);

                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                            if (isCurrencyDiff) {
                                transactionItem.setForeignDebit(transactionItem.getDebit().multiply(expenseReport.getExchangeRate()));
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                    if (edsExpenseItem.getDoubleTax() != null) {
                        HashMap<Integer, BigDecimal> accountTaxesMap = edsExpenseItem.getDoubleTax().calculateAccountTaxes(edsExpenseItem.getUnits().multiply(edsExpenseItem.getCostPerUnit()), expenseReport.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);
                            calculatedTax = calculatedTax.divide(expenseReport.getExchangeRate(), ServerUtils.getCalculationScale(), RoundingMode.HALF_UP);

                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                            if (isCurrencyDiff) {
                                transactionItem.setForeignDebit(transactionItem.getDebit().multiply(expenseReport.getExchangeRate()));
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                }
            } else {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(systemTaxAccount);
                transactionItem.setDebit(totalTaxes);//liability is also a DEBIT in this case

                if (isCurrencyDiff) {
                    transactionItem.setForeignDebit(transactionItem.getDebit().multiply(expenseReport.getExchangeRate()));
                }
                transactionItemList.add(transactionItem);

                /*
                 * REVERSE CHARGE MODE
                 */
                {
                    if (isReverseCharge) {
                        EdsTransactionItem outTaxItem = new EdsTransactionItem();
                        outTaxItem.setAccount(accountingManager.getVatAccount(RECEIVABLE));

                        if (totalTaxes.compareTo(BigDecimal.ZERO) >= 0) {
                            outTaxItem.setCredit(totalTaxes);
                        } else {
                            outTaxItem.setDebit(totalTaxes.abs());
                        }
                        transactionItemList.add(outTaxItem);
                    }
                }
            }
        }

        if (lastTransactionItem != null) {
            BigDecimal credDebDifference = transaction.getDebitCreditDiff(PAYABLE, transactionItemList);
            if (credDebDifference.compareTo(BigDecimal.ZERO) != 0) {
                if (lastTransactionItem.getDebit() != null) {
                    lastTransactionItem.setDebit(lastTransactionItem.getDebit().add(credDebDifference));
                } else if (lastTransactionItem.getCredit() != null) {
                    lastTransactionItem.setCredit(lastTransactionItem.getCredit().subtract(credDebDifference));
                }
            }
        }

        //set transaction item list to transaction
        if (!transactionItemList.isEmpty()) {
            for (EdsTransactionItem ti : transactionItemList) {
                ti.setTransaction(transaction);
            }
        }
        transaction.getTransactionItems().addAll(transactionItemList);

        transactionManager.update(transaction);
    }

    public Integer voidExpenseTransaction(Integer expenseReportId, DateNonConvertable voidDate) {
        EdsExpenseReport expenseReport = expenseReportManager.get(expenseReportId);

        EdsUser user = accountingManager.getUser();
        Integer transactionID = null;
        //clear all expense payment transaction if it has;
        List<EdsExpensePayment> expensePayments = expensePaymentManager.getPayments(expenseReport);
        if (expensePayments != null && !expensePayments.isEmpty()) {
            for (EdsExpensePayment expensePayment : expensePayments) {
                voidExpensePaymentTransaction(expensePayment, voidDate);
            }
        }

        EdsExpenseTransaction expTransaction = transactionManager.getTransactionByExpense(expenseReport);
        if (expTransaction != null) {
            EdsExpenseTransaction transaction = new EdsExpenseTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
            transaction.setExpenseReport(expenseReport);
            transaction.setJournalDate((voidDate != null && voidDate.getNonConvertedDate() != null)
                    ? voidDate.getNonConvertedDate()
                    : expenseReport.getStartDate());
            transaction.setPostedBy(user);
            transaction.setPostedDate(user.getUserDate());
            transaction.setName(expenseReport.getCurrentApprover() != null && expenseReport.getCurrentApprover().getExactEmployee() != null
                    ? expenseReport.getCurrentApprover().getExactEmployee().getFullName()
                    : null);//maybe different name
            transaction.setReversalTransaction(expTransaction);
            transaction.setClient(expTransaction.getClient());
            transaction.setSupplier(expTransaction.getSupplier());


            if (expTransaction.getTransactionItems() != null && !expTransaction.getTransactionItems().isEmpty()) {
                EdsTransactionItem item;
                for (EdsTransactionItem invTransItem : expTransaction.getTransactionItems()) {
                    item = new EdsTransactionItem();
                    item.setAccount(invTransItem.getAccount());
                    item.setDepartment(invTransItem.getDepartment());
                    item.setProject(invTransItem.getProject());
                    item.setDebit(invTransItem.getCredit());
                    item.setCredit(invTransItem.getDebit());
                    item.setItemId(invTransItem.getItemId());
                    item.setForeignDebit(invTransItem.getForeignCredit());
                    item.setForeignCredit(invTransItem.getForeignDebit());
                    item.setCrmAccount(invTransItem.getCrmAccount());
                    transaction.addTransactionItem(item);
                }
            }
            transactionManager.create(transaction);

            expenseReport.setEntityStatus(referenceManager.findReference(EXPENSE_STATUS, EXPENSE_REVERSED));
            transactionID = transaction.getObjectID();
        } else {
            expenseReport.setEntityStatus(referenceManager.findReference(EXPENSE_STATUS, EXPENSE_REVERSED));
        }
        expenseReport.setLastUpdateTime(new Date());

        for (EdsExpense expense : expenseReport.getExpenses()) {
            expenseManager.removeRelatedTimesheetsFromExpense(expense.getObjectID());
        }

        if (expenseReport.getProject() != null || genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.PROJECT_IN_LINE_ITEM_ENABLE)) {
            EdsBusinessEvent e = baseEventPostProcessor.registerEvent(ProjectBudgetCustomEventListenerImpl.TYPE, ProjectBudgetCustomEventListenerImpl.EXPENSE_REPORT_DECLINE, expenseReport, expenseReportManager.getUser());
            e.setCustomStringField(expenseReport.getProject() != null
                    ? expenseReport.getProject().getObjectID().toString()
                    : "");
        }

        try {
            solrManager.addExpenseReportToIndex(expenseReport);
        } catch (SolrServerException | IOException e) {
            e.printStackTrace();
        }

        baseEventPostProcessor.registerEvent(ExpenseReportEventListenerImpl.TYPE, ExpenseReportEventListenerImpl.EVENT_EXPENSE_REPORT_VOID, expenseReport, employeeManager.getUser());


        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsExpense.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.DELETE);
        kpiLog.setEntityId(expenseReportId);
        ServerUtils.kpiLog(log, kpiLog, "Delete expense claim");
        return transactionID != null ? transactionID : -1;
    }

    public void createTransactionForExpencePayment(EdsExpensePayment payment) {
        EdsUser user = accountingManager.getUser();
        EdsExpensePaymentTransaction transaction = new EdsExpensePaymentTransaction();//get the transaction for this invoice
        transaction.setTargetTransaction(transactionManager.getTransactionByExpense(payment.getExpenseReport()));
        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
        transaction.setExpensePayment(payment);
        transaction.getExpensePayment().setObjectID(payment.getObjectID());
        transaction.setJournalDate(payment.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setSupplier(payment.getSupplier());

        EdsExpenseReport expenseReport = payment.getExpenseReport();
        BigDecimal paymentExchangeRate = payment.getExchangeRate() != null && payment.getExchangeRate().compareTo(ZERO) != 0
                ? payment.getExchangeRate()
                : ONE;
        BigDecimal expenseReportExchangeRate;

        if (payment.getCurrencyID() != null && !payment.getCurrencyID().equals(expenseReport.getCurrency().getObjectID())) {
            expenseReportExchangeRate = paymentExchangeRate;
        } else {
            expenseReportExchangeRate = expenseReport.getExchangeRate();
        }
        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED);

        if (expenseReport != null && expenseReport.getReporter() != null) {
            transaction.setName("Payment: " + expenseReport.getReporter().getName());
        } else {
            transaction.setName("Payment: " + user.getName());
        }
        transaction.setReference(payment.getReference());
        BigDecimal diff = paymentExchangeRate.subtract(expenseReportExchangeRate).abs();
        BigDecimal paymentAtCurrentRate = payment.getAmount().divide(paymentExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        BigDecimal paymentAtExpenseReportRate = payment.getAmount().divide(expenseReportExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        EdsTransactionItem transactionItem;
        BigDecimal variance;
        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        Integer paymentCurrencyId = payment.getCurrencyID() != null
                ? payment.getCurrencyID()
                : baseCurrency.getObjectID();


        if (diff.compareTo(BigDecimal.ZERO) > 0) {
            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.EXCHANGE_VARIANCE));
            variance = paymentAtExpenseReportRate.subtract(paymentAtCurrentRate);
            if (paymentExchangeRate.compareTo(expenseReportExchangeRate) < 0) {
                transactionItem.setDebit(variance.abs());
            } else if (paymentExchangeRate.compareTo(expenseReportExchangeRate) > 0) {
                transactionItem.setCredit(variance.abs());
            }

            if (variance.abs().compareTo(BigDecimal.ZERO) > 0) {
                transaction.addTransactionItem(transactionItem);
            }
        }
        transactionItem = new EdsTransactionItem();
        if (expenseReport != null && (!expenseReport.isCompanyExpense() || (expenseReport.isCompanyExpense() && expenseReport.getSupplier() == null))) {
            transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.UNPAID_EXPENSE_CLAIMS));
        } else {
            if (expenseReport.getPayableAccount() != null &&
                    (paymentCurrencyId.equals(expenseReport.getPayableAccount().getCurrency().getObjectID())
                            || baseCurrency.equals(expenseReport.getPayableAccount().getCurrency()))) {
                transactionItem.setAccount(expenseReport.getPayableAccount());
            } else {
                transactionItem.setAccount(accountingManager.getMultiCurrencyAccount(EdsAccount.ACCOUNTS_PAYABLE, expenseReport.getCurrency()));
            }
        }
        transactionItem.setDebit(paymentAtExpenseReportRate);

        if (isMultiCurrencyEnabled && transactionItem.getAccount().isForeignAccount()) {
            transactionItem.setForeignDebit(payment.getAmountInEntityCurrency() != null
                    ? payment.getAmountInEntityCurrency()
                    : payment.getAmount());
        }
        transaction.addTransactionItem(transactionItem);

        transactionItem = new EdsTransactionItem();
        transactionItem.setAccount(payment.getAccount());
        transactionItem.setCredit(paymentAtCurrentRate);

        if (isMultiCurrencyEnabled) {
            transactionItem.setForeignCredit(payment.getAmount());
        }
        transaction.addTransactionItem(transactionItem);
        transactionManager.create(transaction);
    }

    public void voidExpensePaymentTransaction(EdsExpensePayment payment, DateNonConvertable voidDate) {
        EdsUser user = accountingManager.getUser();
        EdsExpensePaymentTransaction expTransaction = transactionManager.getTransactionByExpensePayment(payment);
        if (expTransaction != null) {
            EdsExpensePaymentTransaction transaction = new EdsExpensePaymentTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
            transaction.setExpensePayment(payment);
            transaction.setJournalDate((voidDate != null && voidDate.getNonConvertedDate() != null)
                    ? voidDate.getNonConvertedDate()
                    : payment.getPaymentDate());
            transaction.setPostedDate(user.getUserDate());
            transaction.setPostedBy(user);
            transaction.setName("Payment: " + (payment.getExpenseReport().getCurrentApprover().getExactEmployee() != null
                    ? payment.getExpenseReport().getCurrentApprover().getExactEmployee().getFullName()
                    : null));
            transaction.setReference(payment.getReference());
            transaction.setReversalTransaction(expTransaction);
            transaction.setClient(expTransaction.getClient());
            transaction.setSupplier(expTransaction.getSupplier());

            if (expTransaction.getTransactionItems() != null && !expTransaction.getTransactionItems().isEmpty()) {
                EdsTransactionItem item;
                for (EdsTransactionItem expTransItem : expTransaction.getTransactionItems()) {
                    item = new EdsTransactionItem();
                    item.setAccount(expTransItem.getAccount());
                    item.setDebit(expTransItem.getCredit());
                    item.setCredit(expTransItem.getDebit());
                    item.setForeignDebit(expTransItem.getForeignCredit());
                    item.setForeignCredit(expTransItem.getForeignDebit());
                    item.setCrmAccount(expTransItem.getCrmAccount());
                    transaction.addTransactionItem(item);
                }
            }
            transactionManager.create(transaction);
        }
    }

    /**
     * Creates transaction after inventory item is registered
     *
     * @param inventory created inventory
     * @return transaction to be created
     */
    public Integer createTransactionsForInventory(EdsItem inventory, EdsUser user) {

        EdsInventoryTransaction transaction = transactionManager.getTransactionByInventory(inventory);
        if (transaction != null) {
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsInventoryTransaction(); //creating new transaction
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        }

        transaction.setName(inventory.getName());
        transaction.setInventory(inventory);
        transaction.setJournalDate(inventory.getAsOf());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getUserDate());
        transaction.setTransactionType(TT_OPENING_BALANCE);

        transactionManager.createOrUpdate(transaction);

        Set<EdsTransactionItem> transactionItemList = new HashSet<>();

        EdsTransactionItem transactionItem = new EdsTransactionItem();

        //Debit by asset account
        transactionItem.setAccount(inventory.getAssetAccount());
        transactionItem.setDebit(inventory.getTotalValue());
        transactionItemList.add(transactionItem);

        //Credit by opening balance
        transactionItem = new EdsTransactionItem();
        transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.OPENING_BALANCE));
        transactionItem.setCredit(inventory.getTotalValue());
        transactionItemList.add(transactionItem);

        for (EdsTransactionItem ti : transactionItemList) {
            ti.setTransaction(transaction);
        }
        transaction.setTransactionItems(transactionItemList);

        transactionManager.update(transaction);

        return transaction.getObjectID();
    }

    @Override
    public Integer createTransactionsForGoodsReceived(EdsPurchaseOrder goodsReceived, EdsShippingData shippingData, HashMap<Integer, BigDecimal> oldAllocatedAmounts) {
        clear_old_grn_transactions:
        {
            final List<Integer> transactionIds = this.transactionManager.getTransactionIdsByShippingData(shippingData);
            if (!CollectionUtils.isEmpty(transactionIds)) {
                this.itemStockManager.deleteItemStocksByTransactionIds(transactionIds);
                transactionIds.forEach(tId -> transactionManager.deleteTransaction(tId));
            }
        }

        boolean isReverseCharge = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE) && (goodsReceived.getClientOrSupplier() != null && goodsReceived.getClientOrSupplier().isReverseChargeApplicable()
                || goodsReceived.isReverseChargeApplicable());
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        boolean isDiscountAccountEnabled = financialSettings.getEnableDiscountAccount();

        final EdsUser user = accountingManager.getUser();
        final EdsGoodsReceivedTransaction transaction = new EdsGoodsReceivedTransaction(); //creating new transaction

        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        transaction.setName(goodsReceived.getSupplier().getName());
        if (shippingData != null) {
            transaction.setJournalDate(shippingData.getShippingDate());
            transaction.setShippingData(shippingData);
        } else {
            transaction.setPurchaseOrder(goodsReceived);//transaction belongs to invoice
            transaction.setJournalDate(goodsReceived.getInvoiceDate());
        }
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getUserDate());
        transactionManager.createOrUpdate(transaction);
        //this list for the transaction items container
        final List<EdsTransactionItem> transactionItemList = new ArrayList<>();
        EdsTransactionItem transactionItem;
        List<EdsTransactionItem> expenseAllocationItems = new LinkedList<>();
        final boolean isMultiWarehouseEnabled = financialSettings.getEnableMultiWarehouse();
        EdsWarehouse defaultWarehouse = warehouseManager.getDefaultWarehouse();
        BigDecimal exchangeRate = (goodsReceived.getExchangeRate() != null && goodsReceived.getExchangeRate().compareTo(BigDecimal.ZERO) != 0)
                ? goodsReceived.getExchangeRate()
                : BigDecimal.ONE;
        BigDecimal taxAmountReceived = BigDecimal.ZERO;

        for (EdsShippingDataItem item : shippingData.getItems()) {
            EdsQuoteItem quoteItem = quoteItemManager.get(item.getQuoteItemId());
//            if (quoteItem.getReceive() == null || quoteItem.getReceive().compareTo(BigDecimal.ZERO) <= 0) {
//                continue;
//            }
            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(quoteItem.getAccount());
            transactionItem.setDepartment(quoteItem.getDepartment());
            transactionItem.setProject(quoteItem.getProject());
            transactionItem.setItemId(quoteItem.getObjectID());

            BigDecimal transactionValue = quoteItem.getNet();

            if (isDiscountAccountEnabled) {
                transactionValue = transactionValue.add(quoteItem.getItemCalculatedDiscountAmount().divide(exchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
            }

            if (ReceiveTypeEnum.RECEIVE_BY_VALUE.equals(item.getReceiveType()) && item.getReceivedAmount().compareTo(BigDecimal.ZERO) > 0) {
                transactionValue = item.getReceivedAmount().divide(exchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            } else {
                transactionValue = transactionValue.multiply(item.getReceivedQty()).divide(quoteItem.calculatedQty(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            }
            BigDecimal itemTaxAmountReceived;
            BigDecimal taxPercent = BigDecimal.ZERO;

            if (quoteItem.getVat() != null) {
                taxPercent = quoteItem.getVat().getEffectiveRateAsBigDecimal();
            }
            if (quoteItem.getDoubleVat() != null) {
                taxPercent = taxPercent.add(quoteItem.getDoubleVat().getEffectiveRateAsBigDecimal());
            }

            BigDecimal itemTotalTaxAmount = BigDecimal.ZERO;
            if (Objects.equals(goodsReceived.getTaxCalculationType(), TAX_CALCULATION_INCLUSIVE)) {
                itemTotalTaxAmount = quoteItem.getNet().multiply(taxPercent).divide(HUNDRED.add(taxPercent), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            } else if (!Objects.equals(goodsReceived.getTaxCalculationType(), NO_TAX_CALCULATION)) {
                itemTotalTaxAmount = quoteItem.getNet().multiply(taxPercent.divide(HUNDRED, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
            }

            if (ReceiveTypeEnum.RECEIVE_BY_VALUE.equals(item.getReceiveType())) {
                itemTaxAmountReceived = itemTotalTaxAmount.multiply(transactionValue).divide(quoteItem.getTaxAmount() != null
                        ? quoteItem.getNet().add(quoteItem.getTaxAmount().divide(exchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP))
                        : quoteItem.getNet(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            } else {
                itemTaxAmountReceived = itemTotalTaxAmount.multiply(item.getReceivedQty()).divide(quoteItem.calculatedQty(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
            }
            taxAmountReceived = taxAmountReceived.add(itemTaxAmountReceived);
            BigDecimal calculatedNet = transactionValue;

            {//EXPENSES
                if (goodsReceived.getTaxCalculationType() == null || TAX_CALCULATION_EXCLUSIVE.equals(goodsReceived.getTaxCalculationType())) {

                    if (isReverseCharge) {
                        transactionValue = transactionValue.add(itemTaxAmountReceived);
                    }
                } else if (!isReverseCharge) {
                    transactionValue = transactionValue.subtract(itemTaxAmountReceived);
                }
                if (quoteItem.getTaxAmount() != null && ReceiveTypeEnum.RECEIVE_BY_VALUE.equals(item.getReceiveType())) {
                    transactionValue = transactionValue.subtract(itemTaxAmountReceived);
                }

                //IMPORTANT: this one will use to asset cost
                quoteItem.setTransactionValue(transactionValue);

                if (transactionValue.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setDebit(transactionValue);
                } else {
                    transactionItem.setCredit(transactionValue.abs());
                }
                transactionItemList.add(transactionItem);
            }
            transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.PENDING_GOODS_RECEIVED_NOTES));

            {//PENDING GOODS

                if (goodsReceived.getTaxCalculationType() != null && TAX_CALCULATION_INCLUSIVE.equals(goodsReceived.getTaxCalculationType())) {
                    calculatedNet = calculatedNet.subtract(itemTaxAmountReceived);
                }
                if (quoteItem.getTaxAmount() != null && ReceiveTypeEnum.RECEIVE_BY_VALUE.equals(item.getReceiveType())) {
                    calculatedNet = calculatedNet.subtract(itemTaxAmountReceived);
                }

                if (calculatedNet.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(calculatedNet);
                } else {
                    transactionItem.setDebit(calculatedNet.abs());
                }
                transactionItemList.add(transactionItem);
            }

//            BigDecimal expenseAmountForReceive = quoteItem.calculateAllocationAmountForReceive(goodsReceived.getExpenseAllocationType());
            BigDecimal expenseAmountForReceive = item.getReceivedAllocation();
            if (expenseAmountForReceive.compareTo(ZERO) != 0) {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(quoteItem.getAccount());
                transactionItem.setProject(quoteItem.getProject());
                if (expenseAmountForReceive.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setDebit(expenseAmountForReceive);
                } else {
                    transactionItem.setCredit(expenseAmountForReceive.abs());
                }
                expenseAllocationItems.add(transactionItem);

                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.LANDED_COST));
                if (expenseAmountForReceive.compareTo(BigDecimal.ZERO) >= 0) {
                    transactionItem.setCredit(expenseAmountForReceive);
                } else {
                    transactionItem.setDebit(expenseAmountForReceive.abs());
                }
                expenseAllocationItems.add(transactionItem);
            }

            EdsItem esdItem = quoteItem.getItem();
            if (esdItem != null && Arrays.asList(INVENTORY_ITEM, ASSEMBLY_ITEM, PRODUCT_KIT).contains(esdItem.getType())) {

                if (!isMultiWarehouseEnabled) {
                    item.setWarehouseId(defaultWarehouse.getObjectID());
                    item.setWarehouse(defaultWarehouse);
                }

                //if there is a allocated expense then apply it recieved items
                if (item.getReceivedAllocation() != null) {
                    item.setTransactionValue(quoteItem.getTransactionValue().add(item.getReceivedAllocation()));
                }
                //goods received apply to item stock (this is by Normurod)
                applyPurchasesToItemStock(item, transaction);
            }
            BigDecimal oldAllocatedAmount = oldAllocatedAmounts != null && oldAllocatedAmounts.get(item.getObjectID()) != null ? oldAllocatedAmounts.get(item.getObjectID()) : BigDecimal.ZERO;
            quoteItem.setReceivedAllocation(quoteItem.getReceivedAllocation().subtract(oldAllocatedAmount).add(expenseAmountForReceive));
        }
        baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_GOODS_RECEIVED_NOTE_TRANSACTION, shippingData, user);

        if (isReverseCharge && taxAmountReceived.compareTo(ZERO) != 0) {
            boolean isTaxAccountEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.TAX_ACCOUNT_ENABLED);
            EdsAccount systemTaxAccount = accountingManager.getVatAccount(PAYABLE);

            if (isTaxAccountEnabled) {
                for (EdsQuoteItem edsQuoteItem : goodsReceived.getQuoteItems()) {
                    if (edsQuoteItem.getVat() != null) {
                        BigDecimal netShare = edsQuoteItem.getNet().multiply(edsQuoteItem.getReceive()).divide(edsQuoteItem.calculatedQty(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        HashMap<Integer, BigDecimal> accountTaxesMap = edsQuoteItem.getVat().calculateAccountTaxes(netShare, goodsReceived.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);

                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                transactionItem.setCredit(calculatedTax.abs());//liability is also a CREDIT in this case
                            } else {
                                transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                    if (edsQuoteItem.getDoubleVat() != null) {
                        BigDecimal netShare = edsQuoteItem.getNet().multiply(edsQuoteItem.getReceive()).divide(edsQuoteItem.calculatedQty(), ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        Map<Integer, BigDecimal> accountTaxesMap = edsQuoteItem.getDoubleVat().calculateAccountTaxes(netShare, goodsReceived.getTaxCalculationType());
                        for (Integer accountKey : accountTaxesMap.keySet()) {
                            BigDecimal calculatedTax = accountTaxesMap.get(accountKey);

                            transactionItem = new EdsTransactionItem();
                            transactionItem.setAccount(accountKey > 0
                                    ? accountingManager.get(accountKey)
                                    : systemTaxAccount);
                            if (calculatedTax.compareTo(BigDecimal.ZERO) >= 0) {
                                transactionItem.setCredit(calculatedTax.abs());//liability is also a CREDIT in this case
                            } else {
                                transactionItem.setDebit(calculatedTax);//liability is also a DEBIT in this case
                            }
                            transactionItemList.add(transactionItem);
                        }
                    }
                }
            } else {
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(systemTaxAccount);

                if (taxAmountReceived.compareTo(BigDecimal.ZERO) < 0) {
                    transactionItem.setDebit(taxAmountReceived.abs());//liability is also a DEBIT in this case
                } else {
                    transactionItem.setCredit(taxAmountReceived);//liability is also a CREDIT in this case
                }
                transactionItemList.add(transactionItem);
            }
        }
        if (!expenseAllocationItems.isEmpty()) {
            this.createExpenseAllocationTransactionItems(goodsReceived, shippingData, expenseAllocationItems, user);
        }
        //set transaction item list to transaction
        for (EdsTransactionItem ti : transactionItemList) {
            ti.setTransaction(transaction);
        }
        transaction.getTransactionItems().addAll(transactionItemList);
        transactionManager.update(transaction);

        return transaction.getObjectID();
    }

