    private void createExpenseAllocationTransactionItems(EdsPurchaseOrder goodsReceived,
                                                         EdsShippingData shippingData,
                                                         List<EdsTransactionItem> expenseAllocationItems,
                                                         EdsUser user) {
        EdsGoodsReceivedTransaction allocationTransaction = new EdsGoodsReceivedTransaction(); //creating new transaction
        allocationTransaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        allocationTransaction.setExpenseAllocation(true);
        allocationTransaction.setName(goodsReceived.getSupplier().getName());
        if (shippingData != null) {
            allocationTransaction.setShippingData(shippingData);
        } else {
            allocationTransaction.setPurchaseOrder(goodsReceived);
        }
        Date shippingDate = shippingData.getShippingDate();
        if (shippingDate != null) {
            allocationTransaction.setJournalDate(shippingDate);
        } else {
            allocationTransaction.setJournalDate(goodsReceived.getInvoiceDate());
        }
        allocationTransaction.setPostedBy(user);
        allocationTransaction.setPostedDate(user.getUserDate());
        allocationTransaction.getTransactionItems().addAll(expenseAllocationItems);
        transactionManager.create(allocationTransaction);
    }

    @Override
    public void createTransactionForStockTransfer(EdsStockTransfer stockTransfer) {
        EdsUser user = accountingManager.getUser();

        EdsStockTransferTransaction transaction = transactionManager.getTransactionByStockTransfer(stockTransfer);
        if (transaction != null) {
            itemStockManager.deleteItemStocksByTransaction(transaction.getObjectID());
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsStockTransferTransaction(); //creating new transaction
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        }

        transaction.setName("Stock Transfer: " + stockTransfer.getNumber());
        transaction.setStockTransfer(stockTransfer);//transaction belongs to invoice
        transaction.setJournalDate(stockTransfer.getDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getCompany().getCompanyDate());
        transaction.setReference(stockTransfer.getNumber());
        transactionManager.createOrUpdate(transaction);

        for (EdsStockAdjustment sa : stockTransfer.getItems()) {
            EdsAdjustmentItem fromItem = sa.getAdjustmentItemList().get(0);
            EdsAdjustmentItem toItem = sa.getAdjustmentItemList().get(1);

            EdsItem item = fromItem.getItem();

            if (PRODUCT_KIT.equals(item.getType())) {
                applyStockTransferProductKitToItemStock(fromItem, toItem, transaction);
            } else if ((item.getType().equals(INVENTORY_ITEM) || item.getType().equals(ASSEMBLY_ITEM)) && (item.enableIT() || financialSettingsManager.getFinancialSettings().enableIT())) {
                //from item
                BigDecimal usedQty = fromItem.getUsedQty();
                Integer fromWarehouseId = fromItem.getWarehouse().getObjectID();
                BigDecimal COGS = cogsServices.getService().createCogsTransaction(new FifoItem(transaction.getObjectID(), item.getObjectID(), usedQty, fromWarehouseId, fromItem.getObjectID()));

                BigDecimal newQty = toItem.getNewQty();
                Integer toWarehouseId = toItem.getWarehouse().getObjectID();
                cogsServices.getService().applyStockTransferToItemStock(item, COGS, newQty, transaction, toWarehouseId, toItem.getObjectID());
            }
        }
        baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_STOCK_TRANSFER_TRANSACTION, stockTransfer, userManager.getUser());
    }

    @Override
    public Integer createTransactionsForStockAdjustment(EdsStockAdjustment stockAdjustment) {
        EdsUser user = accountingManager.getUser();

        EdsStockAdjustmentTransaction transaction = transactionManager.getTransactionByStockAdjustment(stockAdjustment);
        if (transaction != null) {
            itemStockManager.deleteItemStocksByTransaction(transaction.getObjectID());
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsStockAdjustmentTransaction(); //creating new transaction
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        }

        transaction.setName("Stock Adjustment. " + stockAdjustment.getNumber());
        transaction.setAdjustment(stockAdjustment);//transaction belongs to invoice
        transaction.setJournalDate(stockAdjustment.getDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getCompany().getCompanyDate());

        String memoText = "";
        if (stockAdjustment.getMemo() != null && !stockAdjustment.getMemo().isEmpty()) {
            memoText = stockAdjustment.getMemo().length() > 30
                    ? stockAdjustment.getMemo().substring(0, 30)
                    : stockAdjustment.getMemo();
            try {
                memoText = new HTMLParser().performParse(memoText);
            } catch (Exception e) {
                log.info("Cannot parse Memo HTML: " + memoText);
                memoText = "";
            }
            if (!memoText.trim().isEmpty()) {
                memoText = " : " + memoText;
            }
        }
        transaction.setReference(stockAdjustment.getNumber() + memoText);
        transactionManager.createOrUpdate(transaction);

        for (EdsAdjustmentItem adjustmentItem : stockAdjustment.getAdjustmentItemList()) {

            if (adjustmentItem.getNewQty().compareTo(BigDecimal.ZERO) > 0) {
                cogsServices.getService().applyAdjustedItemsToStock(adjustmentItem, transaction);
            }
            /*
             * adjustmentItem.getUsedQty().compareTo(BigDecimal.ZERO) > 0
             * ↑ this one we are handling in the post processor event
             */
        }
        baseEventPostProcessor.registerEvent(TransactionCustomEventListenerImpl.TYPE, TransactionCustomEventListenerImpl.EVENT_STOCK_ADJUSTMENT_TRANSACTION, stockAdjustment, user);
        return transaction.getObjectID();
    }

    @Override
    public void createTransactionForVatAdjustment(EdsVatAdjustment vatAdjustment) {
        EdsUser user = accountingManager.getUser();
        EdsVatAdjustmentTransaction transaction = new EdsVatAdjustmentTransaction(); //creating new transaction
        transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
        transaction.setName("VAT Adjustment. " + vatAdjustment.getReference());
        transaction.setVatAdjustmentId(vatAdjustment.getObjectID());//transaction belongs to invoice
        transaction.setJournalDate(vatAdjustment.getDate());
        transaction.setPostedBy(user);
        transaction.setPostedDate(user.getCompany().getCompanyDate());
        transaction.setReference(vatAdjustment.getReference());
        transactionManager.createOrUpdate(transaction);

        EdsTransactionItem transactionItem = new EdsTransactionItem();
        transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.VAT_PAYABLE));
        transactionItem.setCredit(vatAdjustment.getAmount());
        transaction.addTransactionItem(transactionItem);

        transactionItem = new EdsTransactionItem();
        transactionItem.setAccount(vatAdjustment.getAccount());
        transactionItem.setDebit(vatAdjustment.getAmount());
        transaction.addTransactionItem(transactionItem);
    }

    @Override
    public void createTransactionForOverPayment(EdsOverPayment overUnderPayment) {
        EdsUser user = accountingManager.getUser();
        EdsOverPaymentTransaction transaction = transactionManager.getTransactionByOverPayment(overUnderPayment);
        if (transaction == null) {
            transaction = new EdsOverPaymentTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
        } else {
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        }
        transaction.setOverPayment(overUnderPayment);
        transaction.setReference(overUnderPayment.getReference());
        transaction.setJournalDate(overUnderPayment.getPaymentDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setExchangeRate(overUnderPayment.getExchangeRate());
        EdsTransactionItem transactionItem = null;
        switch (overUnderPayment.getType()) {
            case RECEIVABLE_OVERPAYMENT -> {
                transaction.setName("Overpayment: " + overUnderPayment.getOverPaymentAccount().getName());
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(overUnderPayment.getAccount());
                transactionItem.setDebit(overUnderPayment.getAmount());
                if (overUnderPayment.getAmountInEntityCurrency() != null) {
                    transactionItem.setForeignDebit(overUnderPayment.getAmountInEntityCurrency());
                }
                transaction.addTransactionItem(transactionItem);
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(overUnderPayment.getOverPaymentAccount());
                transactionItem.setCredit(overUnderPayment.getAmount());
                if (overUnderPayment.getAmountInEntityCurrency() != null) {
                    transactionItem.setForeignCredit(overUnderPayment.getAmountInEntityCurrency());
                }
                transaction.addTransactionItem(transactionItem);
            }
            case PAYABLE_OVERPAYMENT -> {
                transaction.setName("Overpayment: " + overUnderPayment.getOverPaymentAccount().getName());
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(overUnderPayment.getOverPaymentAccount());
                transactionItem.setDebit(overUnderPayment.getAmount());
                if (overUnderPayment.getAmountInEntityCurrency() != null) {
                    transactionItem.setForeignDebit(overUnderPayment.getAmountInEntityCurrency());
                }
                transaction.addTransactionItem(transactionItem);
                transactionItem = new EdsTransactionItem();
                transactionItem.setAccount(overUnderPayment.getAccount());
                transactionItem.setCredit(overUnderPayment.getAmount());
                if (overUnderPayment.getAmountInEntityCurrency() != null) {
                    transactionItem.setForeignCredit(overUnderPayment.getAmountInEntityCurrency());
                }
                transaction.addTransactionItem(transactionItem);
            }
            default -> {
            }
        }

        transactionManager.createOrUpdate(transaction);

    }

    @Override
    public void deleteTransactionForOverPayment(Integer batchPaymentID) {
        EdsOverPayment edsOverPayment = overPaymentManager.getOverPaymentByBatchPayment(batchPaymentID);
        if (edsOverPayment != null) {
            edsOverPayment.setDeleted(true);
            overPaymentManager.update(edsOverPayment);
            transactionManager.deleteOverPaymentTransaction(edsOverPayment);
        }
    }

