    @Transactional(propagation = Propagation.NEVER, readOnly = true)
    public TrialBalance getTrialBalance(TrialBalanceFilter tbf) {
        String sortBy = tbf.getSortField();
        long start = new Date().getTime();
        TrialBalance trialBalance = new TrialBalance();
        LinkedHashMap<String, LinkedList<TrialBalanceItem>> mapAccountTypeByList = getMapAccountTypeByList();
        HashMap<String, BigDecimal> trailBalanceTotalMap = new HashMap<>();
        trailBalanceTotalMap.put("totalBeginningBalance", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalBeginningDebit", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalBeginningCredit", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalDebit", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalCredit", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalEndingBalance", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalEndingDebit", BigDecimal.ZERO);
        trailBalanceTotalMap.put("totalEndingCredit", BigDecimal.ZERO);

        if (tbf.isConsolidation()) {
            Map<String, TrialBalanceItem> mergeAccountTypeMap = new HashMap<>();
            Map<Integer, String> subsidiariesClusterType = commonServiceLocal.getSubsidiariesCompanyClusterType(SecurityContext.getCompanyID());
            for (Integer companyId : subsidiariesClusterType.keySet()) {
                SecurityContext.getInstance().setDatabase(subsidiariesClusterType.get(companyId));
                SecurityContext.getInstance().setCompanyId(companyId);
                if (companyManager.schemaExists(String.valueOf(companyId))) {
                    accountReportService.getTrialBalanceAllSubsidiariesReport(tbf.getStartDate().getNonConvertedDate(), tbf.getToDate().getNonConvertedDate(), mapAccountTypeByList, mergeAccountTypeMap, trailBalanceTotalMap, null, tbf.getCurrencyId(), tbf.getShowValues(), tbf.isSummary());
                }
                userManager.flushAndClear();
            }
        } else {
            String teamIDs = getParentAndChildDepartmentTreeIDs(tbf.getDepartmentID());
            accountReportService.getTrialBalanceReport(tbf.getStartDate().getNonConvertedDate(), tbf.getToDate().getNonConvertedDate(), mapAccountTypeByList, trailBalanceTotalMap, tbf.getShowValues(), teamIDs, null, tbf.getCurrencyId(), tbf.isSummary());
        }

        if (tbf.getSortDirection() != null && "DESC".equals(tbf.getSortDirection())) {
            mapAccountTypeByList.get(EdsAccountType.ASSETS).sort(comparatorFactoriesDesc.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.LIABILITIES).sort(comparatorFactoriesDesc.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.EQUITY).sort(comparatorFactoriesDesc.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.EXPENSES).sort(comparatorFactoriesDesc.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.REVENUE).sort(comparatorFactoriesDesc.get(sortBy));
        } else {
            mapAccountTypeByList.get(EdsAccountType.ASSETS).sort(comparatorFactories.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.LIABILITIES).sort(comparatorFactories.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.EQUITY).sort(comparatorFactories.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.EXPENSES).sort(comparatorFactories.get(sortBy));
            mapAccountTypeByList.get(EdsAccountType.REVENUE).sort(comparatorFactories.get(sortBy));
        }
        trialBalance.setAssets(mapAccountTypeByList.get(EdsAccountType.ASSETS).toArray(new TrialBalanceItem[]{}));
        trialBalance.setLiabilities(mapAccountTypeByList.get(EdsAccountType.LIABILITIES).toArray(new TrialBalanceItem[]{}));
        trialBalance.setEquity(mapAccountTypeByList.get(EdsAccountType.EQUITY).toArray(new TrialBalanceItem[]{}));
        trialBalance.setExpenses(mapAccountTypeByList.get(EdsAccountType.EXPENSES).toArray(new TrialBalanceItem[]{}));
        trialBalance.setRevenue(mapAccountTypeByList.get(EdsAccountType.REVENUE).toArray(new TrialBalanceItem[]{}));

        trialBalance.setTotalBeginningBalance(trailBalanceTotalMap.get("totalBeginningBalance"));
        trialBalance.setTotalBeginningDebit(trailBalanceTotalMap.get("totalBeginningDebit"));
        trialBalance.setTotalBeginningCredit(trailBalanceTotalMap.get("totalBeginningCredit"));
        trialBalance.setTotalDebit(trailBalanceTotalMap.get("totalDebit"));
        trialBalance.setTotalCredit(trailBalanceTotalMap.get("totalCredit"));
        trialBalance.setTotalEndingBalance(trailBalanceTotalMap.get("totalEndingBalance"));
        trialBalance.setTotalEndingDebit(trailBalanceTotalMap.get("totalEndingDebit"));
        trialBalance.setTotalEndingCredit(trailBalanceTotalMap.get("totalEndingCredit"));

        System.out.println("Execution time of trial balans report: " + (new Date().getTime() - start) / 1000 + " seconds");

        BigDecimal totalEndingBalance = (Optional.ofNullable(trialBalance.getTotalEndingBalance())
                .orElse(BigDecimal.ZERO)).setScale(2, RoundingMode.HALF_UP);
        if (totalEndingBalance.compareTo(BigDecimal.ZERO) != 0) {
            messageManager.sendIncorrectReportBalanceEmail(null);
        }

        return trialBalance;
    }

