    @Transactional(propagation = Propagation.NEVER, readOnly = true)
    public Map<Integer, ArrayList<TrialBalanceItem>> getPRAccountClientSupplierBalance(Date from, Date to) {
        Map<String, TrialBalanceItem> all = accountingManager.getPRAccountClientSupplierBalance(null, null);
        Map<String, TrialBalanceItem> beginningBalanceMap = accountingManager.getPRAccountClientSupplierBalance(from, null);
        Map<String, TrialBalanceItem> balanceMap = accountingManager.getPRAccountClientSupplierBalance(from, to);

        Map<Integer, ArrayList<TrialBalanceItem>> map = new LinkedHashMap<>();

        if (all != null && !all.isEmpty()) {
            for (String key : all.keySet()) {
                if (beginningBalanceMap.get(key) == null && balanceMap.get(key) == null) {
                    continue;
                }

                TrialBalanceItem item = balanceMap.get(key);

                if (item == null) {
                    item = beginningBalanceMap.get(key);
                    BigDecimal debCred = item.getDebit().subtract(item.getCredit());

                    if (debCred.compareTo(BigDecimal.ZERO) >= 0) {
                        item.setBeginningDebit(debCred);
                        item.setDebit(BigDecimal.ZERO);
                        item.setEndingDebit(debCred);

                        item.setBeginningCredit(BigDecimal.ZERO);
                        item.setCredit(BigDecimal.ZERO);
                        item.setEndingCredit(BigDecimal.ZERO);
                    } else {
                        item.setBeginningCredit(debCred.multiply(new BigDecimal(-1)));
                        item.setCredit(BigDecimal.ZERO);
                        item.setEndingCredit(debCred.multiply(new BigDecimal(-1)));

                        item.setBeginningDebit(BigDecimal.ZERO);
                        item.setDebit(BigDecimal.ZERO);
                        item.setEndingDebit(BigDecimal.ZERO);
                    }
                } else {
                    TrialBalanceItem beginningBalance = beginningBalanceMap.get(item.getAccountId() + "_" + item.getParentId());
                    BigDecimal bb = beginningBalance != null
                            ? beginningBalance.getDebit().subtract(beginningBalance.getCredit())
                            : BigDecimal.ZERO;
                    item.setBeginningDebit(bb.compareTo(BigDecimal.ZERO) >= 0 ? bb : BigDecimal.ZERO);
                    item.setBeginningCredit(bb.compareTo(BigDecimal.ZERO) < 0
                            ? bb.multiply(new BigDecimal(-1))
                            : BigDecimal.ZERO);

                    BigDecimal debCred = item.getDebit().subtract(item.getCredit());

                    if (item.getBeginningDebit().compareTo(BigDecimal.ZERO) > 0) {
                        debCred = item.getBeginningDebit().add(debCred);
                    } else if (item.getBeginningCredit().compareTo(BigDecimal.ZERO) > 0) {
                        debCred = (item.getBeginningCredit().subtract(debCred)).multiply(new BigDecimal(-1));
                    }

                    item.setEndingDebit(debCred.compareTo(BigDecimal.ZERO) >= 0 ? debCred : BigDecimal.ZERO);
                    item.setEndingCredit(debCred.compareTo(BigDecimal.ZERO) < 0
                            ? debCred.multiply(new BigDecimal(-1))
                            : BigDecimal.ZERO);
                }

                map.computeIfAbsent(item.getAccountId(), k -> new ArrayList<>());
                map.get(item.getAccountId()).add(item);
            }
        }

        return map;
    }

    @Transactional(propagation = Propagation.NEVER, readOnly = true)
    public CashFlow getCashFlow(ListingFilterParameter filter) {
        CashFlow cashFlow = new CashFlow();

        System.out.println("Server start date: " + filter.getStartDateNC());
        System.out.println("Server end date: " + filter.getEndDateNC());

        Date periodStart = ServerUtils.parseFilterParameterDate(filter.getStartDateNC());
        Date periodEnd = ServerUtils.parseFilterParameterDate(filter.getEndDateNC());

        String teamIDs = getParentAndChildDepartmentTreeIDs(filter.getDepartmentId());

        PnLFilter pnLFilter = new PnLFilter();
        pnLFilter.setMain(new FromToDate(new DateNonConvertable(periodStart), new DateNonConvertable(periodEnd)));
        pnLFilter.setCompareTo(new FromToDate[]{});
        pnLFilter.setConsolidation(false);
        pnLFilter.setDepartmentAndTreeChildIDs(teamIDs);
        pnLFilter.setProjectID(filter.getProjectId());
        pnLFilter.setCurrencyId(filter.getCurrencyID());

        //get financial settings
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();

        BigDecimal exchangeRate = BigDecimal.ONE;
        Integer exchangeRateScale = financialSettings.getExchangeRateScale();

        //get exchange rate for given period (priod date is ToDate)
        if (filter.getCurrencyID() != null) {
            CurrencyListItem item = currencyService.getCurrencyRateByDate(filter.getCurrencyID(), new DateNonConvertable(periodEnd));
            exchangeRate = BigDecimal.valueOf(item.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP);
        }
        //generate PnL report
        BudgetManagerItems pnl = getProfitAndLoss(pnLFilter);

        if (pnl.getNetProfit() != null && !pnl.getNetProfit().isEmpty()) {
            BudgetInDate netProfit = pnl.getNetProfit().get(0);
            if (netProfit != null && netProfit.getValue() != null) {
                cashFlow.setNetProfit(netProfit.getValue());
            }
        }

        //OPERATING ACTIVITIES
        cashFlow.setCurrentAssets(accountingManager.getCashFlowItems("CURRENT_ASSET", filter, teamIDs, false));
        cashFlow.setPrepayments(accountingManager.getCashFlowItems("PREPAYMENT", filter, teamIDs, false));
        cashFlow.setCurrentLiabilities(accountingManager.getCashFlowItems("CURRENT_LIABILITY", filter, teamIDs, false));
        cashFlow.setNetOperatingActivities(cashFlow.getNetOperatingActivities().add(cashFlow.getNetProfit()));

        Map<String, CashFlowItem> accountsBeginningBalanceMap;
        Calendar calendar = new GregorianCalendar();
        calendar.setTime(periodStart);
        calendar.add(Calendar.SECOND, -1);
        ListingFilterParameter fp2 = new ListingFilterParameter();
        fp2.setAscending(filter.isAscending());
        fp2.setCurrencyID(filter.getCurrencyID());
        fp2.setSortField(filter.getSortField());
        fp2.setEndDateNC(new SimpleDateFormat("ddMMyyyy HH:mm:ss").format(calendar.getTime()));
        fp2.setStartDateNC(null);
        LinkedList<CashFlowItem> accountsBeginningBalance = accountingManager.getCashFlowItems(null, fp2, teamIDs, false);
        accountsBeginningBalanceMap = accountsBeginningBalance.stream().collect(Collectors.toMap(CashFlowItem::getCode, x -> x));

        if (cashFlow.getCurrentAssets() != null && !cashFlow.getCurrentAssets().isEmpty()) {
            for (CashFlowItem item : cashFlow.getCurrentAssets()) {

                if (item.isForeignAccount()) {
                    CurrencyListItem currencyItem = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(periodEnd));
                    BigDecimal bankCurrencyExchangeRate = currencyItem != null
                            ? BigDecimal.valueOf(currencyItem.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP)
                            : BigDecimal.ONE;
                    if (item.isGainAndLoss()) {
                        Calendar prevBalanceDateCal = ServerUtils.convertDateIntoCalendar(periodStart);
                        prevBalanceDateCal.add(Calendar.DAY_OF_MONTH, -1);
                        Date prevBalanceDate = ServerUtils.getStartDate(prevBalanceDateCal.getTime());

                        CurrencyListItem currInBegginningPeriod = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(prevBalanceDate));
                        BigDecimal currInBegginningPeriodExchangeRate = currInBegginningPeriod != null
                                ? BigDecimal.valueOf(currInBegginningPeriod.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP)
                                : BigDecimal.ONE;
                        BigDecimal beginBalance = item.getBalance().multiply(exchangeRate).divide(currInBegginningPeriodExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        BigDecimal endbalance = item.getBalance().multiply(exchangeRate).divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        item.setBalance(endbalance.subtract(beginBalance).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        //this line does bank account amount convert to base currency amount
                        BigDecimal balance = item.getBalance().multiply(exchangeRate).divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        CurrencyListItem currInBegginningPeriod = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(calendar.getTime()));
                        BigDecimal exchangeRateInBegginningPeriod = currInBegginningPeriod != null ? BigDecimal.valueOf(currInBegginningPeriod.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP) : BigDecimal.ONE;
                        if (accountsBeginningBalanceMap.get(item.getCode()) != null) {
                            balance = balance.add(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                            balance = balance.subtract(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(exchangeRateInBegginningPeriod, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                        }
                        item.setBalance(balance);
                    }
                }
                cashFlow.setNetOperatingActivities(cashFlow.getNetOperatingActivities().add(item.getBalance()));
            }
        }

        if (cashFlow.getPrepayments() != null && !cashFlow.getPrepayments().isEmpty()) {
            for (CashFlowItem item : cashFlow.getPrepayments()) {

                if (item.isForeignAccount()) {
                    CurrencyListItem currencyItem = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(periodEnd));
                    BigDecimal bankCurrencyExchangeRate = currencyItem != null
                            ? BigDecimal.valueOf(currencyItem.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP)
                            : BigDecimal.ONE;

                    //this line does bank account amount convert to base currency amount
                    BigDecimal balance = item.getBalance().multiply(exchangeRate).divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                    CurrencyListItem currInBegginningPeriod = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(calendar.getTime()));
                    BigDecimal exchangeRateInBegginningPeriod = currInBegginningPeriod != null ? BigDecimal.valueOf(currInBegginningPeriod.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP) : BigDecimal.ONE;
                    if (accountsBeginningBalanceMap.get(item.getCode()) != null) {
                        balance = balance.add(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                        balance = balance.subtract(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(exchangeRateInBegginningPeriod, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    }
                    item.setBalance(balance);
                }
                cashFlow.setNetOperatingActivities(cashFlow.getNetOperatingActivities().add(item.getBalance()));
            }
        }

        if (cashFlow.getCurrentLiabilities() != null && !cashFlow.getCurrentLiabilities().isEmpty()) {
            for (CashFlowItem item : cashFlow.getCurrentLiabilities()) {

                if (item.isForeignAccount()) {
                    CurrencyListItem currencyItem = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(periodEnd));
                    BigDecimal bankCurrencyExchangeRate = currencyItem != null
                            ? BigDecimal.valueOf(currencyItem.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP)
                            : BigDecimal.ONE;

                    if (item.isGainAndLoss()) {
                        Calendar prevBalanceDateCal = ServerUtils.convertDateIntoCalendar(periodStart);
                        prevBalanceDateCal.add(Calendar.DAY_OF_MONTH, -1);
                        Date prevBalanceDate = ServerUtils.getStartDate(prevBalanceDateCal.getTime());

                        CurrencyListItem currInBegginningPeriod = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(prevBalanceDate));
                        BigDecimal currInBegginningPeriodExchangeRate = currInBegginningPeriod != null
                                ? BigDecimal.valueOf(currInBegginningPeriod.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP)
                                : BigDecimal.ONE;
                        BigDecimal beginBalance = item.getBalance().multiply(exchangeRate).divide(currInBegginningPeriodExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        BigDecimal endbalance = item.getBalance().multiply(exchangeRate).divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        item.setBalance(endbalance.subtract(beginBalance).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                    } else {
                        //this line does bank account amount convert to base currency amount
                        BigDecimal balance = item.getBalance().multiply(exchangeRate).divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
                        CurrencyListItem currInBegginningPeriod = currencyService.getCurrencyRateByDate(item.getAccountCurrencyId(), new DateNonConvertable(calendar.getTime()));
                        BigDecimal exchangeRateInBegginningPeriod = currInBegginningPeriod != null ? BigDecimal.valueOf(currInBegginningPeriod.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP) : BigDecimal.ONE;
                        if (accountsBeginningBalanceMap.get(item.getCode()) != null) {
                            balance = balance.add(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(bankCurrencyExchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                            balance = balance.subtract(accountsBeginningBalanceMap.get(item.getCode()).getBalance().divide(exchangeRateInBegginningPeriod, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
                        }
                        item.setBalance(balance);
                    }
                }
                cashFlow.setNetOperatingActivities(cashFlow.getNetOperatingActivities().add(item.getBalance()));
            }
        }

        //INVESTING ACTIVITIES
        cashFlow.setAccumulatedDepreciations(accountingManager.getCashFlowItems("ACCUMULATED_DEPRECIATION", filter, teamIDs, false));
        cashFlow.setFixedAssets(accountingManager.getCashFlowItems("FIXED_ASSET", filter, teamIDs, false));
        cashFlow.setLiabilities(accountingManager.getCashFlowItems("LIABILITY", filter, teamIDs, false));
        cashFlow.setNonCurrentAssets(accountingManager.getCashFlowItems("NON_CURRENT_ASSET", filter, teamIDs, false));


        if (cashFlow.getAccumulatedDepreciations() != null && !cashFlow.getAccumulatedDepreciations().isEmpty()) {
            for (CashFlowItem item : cashFlow.getAccumulatedDepreciations()) {
                cashFlow.setNetInvestingActivities(cashFlow.getNetInvestingActivities().add(item.getBalance()));
            }
        }
        if (cashFlow.getFixedAssets() != null && !cashFlow.getFixedAssets().isEmpty()) {
            for (CashFlowItem item : cashFlow.getFixedAssets()) {
                cashFlow.setNetInvestingActivities(cashFlow.getNetInvestingActivities().add(item.getBalance()));
            }
        }
        if (cashFlow.getLiabilities() != null && !cashFlow.getLiabilities().isEmpty()) {
            for (CashFlowItem item : cashFlow.getLiabilities()) {
                cashFlow.setNetInvestingActivities(cashFlow.getNetInvestingActivities().add(item.getBalance()));
            }
        }
        if (cashFlow.getNonCurrentAssets() != null && !cashFlow.getNonCurrentAssets().isEmpty()) {
            for (CashFlowItem item : cashFlow.getNonCurrentAssets()) {
                cashFlow.setNetInvestingActivities(cashFlow.getNetInvestingActivities().add(item.getBalance()));
            }
        }

        //FINANCING ACTIVITIES
        cashFlow.setLongTermLiabilities(accountingManager.getCashFlowItems("LONG_TERM_LIABILITY", filter, teamIDs, false));
        cashFlow.setEquities(accountingManager.getCashFlowItems("EQUITY", filter, teamIDs, false));

        if (cashFlow.getLongTermLiabilities() != null && !cashFlow.getLongTermLiabilities().isEmpty()) {
            for (CashFlowItem item : cashFlow.getLongTermLiabilities()) {
                cashFlow.setNetFinancingActivities(cashFlow.getNetFinancingActivities().add(item.getBalance()));
            }
        }
        if (cashFlow.getEquities() != null && !cashFlow.getEquities().isEmpty()) {
            for (CashFlowItem item : cashFlow.getEquities()) {
                cashFlow.setNetFinancingActivities(cashFlow.getNetFinancingActivities().add(item.getBalance()));
            }
        }

        cashFlow.setNetIncreaseDecreaseForPeriod(cashFlow.getNetOperatingActivities()
                .add(cashFlow.getNetInvestingActivities())
                .add(cashFlow.getNetFinancingActivities()));

        /*Calendar periodStartCal = new GregorianCalendar();
        periodStartCal.setTime(periodStart);
        periodStartCal.set(Calendar.DATE, periodStartCal.get(Calendar.DATE) - 1);
        ServerUtils.setEndOfTheDay(periodStartCal);
        filter.setStartDateNC(null);
        filter.setEndDateNC(ServerUtils.formatFilterDate(periodStartCal.getTime()));

        cashFlow.setCashAtTheBeginningOfPeriod(accountingManager.getCashFlowItemBalance("CASH_AT_THE_BEGINNING_OF_THE_PERIOD", filter, true));*/

        cashFlow.setCashAtTheEndOfPeriod(cashFlow.getCashAtTheBeginningOfPeriod().add(cashFlow.getNetIncreaseDecreaseForPeriod()));

        return cashFlow;
    }

    @Transactional(propagation = Propagation.NEVER, readOnly = true)
    public BalanceSheet getBalanceSheet(DateNonConvertable fromDate, DateNonConvertable toDate, boolean isConsolidation, Integer departmentID, Integer projectID, Integer currencyId) {
        Map<String, List<BalanceSheetInnerItem>> balanceSheetMap = new HashMap<>();
        Map<String, BigDecimal> balanceSheetTotalMap = new HashMap<>();
        initBalanceSheetTotalMaps(balanceSheetMap, balanceSheetTotalMap);

        //temp solution for fetch all transaction even transactions posted before conversion date
        Calendar tempCal = Calendar.getInstance();
        tempCal.setTime(fromDate.getNonConvertedDate());
        tempCal.set(Calendar.YEAR, 0);
        fromDate = new DateNonConvertable(tempCal.getTime());

        String teamIDs = getParentAndChildDepartmentTreeIDs(departmentID);

        if (isConsolidation) {
            Integer baseCurrencyID = financialSettingsManager.getFinancialSettings().getCurrency().getObjectID();
            Map<String, BalanceSheetInnerItem> mergeBalanceSheetMap = new HashMap<>();
            Map<Integer, String> subsidiariesClusterType = commonServiceLocal.getSubsidiariesCompanyClusterType(SecurityContext.getCompanyID());
            for (Integer companyId : subsidiariesClusterType.keySet()) {
                SecurityContext.getInstance().setDatabase(subsidiariesClusterType.get(companyId));
                SecurityContext.getInstance().setCompanyId(companyId);
                if (companyManager.schemaExists(String.valueOf(companyId))) {
                    accountReportService.getBalanceSheetAllSubsidiariesReport(fromDate.getNonConvertedDate(), toDate.getNonConvertedDate(), balanceSheetMap, balanceSheetTotalMap, baseCurrencyID, mergeBalanceSheetMap, teamIDs, projectID);
                }
                companyManager.flushAndClear();
            }
        } else {
            CurrencyListItem item = currencyService.getCurrencyRateByDate(currencyId, new DateNonConvertable(ServerUtils.getStartDate(new Date())));
            BigDecimal exchangeRate = BigDecimal.valueOf(item.getExchangeRate()).setScale(financialSettingsManager.getFinancialSettings().getExchangeRateScale(), RoundingMode.HALF_UP);
            accountReportService.getBalanceSheetReport(fromDate.getNonConvertedDate(), toDate.getNonConvertedDate(), balanceSheetMap, balanceSheetTotalMap, exchangeRate, teamIDs, currencyId, projectID);
        }

        BalanceSheet sheet = new BalanceSheet();
        sheet.setSettings(getBalancesheetSettings());

        balanceSheetTotalMap.keySet().forEach(key -> {
            if (AccountingConstants.TOTAL_ASSET.equals(key)) {
                sheet.setTotalAsset(new BalanceSheetInnerItem(commonLocalizer.localize(PdfLocalizationName.totalAsset, "Total Assets"), balanceSheetTotalMap.get(AccountingConstants.TOTAL_ASSET)));
            } else if (AccountingConstants.TOTAL_LIABILITY.equals(key)) {
                sheet.setTotalLiability(new BalanceSheetInnerItem(commonLocalizer.localize(PdfLocalizationName.totalLiability, "Total Equity and Liabilities"), balanceSheetTotalMap.get(AccountingConstants.TOTAL_LIABILITY)));
            } else {
                balanceSheetMap.get(key).sort(Comparator.comparing(BalanceSheetInnerItem::getName));
                sheet.putItemsByKey(key, createBalanceSheetItem(key, balanceSheetMap.get(key), balanceSheetTotalMap.get(key)));
            }
        });

        boolean assetEqualsLiability = sheet.getTotalAsset().getValue().setScale(2, RoundingMode.HALF_UP)
                .equals(sheet.getTotalLiability().getValue().setScale(2, RoundingMode.HALF_UP));
        if (!assetEqualsLiability) {
            messageManager.sendIncorrectReportBalanceEmail(null);
        }

        return sheet;
    }

    @Transactional(propagation = Propagation.NEVER, readOnly = true)
    public BalanceSheetSummary getBalanceSheetSummary(DateNonConvertable fromDate, DateNonConvertable toDate, Boolean isConsolidation, Integer departmentID, Integer projectID, Integer currencyId) {
        Map<String, List<BalanceSheetInnerItem>> balanceSheetMap = new HashMap<>();
        Map<String, BigDecimal> balanceSheetTotalMap = new HashMap<>();
        initBalanceSheetTotalMaps(balanceSheetMap, balanceSheetTotalMap);

        //temp solution for fetch all transaction even transactions posted before conversion date
        Calendar tempCal = Calendar.getInstance();
        tempCal.setTime(fromDate.getNonConvertedDate());
        tempCal.set(Calendar.YEAR, 0);
        fromDate = new DateNonConvertable(tempCal.getTime());

        String teamIDs = getParentAndChildDepartmentTreeIDs(departmentID);

        if (isConsolidation) {
            Integer baseCurrencyID = financialSettingsManager.getFinancialSettings().getCurrency().getObjectID();
            Map<String, BalanceSheetInnerItem> mergeBalanceSheetMap = new HashMap<>();
            Map<Integer, String> subsidiariesClusterType = commonServiceLocal.getSubsidiariesCompanyClusterType(SecurityContext.getCompanyID());
            for (Integer companyId : subsidiariesClusterType.keySet()) {
                SecurityContext.getInstance().setDatabase(subsidiariesClusterType.get(companyId));
                SecurityContext.getInstance().setCompanyId(companyId);
                if (companyManager.schemaExists(String.valueOf(companyId))) {
                    accountReportService.getBalanceSheetAllSubsidiariesReport(fromDate.getNonConvertedDate(), toDate.getNonConvertedDate(), balanceSheetMap, balanceSheetTotalMap, baseCurrencyID, mergeBalanceSheetMap, teamIDs, projectID);
                }
                companyManager.flushAndClear();
            }
        } else {
            CurrencyListItem item = currencyService.getCurrencyRateByDate(currencyId, toDate);
            BigDecimal exchangeRate = BigDecimal.valueOf(item.getExchangeRate()).setScale(financialSettingsManager.getFinancialSettings().getExchangeRateScale(), RoundingMode.HALF_UP);
            accountReportService.getBalanceSheetReport(fromDate.getNonConvertedDate(), toDate.getNonConvertedDate(), balanceSheetMap, balanceSheetTotalMap, exchangeRate, teamIDs, currencyId, projectID);
        }
        BalancesheetSettings settings = getBalancesheetSettings();

        BalanceSheetSummary sheet = new BalanceSheetSummary();
        List<BalanceSheetInnerItem> assetInnerItems = new LinkedList<>();
        List<BalanceSheetInnerItem> liabilityInnerItems = new LinkedList<>();

        if (settings.getSettings() != null) {
            settings.getSettings();
            for (BalancesheetSettingsItem setting : settings.getSettings()) {

                if (Constants.ASSETS.equals(setting.getCode())) {
                    for (BalancesheetSettingsItem item : setting.getItems()) {

                        if (balanceSheetTotalMap.containsKey(item.getCode())) {
                            assetInnerItems.add(new BalanceSheetInnerItem(getLabel(item.getCode(), false), balanceSheetTotalMap.get(item.getCode())));
                        }
                    }
                } else {
                    for (BalancesheetSettingsItem item : setting.getItems()) {
                        if (balanceSheetTotalMap.containsKey(item.getCode())) {
                            liabilityInnerItems.add(new BalanceSheetInnerItem(getLabel(item.getCode(), false), balanceSheetTotalMap.get(item.getCode())));
                        }
                    }
                }
            }
        }
        sheet.setAssets(createBalanceSheetItem(AccountingConstants.ASSETS, assetInnerItems, balanceSheetTotalMap.get(AccountingConstants.TOTAL_ASSET)));
        sheet.setLiabilities(createBalanceSheetItem(AccountingConstants.EQUITY_LIABILITIES, liabilityInnerItems, balanceSheetTotalMap.get(AccountingConstants.TOTAL_LIABILITY)));
        return sheet;
    }

    private BalanceSheetItem createBalanceSheetItem(String code, List<BalanceSheetInnerItem> items, BigDecimal total) {
        String name = getLabel(code, false);
        String totalName = getLabel(code, true);
        return new BalanceSheetItem(name, items.toArray(new BalanceSheetInnerItem[]{}), new BalanceSheetInnerItem(totalName, total));
    }

    private String getLabel(String code, boolean total) {
        switch (code) {
            case AccountingConstants.FIXED_ASSET -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalFixedAssets, "Total Fixed Assets");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.fixedAssets, "Fixed Assets");
                }
            }
            case AccountingConstants.CURRENT_ASSET -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalCurentAssets, "Total Current Assets");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.currentAssets, "Current Assets");
                }
            }
            case AccountingConstants.CASH -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalCash, "Total Cash");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.cash, "Cash");
                }
            }
            case AccountingConstants.NON_CURRENT_ASSET -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalNonCurentAssets, "Total Non Current Assets");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.nonCurrentAssets, "Non Current Assets");
                }
            }
            case AccountingConstants.BANK -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalBank, "Total Bank");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.bank, "Bank");
                }
            }
            case AccountingConstants.PREPAYMENT -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalPrepayments, "Total Prepayments");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.prepayments, "Prepayments");
                }
            }
            case AccountingConstants.LIABILITY -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalLiabilities, "Total Liabilities");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.liabilities, "Liabilities");
                }
            }
            case AccountingConstants.CURRENT_LIABILITY -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalCurrentLiabilities, "Total Current Liabilities");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.currentLiabilities, "Current Liabilities");
                }
            }
            case AccountingConstants.LONG_TERM_LIABILITY -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalLongTermLiabilities, "Total Non-Current Liabilities");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.longTermLiabilities, "Non-Current Liabilities");
                }
            }
            case AccountingConstants.EQUITY -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalShareCapital, "Total Equity");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.equity, "Equity");
                }
            }
            case AccountingConstants.ASSETS -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalAsset, "Total Assets");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.assets, "Assets");
                }
            }
            case AccountingConstants.EQUITY_LIABILITIES -> {
                if (total) {
                    return commonLocalizer.localize(PdfLocalizationName.totalLiability, "Total Equity and Liabilities");
                } else {
                    return commonLocalizer.localize(PdfLocalizationName.liabilities, "Liabilities");
                }
            }
        }
        return null;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRED, readOnly = true)
    public TransactionsBetweenDatesInAccount findTransactionsByAccountAndJournalDate(ListingFilterParameter fp,
                                                                                     DateNonConvertable fromDate,
                                                                                     DateNonConvertable toDate) {
        if (fromDate != null) {
            fp.setStartDate(fromDate.getNonConvertedDate());
        }
        if (toDate != null) {
            fp.setEndDate(toDate.getNonConvertedDate());
        }
        String teamIDs = getParentAndChildDepartmentTreeIDs(fp.getDepartmentId());
        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();

        ArrayList<Transaction> tTransfer = new ArrayList<>();
        TransactionsBetweenDatesInAccount transfer = new TransactionsBetweenDatesInAccount();
        EdsAccount account = null;
        if (fp.getAccountID() != null) {
            account = accountingManager.get(fp.getAccountID());
        }

        if (account.getKey() != null && account.getKey() == EdsAccount.RETAINED_EARNINGS) {
            getTransactionsForRetainedEarnings(fp, teamIDs, tTransfer, transfer);
        } else if (account.getKey() != null && account.getKey() == EdsAccount.EXCHANGE_VARIANCE) {
            getTransactionsForGainAndLoss(fp, teamIDs, tTransfer, transfer, fromDate);
        } else {
            getTransactionsForSubAccounts(fp, teamIDs, tTransfer, transfer, fromDate);

            if (account.isForeignAccount() && fp.isShowInBase()) {
                //calculate beginning balance of account with exchange rate at from date

                Map<Integer, TotalDebitCredit> map = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, fp.getProjectId(), null, fromDate.getNonConvertedDate(), account.getObjectID());

                if (map.get(account.getObjectID()) != null && fp.getCurrencyID() == null) {
                    TotalDebitCredit debitCredit = map.get(account.getObjectID());

                    CurrencyListItem item = currencyService.getCurrencyRateByDate(debitCredit.getCurrencyID(), new DateNonConvertable(ServerUtils.getStartDate(new Date())));
                    BigDecimal exchangeRate = BigDecimal.valueOf(item.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP);
                    BigDecimal beginningBalance = debitCredit.getRealDebitCreditDiff().divide(exchangeRate, ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);

                    if (EdsAccountType.LIABILITIES.equalsIgnoreCase(account.getAccountType().getCategory())) {
                        beginningBalance = beginningBalance.multiply(new BigDecimal(-1));
                    }

                    transfer.setTotalBeginningBalance(beginningBalance);
                }

                //calculate bank gain/loss in that date
                getBankAccountsGainLossDetail(account.getObjectID(), teamIDs, fp.getProjectId(), fp.getStartDate(), fp.getEndDate(), tTransfer, transfer, fp.getLimit());
            }
        }
        TotalDebitCredit tDC = TotalDebitCredit.solve(transfer.getTotalDebit(), transfer.getTotalCredit());
        if (tDC.dcCompare() == EdsAccount.DEBIT) {
            transfer.setBalanceDebit(tDC.getDebitCreditDiff());
        } else if (tDC.dcCompare() == EdsAccount.CREDIT) {
            transfer.setBalanceCredit(tDC.getDebitCreditDiff());
        }

        /*
         * BANK,Bank
         * SALES,Sales
         * REVENUE,Revenue
         * OTHER_INCOME,Other Income
         * COST_OF_SALES,Cost of sales
         * DIRECT_EXPENSES,Direct Expenses
         * OVERHEAD,Overhead
         * CURRENT_ASSET,Current Asset
         * FIXED_ASSET,Fixed Asset
         * LIABILITY,Liability
         * EQUITY,Equity
         * CURRENT_LIABILITY,Current Liability
         * DEPRECIATION,Depreciation
         * PREPAYMENT,Prepayment
         * NON_CURRENT_ASSET,Non-Current Asset
         * LONG_TERM_LIABILITY,Non-Current Liability
         */

        {//T6622
            boolean skipBeginningToZero = COST_OF_SALES.equals(account.getAccountType().getCode())
                    || DIRECT_EXPENSES.equals(account.getAccountType().getCode())
                    || OTHER_INCOME.equals(account.getAccountType().getCode())
                    || OVERHEAD.equals(account.getAccountType().getCode())
                    || REVENUE.equals(account.getAccountType().getCode())
                    || SALES.equals(account.getAccountType().getCode());
            if (skipBeginningToZero) {
                transfer.setTotalBeginningBalance(BigDecimal.ZERO);
            }
        }
        return transfer;
    }

    public void getTransactionsForSubAccounts(ListingFilterParameter fp,
                                              String teamIDs,
                                              ArrayList<Transaction> tTransfer,
                                              TransactionsBetweenDatesInAccount transfer, DateNonConvertable fromDate) {
        BigDecimal totalDebit = BigDecimal.ZERO;
        BigDecimal totalCredit = BigDecimal.ZERO;
        BigDecimal beginningDebit = BigDecimal.ZERO;
        BigDecimal beginningCredit = BigDecimal.ZERO;
        int totalCount = 0;
        boolean cashOnly = false;

        if (fp != null) {
            cashOnly = fp.isShowBudget();
        }

        EdsAccount account = null;
        if (fp.getAccountID() != null) {
            account = accountingManager.get(fp.getAccountID());
            transfer.setForeignAccount(account.isForeignAccount());

            if (account.isForeignAccount() && !fp.isShowInBase()) {
                EdsCurrency currency = account.getCurrency();
                transfer.setCurrency(currency.createCurrencyItem());
            } else {
                transfer.setCurrency(currencyService.getBaseCurrency());
            }
        }

        ListingFilterParameter fp1 = new ListingFilterParameter();
        fp1.setAccountID(fp.getAccountID());
        fp1.setSearchKey(fp.getSearchKey());
        fp1.setStartDate(fp.getStartDate());
        fp1.setDepartmentId(fp.getDepartmentId());
        fp1.setShowInBase(fp.isShowInBase());
        fp1.setEndDate(null);
        fp1.setProjectId(fp.getProjectId());

        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();
        Calendar prevBalanceDateCal = ServerUtils.convertDateIntoCalendar(fromDate != null ? fromDate.getNonConvertedDate() : new Date());
        prevBalanceDateCal.add(Calendar.DAY_OF_MONTH, -1);
        Date prevBalanceDate = ServerUtils.getStartDate(prevBalanceDateCal.getTime());

        CurrencyListItem currencyListItem = currencyService.getCurrencyRateByDate(fp.getCurrencyID(), new DateNonConvertable(prevBalanceDate));
        BigDecimal exchangeRate = BigDecimal.valueOf(currencyListItem.getExchangeRate()).setScale(exchangeRateScale, RoundingMode.HALF_UP);

        BigDecimal endingDebit = BigDecimal.ZERO;
        BigDecimal endingCredit = BigDecimal.ZERO;
        final List<Transaction> list = transactionManager.listAttendedInAccountInPeriod2(fp, teamIDs, cashOnly);

        if (cashOnly && !fp.isForExportOnly()) {
            BigDecimal[] totalsCashOnly = transactionManager.getListCashOnlyInAccountInPeriodCount(fp, teamIDs);
            totalCount = totalsCashOnly[0].intValue();
            totalDebit = totalsCashOnly[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            totalCredit = totalsCashOnly[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));

            //for beginning balance
            BigDecimal[] totalCashOnly = transactionManager.getListCashOnlyInAccountInPeriodCount(fp1, teamIDs);
            beginningDebit = totalCashOnly[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            beginningCredit = totalCashOnly[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));

            fp1.setStartDate(null);
            fp1.setEndDate(fp.getEndDate());
            totalCashOnly = transactionManager.getListCashOnlyInAccountInPeriodCount(fp1, teamIDs);
            endingDebit = totalCashOnly[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            endingCredit = totalCashOnly[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
        } else if (!fp.isForExportOnly()) {
            BigDecimal[] totals = transactionManager.getListAttendedInAccountInPeriodCount(fp, teamIDs);
            totalCount = totals[0].intValue();
            totalDebit = totals[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            totalCredit = totals[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));

            //for beginning balance
            BigDecimal[] total = transactionManager.getListAttendedInAccountInPeriodCount(fp1, teamIDs);
            beginningDebit = total[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            beginningCredit = total[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));

            fp1.setStartDate(null);
            fp1.setEndDate(fp.getEndDate());

            total = transactionManager.getListAttendedInAccountInPeriodCount(fp1, teamIDs);
            endingDebit = total[1].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
            endingCredit = total[2].multiply(exchangeRate.setScale(exchangeRateScale, RoundingMode.HALF_UP));
        }
        transfer.setTotalCount(totalCount);
        transfer.setTotalDebit(totalDebit);
        transfer.setTotalCredit(totalCredit);
        if (EdsAccountType.ASSETS.equals(account.getAccountType().getCategory()) || EdsAccountType.EXPENSES.equals(account.getAccountType().getCategory())) {
            transfer.setTotalBeginningBalance(beginningDebit.subtract(beginningCredit));
            transfer.setTotalBalance(endingDebit.subtract(endingCredit));
        } else {
            transfer.setTotalBeginningBalance(beginningCredit.subtract(beginningDebit));
            transfer.setTotalBalance(endingCredit.subtract(endingDebit));
        }
        transfer.setAccountType(account.getAccountType().getCategory());

        BigDecimal balanceStart = ZERO;
        int startLimit = fp.getStart() != null ? fp.getStart() : 0;
        int endLimit = fp.getLimit() != null ? fp.getLimit() + startLimit + 1 : list.size();
        int i = 0;
        String accountType = account.getAccountType().getCategory();
        for (Transaction item : list) {
            EdsTransaction transaction = transactionManager.get(item.getTransactionId());
            item.setTransactionType(transaction.getKeyType());
            item.setKeyId(transaction.getKeyId());

            if (transaction instanceof EdsGoodsReceivedTransaction) {
                if (((EdsGoodsReceivedTransaction) transaction).getPurchaseOrder() != null) {
                    item.setPurchaseOrderId(((EdsGoodsReceivedTransaction) transaction).getPurchaseOrder().getObjectID());
                } else if (((EdsGoodsReceivedTransaction) transaction).getShippingData() != null) {
                    EdsShippingData shippingData = ((EdsGoodsReceivedTransaction) transaction).getShippingData();
                    item.setKeyId(shippingData.getObjectID());
                }
            }
            if (transaction instanceof EdsGoodsDeliveredTransaction) {
                if (((EdsGoodsDeliveredTransaction) transaction).getSaleOrder() != null) {
                    item.setSaleOrderId(((EdsGoodsDeliveredTransaction) transaction).getSaleOrder().getObjectID());
                } else if (((EdsGoodsDeliveredTransaction) transaction).getShippingData() != null) {
                    EdsShippingData shippingData = ((EdsGoodsDeliveredTransaction) transaction).getShippingData();
                    item.setKeyId(shippingData.getObjectID());
                }
            }
            if (INVOICEPAYMENT_TRANSACTION.equals(transaction.getKeyType())) {
                EdsInvoicePayment payment = invoicePaymentManager.get(transaction.getKeyId());
                if (payment != null) {
                    item.setPaymentType(payment.getType());
                    if (payment.getInvoice() != null) {
                        item.setCreditNote(false);
                        item.setInvoicePaymentNumber(payment.getInvoice().getNumber());
                    } else if (payment.getCreditNote() != null) {
                        item.setCreditNote(true);
                        item.setInvoicePaymentNumber(payment.getCreditNote().getNumber());
                    }
                    if (payment.getBatchPaymentID() != null) {
                        EdsBatchPayment batchPayment = batchPaymentManager.getPayment(payment.getBatchPaymentID());
                        if (batchPayment != null) {
                            item.setInvoicePaymentNumber(batchPayment.getNumber());
                            item.setBatchPaymentId(batchPayment.getObjectID());
                        }
                    } else if (payment.getBankTransferID() != null) {
                        EdsBankTransfer bankTransfer = spendReceiveMoneyManager.get(payment.getBankTransferID());
                        item.setInvoicePaymentNumber(bankTransfer.getNumber());
                    } else if (payment.getManualJournalID() != null) {
                        EdsManualJournal manualJournal = manualJournalManager.get(payment.getManualJournalID());
                        item.setInvoicePaymentNumber(manualJournal.getNumber());
                    }
                } else {
                    item.setCreditNote(false);
                }
            }

            item.setJournalDate(new DateNonConvertable(transaction.getJournalDate()));
            item.setJournalName(transaction.getName());

            if (i < startLimit) {
                BigDecimal debit = (item.getTotalDebit() != null ? item.getTotalDebit() : ZERO);
                BigDecimal credit = (item.getTotalCredit() != null ? item.getTotalCredit() : ZERO);
                if (Constants.ASSETS.equals(accountType) || EXPENSES.equals(accountType)) {
                    balanceStart = balanceStart.add(debit.subtract(credit));
                } else {
                    balanceStart = balanceStart.add(credit.subtract(debit));
                }
            } else if (i >= startLimit && i < endLimit) {
                item.setTotalDebit(item.getTotalDebit() != null ? item.getTotalDebit().multiply(exchangeRate.setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP)) : null);
                item.setTotalCredit(item.getTotalCredit() != null ? item.getTotalCredit().multiply(exchangeRate.setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP)) : null);
                tTransfer.add(item);
                companyManager.flushAndClear();
            } else {
                break;
            }
            i++;
        }
        transfer.setBalanceStart(balanceStart);
        transfer.setTransactions(tTransfer);
        companyManager.flushAndClear();
    }

    public void getTransactionsForRetainedEarnings(ListingFilterParameter fp, String teamIDs, ArrayList<Transaction> tTransfer, TransactionsBetweenDatesInAccount transfer) {
        BigDecimal totalDebit = BigDecimal.ZERO, totalCredit = BigDecimal.ZERO, totalBeginningBalance = BigDecimal.ZERO;
        int totalCount = 0;
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        Integer currencyId = financialSettings.getCurrency().getObjectID();
        Integer exchangeRate = financialSettings.getExchangeRateScale();

        Date conversionDate = financialSettings.getConversionDate();
        Date toDate = financialSettings.getFinancialYearEnd();
        Date date = (Date) conversionDate.clone();
        Calendar calendar = Calendar.getInstance();

        transfer.setBalanceStart(ZERO);

        Calendar fpEndDate = Calendar.getInstance();
        fpEndDate.setTime(fp.getEndDate());
        fpEndDate.set(Calendar.HOUR_OF_DAY, 23);
        fpEndDate.set(Calendar.MINUTE, 59);
        fpEndDate.set(Calendar.SECOND, 59);
        fpEndDate.set(Calendar.MILLISECOND, 999);

        boolean periodTransactions = true;

        while (((toDate = accountReportService.getEndingOfAccountingPeriod(toDate, date)).before(fpEndDate.getTime()) || periodTransactions && !financialSettings.isIncludeCurrentYearEariningInRetained())
                || financialSettings.isIncludeCurrentYearEariningInRetained() && accountReportService.getBeginningOfAccountingPeriod(toDate, date).before(fp.getEndDate())) {
            if (toDate.after(fpEndDate.getTime())) {
                periodTransactions = false;
            }

            Date fromDate = accountReportService.getBeginningOfAccountingPeriod(toDate, date);

            if (financialSettings.isIncludeCurrentYearEariningInRetained() && fromDate.before(fp.getEndDate()) && toDate.after(fp.getEndDate())) {
                toDate = fp.getEndDate();
            } else {
                if (toDate.after(fpEndDate.getTime())) {
                    toDate = fpEndDate.getTime();
                }
            }

            ListingFilterParameter fp1 = new ListingFilterParameter();
            fp1.setAccountID(fp.getAccountID());
            fp1.setProjectId(fp.getProjectId());
            fp1.setDepartmentId(fp.getDepartmentId());
            fp1.setStartDate(fromDate);
            fp1.setEndDate(toDate);

            List<Transaction> transactions = transactionManager.listAttendedInAccountInPeriod2(fp1, teamIDs, false);

            Object[] revenueTransItems = transactionManager.getBalanceDataByDateAndAccountCategoryByDepartment(EdsAccountType.REVENUE, fromDate, toDate, teamIDs, fp.getProjectId());
            Object[] expenseTransItems = transactionManager.getBalanceDataByDateAndAccountCategoryByDepartment(EdsAccountType.EXPENSES, fromDate, toDate, teamIDs, fp.getProjectId());
            //Bank account gain and loss
            TotalDebitCredit foreignGainAndLoss = accountReportService.calculateBankAccountsGainLoss(fromDate, toDate, teamIDs, fp.getProjectId(), currencyId, exchangeRate);


            for (Transaction item : transactions) {
                EdsTransaction transaction = transactionManager.get(item.getTransactionId());
                item.setTransactionType(transaction.getKeyType());
                item.setKeyId(transaction.getKeyId());
                item.setJournalDate(new DateNonConvertable(transaction.getJournalDate()));
                item.setJournalName(transaction.getName());
                totalDebit = totalDebit.add(Optional.ofNullable(item.getTotalDebit()).orElse(ZERO));
                totalCredit = totalCredit.add(Optional.ofNullable(item.getTotalCredit()).orElse(ZERO));
                if (fromDate.before(fp.getStartDate())) {
                    totalBeginningBalance = totalBeginningBalance.add(Optional.ofNullable(item.getTotalCredit()).orElse(ZERO)).subtract(Optional.ofNullable(item.getTotalDebit()).orElse(ZERO));
                } else {
                    tTransfer.add(item);
                    totalCount++;
                }
            }


            if (periodTransactions) {
                if ((revenueTransItems != null && revenueTransItems.length > 0) || (expenseTransItems != null && expenseTransItems.length > 0)) {
                    Transaction transaction = new Transaction();
                    transaction.setKeyId(fp.getAccountID());
                    transaction.setTransactionType(Constants.RETAINED_EARNINGS_TRANSACTION);
                    transaction.setJournalDate(new DateNonConvertable(toDate));
                    transaction.setFromDate(new DateNonConvertable(fromDate));
                    transaction.setToDate(new DateNonConvertable(toDate));
                    BigDecimal debit = revenueTransItems[0] != null ? (BigDecimal) revenueTransItems[0] : ZERO;
                    debit = debit.add(expenseTransItems[0] != null ? (BigDecimal) expenseTransItems[0] : ZERO);
                    BigDecimal credit = revenueTransItems[1] != null ? (BigDecimal) revenueTransItems[1] : ZERO;
                    credit = credit.add(expenseTransItems[1] != null ? (BigDecimal) expenseTransItems[1] : ZERO);
                    transaction.setTotalDebit(debit.add(foreignGainAndLoss.debit));
                    transaction.setTotalCredit(credit.add(foreignGainAndLoss.credit));
                    boolean isProfit = transaction.getTotalCredit().subtract(transaction.getTotalDebit()).compareTo(ZERO) >= 0;
                    transaction.setJournalName(isProfit ? "Net Profit" : "Net Loss");
                    totalDebit = totalDebit.add(transaction.getTotalDebit());
                    totalCredit = totalCredit.add(transaction.getTotalCredit());
                    if (fromDate.before(fp.getStartDate())) {
                        totalBeginningBalance = totalBeginningBalance.add(transaction.getTotalCredit().subtract(transaction.getTotalDebit()));
                    } else {
                        tTransfer.add(transaction);
                        totalCount++;
                    }
                }
            }
            calendar.setTime(toDate);
            calendar.add(Calendar.DAY_OF_MONTH, +1);
            calendar.set(Calendar.HOUR_OF_DAY, 0);
            calendar.set(Calendar.MINUTE, 0);
            calendar.set(Calendar.SECOND, 0);
            calendar.set(Calendar.MILLISECOND, 0);
            date = calendar.getTime();
        }

        transfer.setCurrency(currencyService.getBaseCurrency());
        transfer.setTransactions(tTransfer);
        transfer.setTotalCount(totalCount);
        transfer.setTotalDebit(totalDebit);
        transfer.setTotalCredit(totalCredit);
        transfer.setTotalBeginningBalance(totalBeginningBalance);
        transfer.setTotalBalance(totalCredit.subtract(totalDebit));
    }

    public void getTransactionsForGainAndLoss(ListingFilterParameter fp, String teamIDs, ArrayList<Transaction> tTransfer, TransactionsBetweenDatesInAccount transfer, DateNonConvertable fromDate) {
        getTransactionsForSubAccounts(fp, teamIDs, tTransfer, transfer, fromDate);

        //calculate bank gain/loss for beginning balance
        Map<Integer, TotalDebitCredit> foreignDebitCreditMap = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, fp.getProjectId(), null, fp.getStartDate(), null);
        List<EdsAccount> foreignAccounts = accountingManager.getAccountsAttendedInTransactions(fp.getStartDate(), teamIDs, fp.getProjectId(), ALL_ACCOUNTS, true);
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        Integer baseCurrencyId = financialSettings.getCurrency().getObjectID();
        TotalDebitCredit gainLoss = new TotalDebitCredit();

        for (EdsAccount account : foreignAccounts) {

            if (account.getCurrency() == null || baseCurrencyId.equals(account.getCurrency().getObjectID())) {
                continue;
            }

            TotalDebitCredit dcTotalPeriod = new TotalDebitCredit();
            BigDecimal balanceDiff;

            if (foreignDebitCreditMap.get(account.getObjectID()) != null) {
                balanceDiff = accountReportService.calculateGainLossBalance(dcTotalPeriod, foreignDebitCreditMap.get(account.getObjectID()), baseCurrencyId, baseCurrencyId, BigDecimal.ONE, financialSettings.getExchangeRateScale());

                if (balanceDiff.compareTo(BigDecimal.ZERO) > 0) {
                    gainLoss.credit = gainLoss.credit.add(balanceDiff);
                } else {
                    gainLoss.debit = gainLoss.debit.add(balanceDiff.abs());
                }
            }
        }
        transfer.setTotalBeginningBalance(transfer.getTotalBeginningBalance().add(gainLoss.getRealDebitCreditDiff()));

        //calculate bank gain/loss for this period
        getBankAccountsGainLossDetail(fp.getAccountID(), teamIDs, fp.getProjectId(), fp.getStartDate(), fp.getEndDate(), tTransfer, transfer, fp.getLimit());
    }

    /**
     * Calculate bank accounts gain and loss
     * in base currency
     */
    private void getBankAccountsGainLossDetail(Integer accountID, String teamIDs, Integer projectId, Date fromDate, Date toDate, ArrayList<Transaction> tTransfer, TransactionsBetweenDatesInAccount transfer, Integer limit) {
        final Integer totalGainAndLossTransactions = tTransfer != null ? tTransfer.size() : 0;
        BigDecimal totalDebit = BigDecimal.ZERO, totalCredit = BigDecimal.ZERO;
        int totalCount = 0;
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        Integer baseCurrencyId = financialSettings.getCurrency().getObjectID();
        Integer currencyId = baseCurrencyId;

        EdsAccount edsaccount = accountingManager.get(accountID);

        if (edsaccount.getCurrency() != null) {
            currencyId = edsaccount.getCurrency().getObjectID();
        }


        Map<Integer, TotalDebitCredit> beginningBalanceMap;
        Map<Integer, TotalDebitCredit> balanceMap;

        List<EdsAccount> foreignAccounts;

        if (edsaccount.getKey() != null && edsaccount.getKey() == EdsAccount.EXCHANGE_VARIANCE) {
            beginningBalanceMap = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, projectId, null, fromDate, null);
            balanceMap = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, projectId, fromDate, toDate, null);
            foreignAccounts = accountingManager.getAccountsAttendedInTransactions(toDate, teamIDs, projectId, ALL_ACCOUNTS, true);
        } else {
            beginningBalanceMap = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, projectId, null, fromDate, accountID);
            balanceMap = accountingManager.getForeignAccountsDebitCreditTotal(teamIDs, projectId, fromDate, toDate, accountID);

            foreignAccounts = new ArrayList<>();
            foreignAccounts.add(edsaccount);
        }

            for (EdsAccount account : foreignAccounts) {

                TotalDebitCredit dcTotalBeginningBalance = new TotalDebitCredit();
                BigDecimal balanceDiff;

                Transaction transaction = new Transaction();
                transaction.setKeyId(account.getObjectID());
                transaction.setJournalName(account.getName());
                transaction.setJournalDate(new DateNonConvertable(toDate));

                //calculate gain/loss in the piod transactions
                if (balanceMap.get(account.getObjectID()) != null) {
                    TotalDebitCredit glTotalPeriod = new TotalDebitCredit();
                    balanceDiff = accountReportService.calculateGainLossBalance(glTotalPeriod, balanceMap.get(account.getObjectID()), currencyId, baseCurrencyId, BigDecimal.ONE, financialSettings.getExchangeRateScale());

                    if (balanceDiff.compareTo(BigDecimal.ZERO) < 0) {
                        if (edsaccount.getKey() != null && edsaccount.getKey() == EdsAccount.EXCHANGE_VARIANCE) {
                            transaction.setTotalDebit(transaction.getTotalDebit() != null
                                    ? transaction.getTotalDebit().add(balanceDiff.abs())
                                    : balanceDiff.abs());
                            totalDebit = totalDebit.add(balanceDiff.abs());
                        } else {
                            transaction.setTotalCredit(transaction.getTotalCredit() != null
                                    ? transaction.getTotalCredit().add(balanceDiff.abs())
                                    : balanceDiff.abs());
                            totalCredit = totalCredit.add(balanceDiff.abs());
                        }
                    } else {
                        if (edsaccount.getKey() != null && edsaccount.getKey() == EdsAccount.EXCHANGE_VARIANCE) {
                            transaction.setTotalCredit(transaction.getTotalCredit() != null
                                    ? transaction.getTotalCredit().add(balanceDiff)
                                    : balanceDiff);
                            totalCredit = totalCredit.add(balanceDiff);
                        } else {
                            transaction.setTotalDebit(transaction.getTotalDebit() != null
                                    ? transaction.getTotalDebit().add(balanceDiff)
                                    : balanceDiff);
                            totalDebit = totalDebit.add(balanceDiff);
                        }
                    }
                }

                Integer calculationScale = Optional.ofNullable(financialSettings.getCalculationScale()).orElse(0);

                if (transaction.getTotalDebit() != null) {
                    transaction.setTotalDebit(transaction.getTotalDebit().setScale(calculationScale, RoundingMode.HALF_UP));
                }
                if (transaction.getTotalCredit() != null) {
                    transaction.setTotalCredit(transaction.getTotalCredit().setScale(calculationScale, RoundingMode.HALF_UP));
                }
                if (
                    //at least debit value cannot be equals to zero
                        (transaction.getTotalDebit() != null && transaction.getTotalDebit().compareTo(BigDecimal.ZERO) != 0 ||
                                //at least credit value cannot be equals to zero
                                transaction.getTotalCredit() != null && transaction.getTotalCredit().compareTo(BigDecimal.ZERO) != 0) ||
                                //debit & credit values should be different
                                transaction.getTotalCredit() != null && transaction.getTotalDebit() != null && transaction.getTotalDebit().compareTo(transaction.getTotalCredit()) != 0
                ) {

                    if (totalGainAndLossTransactions < 51 || limit > 50) {
                        tTransfer.add(transaction);
                    }
                    totalCount++;

                }
                // do not calculate gain/loss for closed transactions
                if (transaction.getTotalCredit() != null && transaction.getTotalDebit() != null && transaction.getTotalDebit().compareTo(transaction.getTotalCredit()) == 0) {
                    totalCredit = totalCredit.subtract(transaction.getTotalCredit());
                    totalDebit = totalDebit.subtract(transaction.getTotalDebit());
                }
            }


        transfer.setTotalCount(transfer.getTotalCount() + totalCount);
        transfer.setTotalDebit(transfer.getTotalDebit().add(totalDebit));
        transfer.setTotalCredit(transfer.getTotalCredit().add(totalCredit));

        if (EdsAccountType.LIABILITIES.equalsIgnoreCase(edsaccount.getAccountType().getCategory())) {
            transfer.setTotalBalance(transfer.getTotalBeginningBalance().add(transfer.getTotalCredit().subtract(transfer.getTotalDebit())));
        } else {
            transfer.setTotalBalance(transfer.getTotalBeginningBalance().add(transfer.getTotalDebit().subtract(transfer.getTotalCredit())));
        }
    }


    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public TransactionsReport getTransactionsReportForDashboard(DateNonConvertable from, DateNonConvertable to) {
        EdsAccount accountsReceivable = accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_RECEIVABLE);
        EdsAccount accountsPayable = accountingManager.getAccountByKey(EdsAccount.ACCOUNTS_PAYABLE);
        List<EdsBankAccount> bankAccounts = accountingManager.getBankAccounts();

        TransactionsReport report = new TransactionsReport();

        try {
            BigDecimal moneyOwedToUs = ZERO, moneyWeOwe = ZERO;
            TransactionsBetweenDatesInAccount receivable;
            {
                ListingFilterParameter fp = new ListingFilterParameter();
                fp.setAccountID(accountsReceivable.getObjectID());
                if (from != null) {
                    fp.setStartDate(from.getNonConvertedDate());
                }
                fp.setEndDate(to.getNonConvertedDate());
                fp.setShowBudget(false);
                receivable = findTransactionsByAccountAndJournalDate(fp, from, to);
            }

            TransactionsBetweenDatesInAccount payable;
            {
                ListingFilterParameter fp = new ListingFilterParameter();
                fp.setAccountID(accountsPayable.getObjectID());
                fp.setStartDate(from.getNonConvertedDate());
                fp.setEndDate(to.getNonConvertedDate());
                fp.setShowBudget(false);
                payable = findTransactionsByAccountAndJournalDate(fp, from, to);
            }
            ListingFilterParameter fp = new ListingFilterParameter();
            List<TransactionsBetweenDatesInAccount> transForBankAccounts = new LinkedList<>();
            for (EdsBankAccount bankAccount : bankAccounts) {
                {
                    fp.setAccountID(bankAccount.getAccount().getObjectID());
                    fp.setStartDate(from.getNonConvertedDate());
                    fp.setEndDate(to.getNonConvertedDate());
                    fp.setShowBudget(false);
                    transForBankAccounts.add(findTransactionsByAccountAndJournalDate(fp, from, to));
                }
            }
            BigDecimal receivableBalance = receivable.getTotalDebit().subtract(receivable.getTotalCredit());
            BigDecimal payableBalance = payable.getTotalCredit().subtract(payable.getTotalDebit());
            if (receivableBalance.compareTo(ZERO) >= 0) {
                moneyOwedToUs = moneyOwedToUs.add(receivableBalance);
            } else {
                moneyWeOwe = moneyWeOwe.add(receivableBalance.abs());
            }
            if (payableBalance.compareTo(ZERO) >= 0) {
                moneyWeOwe = moneyWeOwe.add(payableBalance);
            } else {
                moneyOwedToUs = moneyOwedToUs.add(payableBalance.abs());
            }
            report.setMoneyOwedToUs(moneyOwedToUs.doubleValue());
            report.setMoneyWeOwe(moneyWeOwe.doubleValue());

            BigDecimal totalDebitForBankAccount = ZERO;
            BigDecimal totalCreditForBankAccount = ZERO;
            for (TransactionsBetweenDatesInAccount t : transForBankAccounts) {
                totalDebitForBankAccount = totalDebitForBankAccount.add(t.getTotalDebit());
                totalCreditForBankAccount = totalCreditForBankAccount.add(t.getTotalCredit());
            }
            report.setCurrentCash(totalDebitForBankAccount.subtract(totalCreditForBankAccount).abs().doubleValue());
        } catch (NullPointerException e) {
            e.printStackTrace();
        }
        return report;
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public BudgetManagerItems getProfitAndLoss(PnLFilter filter) {
        //get financial settings for spicific configs
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();

        BigDecimal exchangeRate = BigDecimal.ONE;
        Integer exchangeRateScale = financialSettings.getExchangeRateScale();

        //generate department tree for filtering data
        String teamIDs = getParentAndChildDepartmentTreeIDs(filter.getDepartmentID());
        filter.setDepartmentAndTreeChildIDs(teamIDs);

        //get exchange rate for given period (priod date is ToDate)
        if (filter.getCurrencyId() != null) {
            CurrencyListItem item = currencyService.getCurrencyRateByDate(filter.getCurrencyId(), filter.getMain().getTo());
            exchangeRate = BigDecimal.valueOf(item.getExchangeRate()).setScale(financialSettings.getExchangeRateScale(), RoundingMode.HALF_UP);
        }
        filter.setExchangeRate(exchangeRate);
        filter.setExchangeRateScale(exchangeRateScale);

        if (filter.isConsolidation()) {//If working company is managable subsidiary company then run pnl for subsidiaries
            return accountReportService.getProfitAndLossSubsidiariesReport(filter);
        } else { //for not subsidiaries
            return accountReportService.getProfitAndLossReport(filter);
        }
    }

    private String getParentAndChildDepartmentTreeIDs(Integer departmentID) {
        StringBuilder teamIDs = new StringBuilder();
        if (departmentID != null) {
            teamIDs.append(departmentID);
            teamIDs.append(departmentService.getChildDepartmentIds(departmentID, true));
        }
        return teamIDs.toString();
    }

    /**
     * Creates a sertain account budget for the given month in the year
     *
     * @param budget account budget
     */
    public BudgetRelatedIds createAccountsBudget(AccountBudget budget) {
        EdsAccountBudget accountBudget;
        if (budget.getId() == null) {
            Calendar from = new GregorianCalendar();
            from.setTime(budget.getDate());
            from.set(Calendar.DAY_OF_MONTH, 1);
            ServerUtils.setBeginningOfTheDay(from);

            Calendar to = new GregorianCalendar();
            to.setTime(budget.getDate());
            to.set(Calendar.DAY_OF_MONTH, to.getActualMaximum(Calendar.DAY_OF_MONTH));
            ServerUtils.setEndOfTheDay(to);

            accountBudget = accountBudgetManager.findAccountBudget(budget.getAccountID(), budget.getDepartmentID(), from.getTime(), to.getTime());

            if (accountBudget == null) {
                accountBudget = new EdsAccountBudget();
            }
            accountBudgetManager.create(accountBudget);
        } else {
            accountBudget = accountBudgetManager.get(budget.getId());
        }
        EdsBudgetedProfit profits;
        if (budget.getProfitId() == null) {
            profits = new EdsBudgetedProfit();
            budgetProfitManager.create(profits);
        } else {
            profits = budgetProfitManager.get(budget.getProfitId());
        }
        accountBudget.setBudgetedProfit(profits);
        profits.setDate(budget.getDate());
        profits.setGrossBudget(budget.getGrossProfit());
        profits.setNetBudget(budget.getNetProfit());

        accountBudget.setAccount(accountingManager.get(budget.getAccountID()));
        accountBudget.setDepartment(budget.getDepartmentID() != null
                ? departmentManager.get(budget.getDepartmentID())
                : null);
        accountBudget.setBudget(budget.getBudget());
        accountBudget.setMonth(budget.getMonth());
        accountBudget.setYear(budget.getYear());
        accountBudget.setDate(budget.getDate());
        BudgetRelatedIds ids = new BudgetRelatedIds();
        ids.setAccountBudgetId(accountBudget.getObjectID());
        ids.setProfitId(profits.getObjectID());
        return ids;
    }

    /**
     * Retreives all budgeted accounts in a range
     *
     * @param fromDate - DateNonConvertable
     * @param toDate   - DateNonConvertable
     */
    //eather obtain Year, Month struct from the client and calculate the
    //corresponding dates or obtain predefined dates from the client
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public BudgetManagerItems getBudgetedDataItem(Integer budgetmanagerId, DateNonConvertable fromDate, DateNonConvertable toDate, boolean isAsc) {
        Stopwatch stopwatch = Stopwatch.createStarted();
        EdsBudgetManager edsBudgetManager = budgetManager.get(budgetmanagerId);
        LinkedHashMap<String, Map<Integer, LinkedList<BudgetInDate>>> editableBudgetMap = null;
        if (edsBudgetManager != null) {
            editableBudgetMap = new LinkedHashMap<>();
            List<EdsBudgetManagerItem> getBudgetData = budgetItemManager.findBudgetedItemsInTheRange(budgetmanagerId, fromDate.getNonConvertedDate(), toDate.getNonConvertedDate());
            if (getBudgetData != null && !getBudgetData.isEmpty()) {
                for (int i = 0; i < getBudgetData.size(); i++) {
                    EdsBudgetManagerItem ab = getBudgetData.get(i);
                    Date budgetDate = new Date(ab.getDate().getTime());
                    BudgetInDate bIndate = new BudgetInDate(ab.getObjectID(), null, budgetDate, ab.getBudget());
                    bIndate.setGroupId(ab.getGroupId());
                    bIndate.setEntityID(ab.getEntityId());
                    if (editableBudgetMap.get(ab.getColumnCode()) != null) {
                        Map<Integer, LinkedList<BudgetInDate>> map = editableBudgetMap.get(ab.getColumnCode());
                        if (map.get(ab.getEntityId()) != null) {
                            LinkedList<BudgetInDate> entityBudgetList = map.get(ab.getEntityId());
                            entityBudgetList.add(bIndate);
                            map.replace(ab.getEntityId(), entityBudgetList);
                        } else {
                            LinkedList<BudgetInDate> accountBudgetList = new LinkedList<>();
                            accountBudgetList.add(bIndate);
                            map.put(ab.getEntityId(), accountBudgetList);
                        }
                        editableBudgetMap.replace(ab.getColumnCode(), map);
                    } else {
                        Map<Integer, LinkedList<BudgetInDate>> map = new LinkedHashMap<>();
                        LinkedList<BudgetInDate> budgetInDates = new LinkedList<>();
                        budgetInDates.add(bIndate);
                        map.put(ab.getEntityId(), budgetInDates);
                        editableBudgetMap.put(ab.getColumnCode(), map);
                    }
                }
            }


            LinkedHashMap<Integer, LinkedHashMap<Date, BudgetInDate>> reportData = new LinkedHashMap<>();
//        if (Constants.FROM_SYSTEM.equals(edsBudgetManager.getExpectedType())) {
////            runReportData(reportData, edsBudgetManager, edsBudgetManager.getType(), true);
//        }
//        if (Constants.FROM_SYSTEM.equals(edsBudgetManager.getActualType())) {
////            runReportData(reportData, edsBudgetManager, edsBudgetManager.getType(), false);
//        }

            HashMap<Integer, List<Integer>> selectedItems = null;
            EdsBudgetManagerSettings edsBudgetManagerSettings = budgetManagerSettings.getSettingsByBudget(budgetmanagerId);
            if (edsBudgetManagerSettings != null) {
                Gson gson = new Gson();
                selectedItems = gson.fromJson(edsBudgetManagerSettings.getSettingsJSONData(), new TypeToken<HashMap<Integer, List<Integer>>>() {
                }.getType());
            }
            BudgetManagerItems budgetManagerItems = new BudgetManagerItems();
            BudgetManagerItem budgetManagerItem = getBudgetManagerData(edsBudgetManager.getObjectID());
            if (edsBudgetManager != null && Constants.CHART_OF_ACCOUNT.equals(edsBudgetManager.getType())) {
                budgetManagerItems = getAccountBudgetItems(isAsc, null, editableBudgetMap, selectedItems, budgetManagerItem);
            } else if (edsBudgetManager != null && Constants.PRODUCTS.equals(edsBudgetManager.getType())) {
                budgetManagerItems = getProductsBudgetItems(reportData, editableBudgetMap, selectedItems, budgetManagerItem);
            } else if (edsBudgetManager != null && Constants.CUSTOMER.equals(edsBudgetManager.getType())) {
                budgetManagerItems = getCustomersBudgetItems(reportData, editableBudgetMap, selectedItems, budgetManagerItem);
            } else if (edsBudgetManager != null && Constants.OPPORTUNITY.equals(edsBudgetManager.getType())) {
                budgetManagerItems = getOpportunityBudgetItems(reportData, editableBudgetMap, selectedItems, budgetManagerItem);
            } else if (edsBudgetManager != null && Constants.PURCHASE_ORDER.equals(edsBudgetManager.getType())) {
                budgetManagerItems = getPurchaseOrderBudgetItems(reportData, editableBudgetMap, selectedItems, budgetManagerItem);
            } else if (edsBudgetManager != null && edsBudgetManager.getType().contains("_FORM")) {
                budgetManagerItems = getCustomFormBudgetItems(reportData, editableBudgetMap, selectedItems, budgetManagerItem);
            }
            budgetManagerItems.setBudgetManagerDetail(budgetManagerItem);
            stopwatch.elapsed(TimeUnit.MILLISECONDS);
            System.out.println("stopwatch " + stopwatch);
            return budgetManagerItems;
        }
        return null;
    }

    private BudgetManagerItems getCustomersBudgetItems(LinkedHashMap<Integer, LinkedHashMap<Date, BudgetInDate>> reportData, LinkedHashMap<String, Map<Integer, LinkedList<BudgetInDate>>> editableBudgetMap, HashMap<Integer, List<Integer>> selectedItems, BudgetManagerItem budgetManagerItem) {

        BudgetManagerItems budgetManagerItems = new BudgetManagerItems();
        if (selectedItems != null && !selectedItems.isEmpty()) {
            LinkedList<AccountItemsByAccountType> items = new LinkedList<>();
            if (CustomFormConstants.COUNTRY.equals(budgetManagerItem.getGroupBy())) {
                List<EdsCountry> countries = countryManager.list();
                if (countries != null && !countries.isEmpty()) {
                    List<EdsAddress> customerAdresses = addressManager.getAddressesByCrmAccount(selectedItems.get(0), CrmConstants.CRM_ACCOUNT);
                    LinkedHashMap<Integer, List<EdsCrmAccount>> addresses = new LinkedHashMap<>();
                    if (customerAdresses != null) {
                        for (EdsAddress address : customerAdresses) {
                            if (address.getCountry() != null) {
                                if (addresses.get(address.getCountry().getObjectID()) != null) {
                                    List<EdsCrmAccount> list = addresses.get(address.getCountry().getObjectID());
                                    list.add(crmAccountManager.get(address.getAccountID()));
                                    addresses.replace(address.getCountry().getObjectID(), list);
                                } else {
                                    List<EdsCrmAccount> list = new LinkedList<>();
                                    list.add(crmAccountManager.get(address.getAccountID()));
                                    addresses.put(address.getCountry().getObjectID(), list);
                                }
                            }
                        }
                    }
                    for (EdsCountry edsCountry : countries) {
                        if (edsCountry != null) {
                            AccountItemsByAccountType customerCountry = new AccountItemsByAccountType(edsCountry.getName(), edsCountry.getObjectID());
                            List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                            HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                            List<EdsCrmAccount> customers = addresses.get(edsCountry.getObjectID());

                            if (customers != null && !customers.isEmpty()) {
                                for (EdsCrmAccount crmAccount : customers) {
                                    calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, edsCountry.getObjectID());
                                }
                                customerCountry.setBudgetItemTotal(budgetItemTotal);
                                items.add(customerCountry.setAccountItems(budgetItemWithDate));
                            }
                        }
                    }
                }
            } else if (CustomFormConstants.CLIENT_TYPE.equals(budgetManagerItem.getGroupBy())) {
                List<SelectItem> clientTypes = new ArrayList<>();
                List<EdsReference> clientTypeRefs = referenceManager.listReferences("CLIENT_TYPES");
                if (clientTypeRefs != null && !clientTypeRefs.isEmpty()) {
                    for (EdsReference reference : clientTypeRefs) {
                        clientTypes.add(reference.getAsSelectItem());
                    }
                }

                clientTypes.add(new SelectItem(0, commonLocalizer.localize("na", "N/A")));

                if (clientTypes != null && !clientTypes.isEmpty()) {
                    List<EdsCrmAccount> selectedCustomers = crmAccountManager.getCrmAccountsByIDs(selectedItems.get(0));
                    LinkedHashMap<Integer, List<EdsCrmAccount>> customersMap = new LinkedHashMap<>();
                    if (selectedCustomers != null) {
                        for (EdsCrmAccount customer : selectedCustomers) {
                            if (customer.getClientType() != null) {
                                if (customersMap.get(customer.getClientType().getObjectID()) != null) {
                                    List<EdsCrmAccount> list = customersMap.get(customer.getClientType().getObjectID());
                                    list.add(customer);
                                    customersMap.replace(customer.getClientType().getObjectID(), list);
                                } else {
                                    List<EdsCrmAccount> list = new LinkedList<>();
                                    list.add(customer);
                                    customersMap.put(customer.getClientType().getObjectID(), list);
                                }
                            } else {
                                if (customersMap.get(0) != null) {
                                    List<EdsCrmAccount> list = customersMap.get(0);
                                    list.add(customer);
                                    customersMap.replace(0, list);
                                } else {
                                    List<EdsCrmAccount> list = new LinkedList<>();
                                    list.add(customer);
                                    customersMap.put(0, list);
                                }
                            }
                        }

                        for (SelectItem clientType : clientTypes) {

                            AccountItemsByAccountType customerType = new AccountItemsByAccountType(clientType.getName(), clientType.getId());
                            List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                            HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                            List<EdsCrmAccount> customers = customersMap.get(clientType.getId());

                            if (customers != null && !customers.isEmpty()) {
                                for (EdsCrmAccount crmAccount : customers) {
                                    calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, clientType.getId());
                                }
                                customerType.setBudgetItemTotal(budgetItemTotal);
                                items.add(customerType.setAccountItems(budgetItemWithDate));
                            }

                        }
                    }
                }
            } else if (CustomFormConstants.CRM_ACCOUNT_OWNER.equals(budgetManagerItem.getGroupBy())) {

                SelectItem[] ownersList = crmServiceLocal.getOwnersListByPermission(PermissionConstants.CRM_LEAD_CONTACT_ASSIGNEE);

                if (ownersList != null && ownersList.length > 0) {
                    List<EdsCrmAccount> selectedCustomers = crmAccountManager.getCrmAccountsByIDs(selectedItems.get(0));
                    LinkedHashMap<Integer, List<EdsCrmAccount>> customersMap = new LinkedHashMap<>();
                    if (selectedCustomers != null) {
                        for (EdsCrmAccount customer : selectedCustomers) {
                            if (customer.getOwners() != null) {
                                for (EdsUser owner : customer.getOwners()) {
                                    if (customersMap.get(owner.getObjectID()) != null) {
                                        List<EdsCrmAccount> list = customersMap.get(owner.getObjectID());
                                        list.add(customer);
                                        customersMap.replace(owner.getObjectID(), list);
                                    } else {
                                        List<EdsCrmAccount> list = new LinkedList<>();
                                        list.add(customer);
                                        customersMap.put(owner.getObjectID(), list);
                                    }
                                }
                            }
                        }

                        for (SelectItem owner : ownersList) {
                            AccountItemsByAccountType customerType = new AccountItemsByAccountType(owner.getName(), owner.getId());
                            List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                            HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                            List<EdsCrmAccount> customers = customersMap.get(owner.getId());

                            if (customers != null && !customers.isEmpty()) {
                                for (EdsCrmAccount crmAccount : customers) {
                                    calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, owner.getId());
                                }
                                customerType.setBudgetItemTotal(budgetItemTotal);
                                items.add(customerType.setAccountItems(budgetItemWithDate));
                            }
                        }
                    }
                }
            } else if (budgetManagerItem.getGroupBy() != null && (budgetManagerItem.getGroupBy().contains("string_value") || budgetManagerItem.getGroupBy().contains("double_value") || budgetManagerItem.getGroupBy().contains("date_value"))) {
                EdsCompanyCustomFieldsSettings companyCustomFieldsSettings = companyCustomFieldsManager.getCompanyCustomField(ViewName.CrmAccount.name(), budgetManagerItem.getGroupBy());

                List<String> cfTypeValue = new ArrayList<>();
                if (companyCustomFieldsSettings != null && Constants.UI_TYPE_DROPDOWN.equals(companyCustomFieldsSettings.getUiType())) {
                    if (companyCustomFieldsSettings.getPredefinedValues() != null) {
                        cfTypeValue.addAll(Arrays.asList(companyCustomFieldsSettings.getPredefinedValues()));
                    }

                    cfTypeValue.add(commonLocalizer.localize("na", "N/A"));

                    if (cfTypeValue != null && !cfTypeValue.isEmpty()) {
                        List<EdsCrmAccount> selectedCustomers = crmAccountManager.getCrmAccountsByIDs(selectedItems.get(0));
                        LinkedHashMap<String, List<EdsCrmAccount>> oppMap = new LinkedHashMap<>();
                        if (selectedCustomers != null) {
                            for (EdsCrmAccount customer : selectedCustomers) {
                                if (customer.getCustomFields() != null && customer.getCustomFields().getStringValue(budgetManagerItem.getGroupBy()) != null) {
                                    String key = customer.getCustomFields().getStringValue(budgetManagerItem.getGroupBy());
                                    if (oppMap.get(key) != null) {
                                        List<EdsCrmAccount> list = oppMap.get(key);
                                        list.add(customer);
                                        oppMap.replace(key, list);
                                    } else {
                                        List<EdsCrmAccount> list = new LinkedList<>();
                                        list.add(customer);
                                        oppMap.put(key, list);
                                    }
                                } else {
                                    if (oppMap.get(commonLocalizer.localize("na", "N/A")) != null) {
                                        List<EdsCrmAccount> list = oppMap.get(commonLocalizer.localize("na", "N/A"));
                                        list.add(customer);
                                        oppMap.replace(commonLocalizer.localize("na", "N/A"), list);
                                    } else {
                                        List<EdsCrmAccount> list = new LinkedList<>();
                                        list.add(customer);
                                        oppMap.put(commonLocalizer.localize("na", "N/A"), list);
                                    }
                                }
                            }

                            for (String cfValue : cfTypeValue) {

                                AccountItemsByAccountType customerType = new AccountItemsByAccountType(cfValue, null);
                                List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                                HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                                List<EdsCrmAccount> customers = oppMap.get(cfValue);

                                if (customers != null && !customers.isEmpty()) {
                                    for (EdsCrmAccount crmAccount : customers) {
                                        calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, null);
                                    }
                                    customerType.setBudgetItemTotal(budgetItemTotal);
                                    items.add(customerType.setAccountItems(budgetItemWithDate));
                                }

                            }
                        }
                    }
                } else if (companyCustomFieldsSettings != null && (Constants.UI_TYPE_LOOKUP.equals(companyCustomFieldsSettings.getUiType()) || Constants.UI_TYPE_MULTI_LOOKUP.equals(companyCustomFieldsSettings.getUiType()))) {
                    for (Integer groupId : selectedItems.keySet()) {
                        if (groupId != 0) {
                            List<EdsCrmAccount> selectedCustomers = crmAccountManager.getCrmAccountsByIDs(selectedItems.get(groupId));
                            if (selectedCustomers != null) {

                                CompanyCustomFieldItem companyCustomFieldItem = companyCustomFieldsSettings.getRPC(null);
                                String groupName = groupId == 0 ? commonLocalizer.localize("na", "N/A") : CustomFieldsUtils.getLookUpStringValue(companyCustomFieldItem, groupId);

                                AccountItemsByAccountType customerType = new AccountItemsByAccountType(groupName, groupId);
                                List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                                HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                                for (EdsCrmAccount crmAccount : selectedCustomers) {
                                    calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, groupId);
                                }
                                customerType.setBudgetItemTotal(budgetItemTotal);
                                items.add(customerType.setAccountItems(budgetItemWithDate));
                            }
                        }
                    }

                    List<EdsCrmAccount> selectedCustomers = crmAccountManager.getCrmAccountsByIDs(selectedItems.get(0));
                    if (selectedCustomers != null) {
                        String groupName = commonLocalizer.localize("na", "N/A");

                        AccountItemsByAccountType customerType = new AccountItemsByAccountType(groupName, 0);
                        List<AccountItemWithBudgetDate> budgetItemWithDate = new ArrayList<>();
                        HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal = new HashMap<>();

                        for (EdsCrmAccount crmAccount : selectedCustomers) {
                            calculateBudgetByCustomer(budgetManagerItem, crmAccount, budgetItemWithDate, editableBudgetMap, reportData, budgetItemTotal, 0);
                        }
                        customerType.setBudgetItemTotal(budgetItemTotal);
                        items.add(customerType.setAccountItems(budgetItemWithDate));
                    }
                }
            }
            budgetManagerItems.setItems(items);
        }

        return budgetManagerItems;

    }

