    private void mergeChildTotals(LinkedHashMap<String, HashMap<Date, BudgetInDate>> budgetItemChildTotal, HashMap<String, ArrayList<BudgetInDate>> childBudgetItemTotal) {

        for (String columnCode : childBudgetItemTotal.keySet()) {
            List<BudgetInDate> list = childBudgetItemTotal.get(columnCode);
            if (list != null) {
                for (BudgetInDate childTotal : list) {
                    if (childTotal != null && childTotal.getDate() != null && childTotal.getValue() != null && childTotal.getValue().compareTo(BigDecimal.ZERO) > 0) {
                        if (budgetItemChildTotal.get(columnCode) != null) {
                            HashMap<Date, BudgetInDate> budgetInDateHashMap = budgetItemChildTotal.get(columnCode);

                            if (budgetInDateHashMap.get(childTotal.getDate()) != null) {
                                BudgetInDate total = new BudgetInDate();
                                total.setDate(budgetInDateHashMap.get(childTotal.getDate()).getDate());

                                BigDecimal newTotal = childTotal.getValue() != null ? childTotal.getValue() : BigDecimal.ZERO;
                                newTotal = newTotal.add(budgetInDateHashMap.get(childTotal.getDate()).getValue());
                                total.setValue(newTotal);

                                budgetInDateHashMap.replace(childTotal.getDate(), total);
                            } else {
                                BudgetInDate total = new BudgetInDate();
                                total.setDate(childTotal.getDate());

                                BigDecimal newTotal = childTotal.getValue() != null ? childTotal.getValue() : BigDecimal.ZERO;
                                total.setValue(newTotal);

                                budgetInDateHashMap.put(childTotal.getDate(), total);
                            }
                            budgetItemChildTotal.replace(columnCode, budgetInDateHashMap);
                        } else {
                            HashMap<Date, BudgetInDate> budgetInDateHashMap = new HashMap<>();
                            BudgetInDate total = new BudgetInDate();
                            total.setDate(childTotal.getDate());
                            total.setValue(childTotal.getValue() != null ? childTotal.getValue() : BigDecimal.ZERO);

                            budgetInDateHashMap.put(childTotal.getDate(), total);
                            budgetItemChildTotal.put(columnCode, budgetInDateHashMap);
                        }
                    }
                }
            }
        }
    }

    private void calculateBudgetByProduct(BudgetManagerItem budgetManagerItem, EdsItem product, List<AccountItemWithBudgetDate> budgetItemWithDate, LinkedHashMap<String, Map<Integer, LinkedList<BudgetInDate>>> editableBudgetMap, LinkedHashMap<Integer, LinkedHashMap<Date, BudgetInDate>> reportData, HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal, Integer groupID) {
        AccountItemWithBudgetDate accountItemWithDate = new AccountItemWithBudgetDate(product.getObjectID(), product.getProductNumber(), product.getProductNumber() != null ? product.getProductNumber() + "->" + product.getName() : product.getName());

        if (product.getParent() != null && !product.getParent().getDeleted()) {
            accountItemWithDate.setParentId(product.getParent().getObjectID());
            accountItemWithDate.setParentCode(product.getParent().getProductNumber());
            accountItemWithDate.setParentName(product.getParent().getProductNumber() != null ? product.getParent().getProductNumber() + "->" + product.getParent().getName() : product.getParent().getName());
        }
        LinkedHashMap<String, LinkedList<BudgetInDate>> budgetData = getBudgetItemDataByColumn(budgetManagerItem, product.getObjectID(), editableBudgetMap, budgetItemTotal, groupID);
        if (budgetData != null) {
            accountItemWithDate.setBudgetData(budgetData);
        }
        budgetItemWithDate.add(accountItemWithDate);
    }

    private LinkedHashMap<String, LinkedList<BudgetInDate>> getBudgetItemDataByColumn(BudgetManagerItem budgetManagerItem, Integer entityID, LinkedHashMap<String, Map<Integer, LinkedList<BudgetInDate>>> editableBudgetMap, HashMap<String, ArrayList<BudgetInDate>> budgetItemTotal, Integer groupId) {
        LinkedHashMap<String, LinkedList<BudgetInDate>> budgetData = new LinkedHashMap<>();
        if (budgetManagerItem.getColumns() != null) {
            for (BudgetColumn budgetColumn : budgetManagerItem.getColumns()) {

                if (Constants.EDITABLE.equals(budgetColumn.getType())) {
                    if (editableBudgetMap.get(budgetColumn.getCode()) != null && editableBudgetMap.get(budgetColumn.getCode()).get(entityID) != null) {
                        LinkedList<BudgetInDate> budgetInDatesByGroup = new LinkedList<>();
                        LinkedList<BudgetInDate> budgetInDates = editableBudgetMap.get(budgetColumn.getCode()).get(entityID);
                        if (groupId != null) {
                            for (BudgetInDate budgetInDate : budgetInDates) {
                                if (groupId.equals(budgetInDate.getGroupId())) {
                                    budgetInDatesByGroup.add(budgetInDate);
                                }
                            }
                        } else {
                            budgetInDatesByGroup = budgetInDates;
                        }

                        budgetData.put(budgetColumn.getCode(), budgetInDatesByGroup);
                        boolean isNew = false;
                        ArrayList<BudgetInDate> result = budgetItemTotal.get(budgetColumn.getCode()) != null ? budgetItemTotal.get(budgetColumn.getCode()) : new ArrayList<>();
                        for (int i = 0; i < budgetInDatesByGroup.size(); i++) {
                            BudgetInDate bInDate = budgetInDatesByGroup.get(i);
                            if (result != null && !result.isEmpty()) {
                                boolean isExist = false;
                                for (BudgetInDate total : result) {
                                    if (total.getDate().equals(bInDate.getDate())) {
                                        total.setValue(total.getValue().add(bInDate.getValue()));
                                        isExist = true;
                                    }
                                }
                                if (!isExist) {
                                    result.add(new BudgetInDate(bInDate.getAccountBudgetID(), bInDate.getProfitID(), bInDate.getDate(), bInDate.getValue(), bInDate.getActualValue()));
                                }
                            } else {
                                if (i == 0) {
                                    isNew = true;
                                }
                                result.add(new BudgetInDate(bInDate.getAccountBudgetID(), bInDate.getProfitID(), bInDate.getDate(), bInDate.getValue(), bInDate.getActualValue()));
                            }
                        }
                        if (!isNew) {
                            budgetItemTotal.replace(budgetColumn.getCode(), result);
                        } else {
                            budgetItemTotal.put(budgetColumn.getCode(), result);
                        }

                    }
                }
            }
        }
        return budgetData;
    }

