    private BudgetManagerItems getAccountBudgetItems(boolean isAsc, FromToDate[] actualRanges, LinkedHashMap<String, Map<Integer, LinkedList<BudgetInDate>>> editableBudgetMap, HashMap<Integer, List<Integer>> selectedItems, BudgetManagerItem budgetManagerItem) {
        List<EdsAccount> expRevAccounts = null;
        StringBuilder ids = new StringBuilder();
        if (selectedItems != null) {
            for (List<Integer> accountIds : selectedItems.values()) {
                if (accountIds != null && !accountIds.isEmpty()) {
                    String coma = "";
                    for (Object id : accountIds) {
                        ids.append(coma);
                        ids.append(id);
                        coma = ",";

                    }
                }
            }
        }
        if (!"".contentEquals(ids)) {
            expRevAccounts = accountingManager.getAccountsByIds(ids.toString());

            if (isAsc) {
                expRevAccounts.sort(accountList.get(ACC_NAME));
            } else {
                expRevAccounts.sort(accountListDesc.get(ACC_NAME));
            }
        }
        BudgetManagerItems budgetManagerItems = new BudgetManagerItems();
        AccountItemsByAccountType revenue = new AccountItemsByAccountType(commonLocalizer.localize("revenue", "Revenue"));
        AccountItemsByAccountType otherIncome = new AccountItemsByAccountType(commonLocalizer.localize("OTHER_INCOME", "Other Income"));
        AccountItemsByAccountType sale = new AccountItemsByAccountType(commonLocalizer.localize("sales", "Sales"));
        AccountItemsByAccountType depreciation = new AccountItemsByAccountType(commonLocalizer.localize("depreciation", "Depreciation"));
        AccountItemsByAccountType directCosts = new AccountItemsByAccountType(commonLocalizer.localize("directCosts", "Direct Costs"));
        AccountItemsByAccountType expense = new AccountItemsByAccountType(commonLocalizer.localize("expenses", "Expenses"));
        AccountItemsByAccountType overhead = new AccountItemsByAccountType(commonLocalizer.localize("overhead", "Overhead"));

        List<AccountItemWithBudgetDate> revenueWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> otherIncomeWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> saleWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> depreciationWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> directCostsWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> expenseWithDate = new ArrayList<>();
        List<AccountItemWithBudgetDate> overheadWithDate = new ArrayList<>();

        HashMap<String, ArrayList<BudgetInDate>> revenueTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> otherIncomeTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> saleTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> depreciationTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> directCostsTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> expenseTotal = new LinkedHashMap<>();
        HashMap<String, ArrayList<BudgetInDate>> overheadTotal = new LinkedHashMap<>();

        List<BudgetInDate> revenueTotalActual = new ArrayList<>();
        List<BudgetInDate> otherIncomeTotalActual = new ArrayList<>();
        List<BudgetInDate> saleTotalActual = new ArrayList<>();
        List<BudgetInDate> depreciationTotalActual = new ArrayList<>();
        List<BudgetInDate> directCostsTotalActual = new ArrayList<>();
        List<BudgetInDate> expenseTotalActual = new ArrayList<>();
        List<BudgetInDate> overheadTotalActual = new ArrayList<>();

        ArrayList<BudgetInDate> grossProfit = new ArrayList<>();
        ArrayList<BudgetInDate> netProfit = new ArrayList<>();

        if (expRevAccounts != null) {
            for (EdsAccount account : expRevAccounts) {
                switch (account.getAccountType().getCode()) {
                    case EdsAccountType.REVENUE ->
                            calculateBudgetByAccount2(budgetManagerItem, account, revenueWithDate, editableBudgetMap, actualRanges, revenueTotal);
                    case OTHER_INCOME ->
                            calculateBudgetByAccount2(budgetManagerItem, account, otherIncomeWithDate, editableBudgetMap, actualRanges, otherIncomeTotal);
                    case SALES ->
                            calculateBudgetByAccount2(budgetManagerItem, account, saleWithDate, editableBudgetMap, actualRanges, saleTotal);
                    case EdsAccountType.DEPRECIATION ->
                            calculateBudgetByAccount2(budgetManagerItem, account, depreciationWithDate, editableBudgetMap, actualRanges, depreciationTotal);
                    case EdsAccountType.DIRECT_EXPENSES ->
                            calculateBudgetByAccount2(budgetManagerItem, account, directCostsWithDate, editableBudgetMap, actualRanges, directCostsTotal);
                    case EdsAccountType.COST_OF_SALES ->
                            calculateBudgetByAccount2(budgetManagerItem, account, expenseWithDate, editableBudgetMap, actualRanges, expenseTotal);
                    case OVERHEAD ->
                            calculateBudgetByAccount2(budgetManagerItem, account, overheadWithDate, editableBudgetMap, actualRanges, overheadTotal);
                }
            }
        }
        revenue.setBudgetItemTotal(revenueTotal);
        budgetManagerItems.setRevenue(revenue.setAccountItems(revenueWithDate).setActualTotal(revenueTotalActual));
        otherIncome.setBudgetItemTotal(otherIncomeTotal);
        budgetManagerItems.setOtherIncome(otherIncome.setAccountItems(otherIncomeWithDate).setActualTotal(otherIncomeTotalActual));
        sale.setBudgetItemTotal(saleTotal);
        budgetManagerItems.setSale(sale.setAccountItems(saleWithDate).setActualTotal(saleTotalActual));
        depreciation.setBudgetItemTotal(depreciationTotal);
        budgetManagerItems.setDepreciation(depreciation.setAccountItems(depreciationWithDate).setActualTotal(depreciationTotalActual));
        directCosts.setBudgetItemTotal(directCostsTotal);
        budgetManagerItems.setDirectCosts(directCosts.setAccountItems(directCostsWithDate).setActualTotal(directCostsTotalActual));
        expense.setBudgetItemTotal(expenseTotal);
        budgetManagerItems.setExpense(expense.setAccountItems(expenseWithDate).setActualTotal(expenseTotalActual));
        overhead.setBudgetItemTotal(overheadTotal);
        budgetManagerItems.setOverhead(overhead.setAccountItems(overheadWithDate).setActualTotal(overheadTotalActual));
        budgetManagerItems.setGrossProfit(grossProfit);
        budgetManagerItems.setNetProfit(netProfit);
        budgetManagerItems.setCurrency(financialSettingsManager.getFinancialSettings().getCurrency().getAsSelectItem());
        LinkedList<AccountItemsByAccountType> items = new LinkedList<>();
        if (budgetManagerItems.getRevenue() != null && budgetManagerItems.getRevenue().getAccountItems() != null && budgetManagerItems.getRevenue().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getRevenue());
        }
        if (budgetManagerItems.getSale() != null && budgetManagerItems.getSale().getAccountItems() != null && budgetManagerItems.getSale().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getSale());
        }
        if (budgetManagerItems.getOtherIncome() != null && budgetManagerItems.getOtherIncome().getAccountItems() != null && budgetManagerItems.getOtherIncome().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getOtherIncome());
        }

        if (budgetManagerItems.getDirectCosts() != null && budgetManagerItems.getDirectCosts().getAccountItems() != null && budgetManagerItems.getDirectCosts().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getDirectCosts());
        }

        if (budgetManagerItems.getExpense() != null && budgetManagerItems.getExpense().getAccountItems() != null && budgetManagerItems.getExpense().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getExpense());
        }

        if (budgetManagerItems.getOverhead() != null && budgetManagerItems.getOverhead().getAccountItems() != null && budgetManagerItems.getOverhead().getAccountItems().length > 0) {
            items.add(budgetManagerItems.getOverhead());
        }

        budgetManagerItems.setItems(items);
        return budgetManagerItems;
    }

    private void verticalMergeChildTotal(HashMap<String, ArrayList<BudgetInDate>> parents, LinkedHashMap<String, HashMap<Date, BudgetInDate>> budgetItemChildTotal) {

        for (String columnCode : budgetItemChildTotal.keySet()) {
            HashMap<Date, BudgetInDate> budgetItemChildMap = budgetItemChildTotal.get(columnCode);

            for (BudgetInDate childTotal : budgetItemChildMap.values()) {
                if (parents != null && !parents.isEmpty()) {
                    ArrayList<BudgetInDate> parentBudgetInDates = parents.get(columnCode) != null ? parents.get(columnCode) : new ArrayList<>();

                    boolean isExist = false;
                    for (BudgetInDate parentTotal : parentBudgetInDates) {
                        if (parentTotal != null && parentTotal.getDate().equals(childTotal.getDate())) {
                            parentTotal.setValue(parentTotal.getValue().add(childTotal.getValue()));
                            isExist = true;
                        }
                    }
                    if (!isExist) {
                        parentBudgetInDates.add(childTotal);
                    }

                    if (parents.get(columnCode) != null) {
                        parents.replace(columnCode, parentBudgetInDates);
                    } else {
                        parents.put(columnCode, parentBudgetInDates);
                    }

                } else {
                    ArrayList<BudgetInDate> totalList = new ArrayList<>();
                    totalList.add(childTotal);
                    parents.put(columnCode, totalList);
                }
            }
        }
    }

    private void verticalMerge(List<BudgetInDate> result, List<BudgetInDate> budgetInOneAccount) {
        if (budgetInOneAccount == null) {
            return;
        }//There is no any budgeted items in database
        for (int i = 0; i < budgetInOneAccount.size(); i++) {
            if (i >= result.size()) {//create instances only first time
                BudgetInDate bInDate = budgetInOneAccount.get(i);
                result.add(i, new BudgetInDate(bInDate.getAccountBudgetID(), bInDate.getProfitID(), bInDate.getDate(), bInDate.getValue()));
            } else {
                result.get(i).setValue(result.get(i).getValue().add(budgetInOneAccount.get(i).getValue()));
            }
        }
    }

    private void verticalMergeMinus(List<BudgetInDate> result, List<BudgetInDate> budgetInOneAccount) {
        for (int i = 0; i < budgetInOneAccount.size(); i++) {
            if (i >= result.size()) {
                BudgetInDate bInDate = budgetInOneAccount.get(i);
                result.add(i, new BudgetInDate(bInDate.getDate(), BigDecimal.ZERO.subtract(bInDate.getValue())));
            } else {
                result.get(i).setValue(result.get(i).getValue().subtract(budgetInOneAccount.get(i).getValue()));
            }
//
//            if (i >= result.size()) {//create instances only first time
//                BudgetInDate bInDate = budgetInOneAccount.get(i);
//                result.add(i, new BudgetInDate(bInDate.getAccountBudgetID(), bInDate.getProfitID(), bInDate.getDate(), bInDate.getValue()));
//            } else {
//                result.get(i).setValue(result.get(i).getValue().add(budgetInOneAccount.get(i).getValue()));
//            }
        }
    }

