        Page<ChartOfAccountSolrDoc> chartOfAccountSolrDocs = chartOfAccountSolrComponent.getList(filterParametrs, solrQuery.toString());
        return getChartOfAccountFromSolrResult(chartOfAccountSolrDocs, filterParametrs);
