    private SolrParams getChartOfAccountSolrQuery(ListingFilterParameter fp, String solrQuery) {
        SolrQuery query = new SolrQuery();
        query.setQuery(solrQuery);
        query.setStart(fp.getStart());
        query.setParam(CommonParams.ROWS, String.valueOf(fp.getLimit()));

        if (fp.getSortField() != null && !"".equals(fp.getSortField())) {
            boolean desc = !fp.isAscending();
            if (AccountListItem.NAME.equals(fp.getSortField())) {
                query.setSort(SolrChartOfAccountRepresenter.SORTABLE_NAME, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            } else if (AccountListItem.CODE.equals(fp.getSortField())) {
                query.setSort(SolrChartOfAccountRepresenter.SORTABLE_CODE, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            } else if (AccountListItem.PARENT.equals(fp.getSortField())) {
                query.setSort(SolrChartOfAccountRepresenter.SORTABLE_PARENT_NAME, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            } else if (AccountListItem.TYPE.equals(fp.getSortField())) {
                query.setSort(SolrChartOfAccountRepresenter.SORTABLE_TYPE_NAME, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            } else if (AccountListItem.CURRENCY.equals(fp.getSortField())) {
                query.setSort(SolrChartOfAccountRepresenter.SORTABLE_CURRENCY_NAME, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            } else {
                query.setSort(SolrChartOfAccountRepresenter.FIELD_LAST_UPDATED_DATE, (desc
                        ? SolrQuery.ORDER.desc
                        : SolrQuery.ORDER.asc));
            }
        } else {
            query.setSort(SolrChartOfAccountRepresenter.FIELD_LAST_UPDATED_DATE, SolrQuery.ORDER.desc);
        }
        return query;
    }

    private ListResult<AccountListItem> getChartOfAccountFromSolrResult(Page<ChartOfAccountSolrDoc> accountSolrDocs, ListingFilterParameter fp) {
        ArrayList<AccountListItem> result = Lists.newArrayList();
        int count = 0;
        if (accountSolrDocs != null && accountSolrDocs.getContent() != null) {
            count = (int) accountSolrDocs.getTotalElements();
            Map<Integer, AccountListItem> balanceMap = accountingManager.getAccountBalanceMap(accountSolrDocs.getContent().stream().map(ChartOfAccountSolrDoc::getAccountId).collect(Collectors.toList()));
            for (ChartOfAccountSolrDoc doc : accountSolrDocs.getContent()) {
                Integer accountId = doc.getAccountId();
                AccountListItem item = new AccountListItem();

                AccountListItem balanceItem = balanceMap.get(accountId);
                if (balanceItem != null) {
                    item.setBalance(balanceItem.getBalance());
                    item.setEditable(balanceItem.isEditable());
                }
                if (!fp.isCheckNumber() || (fp.isCheckNumber() && BigDecimal.ZERO.compareTo(item.getBalance()) != 0)) {
                    item.setObjectID(accountId);
                    item.setName(doc.getName());
                    item.setAccountType(accountingLocalizer.localize(doc.getTypeCode(), doc.getTypeName()));
                    item.setCode(doc.getCode());
                    item.setCurrency(doc.getCurrencyName());
                    item.setParentName(doc.getParentName());
                    item.setLastUpdatedDate(doc.getLastUpdatedDate());
                    item.setActive(doc.getBankAccountActive());
                    item.setShowInExpense(doc.getShowInExpense());
                    item.setActive(doc.isActive());
                    item.setEnablePayments(doc.getEnablePayments());
                    item.setChartOfAccountkey(doc.getChartOfAccountKey());
                    result.add(item);
                }
            }
        }
        return new ListResult<>(result, count);
    }

