    private EdsAccountCustomFields createAccountCustomFields(EdsAccountCustomFields
                                                                     edsAccountCustomFields, List<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            if (edsAccountCustomFields == null) {
                boolean isEmpty = true;
                for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                    if ((fieldItem.getFieldStringValue() != null && !"".equals(fieldItem.getFieldStringValue()))
                            || fieldItem.getFieldDateNonConvertedValue() != null || (fieldItem.getAttachments() != null && fieldItem.getAttachments().length > 0)
                            || (fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty())) {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty) {
                    return null;
                }
                edsAccountCustomFields = new EdsAccountCustomFields();
                accountCFManager.create(edsAccountCustomFields);
            }
            CustomFieldsUtils.setDomenObjectCustomFields(edsAccountCustomFields, customFieldItems);
            return edsAccountCustomFields;
        }
        return null;
    }

