    private void createConversionBallance(EdsInvoiceTransaction
                                                  newTransaction, List<EdsTransactionItem> conversionTransactionItems) {
        List<EdsTransactionItem> itemsToDelete = new ArrayList<>();//items marked to be deleted
        for (EdsTransactionItem convItem : conversionTransactionItems) {
            BigDecimal convDebit = convItem.getDebit();
            BigDecimal convCredit = convItem.getCredit();
            for (EdsTransactionItem newItem : newTransaction.getTransactionItems()) {
                if (newItem.getAccount().equals(convItem.getAccount())) {
                    BigDecimal newDebit = newItem.getDebit();
                    BigDecimal newCredit = newItem.getCredit();
                    if (RECEIVABLE.equals(newTransaction.getInvoice().getType())) {//if invoice is receivable
                        if (newItem.getAccount().getKey() != null && EdsAccount.ACCOUNTS_RECEIVABLE == newItem.getAccount().getKey()) {//if receivable account occured
                            assert (newDebit.compareTo(convDebit) <= 0);
                            convDebit = convDebit.subtract(newDebit);
                            if (convDebit.compareTo(ZERO) == 0) {
                                itemsToDelete.add(convItem);
                            }
                        } else {//for all other accounts
                            if (convCredit.compareTo(ZERO) != 0) {
                                if (convCredit.compareTo(newCredit) > 0) {
                                    convCredit = convCredit.subtract(newCredit);
                                } else if (convCredit.compareTo(newCredit) < 0) {
                                    convDebit = newCredit.subtract(convCredit);
                                } else {//if equal
                                    itemsToDelete.add(convItem);//remove it
                                }
                            } else if (convDebit.compareTo(ZERO) != 0) {
                                convDebit = convDebit.add(newCredit);
                            }
                        }
                    } else if (PAYABLE.equals(newTransaction.getInvoice().getType())) {//if invoice is Payable
                        if (newItem.getAccount().getKey() != null && EdsAccount.ACCOUNTS_PAYABLE == newItem.getAccount().getKey()) {//if GL account name is Payable
                            assert (newCredit.compareTo(convCredit) <= 0);
                            convCredit = convCredit.subtract(newCredit);
                            if (convCredit.compareTo(ZERO) == 0) {
                                itemsToDelete.add(convItem);
                            }
                        } else { //for all other accounts
                            if (convDebit.compareTo(ZERO) != 0) {
                                if (convDebit.compareTo(newDebit) > 0) {
                                    convDebit = convDebit.subtract(newDebit);
                                } else if (convDebit.compareTo(newDebit) < 0) {
                                    convCredit = newDebit.subtract(convDebit);
                                } else {
                                    itemsToDelete.add(convItem);
                                }
                            } else if (convCredit.compareTo(ZERO) != 0) {
                                convCredit = convCredit.add(newDebit);
                            }
                        }
                    }

                }
            }
            convItem.setDebit(convDebit);
            convItem.setCredit(convCredit);
        }
        conversionTransactionItems.removeAll(itemsToDelete);
    }

    /**
     * Revoves GL account and invoices attended in this account
     *
     * @param accountID GL account id
     * @return returns true if account has been deleted and false if account attended in invoice and hence can not be deleted
     */
    public DeleteRPC removeGLAccount(Integer accountID) {
        DeleteRPC deleteResult = new DeleteRPC();
        EdsAccount account = accountingManager.get(accountID);

        Long productCount = itemManager.getProductsCountByAccountCOGSAccountAssetAccount(accountID);
        if (productCount != null && productCount > 0) {
            StringBuilder productNumbers = new StringBuilder();
            for (String productNumber : itemManager.getProductsNumberByAccountCOGSAccountAssetAccount(accountID)) {
                productNumbers.append(productNumber + ", ");
            }
            deleteResult.setDeleted(false);
            deleteResult.setMessage("Account is used in Product(s)/Service(s): " + productNumbers.substring(0, productNumbers.toString().length() - 2));
            return deleteResult;
        }

        if (account != null && account.isUsedInSystem()) {
            deleteResult.setDeleted(false);
            deleteResult.setMessage("Account is used in system");
            return deleteResult;
        }
        if (account != null && account.getKey() != null) {
            deleteResult.setDeleted(false);
            deleteResult.setMessage("Account is default in system");
            return deleteResult;
        }
        EdsBankAccount bankAccount = bankAccountManager.getBankAccountByAccountID(accountID);
        if (bankAccount != null && bankAccount.isUsedInSystem()) {
            deleteResult.setDeleted(false);
            deleteResult.setMessage("Bank Account is used in system");
            return deleteResult;
        }

        if (account != null) {
            EdsBusinessEvent event = baseEventPostProcessor.registerEvent(ChartOfAccountEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_DELETE, account, userManager.getUser());
            event.setCustomStringField(account.getCodeString());
            account.setDeleted(true);
            accountingManager.update(account);
            //deleted account childs make as parent
            Integer parentID;
            List<EdsAccount> edsAccountChildren = Lists.newArrayList();
            if (account.getChildList() != null && !account.getChildList().isEmpty()) {
                for (EdsAccount child : account.getChildList()) {
                    if (child != null) {
                        parentID = child.getParent() != null ? child.getParent().getObjectID() : null;
                        child.setParent(null);
                        accountingManager.update(child);
                        if (parentID != null) {
                            edsAccountChildren.add(child);
                        }
                        log.info("Deleted account - " + child.getObjectID() + " set parent id null. This account parent id was - " + parentID);
                    }
                }
            }

            //update related crm account
            boolean isReceivable = (Integer.valueOf(EdsAccount.ACCOUNTS_RECEIVABLE).equals(account.getKey()) || Integer.valueOf(EdsAccount.ACCOUNTS_RECEIVABLE).equals(account.getGroupKey()));
            crmAccountManager.updateCrmAccountsByAccountType(account.getObjectID(), isReceivable);

            try {
                solrManager.removeChartOfAccount(account.getObjectID(), SecurityContext.getCompanyID());
            } catch (SolrServerException | IOException e) {
                e.printStackTrace();
            }

            if (!edsAccountChildren.isEmpty()) {
                try {
                    chartOfAccountSolrComponent.indexes(edsAccountChildren);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }

            KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
            kpiLog.setEntityName(EdsAccount.class.getSimpleName());
            kpiLog.setActionType(KpiLog.ActionType.DELETE);
            kpiLog.setEntityId(account.getObjectID());
            ServerUtils.kpiLog(log, kpiLog, "delete Account");
        } else {
            System.out.println("Can't delete account because of account is null");
        }
        deleteResult.setDeleted(true);
        deleteResult.setMessage("Deleted Successfully");
        return deleteResult;
    }

    public Boolean deleteSelectedAccounts(ArrayList<Integer> ids) {
        Boolean result = null;
        int countDeleted = 0;
        int size = ids.size();
        for (Integer objectID : ids) {
            DeleteRPC deleted = removeGLAccount(objectID);
            if (deleted.getDeleted()) {
                countDeleted++;
            }
        }
        if (countDeleted == size) {
            result = true;
        } else if (countDeleted != 0) {
            result = false;
        }
        return result;
    }

