    public EdsFinancialSettings saveFinancialSettingsNew(FinancialSettingsItem fs) {
        EdsCompany company = financialSettingsManager.getUser().getCompany();
        EdsFinancialSettings settings = financialSettingsManager.getFinancialSettings();

        if (settings == null) {
            settings = new EdsFinancialSettings();
        }
        //agar base currency ozgarsa - Chart of Accounting dagi currency update qilinadi.
        if (settings.getCurrency() != null && fs.getCurrencyId() != null && !settings.getCurrency().getObjectID().equals(fs.getCurrencyId())) {
            accountingManager.updateAccountCurrency(currencyManager.get(fs.getCurrencyId()));
            //if base currency changes then delete if the new one is already using
            currencyService.deleteCurrency(fs.getCurrencyId());

            allChartOfAccountSolrReindexByCurrency(fs.getCurrencyId());
        }
        settings.setCurrency(currencyManager.get(fs.getCurrencyId()));//set hours minutes seconds mills to financial year end

        if (fs.getConversionDate() != null) {
            settings.setConversionDate(fs.getConversionDate());
        }

        if (fs.getVatRegistered() != null) {
            settings.setVatRegistered(fs.getVatRegistered());
        }
        settings.setFinancialYearEnd(fs.getFinYearEnd().getNonConvertedDate());
        settings.setTaxIdNumber(fs.getTaxIdNumber());
        settings.setTaxIdDisplayNumber(fs.getTaxIdDisplayNumber());
        settings.setTinNumber(fs.getTinNumber());
        settings.setTinDisplayName(fs.getTinDisplayName());
        settings.setOtpNumber(fs.getOtpNumber());
        settings.setCustomVatName(fs.getCustomVatName());
        settings.setEnableContractOutsite(fs.isEnableContractOutsite());
        settings.setVatAccountingBasis(fs.getVatAccountingBasis());
        settings.setEnableReverseCharge(fs.getEnableReverseCharge());

        if (ServerUtils.isUKCompany(userManager.getUser().getCompany())) {
            settings.setSubmitVatManually(fs.getSubmitVatManually() != null && fs.getSubmitVatManually());
        } else {
            settings.setSubmitVatManually(true);
        }

        if (fs.getVatRegisteredOn() != null) {
            settings.setVatRegisteredOn(fs.getVatRegisteredOn().getNonConvertedDate());
        }
        if (fs.getTaxGenerationDate() != null) {
            settings.setTaxGenerationDate(fs.getTaxGenerationDate().getNonConvertedDate());
        }
        if (settings.isEnableContractOutsite()) {
            genericSettingsManager.saveGenericSettings(null, GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE, EdsGenericSettings.YES);
        } else {
            genericSettingsManager.saveGenericSettings(null, GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE, EdsGenericSettings.NO);
        }
        if (fs.getTaxPeriodId() != null) {
            settings.setTaxPeriod(referenceManager.get(fs.getTaxPeriodId()));
        }
        if (fs.getTaxBasisId() != null) {
            settings.setTaxBasis(referenceManager.get(fs.getTaxBasisId()));
        }
        settings.setFlatRateReturn(fs.getFlatRate());
        settings.setShowVatNumberInInvoices(fs.getShowVatNumberInInvoices());
        settings.setUpdateCostPriceOnPurhcase(fs.getUpdateCostPriceOnPurhcase());
        settings.setEnableIT(fs.enableIT());
        settings.setAutomaticExRateUpdate(fs.isAutomaticExRateUpdate());

        if (fs.getCloseBeforeDate() != null && fs.getCloseBeforeDate().getDate() != null) {
            settings.setBlockBeforeDate(fs.getCloseBeforeDate().getNonConvertedDate());
        } else {
            settings.setBlockBeforeDate(null);
        }

        settings.setRestrictCreatingOrUpdatingInvoices(fs.isRestrictCreatingOrUpdatingInvoices());
        settings.setMandatoryProjectForExpenseClaims(fs.getMandatoryProjectForExpenseClaims());
        settings.setMandatoryProjectForPurchaseOrders(fs.getMandatoryProjectForPurchaseOrders());
        settings.setRoundingExchRate(fs.getRoundingExchRate());
        settings.setCalculationScale(fs.getCalculationScale());
        settings.setShowVatNumberInListings(fs.isShowCustomTaxInListing());
        settings.setShowVatReturnReport(fs.getVatReturnReportVisibility());
        settings.setEnablePostedDateTransaction(fs.isEnablePostDatedTransactions());
        settings.setEnableDoubleMessage(fs.getEnableDoubleMessage());
        settings.setIncomeTaxPeriod(fs.getIncomeTaxPeriodID() != null
                ? referenceManager.get(fs.getIncomeTaxPeriodID())
                : null);
        settings.setIncomeTaxRate(fs.getIncomeTaxRate());
        settings.setIncomeTaxAccount(fs.getIncomeTaxAccount() != null ? fs.getIncomeTaxAccount().getId() : null);
        settings.setEnableMultipleSalesPrice(fs.isEnableMultiSalesPrice());
        settings.setEnableDiscountAccount(fs.getEnableDiscountAccount());
        settings.setRoyality(fs.getRoyality());
        settings.setMinRoyality(fs.getMinRoyality());
        settings.setMarketing(fs.getMarketing());
        settings.setMinMarketing(fs.getMinMarketing());
        settings.setEnableDepreciationDatePeriod(fs.getEnableDepreciationDatePeriod());
        settings.setEnableBatchTrackingItems(fs.getEnableBatchTrackingItems());
        settings.setEnableLandedCost(fs.getEnableLandedCost());
        settings.setEnableMultiWarehouse(fs.getEnableMultiWarehouse());
        settings.setEnableDeferredTransaction(fs.getEnableDeferredTransaction());
        settings.setEnableAccountingDepartmentRelation(fs.getEnableAccountingDepartmentRelation());
        settings.setAgedFilterInterval(fs.getAgedFilterInterval());
        settings.setAgedPastDueDays(fs.getAgedPastDueDays());

        /*-----Creating Default Tax Rates End-----*/
        // Set 3 digits to Omand and Kuwait
        EdsCountry country = company.getCountryZone() != null ? company.getCountryZone().getCountry() : null;
        if (country != null && country.getCode() != null && fs.isFromGettingStarted()) {
            if ("OM".equals(country.getCode()) || "KW".equals(country.getCode())) {
                settings.setProductQuantity(3);
                settings.setProductPriceScale(3);
                settings.setCalculationScale(3);
            }
        }
        String key = company.getObjectID() + "_" + CacheConstants.CALCULATION_SCALE;
        RedisClient.setKey(key, settings.getCalculationScale() != null
                ? settings.getCalculationScale()
                : EdsFinancialSettings.SYSTEM_CALCULATION_SCALE, Integer.class);

        if (fs.getEnableDiscountAccount()) {
            setupDiscountAccounts();
        }

        if (settings.isEnableDeferredTransaction()) {
            configureDeferredTransactionsTrigger();
        } else {
            removeDeferredTransactionConfig();
        }
        financialSettingsManager.createOrUpdate(settings);
        if ("SA".equals(country.getCode()) && !ServerUtils.isNullOrEmpty(fs.getTinDisplayName()) && !ServerUtils.isNullOrEmpty(fs.getTinNumber())) {
            try {
                zatcaService.initSettings();
            } catch (ZatcaException e) {
                e.printStackTrace();
            }
        }
        return settings;
    }

