    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public FinancialSettingsItem getCompanyFinancialSettings() {
        FinancialSettingsItem fsi = new FinancialSettingsItem();
        try {
            EdsCompany company = financialSettingsManager.getUser().getCompany();
            if (company.getLocale() != null) {
                fsi.setLocaleCode(company.getLocale());
            } else {
                fsi.setLocaleCode(Locale.ENGLISH.getLanguage());
            }
            List<EdsCurrency> currencyList = currencyManager.getAllCurrency();
            CurrencyItem[] currencies = new CurrencyItem[currencyList.size()];

            int i = 0;
            for (EdsCurrency item : currencyList) {
                currencies[i] = item.createCurrencyItem();
                i++;
            }
            fsi.setCurrencies(currencies);
            fsi.setTaxPeriods(getTaxPeriods());
            fsi.setTaxBasises(getTaxBasises());

            EdsCountry country = company.getCountryZone().getCountry();
            fsi.setUKCompany(country != null && country.getCode() != null && "GB".equals(country.getCode()));
            EdsFinancialSettings fs = financialSettingsManager.getFinancialSettings();

            if (fs != null) {
                fsi.setObjectId(fs.getObjectID());
                if (fs.getCurrency() != null) {
                    fsi.setCurrencyId(fs.getCurrency().getObjectID());
                    fsi.setCurrencyName(fs.getCurrency().getName());
                    fsi.setCurrencySymbol(fs.getCurrency().getSymbol());
                }
                if (fs.getFinancialYearEnd() != null) {
                    fsi.setFinYearEnd(new DateNonConvertable(fs.getFinancialYearEnd()));
                }
                if (fs.getConversionDate() != null) {
                    fsi.setConversionDate(new Date(fs.getConversionDate().getTime()));
                }
                fsi.setProductPrice(fs.getProductPriceScale());
                fsi.setProductQuantity(fs.getProductQuantity());
                fsi.setTaxIdNumber(fs.getTaxIdNumber());
                fsi.setTaxIdDisplayNumber(fs.getTaxIdDisplayNumber());
                fsi.setTinNumber(fs.getTinNumber());
                fsi.setTinDisplayName(fs.getTinDisplayName());
                fsi.setCustomVatName(fs.getCustomVatName());
                fsi.setEnableContractOutsite(fs.isEnableContractOutsite());
                fsi.setVatAccountingBasis(fs.getVatAccountingBasis());
                fsi.setSubmitVatManually(fs.isSubmitVatManually());

                if (fs.getVatRegisteredOn() != null) {
                    fsi.setVatRegisteredOn(new DateNonConvertable(fs.getVatRegisteredOn()));
                }
                if (fs.getTaxGenerationDate() != null) {
                    fsi.setTaxGenerationDate(new DateNonConvertable(fs.getTaxGenerationDate()));
                }
                if (fs.getTaxPeriod() != null) {
                    fsi.setTaxPeriodId(fs.getTaxPeriod().getObjectID());
                }
                if (fs.getTaxBasis() != null) {
                    fsi.setTaxBasisId(fs.getTaxBasis().getObjectID());
                }
                fsi.setFlatRate(fs.getFlatRateReturn());
                fsi.setVatRegistered(fs.isVatRegistered());
                fsi.setShowVatNumberInInvoices(fs.isShowVatNumberInInvoices());
                fsi.setUpdateCostPriceOnPurhcase(fs.getUpdateCostPriceOnPurhcase());
                fsi.setShowCustomTaxInListing(fs.isShowVatNumberInListings());
                fsi.setEnableIT(fs.enableIT()); //set Enable Inventory Transaction;(this is by normurod)
                fsi.setAutomaticExRateUpdate(fs.isAutomaticExRateUpdate());
                if (fs.getBlockBeforeDate() != null) {
                    fsi.setCloseBeforeDate(new DateNonConvertable(fs.getBlockBeforeDate()));
                } else {
                    fsi.setCloseBeforeDate(null);
                }
                fsi.setRoundingExchRate(fs.getRoundingExchRate());
                fsi.setCalculationScale(fs.getCalculationScale());
                fsi.setEnablePostDatedTransactions(fs.isEnablePostedDateTransaction());
                fsi.setEnableDoubleMessage(fs.getEnableDoubleMessage() != null ? fs.getEnableDoubleMessage() : false);
                fsi.setIncomeTaxPeriodID(fs.getIncomeTaxPeriod() != null
                        ? fs.getIncomeTaxPeriod().getObjectID()
                        : null);
                fsi.setIncomeTaxRate(fs.getIncomeTaxRate());
                fsi.setEnableMultiSalesPrice(fs.isEnableMultipleSalesPrice());
                fsi.setEnableDiscountAccount(fs.getEnableDiscountAccount());
                fsi.setRoyality(fs.getRoyality());
                fsi.setMinRoyality(fs.getMinRoyality());
                fsi.setMarketing(fs.getMarketing());
                fsi.setMinMarketing(fs.getMinMarketing());
                fsi.setEnableDepreciationDatePeriod(fs.getEnableDepreciationDatePeriod());
                fsi.setEnableBatchTrackingItems(fs.getEnableBatchTrackingItems());
                fsi.setEnableLandedCost(fs.getEnableLandedCost());
                fsi.setEnableMultiWarehouse(fs.getEnableMultiWarehouse());
                fsi.setEnableDeferredTransaction(fs.isEnableDeferredTransaction());
                fsi.setEnableAccountingDepartmentRelation(fs.getEnableAccountingDepartmentRelation());
                fsi.setRestrictCreatingOrUpdatingInvoices(fs.getRestrictCreatingOrUpdatingInvoices());
                fsi.setMandatoryProjectForExpenseClaims(fs.getMandatoryProjectForExpenseClaims());
                fsi.setMandatoryProjectForPurchaseOrders(fs.getMandatoryProjectForPurchaseOrders());
                EdsAccount incomeTaxAccount = fs.getIncomeTaxAccount() != null
                        ? accountingManager.get(fs.getIncomeTaxAccount())
                        : null;
                if (incomeTaxAccount != null) {
                    fsi.setIncomeTaxAccount(incomeTaxAccount.getAsSelectItem());
                }

            } else if (company.getCountryZone().getCountry().getCurrency() != null) {
                fsi.setCurrencyId(company.getCountryZone().getCountry().getCurrency().getObjectID());
            }
            fsi.setVatReturnReportVisibility(getVatReturnReportVisibility());
            fsi.setHasTransaction(hasTransaction());
            fsi.setAgedPastDueDays(fs.getAgedPastDueDays());
            fsi.setAgedFilterInterval(fs.getAgedFilterInterval());
            fsi.setDefaultWarehouse(warehouseManager.getDefaultWarehouse() != null
                    ? warehouseManager.getDefaultWarehouse().getObjectID()
                    : null);
//            fsi.setEnableMultipleCurrencyForBankAccounts(genericSettingsEnums.contains(GenericSettingsEnum.MULTICURRENCY_ENABLED));

            fsi.setCsrStatus(zatcaService.getZatcaSettingsStatus());
        } catch (Exception e) {
            e.printStackTrace();
            return fsi;
        }
        return fsi;
    }

