    public Integer transferMoney(TransferMoneyData data) {

        if (data.isValidateReference() && accountingManager.isDuplicateReference(data.getReference(), null)) {
            return -1;
        }

        boolean isMultiCurrencyEnabled = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.MULTICURRENCY_ENABLED);
        EdsCurrency baseCurrency = financialSettingsManager.getFinancialSettings().getCurrency();
        EdsBankMoneyTransfer bankMoneyTransfer;
        if (data.getObjectID() != null) {
            bankMoneyTransfer = bankMoneyTransferManager.get(data.getObjectID());
        } else {
            bankMoneyTransfer = new EdsBankMoneyTransfer();
        }
        bankMoneyTransfer.setDate(data.getTransferMoneyDate().getNonConvertedDate());
        bankMoneyTransfer.setFromAccount(accountingManager.get(data.getFromAccount().getId()));
        bankMoneyTransfer.setToAccount(accountingManager.get(data.getToAccount().getId()));
        bankMoneyTransfer.setReference(data.getReference());
        bankMoneyTransfer.setAmount(data.getAmount());
        if (isMultiCurrencyEnabled) {
            bankMoneyTransfer.setAmountCurrency(data.getAmountCurrencyID() != null
                    ? currencyManager.get(data.getAmountCurrencyID())
                    : baseCurrency);
            bankMoneyTransfer.setExchangeRate(data.getExchangeRate());
            bankMoneyTransfer.setCurrency((data.getCurrency() != null && data.getCurrency().getId() != null)
                    ? currencyManager.get(data.getCurrency().getId())
                    : baseCurrency);
        } else {
            bankMoneyTransfer.setExchangeRate(BigDecimal.ONE);
            bankMoneyTransfer.setAmountCurrency(baseCurrency);
            bankMoneyTransfer.setCurrency(baseCurrency);
        }
        bankMoneyTransferManager.createOrUpdate(bankMoneyTransfer);
        createBankMoneyTransferTransaction(bankMoneyTransfer, baseCurrency, data);

        return bankMoneyTransfer.getObjectID();
    }

    private EdsBankTransaction createBankMoneyTransferTransaction(EdsBankMoneyTransfer bankMoneyTransfer, EdsCurrency baseCurrency, TransferMoneyData data) {
        EdsUser user = transactionManager.getUser();
        Integer exchangeRateScale = financialSettingsManager.getFinancialSettings().getExchangeRateScale();

        EdsBankTransaction transaction = transactionManager.getBankTransactionByMoneyTransfer(bankMoneyTransfer.getObjectID());
        if (transaction != null) {
            transactionManager.deleteTransactionItems(transaction.getObjectID());
        } else {
            transaction = new EdsBankTransaction();
            transaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID() + 1);
            transaction.setBankMoneyTransfer(bankMoneyTransfer);
        }
        transaction.setName("Bank Transfer from " + bankMoneyTransfer.getFromAccount().getName() + " to " + bankMoneyTransfer.getToAccount().getName());
        transaction.setJournalDate(bankMoneyTransfer.getDate());
        transaction.setPostedDate(user.getUserDate());
        transaction.setPostedBy(user);
        transaction.setReference(bankMoneyTransfer.getReference());

        BigDecimal amountInBase, amountInForeignCurrency;
        if (baseCurrency.getObjectID().equals(bankMoneyTransfer.getAmountCurrency().getObjectID())) {
            amountInBase = bankMoneyTransfer.getAmount();
            amountInForeignCurrency = bankMoneyTransfer.getAmount().multiply(bankMoneyTransfer.getExchangeRate()).setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP);
        } else {
            amountInBase = data.getBaseAmount();
            amountInForeignCurrency = bankMoneyTransfer.getAmount();
        }

        EdsTransactionItem creditItem = new EdsTransactionItem();
        creditItem.setAccount(bankMoneyTransfer.getFromAccount());
        creditItem.setCredit(amountInBase);
        if (bankMoneyTransfer.getFromAccount().isForeignAccount()) {
            creditItem.setForeignCredit(amountInForeignCurrency);
        }
        transaction.addTransactionItem(creditItem);

        EdsTransactionItem debitItem = new EdsTransactionItem();
        debitItem.setAccount(bankMoneyTransfer.getToAccount());

        if (bankMoneyTransfer.getToAccount().isForeignAccount()) {
            EdsAccount toAccount = bankMoneyTransfer.getToAccount();
            EdsCurrency fromCurrency = bankMoneyTransfer.getFromAccount().getCurrency();
            EdsCurrency toCurrency = bankMoneyTransfer.getToAccount().getCurrency();

            if (!fromCurrency.equals(toCurrency) && !fromCurrency.equals(baseCurrency) && !toCurrency.equals(baseCurrency)) {
                debitItem.setForeignDebit(amountInBase.multiply(data.getToExchangeRate().setScale(exchangeRateScale, RoundingMode.HALF_UP))
                        .setScale(ServerUtils.getSystemCalculationScale(), RoundingMode.HALF_UP));
            } else {
                debitItem.setForeignDebit(amountInForeignCurrency);
            }
        }
        debitItem.setDebit(amountInBase);
        transaction.addTransactionItem(debitItem);

        transactionManager.createOrUpdate(transaction);
        return transaction;
    }

    @Override
    public TransferMoneyData getBankAccountSummaryData(Integer objectId, Integer fromAccountID) {
        TransferMoneyData result = new TransferMoneyData();
        CurrencyItem baseCurrency = invoiceCircularResolver.getBaseCurrency();
        result.setCurrency(baseCurrency);

        if (objectId != null) {
            EdsBankMoneyTransfer bankMoneyTransfer = bankMoneyTransferManager.get(objectId);
            result.setTransferMoneyDate(new DateNonConvertable(bankMoneyTransfer.getDate()));
            EdsBankAccount fromBankAccount = bankAccountManager.getBankAccountByAccountID(bankMoneyTransfer.getFromAccount().getObjectID());
            EdsBankAccount toBankAccount = bankAccountManager.getBankAccountByAccountID(bankMoneyTransfer.getToAccount().getObjectID());

            BankAccountItem fromBankAccountItem = fromBankAccount.createBankAccountItem();
            BankAccountItem toBankAccountItem = toBankAccount.createBankAccountItem();
            if (fromBankAccountItem.getCurrency() == null) {
                fromBankAccountItem.setCurrency(baseCurrency);
            }
            if (toBankAccountItem.getCurrency() == null) {
                toBankAccountItem.setCurrency(baseCurrency);
            }
            result.setFromAccount(fromBankAccountItem);
            result.setToAccount(toBankAccountItem);
            result.setReference(bankMoneyTransfer.getReference());
            result.setAmount(bankMoneyTransfer.getAmount());
            result.setAmountCurrencyID(bankMoneyTransfer.getAmountCurrency().getObjectID());
            result.setExchangeRate(bankMoneyTransfer.getExchangeRate());
            result.setCurrency(bankMoneyTransfer.getCurrency().createCurrencyItem());
        } else if (fromAccountID != null) {
            BankAccountItem fromBankAccountItem = bankAccountManager.get(fromAccountID).createBankAccountItem();
            if (fromBankAccountItem.getCurrency() == null) {
                fromBankAccountItem.setCurrency(baseCurrency);
            }
            result.setFromAccount(fromBankAccountItem);
        }

        return result;
    }

    private HashMap<Integer, Transaction> findBankStatementBestMatchTransaction(Integer
                                                                                        bankGlAccountID, List<BankAccountStatementTO> bankAccountStatements) {
        HashMap<Integer, Transaction> transactionsByStatement = new HashMap<>();
        for (BankAccountStatementTO statement : bankAccountStatements) {
            //Extending date range to capture more transactions
            Calendar calFrom = new GregorianCalendar();
            calFrom.setTime(statement.getTransactionDate());
            calFrom.add(Calendar.DAY_OF_MONTH, -3);
            ServerUtils.setBeginningOfTheDay(calFrom);

            Calendar calTo = new GregorianCalendar();
            calTo.setTime(statement.getTransactionDate());
            calTo.add(Calendar.DAY_OF_MONTH, 3);
            ServerUtils.setEndOfTheDay(calTo);

            FindMatchFilterData filterData = new FindMatchFilterData();
            filterData.setGlAccountID(bankGlAccountID);
            filterData.setDebitCredit(statement.isDebitCredit());
            filterData.setTransactionAmount(statement.getAmount());
            filterData.setStartDate(new DateNonConvertable(calFrom.getTime()));
            filterData.setEndDate(new DateNonConvertable(calTo.getTime()));
            filterData.setReconsiled(statement.isReconsiled());
            filterData.setBankStatementItemID(statement.getBankStatementItemID());
            List<EdsTransactionItem> transactionItems = new ArrayList<>();
            if (filterData.isReconsiled()) {
                EdsTransactionItem transactionItemByStatementItem = transactionManager.getPaymentTransactionByStatementItem(filterData);
                if (transactionItemByStatementItem != null /*&& !transactionItems.contains(transactionItemByStatementItem)*/) {
                    transactionItems.add(transactionItemByStatementItem);
                }
            } else {
                transactionItems.addAll(transactionManager.getPaymentTransactionsByReconsileStatus(filterData));
            }
            if (transactionItems.isEmpty()) {//if list is empty go to next iteration
                continue;
            }
            Map<String, EdsTransactionItem> trasactionItemMap = new HashMap<>();
            Transaction transactionTO = new Transaction();
            for (EdsTransactionItem item : transactionItems) {
                trasactionItemMap.put(ServerUtils.getDateAsString(item.getTransaction().getJournalDate()), item);
            }
            EdsTransactionItem transactionItem = null;
            if (!trasactionItemMap.isEmpty() && trasactionItemMap.get(ServerUtils.getDateAsString(statement.getTransactionDate())) != null) {
                transactionItem = trasactionItemMap.get(ServerUtils.getDateAsString(statement.getTransactionDate()));
            }
            if (transactionItem == null) {
                transactionItem = transactionItems.get(0);//take the first result relying that this one is the most relevant
            }
            transactionTO.setMoreFound(transactionItems.size() - 1);//remaining count
            transactionTO.setTransactionId(transactionItem.getTransaction().getObjectID());
            transactionTO.setJournalId(transactionItem.getTransaction().getJournalId()); //for distinguishing next time
            transactionTO.setJournalName(transactionItem.getTransaction().getName());
            transactionTO.setJournalDate(new DateNonConvertable(transactionItem.getTransaction().getJournalDate()));
            transactionTO.setReconcileStatus(transactionItem.getReconcileStatus());
            if (DEBIT == statement.isDebitCredit()) {
                transactionTO.setTotalDebit(transactionItem.getDebit());
                if (transactionItem.getForeignDebit() != null && transactionItem.getForeignDebit().compareTo(ZERO) != 0) {
                    transactionTO.setTotalDebit(transactionItem.getForeignDebit());
                }
            } else {
                transactionTO.setTotalCredit(transactionItem.getCredit());
                if (transactionItem.getForeignCredit() != null && transactionItem.getForeignCredit().compareTo(ZERO) != 0) {
                    transactionTO.setTotalCredit(transactionItem.getForeignCredit());
                }
            }
            transactionsByStatement.put(statement.getBankStatementItemID(), transactionTO);
        }
        return transactionsByStatement;
    }


