    private SelectItem[] getProductCategoriesSelectItem(ListingFilterParameter filterParametrs) {
        List<EdsProductCategory> categories = productCategoryManager.getCategoriesByFilter(filterParametrs);
        if (categories == null || categories.isEmpty()) {
            return new SelectItem[0];
        } else {
            if (filterParametrs != null && filterParametrs.isLookUp()) {
                return wrapCategoriesAsLookUpSelectItems(categories);
            }
            return wrapCategoriesAsTreeSelectItems(categories);
        }
    }

    private SelectItem[] wrapCategoriesAsLookUpSelectItems(List<EdsProductCategory> categories) {
        List<SelectItem> result = new ArrayList<>();
        for (EdsProductCategory category : categories) {
            flattenCategoryWithHierarchyName(category, result);
        }
        return result.toArray(new SelectItem[0]);
    }

    private void flattenCategoryWithHierarchyName(EdsProductCategory category, List<SelectItem> result) {
        SelectItem item = new SelectItem();
        item.setId(category.getObjectID());
        item.setName(buildHierarchyName(category));
        result.add(item);

        if (category.getChildList() != null) {
            for (EdsProductCategory child : category.getChildList()) {
                if (child.isActive()) {
                    flattenCategoryWithHierarchyName(child, result);
                }
            }
        }
    }

    private String buildHierarchyName(EdsProductCategory category) {
        if (category.getParent() == null) {
            return category.getName();
        }
        return buildHierarchyName(category.getParent()) + " > " + category.getName();
    }

