    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ListResult<ProductCategoryItem> getProductCategoriesList(ListingFilterParameter filterParametrs) {
        if (filterParametrs == null) {
            filterParametrs = new ListingFilterParameter();
        }
        ListPanelToolRpc panelTools = filterParametrs.getListPanelTool();
        filterParametrs.setCustomFieldsShown(true);
        if (panelTools != null && panelTools.isCustomFieldsShown()) {
            filterParametrs.setCustomFieldsShown(panelTools.isCustomFieldsShown());
            panelTools.setListViewCustomFields(commonService.getCompanyCustomFieldsForListView(ViewName.ProductCategoryStoreFront));
            filterParametrs.setColumnsOfListing(panelTools.getColumnCodeName());
        }
        List<EdsProductCategory> categories = productCategoryManager.getCategoriesByFilter(filterParametrs);

        int totalCount = productCategoryManager.getCategoriesByFilterCount(filterParametrs);

        ArrayList<ProductCategoryItem> items = new ArrayList<>();

        for (EdsProductCategory m : categories) {
            ProductCategoryItem productCategoryItem = m.getRPC();
            if (m.getCustomFields() != null && filterParametrs.isCustomFieldsShown()) {
                productCategoryItem.setCustomFieldsMap(CustomFieldsUtils.getRPCCustomFields(m.getCustomFields(), filterParametrs.getColumnsOfListing()));
            }
            if (mapHasValueForLang(productCategoryItem.getNameLocalize(), filterParametrs.getLanguage())) {
                productCategoryItem.setName(productCategoryItem.getNameLocalize().get(filterParametrs.getLanguage()));
            }
            if (mapHasValueForLang(productCategoryItem.getDescriptionLocalize(), filterParametrs.getLanguage())) {
                productCategoryItem.setDescription(productCategoryItem.getDescriptionLocalize().get(filterParametrs.getLanguage()));
            }
            items.add(productCategoryItem);
        }
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsProductCategory.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.LIST);
        ServerUtils.kpiLog(log, kpiLog, "Get product category list");
        return new ListResult<>(items, totalCount);
    }

    private boolean mapHasValueForLang(HashMap<String, String> map, String lang) {
        return lang != null && map != null && map.get(lang) != null && !map.get(lang).isEmpty();
    }

