    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public BankAccountAttachment[] getBankAccountFilesList(Integer bankAccountID) {
        List<EdsBankAccountAttachment> accountAttachments = bankAccountAttachmentManager.getBankAccountAttachments(bankAccountID, "CSV");

        if (accountAttachments == null || accountAttachments.isEmpty()) {
            return null;
        } else {
            BankAccountAttachment[] result = new BankAccountAttachment[accountAttachments.size()];
            int i = 0;
            for (EdsBankAccountAttachment attachment : accountAttachments) {
                result[i] = new BankAccountAttachment();
                result[i].setObjectID(attachment.getObjectID());
                result[i].setBankAccAttchType(attachment.getBankAccAttchType().getCode());
                result[i].setBankAccountID(bankAccountID);
                result[i].setName(attachment.getOriginalName());
                result[i].setImported(attachment.isImported());
                result[i].setReconciled(isBankAccountAttachmentReconciled(attachment));
                i++;
            }
            KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
            kpiLog.setEntityName(EdsBankAccountAttachment.class.getSimpleName());
            kpiLog.setActionType(KpiLog.ActionType.LIST);
            ServerUtils.kpiLog(log, kpiLog, "Get Bank Account Files List");
            return result;
        }
    }

    private boolean isBankAccountAttachmentReconciled(EdsBankAccountAttachment attachment) {
        boolean reconciled = false;
        List<EdsBankStatement> statements = bankStatementManager.getBankStatements(attachment);
        if (statements != null && !statements.isEmpty()) {
            List<EdsBankStatementItem> bsItems = bankStatementItemManager.getBankStatementItems(statements.get(0));
            reconciled = !(bsItems != null && !bsItems.isEmpty());
        }
        return reconciled;
    }

