    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public BankAccountImportStatementData getTransactionMapping(Integer bankAccountAttachmentID) {
        EdsBankAccountAttachment attachment = bankAccountAttachmentManager.get(bankAccountAttachmentID);
        if (attachment != null) {

            BankAccountImportStatementData importStatementData = new BankAccountImportStatementData();

            CSVReader reader = new CSVReader(new InputStreamReader(uploadManager.getInputStream(attachment), StandardCharsets.UTF_8));

            try {
                // headers[] is an array of values from the line
                String[] headers = reader.readNext();
                String[] values = reader.readNext();
                BankAccountTransactionMapper[] result = new BankAccountTransactionMapper[headers.length];
                for (
                        int i = 0;
                        i < headers.length;
                        i++) {
                    result[i] = new BankAccountTransactionMapper();
                    result[i].setBankAccountID(attachment.getBankAccount().getObjectID());
                    result[i].setFileColumnName(headers[i]);
                    result[i].setFileColumnIndex(i);
                    result[i].setBankAccountAttachmentID(bankAccountAttachmentID);
                    if (values != null && i <= values.length) {
                        result[i].setFileColumnValue(values[i]);
                    }
                }

                importStatementData.setFormMappedData(result);
                SelectItem[] csvTemplates = getCsvTemplates(CSV_TEMPLATE_IMPORT_BANK_STATEMENT);
                importStatementData.setCsvTemplates(csvTemplates);
                if (csvTemplates != null && csvTemplates.length > 0) {
                    importStatementData.setCsvTemplateID(csvTemplates[0].getId());
                    importStatementData.setCsvTemplateData(getCsvTemplateData(importStatementData.getCsvTemplateID()));
                }
                String fileUrl = uploadManager.getFileURL(attachment); // Your S3 file URL
                File tempFile;
                try {
                    tempFile = downloadFileFromURL(fileUrl);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to download file from URL: " + fileUrl, e);
                }

                FileSystemResource fileResource = new FileSystemResource(tempFile);
                MultiValueMap<String, Object> body = new LinkedMultiValueMap<>();
                body.add("csv", fileResource);

                HttpHeaders header = new HttpHeaders();
                header.setContentType(MediaType.MULTIPART_FORM_DATA);

                HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(body, header);

                String url = "https://aiarc.kpi.com/api/v1/mapping/map";
                RestTemplate restTemplate = new RestTemplate();

                ResponseEntity<ResponseDto> mappingResponse;
                try {
                    mappingResponse = restTemplate.exchange(url, HttpMethod.POST, requestEntity, ResponseDto.class);
                } catch (Exception e) {
                    throw new RuntimeException("Error while calling AI mapping API: " + url, e);
                }
                importStatementData.setMappinMap(mappingResponse.getBody().getData());
                return importStatementData;
            } catch (IOException e) {
                e.printStackTrace();
                System.err.println("AccountinServiceImpl.getTransactionMapping(Integer bankAccountAttachmentID) Error while parsing, check the file entry format!");
            }
            return null;
        } else {
            return null;
        }
    }


    @Override
    public BankAccountImportStatementData getTransactionMappingByAI(Integer bankAccountAttachmentID) {
        EdsBankAccountAttachment attachment = bankAccountAttachmentManager.get(bankAccountAttachmentID);
        if (attachment == null) {
            return null;
        }

        BankAccountImportStatementData importStatementData = new BankAccountImportStatementData();
        String fileUrl = uploadManager.getFileURL(attachment); // Your S3 file URL

        File tempFile;
        try {
            tempFile = downloadFileFromURL(fileUrl);
        } catch (IOException e) {
            throw new RuntimeException("Failed to download file from URL: " + fileUrl, e);
        }

        // Prepare request
        FileSystemResource fileResource = new FileSystemResource(tempFile);
        MultiValueMap<String, Object> body = new LinkedMultiValueMap<>();
        body.add("csv", fileResource);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.MULTIPART_FORM_DATA);

        HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(body, headers);

        String url = "https://aiarc.kpi.com/api/v1/mapping/map-with-value";
        RestTemplate restTemplate = new RestTemplate();

        ResponseEntity<ApiResponseDTO> response;
        ResponseEntity<ResponseDto> mappingResponse;
        try {
            response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, ApiResponseDTO.class);
            mappingResponse = restTemplate.exchange("https://aiarc.kpi.com/api/v1/mapping/map", HttpMethod.POST, requestEntity, ResponseDto.class);
        } catch (Exception e) {
            throw new RuntimeException("Error while calling AI mapping API: " + url, e);
        }


        // Process response
        ApiResponseDTO responseBody = response.getBody();
        if (responseBody == null || responseBody.getData() == null || responseBody.getData().getMappings() == null) {
            return null;
        }

        Integer bankAccountId = attachment.getBankAccount().getObjectID();
        List<MappingDto> mappings = responseBody.getData().getMappings();

        BankAccountTransactionMapper[] result = mappings.parallelStream()
                .map(mapping -> {
                    BankAccountTransactionMapper mapper = new BankAccountTransactionMapper();
                    mapper.setBankAccountID(bankAccountId);
                    mapper.setBankAccountAttachmentID(bankAccountAttachmentID);
                    mapper.setFileColumnName(mapping.getSystemField());
                    mapper.setFileColumnIndex(mapping.getIndex());
                    mapper.setFileColumnValue(mapping.getValues() != null && !mapping.getValues().isEmpty()
                            ? String.valueOf(mapping.getValues().get(0).getValue())
                            : "");
                    return mapper;
                })
                .toArray(BankAccountTransactionMapper[]::new);

        importStatementData.setFormMappedData(result);
        importStatementData.setMappings(mappings);
        Map<String, String> mappingMap = new HashMap<>();
        for (Map.Entry<String, String> entry : mappingMap.entrySet()) {
            mappingMap.put(entry.getValue(), entry.getKey());
        }
        importStatementData.setMappinMap(mappingMap);
        return importStatementData;
    }


    private static File downloadFileFromURL(String fileUrl) throws IOException {
        URL url = new URL(fileUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        File tempFile = File.createTempFile("upload-", ".csv");
        try (InputStream in = connection.getInputStream();
             FileOutputStream out = new FileOutputStream(tempFile)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = in.read(buffer)) != -1) {
                out.write(buffer, 0, bytesRead);
            }
        }
        return tempFile;
    }

    public EdsBankTransferCustomFields createBankTransferCustomFields
            (List<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            EdsBankTransferCustomFields bankTransferCustomFields;
            if (customFieldItems.get(0).getObjectId() != null) {
                bankTransferCustomFields = bankTransferCFManager.get(customFieldItems.get(0).getObjectId());
            } else {
                boolean isEmpty = true;
                for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                    if ((fieldItem.getFieldStringValue() != null && !"".equals(fieldItem.getFieldStringValue()))
                            || fieldItem.getFieldDateNonConvertedValue() != null
                            || fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty()) {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty) {
                    return null;
                }
                bankTransferCustomFields = new EdsBankTransferCustomFields();
                bankTransferCFManager.create(bankTransferCustomFields);
            }
            CustomFieldsUtils.setAccountingDomainObjectCustomFields(bankTransferCustomFields, customFieldItems);
            return bankTransferCustomFields;
        }
        return null;
    }

