    @Transactional
    public List<HistoryNote> getBankTransferHistoryNotes(Integer id, String viewType) {
        if (id == null) {
            return null;
        }
        if (viewType == null) {
            return null;
        }
        List<HistoryNote> result = new ArrayList<>();
        HistoryListItem[] asHistoryItems = getAsHistoryItems(bankTransferNoteManager.getBankTransferNotes(id));
        if (asHistoryItems != null) {
            result.addAll(Arrays.asList(asHistoryItems));
        }
        result.addAll(invoiceServiceLocal.getAllHistory(id, viewType));
        return result;
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public NewManualTransaction getBankTransferData(ListingFilterParameter fp) {
        Integer objectID = fp.getObjectId();
        Integer transferType = fp.getType();
        Integer bankAccountID = fp.getAccountID();
        Integer projectID = fp.getProjectId();
        boolean copy = fp.isCopy();
        NewManualTransaction newManualTransaction;

        CurrencyItem baseCurrency = invoiceCircularResolver.getBaseCurrency();
        if (objectID != null) {
            EdsBankTransfer spendReceive = spendReceiveMoneyManager.get(objectID);
            transferType = spendReceive != null ? spendReceive.getTransferType() : null;
            if (transferType != null) {
                switch (transferType) {
                    case 0 ->
                            spendReceive.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.BankReceiptItem));
                    case 1 ->
                            spendReceive.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.BankPaymentItem));
                    case 2 ->
                            spendReceive.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.CashReceiptItem));
                    case 3 ->
                            spendReceive.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.CashPaymentItem));
                }
            }
            newManualTransaction = spendReceive != null ? spendReceive.creatTransferData() : new NewManualTransaction();
            transferType = newManualTransaction.getTransferType();
            if (Objects.equals(SPEND_MONEY, transferType) || Objects.equals(RECEIVE_MONEY, transferType)) {
                newManualTransaction.setTaxTreatments(ServerUtils.getAsSelectItem(filterTaxTreatment(referenceManager.listReferences(Constants._TAX_TREATMENT)), ServerUtils.REFERENCE));
                if (spendReceive.getTaxTreatment() != null) {
                    newManualTransaction.setTaxTreatment(spendReceive.getTaxTreatment().getAsSelectItem());
                    newManualTransaction.getTaxTreatment().setCode(spendReceive.getTaxTreatment().getCode());
                }
                if (spendReceive.getPlaceOfSupply() != null) {
                    newManualTransaction.setPlaceOfSupply(spendReceive.getPlaceOfSupply().getAsSelectItem());
                    newManualTransaction.getPlaceOfSupply().setCode(spendReceive.getPlaceOfSupply().getCode());
                    newManualTransaction.getPlaceOfSupply().setCategory(PLACEOFSUPPLY_CATEGORY.REGION);
                } else if (spendReceive.getPlaceOfSupplyGCCCountry() != null) {
                    newManualTransaction.setPlaceOfSupply(spendReceive.getPlaceOfSupplyGCCCountry().getAsSelectItem());
                    newManualTransaction.getPlaceOfSupply().setCode(spendReceive.getPlaceOfSupplyGCCCountry().getCode());
                    newManualTransaction.getPlaceOfSupply().setCategory(PLACEOFSUPPLY_CATEGORY.COUNTRY);
                }
                newManualTransaction.setReversechargeApplicable(spendReceive.isReverseChargeApplicable());
            }

            if (spendReceiveMoneyManager.getUser() != null) {
                newManualTransaction.setAttachments(getManualTransactionAttachments(objectID));
            }
            FileResource[] attachmentResources = getAttachmentResources(F_BANK_TRANSFER, spendReceive.getObjectID());
            if (attachmentResources != null && attachmentResources.length > 0) {
                newManualTransaction.setAttachmentResources(attachmentResources);
            } else {
                newManualTransaction.setAttachmentResources(new FileResource[0]);
            }
            if (copy) {
                BankTransferNumberData numberData = getBankTransferNumberData(transferType);
                newManualTransaction.setTransferNumberData(numberData);
                if (newManualTransaction.getTransferNumberData() != null) {
                    newManualTransaction.setNumber(newManualTransaction.getTransferNumberData().getTransferNumber());
                }
            } else {
                newManualTransaction.setNumber(spendReceive.getNumber());
                newManualTransaction.setTransferNumberData(getBankTransferNumberData(spendReceive.getTransferType()));
                List<EdsBankTransferTransaction> transaction = transactionManager.getBankTransferTransaction(spendReceive);
                if (transaction != null && !transaction.isEmpty()) {
                    newManualTransaction.setJournalID(transaction.get(0).getJournalId());
                }
            }

            newManualTransaction.setHistoryListItems(getAsHistoryItems(bankTransferNoteManager.getBankTransferNotes(objectID)));
            ////Load Custom Fields
            EdsBankTransferCustomFields customFields = spendReceive.getCustomFields();
            ArrayList<CompanyCustomFieldItem> customFieldsItems = commonServiceLocal.getCompanyCustomFields(ViewName.BankTransferList);
            newManualTransaction.setCustomFieldItems(CustomFieldsUtils.setRPCCustomFieldItems(customFields, customFieldsItems));
            newManualTransaction.setUsed(spendReceiveMoneyManager.isUsedForPayment(newManualTransaction.getObjectId()));
            //\\End Load CustomFields
        } else {
            newManualTransaction = new NewManualTransaction();
            newManualTransaction.setCurrency(baseCurrency);
            newManualTransaction.setExchangeRate(BigDecimal.ONE);
            newManualTransaction.setReference(fp.getDescription());
            if (Objects.equals(SPEND_MONEY, transferType) || Objects.equals(RECEIVE_MONEY, transferType)) {
                newManualTransaction.setTaxTreatments(ServerUtils.getAsSelectItem(filterTaxTreatment(referenceManager.listReferences(Constants._TAX_TREATMENT)), ServerUtils.REFERENCE));
            }
            if (bankAccountID != null) {
                EdsBankAccount bankAccount = bankAccountManager.get(bankAccountID);
                newManualTransaction.setBankAccountItem(bankAccount.createBankItem());
                newManualTransaction.setExchangeRate(bankAccount.getExchangeRate());
                if (bankAccount.getAccount() != null && bankAccount.getAccount().getCurrency() != null) {
                    newManualTransaction.setCurrency(bankAccount.getAccount().getCurrency().createCurrencyItem());
                }
            }
            if (projectID != null) {
                EdsProject edsProject = projectManager.get(projectID);
                if (edsProject != null) {
                    if (genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.PROJECT_IN_LINE_ITEM_ENABLE)) {
                        NewManualTransactionItem item = new NewManualTransactionItem();
                        item.setProject(edsProject.getAsSelectItem());
                        newManualTransaction.setItems(new NewManualTransactionItem[]{item});
                    } else {
                        newManualTransaction.setProject(edsProject.getAsSelectItem());
                    }
                }
            }
            BankTransferNumberData numberData = getBankTransferNumberData(transferType);
            newManualTransaction.setTransferNumberData(numberData);
            if (newManualTransaction.getTransferNumberData() != null) {
                newManualTransaction.setNumber(newManualTransaction.getTransferNumberData().getTransferNumber());
            }

            //get Petty Cash account
            if (Objects.equals(CASH_RECEIPT, transferType) || Objects.equals(CASH_PAYMENT, transferType)) {
                EdsAccount pattyCash = accountingManager.getAccountByName("Petty Cash");
                if (pattyCash != null) {
                    SelectItem cashAccount = new SelectItem();
                    cashAccount.setId(pattyCash.getObjectID());
                    cashAccount.setName(pattyCash.getName());
                    cashAccount.setDescription(pattyCash.getCurrency() != null
                            ? pattyCash.getCurrency().getName()
                            : "");
                    cashAccount.setReferenceCode(pattyCash.getAccountCode());
                    newManualTransaction.setCashAccount(cashAccount);
                }
            }
            ArrayList<CompanyCustomFieldItem> customFieldsItems = commonServiceLocal.getCompanyCustomFields(ViewName.BankTransferList);
            newManualTransaction.setCustomFieldItems(CustomFieldsUtils.setRPCCustomFieldItems(null, customFieldsItems));

        }
        if (transferType != null) {
            switch (transferType) {
                case 0 -> {
                    newManualTransaction.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.BankReceiptItem));
                    newManualTransaction.setCustomItemColumns(itemTableSettingService.getColumnConfigs(ItemTableEnum.BANK_RECEIPT_ITEM));
                    newManualTransaction.setPdfTemplateList(invoiceServiceLocal.getCompanyPdfTemplatesByType(PdfReferenceCodeNameEnum.BANK_RECEIPT.name()));
                }
                case 1 -> {
                    newManualTransaction.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.BankPaymentItem));
                    newManualTransaction.setCustomItemColumns(itemTableSettingService.getColumnConfigs(ItemTableEnum.BANK_PAYMENT_ITEM));
                    newManualTransaction.setPdfTemplateList(invoiceServiceLocal.getCompanyPdfTemplatesByType(PdfReferenceCodeNameEnum.BANK_PAYMENT.name()));
                }
                case 2 -> {
                    newManualTransaction.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.CashReceiptItem));
                    newManualTransaction.setCustomItemColumns(itemTableSettingService.getColumnConfigs(ItemTableEnum.CASH_RECEIPT_ITEM));
                    newManualTransaction.setPdfTemplateList(invoiceServiceLocal.getCompanyPdfTemplatesByType(PdfReferenceCodeNameEnum.CASH_RECEIPT.name()));
                }
                case 3 -> {
                    newManualTransaction.setItemCustomFields(commonService.getCompanyCustomFields(ViewName.CashPaymentItem));
                    newManualTransaction.setCustomItemColumns(itemTableSettingService.getColumnConfigs(ItemTableEnum.CASH_PAYMENT_ITEM));
                    newManualTransaction.setPdfTemplateList(invoiceServiceLocal.getCompanyPdfTemplatesByType(PdfReferenceCodeNameEnum.CASH_PAYMENT.name()));
                }
            }
        }
        newManualTransaction.setBaseCurrency(baseCurrency);
        if (newManualTransaction.getBankAccountItem() != null && newManualTransaction.getBankAccountItem().getCurrency() == null) {
            newManualTransaction.getBankAccountItem().setCurrency(baseCurrency);
        }
        newManualTransaction.setLayoutHtml(PathFinder.getLayoutHTML(BANK_TRANSACTION_FORM));

        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        if (bankAccountManager.getUser() != null) {
            newManualTransaction.setEnabledPostDatedTransaction(financialSettings.isEnablePostedDateTransaction());
        }
        newManualTransaction.setEnabledDepartmentRelation(financialSettings.getEnableAccountingDepartmentRelation());
        newManualTransaction.setEnabledProjectInLineItem(genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.PROJECT_IN_LINE_ITEM_ENABLE));
        SelectItem defaultDepartment = allInOneService.getDepartmentForInvoice();
        if (defaultDepartment != null) {
            newManualTransaction.setDefaultDepartment(defaultDepartment);
        }
        return newManualTransaction;
    }

    private List<EdsReference> filterTaxTreatment(List<EdsReference> list) {
        List<EdsReference> filteredItems = new ArrayList<>();
        boolean isReverseCharge = genericSettingsManager.isSettingsEnabled(GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE);
        String countryCode = userManager.getUser().getCompany().getCountry().getCode();

        for (EdsReference t : list) {

            if (Constants.GCC_VAT_REGISTERED.equals(t.getCode()) || Constants.GCC_NON_VAT_REGISTERED.equals(t.getCode()) || Constants.NON_GCC.equals(t.getCode())) {

                if (isReverseCharge) {
                    filteredItems.add(t);
                }
            } else if (Constants.VAT_REGISTERED_DESIGNATED_ZONE.equals(t.getCode()) || Constants.NON_VAT_REGISTERED_DESIGNATED_ZONE.equals(t.getCode())) {

                if (Constants.AE.equals(countryCode)) {
                    filteredItems.add(t);
                }
            } else {
                filteredItems.add(t);
            }
        }

        return filteredItems;
    }

    private HistoryListItem[] getAsHistoryItems(List<EdsBankTransferNote> btNotes) {
        if (btNotes != null && !btNotes.isEmpty()) {
            HistoryListItem[] hisItems = new HistoryListItem[btNotes.size()];
            int i = 0;
            for (EdsBankTransferNote note : btNotes) {
                hisItems[i] = new HistoryListItem();
                hisItems[i].setObjectID(note.getObjectID());
                hisItems[i].setComment(note.getComment());
                if (note.isSuperUser()) {
                    hisItems[i].setEmployee(Constants.defaultSupportName);
                } else {
                    hisItems[i].setEmployee(note.getCommentator().getFullName());
                }
                hisItems[i].setEmployeeID(note.getCommentator().getObjectID());
                hisItems[i].setEventDate(note.getDate());
                i++;
            }
            return hisItems;
        }
        return null;
    }

    @Transactional
    public void deleteBankTransfer(Integer objectID, String transactionType) {
        EdsUser user = userManager.getUser();
        if (BANK_TRANSFER_TRANSACTION.equals(transactionType)) {
            EdsBankTransfer bankTransfer = spendReceiveMoneyManager.get(objectID);
            EdsBankTransferTransaction edsBankTransferTransaction = bankTransfer.getBankTransferTransaction();
            if (edsBankTransferTransaction != null) {
                edsBankTransferTransaction.setDeleted(true);
                transactionManager.update(edsBankTransferTransaction);
                //update bank reconsile item
                EdsBankStatementItem edsBankStatementItem = edsBankTransferTransaction.getBankStatementItem();
                if (edsBankStatementItem != null) {
                    edsBankStatementItem.setReconciled(false);
                    bankStatementItemManager.update(edsBankStatementItem);
                }
                edsBankTransferTransaction.getTransactionItems().forEach(item -> {
                    item.setReconcileStatus(UNRECONCILED);
                    transactionItemManager.update(item);
                });
            }

            String code = getSpendReceiveMoneyNumberCode(bankTransfer.getTransferType());
            EdsSharedNumber sharedNumber = sharedNumberManager.getByEntityID(bankTransfer.getObjectID(), code);
            if (sharedNumber != null) {
                sharedNumber.setDeleted(true);
                sharedNumberManager.update(sharedNumber);
            }
            bankTransfer.setDeleted(true);
            spendReceiveMoneyManager.update(bankTransfer);
            baseEventPostProcessor.registerEvent(BankTransferEventListenerImpl.TYPE, BaseEventsPostProcessorImpl.EVENT_TYPE_DELETE, bankTransfer, user);
        } else if (BANK_MONEY_TRANSFER_TRANSACTION.equals(transactionType)) {
            EdsTransaction bankTransaction = transactionManager.getBankTransactionByMoneyTransfer(objectID);
            bankTransaction.setDeleted(true);
            transactionManager.update(bankTransaction);
        }
        if (objectID != null) {
            bankTransferNoteManager.deleteBankTransferNotes(objectID);
        }
    }

    private String getSpendReceiveMoneyNumberCode(Integer transferType) {
        return (Objects.equals(transferType, SPEND_MONEY)
                ? EdsNumberingSettings.DEF_BANK_PAYMENT_PREFIX
                : Objects.equals(transferType, RECEIVE_MONEY)
                ? EdsNumberingSettings.DEF_BANK_RECEIPT_PREFIX
                : Objects.equals(transferType, CASH_RECEIPT)
                ? EdsNumberingSettings.DEF_CASH_RECEIPT_PREFIX
                : EdsNumberingSettings.DEF_CASH_PAYMENT_PREFIX);
    }

    public ProductPicture[] getProductCategoryPictures(Integer categoryID, Integer fileSizeType) {


        List<EdsProductCategoryPicture> pictures = productCategoryPictureManager.getCategoryPictures(productCategoryManager.get(categoryID), fileSizeType);
        ProductPicture[] result = new ProductPicture[pictures.size()];
        int i = 0;
        for (EdsProductCategoryPicture picture : pictures) {
            String url = null;
            result[i] = new ProductPicture();
            result[i].setName(picture.getName());
            result[i].setPictureID(picture.getObjectID());
            result[i].setProductID(categoryID);
            result[i].setDefaultPicture(picture.getDefaultPicture() != null
                    ? picture.getDefaultPicture()
                    : Boolean.FALSE);
            url = uploadManager.getFileURL(picture);
            result[i].setUrl(url);
            i++;
        }
        return result;
    }

    public DateNonConvertable[] getVatReturnDateInterval() {
        Calendar start = new GregorianCalendar();
        Calendar end = new GregorianCalendar();

        start.set(Calendar.DAY_OF_MONTH, 1);
        start.set(Calendar.HOUR_OF_DAY, 0);
        start.set(Calendar.MINUTE, 0);
        start.set(Calendar.SECOND, 0);
        start.set(Calendar.MILLISECOND, start.getActualMinimum(Calendar.MILLISECOND));

        end.set(Calendar.HOUR_OF_DAY, 23);
        end.set(Calendar.MINUTE, 59);
        end.set(Calendar.SECOND, 59);
        end.set(Calendar.MILLISECOND, end.getActualMaximum(Calendar.MILLISECOND));
        end.set(Calendar.DAY_OF_MONTH, end.getActualMaximum(Calendar.DAY_OF_MONTH));

        EdsFinancialSettings fs = financialSettingsManager.getFinancialSettings();

        if (fs.getTaxPeriod() != null) {
            if (MONTHLY2.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 1);
            } else if (QUARTERLY.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 2);
            } else if (MONTHLY4.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 3);
            } else if (MONTHLY5.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 4);
            } else if (MONTHLY6.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 5);
            } else if (ANNUAL.equals(fs.getTaxPeriod().getCode())) {
                start.set(Calendar.MONTH, start.get(Calendar.MONTH) - 11);
            }
        }

        return new DateNonConvertable[]{new DateNonConvertable(start.getTime()), new DateNonConvertable(end.getTime())};
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public VatReturnTransferObject getVatReturnReport(DateNonConvertable from, DateNonConvertable to, BigDecimal
            flatPercent) {
        VatReturnTransferObject vatReturn = new VatReturnTransferObject();
        EdsFinancialSettings fs = financialSettingsManager.getFinancialSettings();

        Integer calculationScale = fs.getAccountingCalculationScale();

        vatReturn.setRegistrationNumber(fs.getTaxIdNumber());
        vatReturn.setFlatRate(fs.isFlatRate());
        vatReturn.setPeriodCovered(getVatReturnPeriodType(from, to));
        vatReturn.setPaymentDueDate(getVatReturnPaymentDueDate(to));

        boolean accrual = !(fs.getTaxBasis() != null && CASH.equals(fs.getTaxBasis().getCode()));

        HashMap<Integer, LinkedList<VatReturnDetailItem>> detailItemsMap = new HashMap<>();

        if (accrual) {
            List<EdsInvoice> invoices = invoiceManager.getInvoicesByDate(from.getNonConvertedDate(), to.getNonConvertedDate(), accrual);
            for (EdsInvoice i : invoices) {
                if (i instanceof EdsSaleInvoice || i instanceof EdsPurchaseInvoice) {
                    Integer transType = RECEIVABLE.equals(i.getType()) ? TAX_SALES : TAX_PURCHASE;
                    for (EdsInvoiceItem ii : i.getInvoiceItems()) {
                        BigDecimal exchangeRate = ii.getInvoice().getExchangeRate();
                        BigDecimal discountedNet = ii.calculateDiscountedNet();
                        if (i.isCreditNote()) {
                            discountedNet = ZERO.subtract(discountedNet);
                        }

                        LinkedList<VatReturnDetailItem> detailList = addUpVatReturnData(vatReturn, ii.getVat(), i.getTaxCalculationType(), transType, discountedNet, null/*paymentShare*/, flatPercent, calculationScale, exchangeRate);
                        for (VatReturnDetailItem detail : detailList) {
                            detail.setObjectID(i.getObjectID());
                            detail.setType(INVOICE_TRANSACTION);
                            detail.setTransferType(i.getType());
                            detail.setName(i.getNumber());
                            detail.setNumber(i.getNumber());
                            addDetailItemToMap(detailItemsMap, detail);
                        }
                    }
                }
            }
        } else {
            HashSet<Integer> invoiceIDSUsed = new HashSet<>();
            List<EdsInvoice> invoices = invoiceManager.getInvoicesByPaymentsDate(from.getNonConvertedDate(), to.getNonConvertedDate(), accrual);
            for (EdsInvoice i : invoices) {
                if (!invoiceIDSUsed.contains(i.getObjectID())) {
                    BigDecimal paymentShare = i.getPaymentShare(from.getNonConvertedDate(), to.getNonConvertedDate());
                    if (i instanceof EdsSaleInvoice || i instanceof EdsPurchaseInvoice) {
                        Integer transType = RECEIVABLE.equals(i.getType()) ? TAX_SALES : TAX_PURCHASE;
                        for (EdsInvoiceItem ii : i.getInvoiceItems()) {
                            BigDecimal exchangeRate = ii.getInvoice().getExchangeRate();
                            BigDecimal discountedNet = ii.calculateDiscountedNet();
                            if (i.isCreditNote()) {
                                discountedNet = ZERO.subtract(discountedNet);
                            }

                            LinkedList<VatReturnDetailItem> detailList = addUpVatReturnData(vatReturn, ii.getVat(), i.getTaxCalculationType(), transType, discountedNet, paymentShare, flatPercent, calculationScale, exchangeRate);
                            for (VatReturnDetailItem detail : detailList) {
                                detail.setObjectID(i.getObjectID());
                                detail.setType(INVOICE_TRANSACTION);
                                detail.setTransferType(i.getType());
                                detail.setName(i.getNumber());
                                detail.setNumber(i.getNumber());
                                addDetailItemToMap(detailItemsMap, detail);
                            }
                        }
                    }

                    invoiceIDSUsed.add(i.getObjectID());
                }
            }
        }

        if (accrual) {
            List<EdsExpenseReport> expenseReports = invoiceManager.getExpenseReportsByDate(from.getNonConvertedDate(), to.getNonConvertedDate(), accrual);
            for (EdsExpenseReport er : expenseReports) {
                List<EdsExpense> expenses = er.getExpenses();
                for (EdsExpense e : expenses) {
                    BigDecimal net = e.getUnits().multiply(e.getCostPerUnit());
                    BigDecimal exchangeRate = e.getCurrency() != null
                            ? e.getExchageRate()
                            : e.getReport().getExchangeRate();

                    LinkedList<VatReturnDetailItem> detailList = addUpVatReturnData(vatReturn, e.getTax(), TAX_CALCULATION_EXCLUSIVE, TAX_PURCHASE, net, null/*paymentShare*/, flatPercent, calculationScale, exchangeRate);
                    for (VatReturnDetailItem detail : detailList) {
                        detail.setObjectID(e.getReport().getObjectID());
                        detail.setType(EXPENSE_TRANSACTION);
                        detail.setName(e.getReport().getTitle());
                        detail.setNumber(e.getReport().getNumber());
                        addDetailItemToMap(detailItemsMap, detail);
                    }
                }
            }
        } else {
            HashSet<Integer> expenseIDSUsed = new HashSet<>();
            List<EdsExpenseReport> expenseReports = invoiceManager.getExpenseReportsByPaymentsDate(from.getNonConvertedDate(), to.getNonConvertedDate(), accrual);
            for (EdsExpenseReport er : expenseReports) {
                if (!expenseIDSUsed.contains(er.getObjectID())) {
                    BigDecimal paymentShare = er.getPaymentShare(from.getNonConvertedDate(), to.getNonConvertedDate());
                    List<EdsExpense> expenses = er.getExpenses();
                    for (EdsExpense e : expenses) {
                        //Calculating Net Amount
                        BigDecimal net = e.getUnits().multiply(e.getCostPerUnit());
                        BigDecimal exchangeRate = e.getCurrency() != null
                                ? e.getExchageRate()
                                : e.getReport().getExchangeRate();

                        LinkedList<VatReturnDetailItem> detailList = addUpVatReturnData(vatReturn, e.getTax(), TAX_CALCULATION_EXCLUSIVE, TAX_PURCHASE, net, paymentShare, flatPercent, calculationScale, exchangeRate);
                        for (VatReturnDetailItem detail : detailList) {
                            detail.setObjectID(e.getReport().getObjectID());
                            detail.setType(EXPENSE_TRANSACTION);
                            detail.setName(e.getReport().getTitle());
                            detail.setNumber(e.getReport().getNumber());
                            addDetailItemToMap(detailItemsMap, detail);
                        }
                    }
                    expenseIDSUsed.add(er.getObjectID());
                }
            }
        }

        List<EdsBankTransfer> bankTransfers = invoiceManager.getBankTransferByDate(from.getNonConvertedDate(), to.getNonConvertedDate());
        for (EdsBankTransfer bt : bankTransfers) {
            Integer transType = RECEIVE_MONEY.equals(bt.getTransferType()) ? TAX_SALES : TAX_PURCHASE;
            for (EdsBankTransferItem bti : bt.getItems()) {
                BigDecimal net = bti.getAmount();//bti.getQuantity().multiply(bti.getUnitPrice());

                LinkedList<VatReturnDetailItem> detailList = addUpVatReturnData(vatReturn, bti.getTax(), bti.getMoneyTransfer().getTaxCalculationType(), transType, net, null, flatPercent, calculationScale, bt.getExchangeRate());
                for (VatReturnDetailItem detail : detailList) {
                    detail.setObjectID(bt.getObjectID());
                    detail.setType(BANK_TRANSFER_TRANSACTION);
                    detail.setTransferType(Integer.valueOf(0).equals(bt.getTransferType())
                            ? RECEIVE_MONEY_STR
                            : SPEND_MONEY_STR);
                    detail.setName(bt.getName() + " | " + bt.getNumber());
                    detail.setNumber(bt.getNumber());
                    addDetailItemToMap(detailItemsMap, detail);
                }
            }
        }

        if (vatReturn.isFlatRate()) {
            vatReturn.setVatScheme(accrual ? "Flat Rate Accrual Scheme" : "Flat Rate Cash Scheme");
        } else {
            vatReturn.setVatScheme(accrual ? "Accrual Scheme" : "Cash Scheme");
        }

        vatReturn.setDetails(detailItemsMap);

        //Box3 calculation
        vatReturn.setTotalVatDue(vatReturn.getVatOnSalesAndOutputs().add(vatReturn.getVatFromECMemberStates()));
        //Box5 calculation
        vatReturn.setVatToReclaimFromCustoms(vatReturn.getTotalVatDue().subtract(vatReturn.getVatOnPurchaseAndInputs()));
        return vatReturn;
    }

    private DateNonConvertable getVatReturnPaymentDueDate(DateNonConvertable to) {
        Calendar toCalendar = new GregorianCalendar();
        toCalendar.setTime(to.getNonConvertedDate());
        toCalendar.set(Calendar.DATE, 1);
        toCalendar.set(Calendar.MONTH, toCalendar.get(Calendar.MONTH) + 1);
        toCalendar.set(Calendar.DATE, toCalendar.getActualMaximum(Calendar.DATE));
        return new DateNonConvertable(toCalendar.getTime());
    }

    private String getVatReturnPeriodType(DateNonConvertable from, DateNonConvertable to) {
        Calendar calFrom = new GregorianCalendar(), calTo = new GregorianCalendar();
        calFrom.setTime(from.getNonConvertedDate());
        calTo.setTime(to.getNonConvertedDate());
        if (calFrom.get(Calendar.DATE) == 1 && calTo.get(Calendar.DATE) == calTo.getActualMaximum(Calendar.DATE)) {
            if (calFrom.get(Calendar.MONTH) == calTo.get(Calendar.MONTH)) {
                int yearDifference = calTo.get(Calendar.YEAR) - calFrom.get(Calendar.YEAR);
                if (yearDifference == 1) {
                    return ANNUAL;
                } else if (yearDifference == 0) {
                    return MONTHLY1;
                } else {
                    return CUSTOM_RANGE;
                }
            } else {
                calFrom.set(Calendar.MONTH, calFrom.get(Calendar.MONTH) + 2);
                if (calFrom.get(Calendar.MONTH) == calTo.get(Calendar.MONTH)) {
                    return QUARTERLY;
                } else {
                    return CUSTOM_RANGE;
                }
            }
        } else {
            return CUSTOM_RANGE;
        }
    }

    private LinkedList<VatReturnDetailItem> addUpVatReturnData(VatReturnTransferObject vatReturn, EdsVat
            tax, Integer taxCalculationType, Integer transType, BigDecimal net, BigDecimal paymentShare, BigDecimal
                                                                       flatPercent, Integer calculationScale, BigDecimal exchangeRate) {
        if (vatReturn.isFlatRate()) {
            return addUpFlatRateVatReturnData(vatReturn, tax, taxCalculationType, transType, net, paymentShare, flatPercent, calculationScale, exchangeRate);
        } else {
            return addUpSimpleVatReturnData(vatReturn, tax, taxCalculationType, transType, net, paymentShare, calculationScale, exchangeRate);
        }
    }

    private void addDetailItemToMap
            (HashMap<Integer, LinkedList<VatReturnDetailItem>> detailItemsMap, VatReturnDetailItem detailItem) {
        if (detailItemsMap.containsKey(detailItem.getBoxID())) {
            LinkedList<VatReturnDetailItem> itemList = detailItemsMap.get(detailItem.getBoxID());
            VatReturnDetailItem groupItem = null;
            for (VatReturnDetailItem item : itemList) {
                if (item.getType().equals(detailItem.getType()) && item.getObjectID().equals(detailItem.getObjectID())) {
                    groupItem = item;
                }
            }
            if (groupItem != null) {
                groupItem.setAmount(groupItem.getAmount().add(detailItem.getAmount()));
            } else {
                detailItemsMap.get(detailItem.getBoxID()).add(detailItem);
            }
        } else {
            LinkedList<VatReturnDetailItem> itemList = new LinkedList<>();
            itemList.add(detailItem);
            detailItemsMap.put(detailItem.getBoxID(), itemList);
        }
    }

    public LinkedList<VatReturnDetailItem> addUpSimpleVatReturnData(VatReturnTransferObject vatReturn,
                                                                    EdsVat edsTax,
                                                                    Integer taxCalcType,
                                                                    Integer transType,
                                                                    BigDecimal discountedNet,
                                                                    BigDecimal paymentShare,
                                                                    Integer calculationScale,
                                                                    BigDecimal exchangeRate) {
        Integer taxType = edsTax != null && edsTax.getTaxType() != null ? edsTax.getTaxType() : 0;
        BigDecimal taxRate = edsTax != null ? edsTax.getTaxRateAsBigDecimal() : ZERO;

        if (paymentShare != null) {
            discountedNet = discountedNet.multiply(paymentShare);
        }
        if (exchangeRate == null) {
            exchangeRate = BigDecimal.ONE;
        }

        BigDecimal taxAmount = calculateVatReturnTax(taxCalcType, discountedNet, taxRate).setScale(calculationScale, RoundingMode.HALF_UP);

        BigDecimal calculatedNetAmount = (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType))
                ?
                discountedNet.subtract(taxAmount).setScale(calculationScale, RoundingMode.HALF_UP)
                :
                discountedNet.setScale(calculationScale, RoundingMode.HALF_UP);
        taxAmount = taxAmount.divide(exchangeRate, calculationScale, RoundingMode.UP);
        calculatedNetAmount = calculatedNetAmount.divide(exchangeRate, calculationScale, RoundingMode.HALF_UP);

        LinkedList<VatReturnDetailItem> detailItemList = new LinkedList<>();

        //Box1 calculation
        if (TAX_SALES.equals(transType) && TAX_SIMPLE.equals(taxType)) {
            vatReturn.setVatOnSalesAndOutputs(vatReturn.getVatOnSalesAndOutputs().add(taxAmount));
            detailItemList.add(new VatReturnDetailItem(1, taxAmount));
        }
        //Box2 calculation
        if (TAX_PURCHASE.equals(transType) && TAX_EC.equals(taxType)) {
            vatReturn.setVatFromECMemberStates(vatReturn.getVatFromECMemberStates().add(taxAmount));
            detailItemList.add(new VatReturnDetailItem(2, taxAmount));
        }

        // Box4 calculation
        if (TAX_PURCHASE.equals(transType) && (TAX_SIMPLE.equals(taxType) || TAX_EC.equals(taxType))) {
            vatReturn.setVatOnPurchaseAndInputs(vatReturn.getVatOnPurchaseAndInputs().add(taxAmount));
            detailItemList.add(new VatReturnDetailItem(4, taxAmount));
        }

        //Box6 calculation
        if (TAX_SALES.equals(transType) && (TAX_SIMPLE.equals(taxType) || TAX_EC.equals(taxType) || TAX_EXEMPT.equals(taxType))) {
            vatReturn.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs().add(calculatedNetAmount));
            detailItemList.add(new VatReturnDetailItem(6, calculatedNetAmount));
        }
        //Box7 calculation
        if (TAX_PURCHASE.equals(transType) && (TAX_SIMPLE.equals(taxType) || TAX_EC.equals(taxType) || TAX_EXEMPT.equals(taxType))) {
            vatReturn.setTotalPurchasesAndInputs(vatReturn.getTotalPurchasesAndInputs().add(calculatedNetAmount));
            detailItemList.add(new VatReturnDetailItem(7, calculatedNetAmount));
        }
        //Box8 calculation
        if (TAX_SALES.equals(transType) && TAX_EC.equals(taxType)) {
            vatReturn.setTotalSupplies(vatReturn.getTotalSupplies().add(calculatedNetAmount));
            detailItemList.add(new VatReturnDetailItem(8, calculatedNetAmount));
        }
        //Box9 calculation
        if (TAX_PURCHASE.equals(transType) && TAX_EC.equals(taxType)) {
            vatReturn.setTotalAcquisitions(vatReturn.getTotalAcquisitions().add(calculatedNetAmount));
            detailItemList.add(new VatReturnDetailItem(9, calculatedNetAmount));
        }

        return detailItemList;
    }

    public LinkedList<VatReturnDetailItem> addUpFlatRateVatReturnData(VatReturnTransferObject vatReturn,
                                                                      EdsVat edsTax,
                                                                      Integer taxCalcType,
                                                                      Integer transType,
                                                                      BigDecimal discountedNet,
                                                                      BigDecimal paymentShare,
                                                                      BigDecimal flatPercent,
                                                                      Integer calculationScale,
                                                                      BigDecimal exchangeRate) {
        Integer taxType = edsTax != null && edsTax.getTaxType() != null ? edsTax.getTaxType() : 0;
        BigDecimal taxRate = edsTax != null ? edsTax.getTaxRateAsBigDecimal() : ZERO;

        if (paymentShare != null) {
            discountedNet = discountedNet.multiply(paymentShare);
        }
        if (exchangeRate == null) {
            exchangeRate = BigDecimal.ONE;
        }

        BigDecimal taxAmount = calculateVatReturnTax(taxCalcType, discountedNet, taxRate).setScale(calculationScale, RoundingMode.HALF_UP);
        BigDecimal itemTotalAmount = (taxCalcType == null || TAX_CALCULATION_EXCLUSIVE.equals(taxCalcType))
                ? discountedNet.add(taxAmount).setScale(calculationScale, RoundingMode.HALF_UP)
                : discountedNet.setScale(calculationScale, RoundingMode.HALF_UP);
        BigDecimal flatRateTax = TAX_CAPITAL.equals(taxType)
                ? taxAmount
                : calculateVatReturnTax(TAX_CALCULATION_EXCLUSIVE, itemTotalAmount, flatPercent).setScale(calculationScale, RoundingMode.HALF_UP);

        taxAmount = taxAmount.divide(exchangeRate, calculationScale, RoundingMode.HALF_UP);
        itemTotalAmount = itemTotalAmount.divide(exchangeRate, calculationScale, RoundingMode.HALF_UP);
        flatRateTax = flatRateTax.divide(exchangeRate, calculationScale, RoundingMode.HALF_UP);
        discountedNet = discountedNet.divide(exchangeRate, calculationScale, RoundingMode.HALF_UP);

        LinkedList<VatReturnDetailItem> detailItemList = new LinkedList<>();

        //Box1 calculation
        if (TAX_SALES.equals(transType) && (TAX_SIMPLE.equals(taxType) || TAX_EXEMPT.equals(taxType) || TAX_CAPITAL.equals(taxType))) {
            vatReturn.setVatOnSalesAndOutputs(vatReturn.getVatOnSalesAndOutputs().add(flatRateTax));
            detailItemList.add(new VatReturnDetailItem(1, flatRateTax));
            //Set Flat Rate Scheme VAT Difference
            vatReturn.setFlatRateSchemeVatDifference(vatReturn.getFlatRateSchemeVatDifference().add(taxAmount.subtract(flatRateTax)));
        }

        // Box4 calculation
        if (TAX_PURCHASE.equals(transType) && TAX_CAPITAL.equals(taxType)) {
            vatReturn.setVatOnPurchaseAndInputs(vatReturn.getVatOnPurchaseAndInputs().add(taxAmount));
            detailItemList.add(new VatReturnDetailItem(4, taxAmount));
        }

        //Box6 calculation
        if (TAX_SALES.equals(transType) && (TAX_SIMPLE.equals(taxType) || TAX_EC.equals(taxType) || TAX_EXEMPT.equals(taxType) || TAX_CAPITAL.equals(taxType))) {
            if (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType)) {
                if (TAX_CAPITAL.equals(taxType)) {
                    vatReturn.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs().add(discountedNet.subtract(taxAmount)));
                    detailItemList.add(new VatReturnDetailItem(6, discountedNet.subtract(taxAmount)));
                } else {
                    vatReturn.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs().add(itemTotalAmount));
                    detailItemList.add(new VatReturnDetailItem(6, itemTotalAmount));
                }
            } else {
                if (TAX_CAPITAL.equals(taxType)) {
                    vatReturn.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs().add(discountedNet));
                    detailItemList.add(new VatReturnDetailItem(6, discountedNet));
                } else {
                    vatReturn.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs().add(itemTotalAmount));
                    detailItemList.add(new VatReturnDetailItem(6, itemTotalAmount));
                }
            }
        }
        //Box7 calculation
        if (TAX_PURCHASE.equals(transType) && (TAX_EC.equals(taxType) || TAX_CAPITAL.equals(taxType))) {
            if (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType)) {
                vatReturn.setTotalPurchasesAndInputs(vatReturn.getTotalPurchasesAndInputs().add(discountedNet.subtract(taxAmount)));
                detailItemList.add(new VatReturnDetailItem(7, discountedNet.subtract(taxAmount)));
            } else {
                vatReturn.setTotalPurchasesAndInputs(vatReturn.getTotalPurchasesAndInputs().add(discountedNet));
                detailItemList.add(new VatReturnDetailItem(7, discountedNet));
            }
        }
        //Box8 calculation
        if (TAX_SALES.equals(transType) && TAX_EC.equals(taxType)) {
            if (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType)) {
                vatReturn.setTotalSupplies(vatReturn.getTotalSupplies().add(discountedNet.subtract(taxAmount)));
                detailItemList.add(new VatReturnDetailItem(8, discountedNet.subtract(taxAmount)));
            } else {
                vatReturn.setTotalSupplies(vatReturn.getTotalSupplies().add(discountedNet));
                detailItemList.add(new VatReturnDetailItem(8, discountedNet.subtract(taxAmount)));
            }
        }
        //Box9 calculation
        if (TAX_PURCHASE.equals(transType) && TAX_EC.equals(taxType)) {
            if (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType)) {
                vatReturn.setTotalAcquisitions(vatReturn.getTotalAcquisitions().add(discountedNet.subtract(taxAmount)));
            } else {
                vatReturn.setTotalAcquisitions(vatReturn.getTotalAcquisitions().add(discountedNet).setScale(calculationScale, RoundingMode.HALF_UP));
            }
        }

        return detailItemList;
    }

    private BigDecimal calculateVatReturnTax(Integer taxCalcType, BigDecimal discountedNet, BigDecimal taxRate) {
        BigDecimal tax;
        if (TAX_CALCULATION_INCLUSIVE.equals(taxCalcType)) {
            tax = discountedNet.multiply(taxRate).divide(HUNDRED.add(taxRate), 8, RoundingMode.HALF_UP);
        } else {
            tax = discountedNet.multiply(taxRate).divide(HUNDRED, 8, RoundingMode.HALF_UP);
        }
        return tax;
    }

    public String saveVatReturnReport(DateNonConvertable fromDateNC, DateNonConvertable
            toDateNC, VatReturnTransferObject vatReturn) {
        EdsUser user = vatEFilingManager.getUser();

        Integer calculationScale = financialSettingsManager.getFinancialSettings().getAccountingCalculationScale();

        Date from = fromDateNC.getNonConvertedDate();
        Date to = toDateNC.getNonConvertedDate();

        boolean containsDate = false;
        List<EdsVatEFiling> reportsList = vatEFilingManager.getCompanyVatReturnReportList();
        for (EdsVatEFiling vef : reportsList) {
            if (from.after(vef.getFromDate()) && from.before(vef.getToDate())) {
                containsDate = true;
            }
            if (to.after(vef.getFromDate()) && to.before(vef.getToDate())) {
                containsDate = true;
            }
            if (vef.getFromDate().after(from) && vef.getFromDate().before(to)) {
                containsDate = true;
            }
            if (vef.getToDate().after(from) && vef.getToDate().before(to)) {
                containsDate = true;
            }
            if (from.equals(vef.getFromDate()) && to.equals(vef.getToDate())) {
                containsDate = true;
            }
        }
        if (containsDate) {
            return "Vat Return Report for this period already submitted. Please select another period.";
        }

        EdsVatEFiling vatEFiling = new EdsVatEFiling();
        vatEFiling.setRegistrationNumber(vatReturn.getRegistrationNumber());
        vatEFiling.setVatScheme(vatReturn.getVatScheme());
        vatEFiling.setFromDate(from);
        vatEFiling.setToDate(to);
        vatEFiling.setSubmissionDate(new Date());
        vatEFiling.setSubmitter(user.getObjectID());
        vatEFiling.setCompanyID(user.getCompany().getObjectID());
        vatEFiling.setVatOnSalesAndOutputs(vatReturn.getVatOnSalesAndOutputs());
        vatEFiling.setVatFromECMemberStates(vatReturn.getVatFromECMemberStates());
        vatEFiling.setTotalVatDue(vatReturn.getTotalVatDue());
        vatEFiling.setVatOnPurchaseAndInputs(vatReturn.getVatOnPurchaseAndInputs());
        vatEFiling.setVatToReclaimFromCustoms(vatReturn.getVatToReclaimFromCustoms());
        vatEFiling.setTotalSalesAndOutputs(vatReturn.getTotalSalesAndOutputs());
        vatEFiling.setTotalPurchasesAndInputs(vatReturn.getTotalPurchasesAndInputs());
        vatEFiling.setTotalSupplies(vatReturn.getTotalSupplies());
        vatEFiling.setTotalAcquisitions(vatReturn.getTotalAcquisitions());
        if (vatReturn.getVatToReclaimFromCustoms().setScale(calculationScale, RoundingMode.HALF_UP).compareTo(ZERO) == 0) {
            vatEFiling.setStatus(SUBMISSION_PENDING);
        } else {
            vatEFiling.setStatus(SUBMISSION_SAVED);
        }
        vatEFilingManager.create(vatEFiling);
        return null;
    }

    @Override
    public String submitVatReturnReportToHMRC(Integer vatReturnID) {
        EdsVatEFiling vatEFiling = vatEFilingManager.get(vatReturnID);
        vatEFiling.setStatus(SUBMISSION_PENDING);
        vatEFilingManager.update(vatEFiling);
        return null;
    }

    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ListResult<VatReturnTransferObject> getVatReturnReportList(ListingFilterParameter filterParameter) {
        List<EdsVatEFiling> vefList = vatEFilingManager.getCompanyVatReturnReportList();
        int total = vefList.size();
        if (filterParameter != null) {
            vefList = ListUtils.getSublist(vefList, filterParameter.getStart(), filterParameter.getLimit());
        }
        ArrayList<VatReturnTransferObject> items = new ArrayList<>();
        for (EdsVatEFiling vef : vefList) {
            VatReturnTransferObject vrData = vef.createTransferObject();
            vrData.setPaidAmount(vatEFilingManager.getVatReturnPaymentTotal(vef.getObjectID()));
            items.add(vrData);
        }
        return new ListResult<>(items, total);
    }

