    @Override
    public SelectItem[] getUnitMeasurements(ListingFilterParameter filterParametrs) {
        List<EdsUnitMeasurement> measurements = unitMeasurementManager.getUnitMeasurements(null, /*accountingManager.getUser().getCompany().getObjectID()*/null);
        if (measurements == null || measurements.isEmpty()) {
            return new SelectItem[0];
        } else {
            SelectItem[] result = new SelectItem[measurements.size()];
            int i = 0;
            for (EdsUnitMeasurement m : measurements) {
                result[i] = new SelectItem(m.getObjectID(), m.getName(), m.getDescription());
                i++;
            }
            return result;
        }

    }

