    @Override
    public ImportStatus onChartOfAccountsImport(ImportFile importFile, boolean deleteNotUsedAccounts) {
//        EdsImportFile edsImportFile = importFileManager.get(importFile.getObjectID());
        EdsAttachment attachment = attachmentManager.get(importFile.getFileID());
        EdsUser user = userManager.getUser();
        InputStream inputStream = uploadManager.getInputStream(attachment);
        InputStreamReader isr = new InputStreamReader(inputStream);
        CSVReader reader = new CSVReader(isr, importFile.getDefaultSeparator());
        importFile.setUserID(user.getObjectID());
//        RejectedImportRecordsExcelHandler rejectedRecordsExcelHandler = (RejectedImportRecordsExcelHandler) ApplicationContextProvider.applicationContext.getBean("rejectedImportRecordsExcelHandler");
        RejectedImportRecordsExcelHandler rejectedRecordsExcelHandler = new RejectedImportRecordsExcelHandler();
        if (deleteNotUsedAccounts) {
            accountingManager.deleteGLAccountsInattendedInInvoices();
        }

        List<String> accountsImported = new LinkedList<>();
        List<String> accountsNotImported = new LinkedList<>();
        List<String> updatedAccountCodes = Lists.newArrayList();
        try {
            List<String[]> listOfRows = reader.readAll();
            //Import Accounts
            ArrayList<RejectedImportRecord[]> rejectedRecords = importChartOfAccounts(importFile, listOfRows, accountsImported, accountsNotImported, updatedAccountCodes);

            EdsImportFile edsImportFile = importFile.getObjectID() != null
                    ? importFileManager.get(importFile.getObjectID())
                    : new EdsImportFile(importFile);
            edsImportFile.setCommitted(true);
            if (user != null) {
                edsImportFile.setOwner(user);
            }
            //Set Total number of created Opportunities
            edsImportFile.setImportedColumns(importFile.getImportedColumns());
            //Set Total number of REJECTED Opportunities
            edsImportFile.setIgnoredColumns(importFile.getIgnoredColumns());
            //Set Total non empty rows which were processed
            edsImportFile.setCsvColumns(edsImportFile.getImportedColumns() + edsImportFile.getIgnoredColumns() + (
                    edsImportFile.isHasHeader()
                            ? 1
                            : 0));

            if (rejectedRecords.size() > (edsImportFile.isHasHeader() ? 1 : 0)) {
                initRejectedRecordsForSending(edsImportFile, rejectedRecordsExcelHandler.run2(rejectedRecords, "Rejected_ChartOfAccounts"), "Rejected_ChartOfAccounts.xls");
            }
            //Set Status as COMPLETED
            edsImportFile.setStatus(ImportStatusEnum.COMPLETED);
            //Update import file which will displayed in the UI (Settings->System Logs)
            if (edsImportFile.getObjectID() != null) {
                importFileManager.update(edsImportFile);
            } else {
                importFileManager.create(edsImportFile);
            }
            messageManager.sendImportReportMessage(edsImportFile.getObjectID());

//            Integer attachmentID = rejectedRecords != null && rejectedRecords.size() > (importFile.isHasHeader() ? 1 : 0) ? initRejectedRecordsForSending(rejectedRecordsExcelHandler.run(rejectedRecords, "ChartOfAccounts"), "Chart_of_Accounts.xls") : null;
//            if (attachmentID != null) {
//                edsImportFile.setRejectedRecords(attachmentManager.get(attachmentID));
//            }
//            messageManager.sendImportReportMessage(importFile.getObjectID());
        } catch (IOException e) {
            e.printStackTrace();
        }

        ImportStatus status = new ImportStatus();
        status.setImportedAccounts(accountsImported.toArray(new String[]{}));
        status.setNotImportedAccounts(accountsNotImported.toArray(new String[]{}));

        sorlReindexImportedChartOfAccounts(updatedAccountCodes);
        return status;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void onTransactionImport(ImportFile importFile, ArrayList<RejectedImportRecord[]> rejectedRecords) {
        EdsBankAccountAttachment att = bankAccountAttachmentManager.get(importFile.getFileID());
        EdsUser user = userManager.getUser();
        importFile.setUserID(user.getObjectID());
        RejectedImportRecordsExcelHandler rejectedRecordsExcelHandler = new RejectedImportRecordsExcelHandler();
        EdsImportFile edsImportFile = importFile.getObjectID() != null
                ? importFileManager.get(importFile.getObjectID())
                : new EdsImportFile(importFile);
        edsImportFile.setCommitted(true);
        if (user != null) {
            edsImportFile.setOwner(user);
        }
        edsImportFile.setImportedColumns(importFile.getImportedColumns());
        edsImportFile.setIgnoredColumns(importFile.getIgnoredColumns());
        edsImportFile.setSkippedColumns(importFile.getSkippedColumns());
        edsImportFile.setCsvColumns(importFile.getCsvColumns());

        if (rejectedRecords.size() > (edsImportFile.isHasHeader() ? 1 : 0)) {
            initRejectedRecordsForSending(edsImportFile, rejectedRecordsExcelHandler.run2(rejectedRecords, "Rejected_Transactions"), "Rejected_Transactions.xls");
        }
        edsImportFile.setStatus(ImportStatusEnum.COMPLETED);
        edsImportFile.setType(ImportTypeEnum.TRANSACTION);
        edsImportFile.setDefaultSeparator(",");
        EdsAttachment attachment = new EdsAttachment();
        if (attachmentManager.get(importFile.getFileID()) == null) {
            attachment.setCaseAttachmentCopied(false);
            attachment.setCreator(userManager.getUser());
            attachment.setCreationTime(new Date());
            attachment.setDeleted(false);
            attachment.setLastUpdateTime(new Date());
            attachment.setDownloadable(true);
            attachment.setOriginalName(att.getOriginalName());
            attachment.setContentType(att.getContentType());
            attachment.setSize(att.getSize());
            attachment.setLocalPath(att.getLocalPath());
            attachment.setType(att.getType());
            attachment.setInputStream(uploadManager.getInputStream(att));
            attachmentManager.create(attachment);
        }
        //Update import file which will displayed in the UI (Settings->Import Logs)
        edsImportFile.setFileID(attachment.getObjectID());
        if (edsImportFile.getObjectID() != null) {
            importFileManager.update(edsImportFile);
        } else {
            importFileManager.create(edsImportFile);
        }
        messageManager.sendImportReportMessage(edsImportFile.getObjectID());
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public ArrayList<RejectedImportRecord[]> importChartOfAccounts(ImportFile importFile, List<String[]> dataBank,
                                                                   List<String> accountsImported, List<String> accountsNotImported, List<String> updatedAccountCodes) {

        /*List<MapEntry<String, MapEntry<Boolean, String>>[]> rejectedRecords = new LinkedList<>();
        MapEntry<String, MapEntry<Boolean, String>>[] rejectedRow;*/

        ArrayList<RejectedImportRecord[]> rejectedRows = new ArrayList<>();

        Integer FIELD_ACCOUNT_TYPE = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_ACCOUNT_TYPE);
        Integer FIELD_CODE = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_CODE);
        Integer FIELD_NAME = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_NAME);
        Integer FIELD_DESCRIPTION = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_DESCRIPTION);
        Integer FIELD_TAX_RATE = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_TAX_RATE);
        Integer FIELD_SHOW_IN_EXPENSE = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_SHOW_IN_EXPENSE);
        Integer FIELD_ENABLE_PAYMENT = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_ENABLE_PAYMENT);
        Integer FIELD_PARENT_CODE = importFile.getColumnID(ImportField.ChartOfAccountsFields.FIELD_PARENT_CODE);

        Integer sysDefaultAccountTypeId = importFile.getColumnID(ImportField.ChartOfAccountsFields.SYSTEM_ACCOUNT_TYPE);
        Integer sysDefaultTaxRateId = importFile.getColumnID(ImportField.ChartOfAccountsFields.SYSTEM_TAX_RATE);

        List<EdsAccountType> accountTypeList = accountingManager.getAccountTypes();
        List<EdsAccount> accountsList = accountingManager.getAccounts(null);
        //Convert AccountTypes to Map using JAVA 8 features
        Map<String, EdsAccountType> accTypes = accountTypeList.stream().collect(Collectors.toMap(accType -> accountingLocalizer.localize(accType.getCode(), accType.getName()).toLowerCase(), accType -> accType));
        //Convert AccountList to Map using JAVA 8 features
        Map<String, String> accountCodes = accountsList.stream().collect(Collectors.toMap(EdsAccount::getAccountCode, EdsAccount::getAccountCode));
        Map<String, String> accountCodesMap = new HashMap<>();
        Map<String, EdsVat> taxRates = getTaxesMap();

        EdsCurrency basecurrency = null;
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        if (financialSettings != null) {
            basecurrency = financialSettings.getCurrency();
        }

        List<EdsAccount> accountsForImport = new LinkedList<>();
        boolean hasHeader = importFile.isHasHeader();

        nextRow:
        for (String[] row : dataBank) {

            if (hasHeader) {
                RejectedImportRecord[] rejectedCells = new RejectedImportRecord[row.length];
                int cellIndex = 0;
                for (String cellValue : row) {
                    rejectedCells[cellIndex++] = new RejectedImportRecord(cellValue);
                }
                //Add Header row into final result
                rejectedRows.add(rejectedCells);
                hasHeader = false;
            } else {

                boolean rowIsEmpty = true;//To check if row is not blank

                for (String cellvalue : row) {
                    if (rowIsEmpty && StringUtils.isNotBlank(cellvalue)) {
                        rowIsEmpty = false;
                        break;
                    }
                }
                if (rowIsEmpty) {
                    continue nextRow;
                }

                EdsAccountType accountType = null;
                EdsVat taxRate = null;
                EdsAccount parent = null;
                String code = null, name = null, description = null;
                String acc_f_code = row[FIELD_CODE];

                RejectedImportRecord[] rejectedCells = new RejectedImportRecord[row.length];

                String parent_acc_f_code = FIELD_PARENT_CODE > -1 ? row[FIELD_PARENT_CODE] : null;
                if (parent_acc_f_code != null && !accountCodes.containsKey(acc_f_code.trim())) {
                    accountCodesMap.put(acc_f_code.trim(), parent_acc_f_code.trim());
                }

                boolean showInExpense = false, enablePayment = false;

                Integer csvColumnID = 0;

                for (String cellValue : row) {

                    rejectedCells[csvColumnID] = new RejectedImportRecord(cellValue);
                    //We will process only if CellValue is not blank
                    if (StringUtils.isNotBlank(cellValue)) {
                        //Trim value
                        cellValue = cellValue.trim();
                        //Truncate CellValue
                        if (cellValue != null && cellValue.length() > 250) {
                            log.info("!!!!!!!!!!!!!" + csvColumnID + ":::" + cellValue + ":::" + cellValue.length());
                            cellValue = cellValue.substring(0, 250).trim();
                        }

//                        Integer columnID = i;
                        if (csvColumnID.equals(FIELD_ACCOUNT_TYPE)) {
                            accountType = accTypes.get(cellValue.toLowerCase());
                        }
                        if (csvColumnID.equals(FIELD_CODE)) {
                            code = cellValue;
                        }
                        if (csvColumnID.equals(FIELD_NAME)) {
                            name = cellValue;
                        }
                        if (csvColumnID.equals(FIELD_DESCRIPTION)) {
                            description = cellValue;
                        }
                        if (csvColumnID.equals(FIELD_TAX_RATE)) {
                            taxRate = taxRates.get(cellValue.trim().toLowerCase());
                        }
                        if (csvColumnID.equals(FIELD_SHOW_IN_EXPENSE)) {
                            showInExpense = cellValue.equalsIgnoreCase("yes");
                        }
                        if (csvColumnID.equals(FIELD_ENABLE_PAYMENT)) {
                            enablePayment = cellValue.equalsIgnoreCase("yes");
                        }
                        if (csvColumnID.equals(FIELD_PARENT_CODE)) {
                            parent = accountingManager.getAccountByCode(cellValue.trim());
                        }
                    }
                    csvColumnID++;
                }

                if (accountType == null && sysDefaultAccountTypeId != null) {
                    accountType = accountTypeManager.get(sysDefaultAccountTypeId);
                }
                if (taxRate == null && sysDefaultTaxRateId != null) {
                    taxRate = vatManager.get(sysDefaultTaxRateId);
                }

                int errors = 0;
                if (accountType == null) {
                    errors++;
                    rejectedCells[FIELD_ACCOUNT_TYPE].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, rejectedCells[FIELD_ACCOUNT_TYPE].getData()));
                }

                if (StringUtils.isBlank(code) || accountCodes.containsKey(code.trim())) {
                    errors++;
                    rejectedCells[FIELD_CODE].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.accountWithThisCodeAlreadyExists, code));
                }
                if (StringUtils.isBlank(name)) {
                    errors++;
                    rejectedCells[FIELD_NAME].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, rejectedCells[FIELD_NAME].getData()));
                }

                if (errors == 0) {
                    //If all validation passed
                    code = code.trim();
                    accountCodes.put(code, code);
                    EdsUser user = userManager.getUser();

                    EdsAccount account = new EdsAccount();
                    account.setAccountType(accountType);
                    account.setAccountCode(code);
                    account.setCodeString(code);
                    account.setName(name);
                    account.setDescription(description);
                    account.setTax(taxRate);
                    account.setParent(parent != null && !code.equals(parent.getAccountCode()) && (accountType == null || accountType.equals(parent.getAccountType()))
                            ? parent
                            : null);
                    account.setShowInExpense(showInExpense);
                    account.setEnablePayments(enablePayment);
                    account.setCreationTime(new Date());
                    account.setLastUpdatedDate(new Date());
                    if (user != null) {
                        account.setCreator(user);
                        account.setUpdater(user);
                    }
                    if (basecurrency != null) {
                        account.setCurrency(basecurrency);
                    }
                    accountsForImport.add(account);

                    //Increment number of imported ROWs
                    importFile.setImportedColumns(importFile.getImportedColumns() + 1);

                } else {
                    //If validation not passed
                    accountsNotImported.add(name);

                    rejectedRows.add(rejectedCells);
                    //Increment number of rejected ROWs
                    importFile.setIgnoredColumns(importFile.getIgnoredColumns() + 1);
                }
            }
        }

        if (!accountsForImport.isEmpty()) {
            for (EdsAccount account : accountsForImport) {
                accountingManager.create(account);

                if (account.getAccountType() != null && EdsAccountType.BANK.equals(account.getAccountType().getCode())) {
                    createBankAcount(account, new AddAccountItem());
                }
                accountsImported.add(account.getName());
            }

            try {
                chartOfAccountSolrComponent.indexes(accountsForImport);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        if (!accountCodesMap.isEmpty()) {
            StringBuilder sql = new StringBuilder();
            for (Map.Entry<String, String> mapItem : accountCodesMap.entrySet()) {
                String accCode = mapItem.getKey();
                String parentAccCode = mapItem.getValue();
                if (StringUtils.isNotBlank(parentAccCode) && StringUtils.isNotBlank(accCode) && !accCode.equalsIgnoreCase(parentAccCode)) {
                    sql.append("UPDATE ").append(BaseManager.getCompanyId()).append(".account ");
                    sql.append(" SET parentid = (SELECT id from ").append(BaseManager.getCompanyId());
                    sql.append(".account WHERE deleted is not true AND accountcode = '").append(parentAccCode);
                    sql.append("') WHERE deleted is not true AND accountcode = '").append(accCode).append("'; \n");
                    updatedAccountCodes.add(accCode);
                }
            }
            accountingManager.setParentCodesToChilds(sql.toString());
        }
        return rejectedRows;
    }

    @Override
    @Transactional
    public void sorlReindexImportedChartOfAccounts(List<String> updatedAccountCodes) {
        if (updatedAccountCodes != null && !updatedAccountCodes.isEmpty()) {
            accountingManager.flushAndClear();
            for (List<String> partitionedCodes : Lists.partition(updatedAccountCodes, 50)) {
                List<EdsAccount> edsAccounts = accountingManager.getAccountByCodes(partitionedCodes);

                if (edsAccounts != null && !edsAccounts.isEmpty()) {
                    try {
                        chartOfAccountSolrComponent.indexes(edsAccounts);
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }

