    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public ArrayList<RejectedImportRecord[]> importBudgetManagerItems(ImportFile importFile, List<String[]> dataBank,
                                                                      List<String> budgetItemsImported, List<String> budgetItemsNotImported, List<String> updatedBudgetItems) {

        ArrayList<RejectedImportRecord[]> rejectedRows = null;
        EdsBudgetManager edsBudgetManager = budgetManager.get(importFile.getBudgetID());
        if (edsBudgetManager != null && edsBudgetManager.getBudgetColumns() != null) {

            List<EdsBudgetManagerItem> budgetItemsForImport = new LinkedList<>();
            rejectedRows = new ArrayList<>();
            boolean hasHeader = importFile.isHasHeader();
            SimpleDateFormat format = new SimpleDateFormat(DATE_PATTERN);
            HashMap<String, String> columnsBudget = new HashMap<>();
            Gson gson = new Gson();
            BudgetColumn[] columns = gson.fromJson(edsBudgetManager.getBudgetColumns(), BudgetColumn[].class);
            if (columns != null) {
                for (BudgetColumn budgetCol : columns) {
                    if (StringUtils.isNotBlank(budgetCol.getName()) && Constants.EDITABLE.equals(budgetCol.getType())) {
                        columnsBudget.put(budgetCol.getName().trim().toLowerCase(), budgetCol.getCode());
                    }
                }
            }
            EdsBudgetManagerSettings edsBudgetManagerSettings = budgetManagerSettings.getSettingsByBudget(edsBudgetManager.getObjectID());
            HashMap<Integer, List<Integer>> selectedItems = new HashMap<>();
            HashMap<Integer, String> budgetColumns = new HashMap<>();
            nextRow:
            for (String[] row : dataBank) {

                if (hasHeader) {
                    RejectedImportRecord[] rejectedCells = new RejectedImportRecord[row.length];
                    int cellIndex = 0;
                    int i = 0;
                    for (String cellValue : row) {
                        rejectedCells[cellIndex++] = new RejectedImportRecord(cellValue);
                        if (i > 2 && StringUtils.isNotBlank(cellValue) && columnsBudget.get(cellValue.trim().toLowerCase()) != null) {
                            budgetColumns.put(i, columnsBudget.get(cellValue.trim().toLowerCase()));
                        }
                        i++;
                    }
                    //Add Header row into final result
                    rejectedRows.add(rejectedCells);
                    hasHeader = false;
                } else {
                    boolean rowIsEmpty = true;//To check if row is not blank

                    for (String cellvalue : row) {
                        if (rowIsEmpty && StringUtils.isNotBlank(cellvalue)) {
                            rowIsEmpty = false;
                            break;
                        }
                    }
                    if (rowIsEmpty) {
                        continue nextRow;
                    }

                    RejectedImportRecord[] rejectedCells = new RejectedImportRecord[row.length];


                    Integer csvColumnID = 0;
                    String groupBy = null;
                    Integer groupID = null;
                    String entityName = null;
                    Integer entityID = null;
                    Date period = null;
                    int errors = 0;
                    List<AccountBudget> budgetManagerItems = new ArrayList<>();
                    for (String cellValue : row) {

                        rejectedCells[csvColumnID] = new RejectedImportRecord(cellValue);
                        //We will process only if CellValue is not blank
                        if (StringUtils.isNotBlank(cellValue)) {
                            //Trim value
                            cellValue = cellValue.trim();
                            //Truncate CellValue
                            if (cellValue != null && cellValue.length() > 250) {
                                log.info("!!!!!!!!!!!!!" + csvColumnID + ":::" + cellValue + ":::" + cellValue.length());
                                cellValue = cellValue.substring(0, 250).trim();
                            }

                            if (csvColumnID == 0) {
                                groupBy = cellValue;
                            } else if (csvColumnID == 1) {
                                entityName = cellValue;
                            } else if (csvColumnID == 2) {
                                try {
                                    period = format.parse(cellValue.toLowerCase());
                                } catch (Exception e) {
                                    errors++;
                                    rejectedCells[2].setErrorComment(commonLocalizer.localize(PdfLocalizationName.invalidDateFormat));
                                }
                            } else if (csvColumnID > 2 && budgetColumns.get(csvColumnID) != null) {
                                BigDecimal budget = null;
                                try {
                                    budget = new BigDecimal(cellValue.trim().replace(",", ""));
                                } catch (Exception ignored) {
                                }
                                if (budget == null) {
                                    errors++;
                                    rejectedCells[csvColumnID].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, entityName));
                                } else {
                                    AccountBudget budgetManagerItem = new AccountBudget();
                                    budgetManagerItem.setId(csvColumnID);
                                    budgetManagerItem.setColumnCode(budgetColumns.get(csvColumnID));
                                    budgetManagerItem.setBudget(budget);
                                    budgetManagerItems.add(budgetManagerItem);
                                }
                            }
                        }
                        csvColumnID++;
                    }

                    if (Constants.PRODUCTS.equals(edsBudgetManager.getType())) {
                        EdsItem edsItem = itemManager.getItemByNumber(entityName);
                        if (edsItem != null) {
                            entityID = edsItem.getObjectID();

                            if (CustomFormConstants.CATEGORY.equals(edsBudgetManager.getGroupBy())) {
                                if (StringUtils.isNotBlank(groupBy)) {
                                    EdsProductCategory edsProductCategory = productCategoryManager.getCategoryByName(groupBy);
                                    if (edsProductCategory != null) {
                                        groupID = edsProductCategory.getObjectID();
                                    }
                                } else if (edsItem != null && edsItem.getCategory() != null) {
                                    groupID = edsItem.getCategory().getObjectID();
                                }

                            } else if (CustomFormConstants.BRAND.equals(edsBudgetManager.getGroupBy())) {
                                if (StringUtils.isNotBlank(groupBy)) {
                                    EdsBrand edsBrand = brandManager.getBrandByName(groupBy);
                                    if (edsBrand != null) {
                                        groupID = edsBrand.getObjectID();
                                    }
                                } else if (edsItem != null && edsItem.getBrand() != null) {
                                    groupID = edsItem.getBrand().getObjectID();
                                }
                                if (groupID == null) {
                                    groupID = 0;
                                }


                            } else if (edsBudgetManager.getGroupBy() != null && (edsBudgetManager.getGroupBy().contains("string_value") || edsBudgetManager.getGroupBy().contains("double_value") || edsBudgetManager.getGroupBy().contains("date_value"))) {
                                EdsCompanyCustomFieldsSettings companyCustomFieldsSettings = this.companyCustomFieldsManager.getCompanyCustomField(ViewName.ProductServiceView.name(), edsBudgetManager.getGroupBy());
                                if (companyCustomFieldsSettings != null && companyCustomFieldsSettings.getLookUpType() != null && (Constants.UI_TYPE_LOOKUP.equals(companyCustomFieldsSettings.getUiType()) || Constants.UI_TYPE_MULTI_LOOKUP.equals(companyCustomFieldsSettings.getUiType()))) {
                                    ListingFilterParameter filterParameter = new ListingFilterParameter();
                                    filterParameter.setSearchKey(groupBy);
                                    filterParameter.setStart(0);
                                    filterParameter.setLimit(1);
                                    if (CustomFieldLookUpTypeEnum.REFERENCE.equals(companyCustomFieldsSettings.getLookUpType())) {
                                        filterParameter.setParentID(companyCustomFieldsSettings.getReference() != null ? companyCustomFieldsSettings.getReference().getId() : null);
                                    }
                                    SelectItem[] selectItems = allInOneService.getCustomFieldLookUpData(filterParameter, companyCustomFieldsSettings.getLookUpType());
                                    if (selectItems != null && selectItems.length > 0) {
                                        groupID = selectItems[0].getId();
                                    }
                                }
                            }

                            if (groupID == null) {
                                groupID = 0;
                            }
                        }
                    } else if (Constants.CUSTOMER.equals(edsBudgetManager.getType())) {
                        EdsCrmAccount edsCrmAccount = crmAccountManager.getCrmAccountByNumber(entityName);
                        if (edsCrmAccount != null) {
                            entityID = edsCrmAccount.getObjectID();
                        }
                        if (StringUtils.isNotBlank(groupBy)) {
                            if (edsBudgetManager.getGroupBy() != null && (edsBudgetManager.getGroupBy().contains("string_value") || edsBudgetManager.getGroupBy().contains("double_value") || edsBudgetManager.getGroupBy().contains("date_value"))) {
                                EdsCompanyCustomFieldsSettings companyCustomFieldsSettings = this.companyCustomFieldsManager.getCompanyCustomField(ViewName.CrmAccount.name(), edsBudgetManager.getGroupBy());
                                if (companyCustomFieldsSettings != null && companyCustomFieldsSettings.getLookUpType() != null && (Constants.UI_TYPE_LOOKUP.equals(companyCustomFieldsSettings.getUiType()) || Constants.UI_TYPE_MULTI_LOOKUP.equals(companyCustomFieldsSettings.getUiType()))) {
                                    ListingFilterParameter filterParameter = new ListingFilterParameter();
                                    filterParameter.setSearchKey(groupBy);
                                    filterParameter.setStart(0);
                                    filterParameter.setLimit(1);
                                    if (CustomFieldLookUpTypeEnum.REFERENCE.equals(companyCustomFieldsSettings.getLookUpType())) {
                                        filterParameter.setParentID(companyCustomFieldsSettings.getReference() != null ? companyCustomFieldsSettings.getReference().getId() : null);
                                    }
                                    SelectItem[] selectItems = allInOneService.getCustomFieldLookUpData(filterParameter, companyCustomFieldsSettings.getLookUpType());
                                    if (selectItems != null && selectItems.length > 0) {
                                        groupID = selectItems[0].getId();
                                    }
                                }
                            }
                        }
                    } else if (Constants.CHART_OF_ACCOUNT.equals(edsBudgetManager.getType())) {
                        EdsAccount edsCrmAccount = accountingManager.getAccountByCode(entityName);
                        if (edsCrmAccount != null) {
                            entityID = edsCrmAccount.getObjectID();
                        }
                    } else if (Constants.OPPORTUNITY.equals(edsBudgetManager.getType())) {
                        EdsOpportunity edsOpportunity = opportunityManager.getByNumber(entityName);
                        if (edsOpportunity != null) {
                            entityID = edsOpportunity.getObjectID();
                        }
                        if (StringUtils.isNotBlank(groupBy)) {
                            if (CustomFormConstants.ASSIGNEE.equals(edsBudgetManager.getGroupBy()) || CustomFormConstants.BACKUP_ASSIGNEE.equals(edsBudgetManager.getGroupBy())) {
                                EdsEmployee edsEmployee = employeeManager.getEmployeeByNumber(groupBy);
                                if (edsEmployee != null) {
                                    groupID = edsEmployee.getObjectID();
                                }
                            } else if (CustomFormConstants.CRM_OPPORTUNITY_STAGE.equals(edsBudgetManager.getGroupBy())) {
                                EdsReference stage = referenceManager.findByParentCodeAndName(EdsOpportunity._OPPORTUNITY_STAGE, groupBy);
                                if (stage != null) {
                                    groupID = stage.getObjectID();
                                }
                            } else if (Constants.PRODUCTS.equals(edsBudgetManager.getGroupBy())) {
                                EdsItem edsItem = itemManager.getItemByNumber(groupBy);
                                if (edsItem != null) {
                                    groupID = edsItem.getObjectID();
                                }
                            } else if (edsBudgetManager.getGroupBy() != null && (edsBudgetManager.getGroupBy().contains("string_value") || edsBudgetManager.getGroupBy().contains("double_value") || edsBudgetManager.getGroupBy().contains("date_value"))) {
                                EdsCompanyCustomFieldsSettings companyCustomFieldsSettings = this.companyCustomFieldsManager.getCompanyCustomField(ViewName.Opportunity.name(), edsBudgetManager.getGroupBy());
                                if (companyCustomFieldsSettings != null && companyCustomFieldsSettings.getLookUpType() != null && (Constants.UI_TYPE_LOOKUP.equals(companyCustomFieldsSettings.getUiType()) || Constants.UI_TYPE_MULTI_LOOKUP.equals(companyCustomFieldsSettings.getUiType()))) {
                                    ListingFilterParameter filterParameter = new ListingFilterParameter();
                                    filterParameter.setSearchKey(groupBy);
                                    filterParameter.setStart(0);
                                    filterParameter.setLimit(1);
                                    if (CustomFieldLookUpTypeEnum.REFERENCE.equals(companyCustomFieldsSettings.getLookUpType())) {
                                        filterParameter.setParentID(companyCustomFieldsSettings.getReference() != null ? companyCustomFieldsSettings.getReference().getId() : null);
                                    }
                                    SelectItem[] selectItems = allInOneService.getCustomFieldLookUpData(filterParameter, companyCustomFieldsSettings.getLookUpType());
                                    if (selectItems != null && selectItems.length > 0) {
                                        groupID = selectItems[0].getId();
                                    }
                                }
                            }
                        }
                        if (groupID == null) {
                            groupID = 0;
                        }
                    } else if (Constants.PURCHASE_ORDER.equals(edsBudgetManager.getType())) {
                        EdsPurchaseOrder edsPurchaseOrder = quoteManager.getPurchaseOrderByNumber(entityName);
                        if (edsPurchaseOrder != null) {
                            entityID = edsPurchaseOrder.getObjectID();
                        }
                        if (StringUtils.isNotBlank(groupBy)) {
                            if (Constants.PRODUCTS.equals(edsBudgetManager.getGroupBy())) {
                                EdsItem edsItem = itemManager.getItemByNumber(groupBy);
                                if (edsItem != null) {
                                    groupID = edsItem.getObjectID();
                                }
                            } else if (edsBudgetManager.getGroupBy() != null && (edsBudgetManager.getGroupBy().contains("string_value") || edsBudgetManager.getGroupBy().contains("double_value") || edsBudgetManager.getGroupBy().contains("date_value"))) {
                                EdsCompanyCustomFieldsSettings companyCustomFieldsSettings = this.companyCustomFieldsManager.getCompanyCustomField(ViewName.PurchaseOrder.name(), edsBudgetManager.getGroupBy());
                                if (companyCustomFieldsSettings != null && companyCustomFieldsSettings.getLookUpType() != null && (Constants.UI_TYPE_LOOKUP.equals(companyCustomFieldsSettings.getUiType()) || Constants.UI_TYPE_MULTI_LOOKUP.equals(companyCustomFieldsSettings.getUiType()))) {
                                    ListingFilterParameter filterParameter = new ListingFilterParameter();
                                    filterParameter.setSearchKey(groupBy);
                                    filterParameter.setStart(0);
                                    filterParameter.setLimit(1);
                                    if (CustomFieldLookUpTypeEnum.REFERENCE.equals(companyCustomFieldsSettings.getLookUpType())) {
                                        filterParameter.setParentID(companyCustomFieldsSettings.getReference() != null ? companyCustomFieldsSettings.getReference().getId() : null);
                                    }
                                    SelectItem[] selectItems = allInOneService.getCustomFieldLookUpData(filterParameter, companyCustomFieldsSettings.getLookUpType());
                                    if (selectItems != null && selectItems.length > 0) {
                                        groupID = selectItems[0].getId();
                                    }
                                }
                            }
                        }
                    }

                    if (entityID == null) {
                        errors++;
                        rejectedCells[1].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.entityNotFound, entityName));
                    }

                    if (period == null) {
                        errors++;
                        rejectedCells[2].setErrorComment(commonLocalizer.localize(PdfLocalizationName.invalidDateFormat));
                    }

                    if (groupID != null) {
                        if (selectedItems.get(groupID) != null) {
                            List<Integer> list = selectedItems.get(groupID);
                            list.add(entityID);
                            selectedItems.replace(groupID, list);
                        } else {
                            List<Integer> list = new ArrayList<>();
                            list.add(entityID);
                            selectedItems.put(groupID, list);
                        }
                    }


                    if (errors == 0 && period != null && budgetManagerItems != null && !budgetManagerItems.isEmpty()) {

                        for (AccountBudget accountBudget : budgetManagerItems) {
                            EdsBudgetManagerItem edsBudgetManagerItem = new EdsBudgetManagerItem();
                            edsBudgetManagerItem.setBudgetManager(edsBudgetManager);
                            Calendar calendar = new GregorianCalendar();
                            calendar.setTime(period);
                            ServerUtils.setBeginningOfTheDay(calendar);
                            edsBudgetManagerItem.setDate(ServerUtils.convertServerDateToUserDate(calendar.getTime(), userManager.getUser().getUserTimezone()));
                            edsBudgetManagerItem.setBudget(accountBudget.getBudget());
                            edsBudgetManagerItem.setColumnCode(accountBudget.getColumnCode());
                            edsBudgetManagerItem.setEntityId(entityID);
                            edsBudgetManagerItem.setGroupId(groupID);
                            budgetItemsForImport.add(edsBudgetManagerItem);
                        }

                        //Increment number of imported ROWs
                        importFile.setImportedColumns(importFile.getImportedColumns() + 1);

                    } else {
                        //If validation not passed
                        budgetItemsNotImported.add(entityName);

                        rejectedRows.add(rejectedCells);
                        //Increment number of rejected ROWs
                        importFile.setIgnoredColumns(importFile.getIgnoredColumns() + 1);
                    }
                }
            }

            if (!budgetItemsForImport.isEmpty()) {
                for (EdsBudgetManagerItem edsBudgetManagerItem : budgetItemsForImport) {

                    EdsBudgetManagerItem edsBudgetManagerItem1 = budgetItemManager.findBudgetedItem(edsBudgetManager.getObjectID(), edsBudgetManagerItem.getDate(), edsBudgetManagerItem.getColumnCode(), edsBudgetManagerItem.getEntityId(), edsBudgetManagerItem.getGroupId());
                    if (edsBudgetManagerItem1 != null) {
                        if (!importFile.isSkip()) {
                            edsBudgetManagerItem1.setBudget(edsBudgetManagerItem.getBudget());
                        }
                        budgetItemManager.update(edsBudgetManagerItem1);
                    } else {
                        budgetItemManager.create(edsBudgetManagerItem);
                    }

                    budgetItemsImported.add(edsBudgetManagerItem.getName());
                }

                if (edsBudgetManagerSettings != null && selectedItems != null && !selectedItems.isEmpty()) {
                    Gson gsonSettings = new Gson();
                    edsBudgetManagerSettings.setSettingsJSONData(gsonSettings.toJson(selectedItems));
                    budgetManagerSettings.createOrUpdate(edsBudgetManagerSettings);
                }

            }
        }

        return rejectedRows;
    }

    @Transactional
    public Integer initRejectedRecordsForSending(ByteArrayOutputStream baos, String filename) {
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        try {
            baos.flush();
            baos.close();
        } catch (Exception ex) {
            System.out.print("......................................");
        }
        System.out.print("*****************Upload to Amazon S3 server****************");
        EdsUpload upload = new EdsUpload();
        upload.setContentType("application/xls");
        upload.setOriginalName(filename);

        EdsReference uploadType = referenceManager.findReference(_UPLOAD_TYPE, EdsContextParams.getUploadType());
        upload.setType(uploadType);
        upload.setInputStream(bais);
        try {
            uploadManager.create(upload);
            System.out.print("****************File Uploaded******************");
        } catch (Exception ex) {
            System.err.println("****************Failed to Upload File******************");
        }
        try {
            bais.close();
        } catch (IOException ex) {
            System.err.println("Unable to close stream");
        }
        return upload.getObjectID();
    }

    @Transactional
    public void initRejectedRecordsForSending(EdsImportFile edsImportFile, ByteArrayOutputStream baos, String
            filename) {
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        try {
            baos.flush();
            baos.close();
        } catch (Exception ex) {
            System.out.print("......................................");
        }
        System.out.print("*****************Upload to Amazon S3 server****************");
        EdsUpload upload = new EdsUpload();
        upload.setContentType("application/xls");
        upload.setOriginalName(filename);

        upload.setType(referenceManager.findReference(_UPLOAD_TYPE, EdsContextParams.getUploadType()));
        upload.setInputStream(bais);
        try {
            uploadManager.create(upload);
            edsImportFile.setRejectedRecords(upload);
            System.out.print("****************File Uploaded******************");
        } catch (Exception ex) {
            System.err.println("****************Failed to Upload File******************");
        }
        try {
            bais.close();
        } catch (IOException ex) {
            System.err.println("Unable to close stream");
        }
    }

    @Override
    @Transactional(propagation = Propagation.SUPPORTS, readOnly = true)
    public ProductImportFillingData getProductImportFillingData() {
        EdsCompany company = companyManager.getUser().getCompany();
        ProductImportFillingData data = new ProductImportFillingData();
        data.setCategories(getCategoriesAsSelectItem());
        data.setUnitMeasurements(getUnitMeasurementsAsSelectItem());
        data.setVendors(getVendorsAsSelectItem());
        data.setBrands(getBrandsAsSelectItem());
        data.setWarehouses(getWarehousesAsSelectItem());
        data.setPriceLevels(getPriceLevelsAsSelectItem());
        data.setProducts(productServiceLocal.getProductsAsSelectItem(null));
        TaxList taxList = createCompanyTaxList(companyVatList(null, company.getObjectID()));
        data.setTaxes(taxList.getTaxItems());
        data.setLocations(getLocationsAsSelectItem());

        EdsAccount sales = accountingManager.getAccountTypeWithMinCode(SALES);
        EdsAccount costOfSales = accountingManager.getAccountTypeWithMinCode(EdsAccountType.COST_OF_SALES);
        EdsAccount stock = accountingManager.getAccountTypeWithMinCode(EdsAccountType.CURRENT_ASSET);
        if (sales != null) {
            data.setDefaultAccount(new SelectItem(sales.getObjectID(), sales.getName()));
        }
        if (costOfSales != null) {
            data.setDefaultCogsAccount(new SelectItem(costOfSales.getObjectID(), costOfSales.getName()));
        }
        if (stock != null) {
            data.setDefaultAssetAccount(new SelectItem(stock.getObjectID(), stock.getName()));
        }

        EdsWarehouse defaultWarehouse = warehouseManager.getDefaultWarehouse();
        data.setDefaultWarehouseId(defaultWarehouse != null ? defaultWarehouse.getObjectID() : null);

        return data;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public ArrayList<RejectedImportRecord[]> importProducts(ImportFile importFile, List<String[]> dataBank) {
        ArrayList<RejectedImportRecord[]> rejectedRecords = new ArrayList<>();

        importFile.setCsvColumns(Optional.ofNullable(importFile.getCsvColumns()).orElse(0) +
                (importFile.isHasHeader() ? dataBank.size() - 1 : dataBank.size()));
        final EdsEmployee employee = employeeManager.get(importFile.getUserID());

        if (employee == null) {
            return rejectedRecords;
        }
        final Integer FIELD_NUMBER = importFile.getColumnID(ProductFields.FIELD_NUMBER);
        final Integer FIELD_NAME = importFile.getColumnID(ProductFields.FIELD_NAME);

        final Integer sysDefaultProductType = importFile.getColumnID(ProductFields.SYSTEM_PRODUCT_TYPE_ID);
        final EdsProductCategory sysDefaultCategory = productCategoryManager.get(importFile.getColumnID(ProductFields.SYSTEM_CATEGORY_ID));
        final EdsUnitMeasurement sysDefaultUM = unitMeasurementManager.get(importFile.getColumnID(ProductFields.SYSTEM_UNIT_MEASUREMENT_ID));
        final EdsCrmAccount sysDefaultSupplier = crmAccountManager.get(importFile.getColumnID(ProductFields.SYSTEM_VENDOR_ID));
        final EdsAccount sysDefaultAccount = accountingManager.get(importFile.getColumnID(ProductFields.SYSTEM_ACCOUNT_ID));
        final EdsAccount sysDefaultCogsAccount = accountingManager.get(importFile.getColumnID(ProductFields.SYSTEM_COGS_ACCOUNT_ID));
        final EdsVat sysDefaultTax = vatManager.get(importFile.getColumnID(ProductFields.SYSTEM_TAX_RATE_ID));
        final EdsAccount sysAssetAccount = accountingManager.get(importFile.getColumnID(ProductFields.SYSTEM_ASSET_ACCOUNT_ID));

        final Map<String, EdsProductCategory> categories = Maps.newHashMap();//this.getCategoriesMap();
        final Map<String, EdsBrand> brands = Maps.newHashMap();//this.getBrandsMap();
        final Map<String, EdsUnitMeasurement> measurements = Maps.newHashMap();//this.getMeasurementsMap();
        final Map<String, EdsCrmAccount> vendors = Maps.newHashMap();//this.getVendorsMap();
        final Map<String, EdsAccount> accounts = Maps.newHashMap();//this.getAccountsMap();
        final Map<String, EdsVat> taxes = Maps.newHashMap();//this.getTaxesMap();
        final Map<Integer, EdsPriceLevel> priceLevels = this.getPriceLevelsMap();
        final Map<Integer, EdsPriceLevel> priceLevelsColumnIdMap = Maps.newLinkedHashMap();//pricelevel,cvs column index
        Map<EdsPriceLevel, Double> priceLevelMap;
        final Map<String, String> existingProducts = itemManager.getProductsNumberAndNameAsMap();
        final Map<Integer, EdsWarehouse> warehouses = this.getWarehousesMap();
        final Map<Integer, EdsWarehouse> warehousesColumnIdMap = Maps.newLinkedHashMap();//warehouse,cvs column index
        Map<EdsWarehouse, BigDecimal> warehouseQuantityMap;

        final EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        final boolean isMultipleWarehouseEnabled = financialSettings.getEnableMultiWarehouse();
        final boolean enableMultiPriceProductImport = financialSettings != null
                ? financialSettings.isEnableMultipleSalesPrice()
                : false;

        Integer intNumber = Optional.ofNullable(accountingManager.getProductLastIntNumber()).orElse(1);
        boolean hasHeader = importFile.isHasHeader();
        Map<EdsItem, Boolean> products = Maps.newHashMap();
        Set<EdsLocation> locations = Sets.newHashSet();

        for (Integer warehouseId : warehouses.keySet()) {
            final Integer warehouseColumnID = importFile.getColumnID((WAREHOUSE_ID_PART + warehouseId));

            if (warehouseColumnID != null && warehouseColumnID > 0) {
                warehousesColumnIdMap.put(warehouseColumnID, warehouses.get(warehouseId));
            }
        }
        EdsWarehouse defaultWarehouse;
        for (Integer priceLevelId : priceLevels.keySet()) {
            final Integer columnID = importFile.getColumnID((PRICELEVEL_ID_PART + priceLevelId));

            if (columnID != null && columnID > 0) {
                priceLevelsColumnIdMap.put(columnID, priceLevels.get(priceLevelId));
            }
        }

        if (isMultipleWarehouseEnabled && importFile.getColumnID(ProductFields.SYSTEM_WAREHOUSE_ID) != null) {
            defaultWarehouse = warehouseManager.get(importFile.getColumnID(ProductFields.SYSTEM_WAREHOUSE_ID));
        } else {
            defaultWarehouse = warehouseManager.getDefaultWarehouse();
        }
        for (String[] row : dataBank) {
            RejectedImportRecord[] rejectedRow = new RejectedImportRecord[row.length];
            warehouseQuantityMap = Maps.newLinkedHashMap();
            priceLevelMap = Maps.newLinkedHashMap();
            List<CompanyCustomFieldItem> customFields = Lists.newArrayList();

            if (!hasHeader) {
                boolean rowIsEmpty = true;//To check if row is not blank
                for (String cellvalue : row) {

                    if (rowIsEmpty && StringUtils.isNotBlank(cellvalue)) {
                        rowIsEmpty = false;
                        break;
                    }
                }
                if (rowIsEmpty) {
                    continue;
                }

                try {
                    EdsItem product = null, existingProduct = null;
                    boolean duplicateDetected = false;
                    Integer columnId = 0;
                    int errors = 0;

                    if (row.length > FIELD_NUMBER && row[FIELD_NUMBER] != null) {
                        if (existingProducts.containsKey(row[FIELD_NUMBER].trim())) {
                            duplicateDetected = true;

                            if (importFile.isSkip()) {
                                importFile.setSkippedColumns(importFile.getSkippedColumns() + 1);
                                continue;
                            }
                            if (importFile.isMerge()) {
                                product = itemManager.getItemByNumber(row[FIELD_NUMBER].trim());
                            }
                        }
                    }
                    if (importFile.isClone() || product == null) {
                        duplicateDetected = false;
                        product = new EdsItem();
                    }

                    if (!importFile.isClone()) {
                        if (existingProducts.containsKey(row[FIELD_NUMBER].trim())) {
                            existingProduct = itemManager.getItemByNumber(row[FIELD_NUMBER].trim());
                        } else if (existingProducts.containsValue(row[FIELD_NAME].trim())) {
                            existingProduct = itemManager.getItemByName(row[FIELD_NAME].trim());
                        }
                    }

                    EdsWarehouse warehouse = null;
                    EdsAccount account = null, cogsAccount = null, assetAccount = null;

                    BigDecimal quantity = null, totalQuantity = BigDecimal.ZERO;
                    BigDecimal globalReorderPoint = null;
                    for (String columnValue : row) {
                        rejectedRow[columnId] = new RejectedImportRecord(columnValue);
                        columnValue = columnValue.trim();

                        if (columnId.equals(FIELD_NUMBER)) {//Auto generate number if not set or exists
                            if (columnValue != null && columnValue.length() >= 4) {
                                try {
                                    if (StringUtils.isNotBlank(columnValue) && !accountingManager.isProductNumberExists(columnValue, product.getObjectID())) {
                                        product.setProductNumber(columnValue);
                                        product.setIntNumber(Integer.parseInt(columnValue.substring(columnValue.length() - 4)));
                                    } else {
                                        NumberData numberData = productServiceLocal.generateProductNumber(intNumber);
                                        product.setProductNumber(numberData.getNumberString());
                                        product.setIntNumber(numberData.getIntNumber());
                                    }
                                } catch (NumberFormatException e) {
                                    System.out.println("Can't parse product last 4 number: " + columnValue);
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localize(PdfLocalizationName.number) + commonLocalizer.localize(PdfLocalizationName.issue));
                                }
                            } else if (product.getObjectID() == null) {
                                final NumberData numberData = productServiceLocal.generateProductNumber(intNumber);
                                product.setIntNumber(numberData.getIntNumber());
                                product.setProductNumber(numberData.getNumberString());
                            }
                            intNumber = product.getIntNumber();
                        }
                        if (!StringUtil.isEmpty(columnValue)) {

                            if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_ITEM_ID))) {
                                if (columnValue != null && !columnValue.isEmpty()) {
                                    product = itemManager.get(Integer.parseInt(columnValue));
                                    if (product == null) {
                                        product = new EdsItem();
                                        NumberData numberData = productServiceLocal.generateProductNumber(intNumber);
                                        product.setProductNumber(numberData.getNumberString());
                                        product.setIntNumber(numberData.getIntNumber());
                                        intNumber = product.getIntNumber();
                                    }
                                }
                            } else if (columnId.equals(FIELD_NAME)) {
                                product.setName(StringUtil.cut(columnValue, 999));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_DESCRIPTION))) {
                                product.setDescription(columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_LOCATION))) {
                                LinkedHashMap<String, EdsLocation> locationMap = new LinkedHashMap<>();
                                if (columnValue != null && !columnValue.isEmpty()) {
                                    EdsLocation location = locationMap.get(columnValue.toLowerCase());
                                    if (location == null) {
                                        location = locationManager.getLocationByCode(columnValue, null);
                                        if (location != null) {
                                            locations.add(location);
                                        }
                                    } else {
                                        locations.add(location);
                                    }
                                    if (!locations.isEmpty()) {
                                        product.setLocations(locations);
                                    }
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_CATEGORY))) {
                                EdsProductCategory category = categories.get(columnValue.toLowerCase());

                                if (category == null) {
                                    category = productCategoryManager.getCategoryByName(columnValue);

                                    if (category != null) {
                                        categories.put(category.getName().toLowerCase(), category);
                                    } else if (sysDefaultCategory != null) {
                                        category = sysDefaultCategory;
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                                product.setCategory(category);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_BRAND))) {
                                EdsBrand brand = brands.get(columnValue.toLowerCase());

                                if (brand == null) {
                                    brand = brandManager.getBrandByName(columnValue);

                                    if (brand != null) {
                                        brands.put(brand.getName().toLowerCase(), brand);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                                product.setBrand(brand);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_PRODUCT_TYPE))) {
                                Integer pType = getProductType(columnValue);

                                if (pType != null) {
                                    product.setType(pType);
                                } else {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SKU_NUMBER))) {
                                product.setInternalSKUNumber(StringUtil.cut(columnValue, 254));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_MANUFACTURER))) {
                                product.setManufacturer(StringUtil.cut(columnValue, 254));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_PART_NUMBER))) {
                                product.setPartNumber(StringUtil.cut(columnValue, 254));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_UPC_NUMBER))) {
                                product.setUpcNumber(StringUtil.cut(columnValue, 254));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_BARCODE))) {
                                product.setBarCode(StringUtil.cut(columnValue, 254));
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_UNIT_MEASUREMENT))) {
                                EdsUnitMeasurement measurement = measurements.get(columnValue.toLowerCase());

                                if (measurement == null) {
                                    measurement = unitMeasurementManager.getByName(columnValue);

                                    if (measurement != null) {
                                        measurements.put(columnValue.toLowerCase(), measurement);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                                product.setUnitMeasurement(measurement);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_VENDOR))) {
                                String[] vndrs = columnValue.split(Constants.MULTIVALUE_SEPARATOR);

                                for (String vndr : vndrs) {
                                    vndr = vndr.trim().toLowerCase();
                                    EdsCrmAccount vendor = vendors.get(vndr);

                                    if (vendor == null) {
                                        vendor = crmAccountManager.getCrmAccountByName(vndr);

                                        if (vendor != null) {
                                            vendors.put(vndr, vendor);
                                        } else if (sysDefaultSupplier != null) {
                                            vendor = sysDefaultSupplier;
                                        } else {
                                            errors++;
                                            rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                            break;
                                        }
                                    }

                                    if (existingProduct != null && vendor != null) {
                                        //                                            itemManager.update(existingProduct);
                                        existingProduct.getSuppliers().add(vendor);
                                    } else if (vendor != null) {
//                                        itemManager.createOrUpdate(product);
                                        product.getSuppliers().add(vendor);
                                    }
                                }

                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE))) {
                                product.setUnitPrice(this.parseFinancialValue(columnValue));

                                if (product.getUnitPrice() == null) {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, columnValue));
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_AED))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "AED", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_USD))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "USD", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_GBP))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "GBP", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_EUR))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "EUR", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_RUB))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "RUB", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_SAR))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "SAR", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_PKR))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "PKR", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COST_PRICE_KWD))) {
                                this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.PAYABLE, "KWD", columnValue);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE))) {
                                BigDecimal sellingPrice = parseFinancialValue(columnValue);

                                if (sellingPrice != null && sellingPrice.compareTo(BigDecimal.ZERO) >= 0) {
                                    product.setSellingPrice(sellingPrice);
                                } else {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, columnValue));
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_AED))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_AED, rejectedRow, product, columnValue, "AED");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_USD))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_USD, rejectedRow, product, columnValue, "USD");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_GBP))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_GBP, rejectedRow, product, columnValue, "GBP");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_EUR))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_EUR, rejectedRow, product, columnValue, "EUR");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_RUB))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_RUB, rejectedRow, product, columnValue, "RUB");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_SAR))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_SAR, rejectedRow, product, columnValue, "SAR");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_PKR))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_PKR, rejectedRow, product, columnValue, "PKR");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE_KWD))) {
                                errors += setSellingPrice(ProductFields.FIELD_SELLING_PRICE_KWD, rejectedRow, product, columnValue, "KWD");
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_TAX_RATE))) {
                                EdsVat vat = taxes.get(columnValue.toLowerCase().trim());

                                if (vat == null) {
                                    vat = vatManager.getVatByName(columnValue.toLowerCase());

                                    if (vat != null) {
                                        taxes.put(columnValue.toLowerCase(), vat);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                                product.setVat(vat);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_ACCOUNT))) {
                                account = accounts.get(columnValue.toLowerCase());

                                if (account == null) {
                                    account = accountingManager.getAccountByName(columnValue.toLowerCase());

                                    if (account != null) {
                                        accounts.put(columnValue.toLowerCase(), account);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                                product.setAccount(account);
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_COGS_ACCOUNT))) {
                                cogsAccount = accounts.get(columnValue.toLowerCase());

                                if (cogsAccount == null) {
                                    cogsAccount = accountingManager.getAccountByName(columnValue.toLowerCase());

                                    if (cogsAccount != null) {
                                        accounts.put(columnValue.toLowerCase(), cogsAccount);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_QUANTITY))) {
                                quantity = this.parseBigDecimal(columnValue);

                                if (quantity == null) {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_ASSET_ACCOUNT))) {
                                assetAccount = accounts.get(columnValue.toLowerCase());

                                if (assetAccount == null) {
                                    assetAccount = accountingManager.getAccountByName(columnValue.toLowerCase());

                                    if (assetAccount != null) {
                                        accounts.put(columnValue.toLowerCase(), assetAccount);
                                    } else {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueIsNotAvailable, columnValue));
                                    }
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_GLOBAL_REORDER_POINT))) {
                                globalReorderPoint = this.parseBigDecimal(columnValue);

                                if (globalReorderPoint == null) {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, columnValue));
                                }
                            } else if (columnId.equals(importFile.getColumnID(ProductFields.FIELD_OPENING_BALANCE_DATE))) {
                                try {
                                    if (existingProduct == null || existingProduct != null && !INVENTORY_ITEM.equals(existingProduct.getType())) {
                                        SimpleDateFormat simpleDateFormat = new SimpleDateFormat(Constants.DATE_PATTERN);
                                        simpleDateFormat.setLenient(false);
                                        product.setAsOf(simpleDateFormat.parse(columnValue));
                                    }
                                } catch (ParseException e) {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localize(PdfLocalizationName.invalidDateFormat));
                                }
                            } else if (warehousesColumnIdMap.get(columnId) != null) {
                                if (isMultipleWarehouseEnabled) {
                                    try {
                                        warehouseQuantityMap.put(warehousesColumnIdMap.get(columnId), this.parseBigDecimal(columnValue));
                                        totalQuantity = totalQuantity.add(this.parseBigDecimal(columnValue));
                                    } catch (Exception e) {
                                        errors++;
                                        rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, accountingLocalizer.localize(PdfLocalizationName.warehouse)));
                                    }
                                }
                            } else if (priceLevelsColumnIdMap.get(columnId) != null) {
                                try {
                                    Double t = null;
                                    BigDecimal t1 = this.parseBigDecimal(columnValue.toLowerCase());
                                    t = t1 != null ? t1.doubleValue() : null;
                                    priceLevelMap.put(priceLevelsColumnIdMap.get(columnId), t);
                                } catch (Exception e) {
                                    errors++;
                                    rejectedRow[columnId].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.fieldShouldBeNumberFormat, commonLocalizer.localize(PdfLocalizationName.priceLevel)));
                                }
                            }

                            if (importFile.getExtraColumns() != null) {
                                for (Map.Entry<Integer, String> extraColumnEntry : importFile.getExtraColumns().entrySet()) {

                                    if (!columnId.equals(importFile.getExtraColumnID(extraColumnEntry.getValue()))
                                            || extraColumnEntry.getKey() < ProductFields.FIELD_CUSTOM_FIELD_START_NUMBER) {
                                        continue;
                                    }

                                    CompanyCustomFieldItem customField = commonServiceLocal.getValidCustomFieldItem(extraColumnEntry, columnId, columnValue, rejectedRow, columnValue);

                                    if (customField == null) {
                                        errors++;
                                        break;
                                    }

                                    customFields.add(customField);
                                }
                            }
                        }
                        columnId++;
                    }

                    //If there were rejected items then read next row from csv
                    if (errors > 0) {
                        rejectedRecords.add(rejectedRow);
                        importFile.setIgnoredColumns(importFile.getIgnoredColumns() + 1);
                        continue;
                    }

                    if (product.getAccount() == null && sysDefaultAccount != null) {
                        product.setAccount(sysDefaultAccount);
                    }

                    if (product.getCategory() == null && sysDefaultCategory != null) {
                        product.setCategory(sysDefaultCategory);
                    }
                    if (product.getProductType() == null && sysDefaultProductType != null) {
                        product.setType(sysDefaultProductType);
                    }
                    if (product.getUnitMeasurement() == null && sysDefaultUM != null) {
                        product.setUnitMeasurement(sysDefaultUM);
                    }
                    if (sysDefaultSupplier != null && product.getSuppliers().isEmpty()) {
                        product.getSuppliers().add(sysDefaultSupplier);
                    }
                    if (product.getVat() == null && sysDefaultTax != null) {
                        product.setVat(sysDefaultTax);
                    }
                    if (product.getSellingPrice() == null) {
                        product.setSellingPrice(BigDecimal.ZERO);
                    }
                    if (product.getUnitPrice() == null) {
                        product.setUnitPrice(BigDecimal.ZERO);
                    }

                    boolean hasItemOutTransaction = false;
                    if (INVENTORY_ITEM.equals(product.getType())
                            || NON_INVENTORY_ITEM.equals(product.getType())
                            || SERVICE.equals(product.getType())
                            || OTHER_CHARGE.equals(product.getType())) {

                        if (cogsAccount != null) {
                            product.setCogsAccount(cogsAccount);
                        } else if (cogsAccount == null && sysDefaultCogsAccount != null) {
                            product.setCogsAccount(sysDefaultCogsAccount);
                        }

                        /*-------------- Asset Account Details Start ------------*/
                        if (assetAccount != null) {
                            product.setAssetAccount(assetAccount);
                        } else if (assetAccount == null && sysAssetAccount != null) {
                            product.setAssetAccount(sysAssetAccount);
                        }
                        product.setGlobalReorderPoint(globalReorderPoint);

                        if (isMultipleWarehouseEnabled) {
                            product.setTotalValue(totalQuantity.multiply(product.getUnitPrice()));
                        } else {
                            product.setTotalValue(Optional.ofNullable(quantity).orElse(BigDecimal.ZERO).multiply(product.getUnitPrice()));
                        }
                        if (product.getAsOf() == null) {
                            product.setAsOf(new Date());
                        }
                        product.setEnableIT(financialSettings != null ? financialSettings.enableIT() : null);
                        /*-------------- Asset Account Details End -----------------*/

                        if (product.getProductNumber() == null) {
                            product.setProductNumber("");
                        }
                        if (product.getName() == null) {
                            product.setName("");
                        }
                        final boolean containsProduct = !StringUtil.isEmpty(product.getProductNumber())
                                && !StringUtil.isEmpty(product.getName())
                                && existingProducts.containsKey(product.getProductNumber().trim())
                                && !enableMultiPriceProductImport;

                        if (INVENTORY_ITEM.equals(product.getType())) {

                            if (product.getCogsAccount() == null) {
                                rejectedRow[importFile.getColumnID(ProductFields.FIELD_COGS_ACCOUNT)].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueCannotBeEmpty, "COGS Account"));
                                errors++;
                            }
                            if (product.getAssetAccount() == null) {
                                rejectedRow[importFile.getColumnID(ProductFields.FIELD_ASSET_ACCOUNT)].setErrorComment(commonLocalizer.localizeWithParamAccounting(PdfLocalizationName.valueCannotBeEmpty, "Asset Account"));
                                errors++;
                            }

                            if (errors > 0) {
                                rejectedRecords.add(rejectedRow);
                                importFile.setIgnoredColumns(importFile.getIgnoredColumns() + 1);
                                continue;
                            }

                            products.put(product, duplicateDetected);

                            if (!containsProduct) {
                                existingProducts.put(product.getProductNumber().trim(), product.getName().trim());
                            }
                            if (importFile.isMerge()) {
                                for (EdsItemStock itemStock : product.getItemStockList()) {
                                    if (Constants.TC_OUT.equals(itemStock.getTranCode())) {
                                        hasItemOutTransaction = true;
                                        break;
                                    }
                                }
                                product.setHasItemOutTransaction(hasItemOutTransaction);
                            }
                            if (!duplicateDetected || (importFile.isMerge() && !hasItemOutTransaction)) {
                                this.applyProductBatchPriceLevels(product, priceLevelMap);

                                if (isMultipleWarehouseEnabled) {
                                    this.applyProductBatchWarehouseLocations(product, warehouseQuantityMap);
                                } else {
                                    if (warehouse == null) {
                                        warehouse = defaultWarehouse;
                                    }
                                    this.applyProductWarehouseLocations(product, warehouse, quantity);
                                }
                            }
                        } else {

                            if (product.getCogsAccount() != null && (NON_INVENTORY_ITEM.equals(product.getType()) || SERVICE.equals(product.getType()))) {
                                product.setPurchasedFromSupplier(true);
                            }
                            products.put(product, duplicateDetected);

                            if (!containsProduct) {
                                existingProducts.put(product.getProductNumber().trim(), product.getName().trim());
                            }
                        }
                        if (/*!containsProduct && */!customFields.isEmpty()) {
                            product.setCustomFields(this.createProductCustomFields(customFields));
                        }

                        if (product.getObjectID() != null) {
                            importFile.setOverwrittenColumns(importFile.getOverwrittenColumns() + 1);
                        } else {
                            importFile.setImportedColumns(importFile.getImportedColumns() + 1);
                        }
                    } else {
                        rejectedRow[0].setComment("System imports only these types: Inventory Item, Non-Inventory Item, Service and Other Charge!");
                        rejectedRecords.add(rejectedRow);
                        importFile.setImportedColumns(importFile.getImportedColumns() + 1);
                        continue;
                    }

                    products = this.batchImportProducts(products,
                            warehouse,
                            employee,
                            false,
                            false,
                            isMultipleWarehouseEnabled, null);


                } catch (Exception e) {
                    e.printStackTrace();
                    rejectedRow[0].setComment("System imports only these types: Inventory Item, Non-Inventory Item, Service and Other Charge!");
                    rejectedRecords.add(rejectedRow);
                    importFile.setImportedColumns(importFile.getImportedColumns() + 1);
                }
            } else {
                for (int i = 0; i < row.length; i++) {
                    rejectedRow[i] = new RejectedImportRecord(row[i]);
                }
                rejectedRecords.add(rejectedRow);
                hasHeader = false;
            }
            //todo we need to add Price Level and custom price.
        }
        batchImportProducts(products, defaultWarehouse, employee, true, false, isMultipleWarehouseEnabled, importFile);

        importFile.setImportedColumns(Optional.ofNullable(importFile.getImportedColumns()).orElse(0) + products.size());

        return rejectedRecords;
    }

    private int setSellingPrice(int fieldID, RejectedImportRecord[] rejectedRow, EdsItem product, String
            columnValue, String currencyCode) {
        BigDecimal sellingPrice = parseFinancialValue(columnValue);
        if (sellingPrice != null && sellingPrice.compareTo(BigDecimal.ZERO) >= 0) {
            this.setMultiPriceData(product.getMultiPrices(), EdsItemMultiPrice.RECEIVABLE, currencyCode, columnValue);
            return 0;
        } else {
            rejectedRow[fieldID].setErrorComment("Mandatory field missing or not valid: Selling Price " + currencyCode);
        }
        return 1;
    }

    private void setMultiPriceData(List<EdsItemMultiPrice> multiPrices, String type, String currencyName, String
            columnValue) {
        boolean found = false;
        if (multiPrices != null) {
            for (EdsItemMultiPrice multiPrice : multiPrices) {
                if (multiPrice.getType().equals(type) && multiPrice.getCurrency().getName().equals(currencyName)) {
                    found = true;
                    multiPrice.setSellingPrice(parseBigDecimal(columnValue));
                    break;
                }
            }
            if (!found && columnValue != null && !columnValue.isEmpty()) {
                EdsItemMultiPrice multiPrice = new EdsItemMultiPrice();
                multiPrice.setCurrency(currencyManager.getCurrency(currencyName));
                multiPrice.setSellingPrice(parseBigDecimal(columnValue));
                multiPrice.setType(type);
                multiPrices.add(multiPrice);
            }
        }
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void importProductsFromParentCompany(ImportFile importFile) {
        EdsEmployee employee = employeeManager.get(importFile.getUserID());
        Integer FIELD_NUMBER = importFile.getColumnID(ProductFields.FIELD_NUMBER);
        Integer FIELD_NAME = importFile.getColumnID(ProductFields.FIELD_NAME);
        Integer FIELD_DESCRIPTION = importFile.getColumnID(ProductFields.FIELD_DESCRIPTION);
        Integer FIELD_CATEGORY = importFile.getColumnID(ProductFields.FIELD_CATEGORY);
        Integer FIELD_PRODUCT_TYPE = importFile.getColumnID(ProductFields.FIELD_PRODUCT_TYPE);
        Integer FIELD_SKU_NUMBER = importFile.getColumnID(ProductFields.FIELD_SKU_NUMBER);
        Integer FIELD_MANUFACTURER = importFile.getColumnID(ProductFields.FIELD_MANUFACTURER);
        Integer FIELD_PART_NUMBER = importFile.getColumnID(ProductFields.FIELD_PART_NUMBER);
        Integer FIELD_UPC_NUMBER = importFile.getColumnID(ProductFields.FIELD_UPC_NUMBER);
        Integer FIELD_UNIT_MEASUREMENT = importFile.getColumnID(ProductFields.FIELD_UNIT_MEASUREMENT);
        Integer FIELD_VENDOR = importFile.getColumnID(ProductFields.FIELD_VENDOR);

        Integer FIELD_COST_PRICE = importFile.getColumnID(ProductFields.FIELD_COST_PRICE);
        Integer FIELD_SELLING_PRICE = importFile.getColumnID(ProductFields.FIELD_SELLING_PRICE);
        Integer FIELD_TAX_RATE = importFile.getColumnID(ProductFields.FIELD_TAX_RATE);
        Integer FIELD_ACCOUNT = importFile.getColumnID(ProductFields.FIELD_ACCOUNT);

        Integer sysDefaultCategoryID = importFile.getColumnID(ProductFields.SYSTEM_CATEGORY_ID);
        Integer sysDefaultUnitMeasurementID = importFile.getColumnID(ProductFields.SYSTEM_UNIT_MEASUREMENT_ID);
        Integer sysDefaultVendorID = importFile.getColumnID(ProductFields.SYSTEM_VENDOR_ID);
        Integer sysDefaultAccountID = importFile.getColumnID(ProductFields.SYSTEM_ACCOUNT_ID);
        Integer sysDefaultCogsAccountID = importFile.getColumnID(ProductFields.SYSTEM_COGS_ACCOUNT_ID);
        Integer sysDefaultTaxRateID = importFile.getColumnID(ProductFields.SYSTEM_TAX_RATE_ID);
        Integer sysDefaultWarehouseID = importFile.getColumnID(ProductFields.SYSTEM_WAREHOUSE_ID);
        Integer sysAssetAccountID = importFile.getColumnID(ProductFields.SYSTEM_ASSET_ACCOUNT_ID);

        EdsProductCategory sysDefaultCategory = (sysDefaultCategoryID != null
                ? productCategoryManager.get(sysDefaultCategoryID)
                : null);
        Integer sysDefaultProductType = importFile.getColumnID(ProductFields.SYSTEM_PRODUCT_TYPE_ID);
        EdsUnitMeasurement sysDefaultUM = (sysDefaultUnitMeasurementID != null
                ? unitMeasurementManager.get(sysDefaultUnitMeasurementID)
                : null);
        EdsCrmAccount sysDefaultVendor = (sysDefaultVendorID != null
                ? crmAccountManager.get(sysDefaultVendorID)
                : null);
        EdsAccount sysDefaultAccount = (sysDefaultAccountID != null
                ? accountingManager.get(sysDefaultAccountID)
                : null);
        EdsAccount sysDefaultCogsAccount = (sysDefaultCogsAccountID != null
                ? accountingManager.get(sysDefaultCogsAccountID)
                : null);
        EdsVat sysDefaultTax = (sysDefaultTaxRateID != null ? vatManager.get(sysDefaultTaxRateID) : null);
        EdsAccount sysAssetAccount = (sysAssetAccountID != null ? accountingManager.get(sysAssetAccountID) : null);

        Map<String, EdsProductCategory> categories = getCategoriesMap();
        Map<String, EdsUnitMeasurement> measurements = getMeasurementsMap();
        Map<String, EdsCrmAccount> vendors = getVendorsMap();
        Map<String, EdsAccount> accounts = getAccountsMap();
        Map<String, EdsVat> taxes = getTaxesMap();
        HashMap<String, String> existingProducts = itemManager.getProductsSSUniqNumberAndNameAsMap();

        EdsWarehouse defaultWarehouse;
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        boolean isMultipleWarehouseEnabled = financialSettings.getEnableMultiWarehouse();
        if (isMultipleWarehouseEnabled && sysDefaultWarehouseID != null) {
            defaultWarehouse = warehouseManager.get(sysDefaultWarehouseID);
        } else {
            defaultWarehouse = warehouseManager.getDefaultWarehouse();
        }

        Map<EdsItem, Boolean> products = Maps.newHashMap();
        List<CompanyCustomFieldItem> customFields = new ArrayList<>();

        EdsCompany company = companyManager.get(Integer.parseInt(ServerSecurityContext.getInstance().getCompanyId()));

        if (company.getParentCompanyId() == null) {
            return;
        }

        SelectItem[] columns = productServiceLocal.getProductColumns();
        QueryResponse resp = getParentCompanyProductListFromSolr(company.getParentCompanyId());

        if (resp != null && resp.getResults() != null) {
            for (SolrDocument doc : resp.getResults()) {

                if (doc != null) {
                    EdsItem product = new EdsItem();
                    EdsAccount account = null;

                    ProductItem productItem = EdsItem.wrapSolrDocumentToRPC(doc);
                    product.setSubsidiaryProductUniqNum(productItem.getSubsidiaryProductUniqNum());


                    for (SelectItem column : columns) {
                        Integer columnID = column.getId();
                        String columnValue = "";
                        Object object = (column.getDescription() != null && !column.getDescription().isEmpty())
                                ? doc.getFieldValue(column.getDescription().toUpperCase())
                                : null;

                        if (object instanceof String) {
                            columnValue = (String) object;
                        }

                        if (columnID.equals(FIELD_NUMBER)) {
                            if (columnValue != null && columnValue.length() >= 4) {
                                try {
                                    product.setIntNumber(Integer.parseInt(columnValue.substring(columnValue.length() - 4)));
                                } catch (NumberFormatException e) {
                                    System.out.println("Can't parse product last 4 number: " + columnValue);
                                } finally {
                                    product.setProductNumber(columnValue.trim());
                                }
                            } else {
                                product.setProductNumber(columnValue != null ? columnValue.trim() : null);
                            }
                        }
                        if (columnID.equals(FIELD_NAME)) {
                            if (columnValue != null && columnValue.trim().length() > 255) {
                                product.setName(columnValue.trim().substring(0, 254));
                                product.setDescription(columnValue.trim());
                            } else {
                                product.setName(columnValue != null ? columnValue.trim() : null);
                            }
                        }
                        if (columnID.equals(FIELD_DESCRIPTION)) {
                            product.setDescription(columnValue);
                        }
                        if (columnID.equals(FIELD_CATEGORY)) {
                            product.setCategory(columnValue != null ? categories.get(columnValue.trim()) : null);
                        }
                        if (columnID.equals(FIELD_PRODUCT_TYPE)) {
                            product.setType(getProductType(columnValue.trim()));
                        }

                        if (columnID.equals(FIELD_SKU_NUMBER)) {
                            product.setInternalSKUNumber(columnValue);
                        }

                        if (columnID.equals(FIELD_MANUFACTURER)) {
                            product.setManufacturer(columnValue);
                        }

                        if (columnID.equals(FIELD_PART_NUMBER)) {
                            product.setPartNumber(columnValue);
                        }

                        if (columnID.equals(FIELD_UPC_NUMBER)) {
                            product.setUpcNumber(columnValue);
                        }
                        if (columnID.equals(FIELD_UNIT_MEASUREMENT)) {
                            product.setUnitMeasurement(columnValue != null
                                    ? measurements.get(columnValue.trim())
                                    : null);
                        }
                        if (columnID.equals(FIELD_VENDOR)) {
                            product.setVendor(columnValue != null ? vendors.get(columnValue.trim()) : null);
                        }

                        if (columnID.equals(FIELD_COST_PRICE)) {
                            product.setUnitPrice(object != null ? BigDecimal.valueOf((Double) object) : BigDecimal.ZERO);
                        }
                        if (columnID.equals(FIELD_SELLING_PRICE)) {
                            product.setSellingPrice(object != null ? BigDecimal.valueOf((Double) object) : BigDecimal.ZERO);
                        }
                        if (columnID.equals(FIELD_TAX_RATE)) {
                            product.setVat(taxes.get(columnValue.trim().toLowerCase()));
                        }
                        if (columnID.equals(FIELD_ACCOUNT)) {
                            account = accounts.get(columnValue.trim());
                        }

                        if (importFile.getExtraColumns() != null && !importFile.getExtraColumns().isEmpty()) {
                            for (Map.Entry<Integer, String> extraColumnEntry : importFile.getExtraColumns().entrySet()) {
                                if (!columnID.equals(importFile.getExtraColumnID(extraColumnEntry.getValue())) || extraColumnEntry.getKey() < ProductFields.FIELD_CUSTOM_FIELD_START_NUMBER) {
                                } else {
                                    CompanyCustomFieldItem customField = new CompanyCustomFieldItem();
                                    customField.setDataType(importFile.getExtraColumnValues(extraColumnEntry.getValue())[1]);
                                    customField.setColumnCode(importFile.getExtraColumnValues(extraColumnEntry.getValue())[2]);
                                    try {
                                        customField.setCustomFieldSettingID(Integer.parseInt(importFile.getExtraColumnValues(extraColumnEntry.getValue())[3]));
                                    } catch (NumberFormatException e) {
                                        System.out.print(e.getMessage());
                                    }
                                    if (importFile.getExtraColumnValues(extraColumnEntry.getValue()).length > 4) {
                                        customField.setPredefinedValues(importFile.getExtraColumnValues(extraColumnEntry.getValue())[4].split("-:-"));
                                    }

                                    CustomFieldsUtils.setValueByDataType(customField, String.valueOf(doc.getFieldValue(column.getDescription().toUpperCase())));
                                    customFields.add(customField);
                                }
                            }
                        }
                    }

                    if (product.getCategory() == null && sysDefaultCategory != null) {
                        product.setCategory(sysDefaultCategory);
                    }
                    if (product.getProductType() == null && sysDefaultProductType != null) {
                        product.setType(sysDefaultProductType);
                    }
                    if (product.getUnitMeasurement() == null && sysDefaultUM != null) {
                        product.setUnitMeasurement(sysDefaultUM);
                    }
                    if (product.getVendor() == null && sysDefaultVendor != null) {
                        product.setVendor(sysDefaultVendor);
                    }
                    if (product.getVat() == null && sysDefaultTax != null) {
                        product.setVat(sysDefaultTax);
                    }

                    if (product.getSellingPrice() == null) {
                        product.setSellingPrice(ZERO);
                    }
                    if (product.getUnitPrice() == null) {
                        product.setUnitPrice(ZERO);
                    }
                    product.setAccount(account != null ? account : sysDefaultAccount);

                    if (INVENTORY_ITEM.equals(product.getType()) || NON_INVENTORY_ITEM.equals(product.getType()) || SERVICE.equals(product.getType()) || OTHER_CHARGE.equals(product.getType())) {
                        product.setCogsAccount(sysDefaultCogsAccount);

                        /*-------------- Asset Account Details Start ------------*/
                        product.setAssetAccount(sysAssetAccount);
                        product.setGlobalReorderPoint(BigDecimal.ONE);
                        product.setTotalValue(BigDecimal.ZERO);
                        product.setAsOf(employee.getUserDate());

                        /*-------------- Asset Account Details End -----------------*/

                        if (product.getProductNumber() == null) {
                            product.setProductNumber("");
                        }
                        if (product.getName() == null) {
                            product.setName("");
                        }

                        boolean containsProduct = (!"".equals(product.getSubsidiaryProductUniqNum().trim()) && !"".equals(product.getName().trim()) && existingProducts.containsKey(product.getSubsidiaryProductUniqNum().trim()));

                        if (INVENTORY_ITEM.equals(product.getType())) {
                            applyProductWarehouseLocations(product, defaultWarehouse, BigDecimal.ZERO);

                            if (product.getAssetAccount() != null && product.getCogsAccount() != null && product.getAccount() != null) {
                                product.setType(INVENTORY_ITEM);
                                if (!containsProduct) {
                                    existingProducts.put(product.getSubsidiaryProductUniqNum().trim(), product.getName().trim());
                                    products.put(product, false);
                                }
                            }
                        } else {
                            if (product.getCogsAccount() != null && (NON_INVENTORY_ITEM.equals(product.getType()) || SERVICE.equals(product.getType()))) {
                                product.setPurchasedFromSupplier(true);
                            }
                            if (!containsProduct) {
                                existingProducts.put(product.getSubsidiaryProductUniqNum().trim(), product.getName().trim());
                                products.put(product, false);
                            }
                        }

                        if (!containsProduct) {
                            if (!customFields.isEmpty()) {
                                EdsItemCustomFields customField = createProductCustomFields(customFields);
                                product.setCustomFields(customField);
                            }
                        }
                    }
                }
            }
            batchImportProducts(products, defaultWarehouse, employee, true, true, isMultipleWarehouseEnabled, importFile);
        }
    }

    @Transactional
    public EdsItemCustomFields createProductCustomFields(List<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            boolean isEmpty = true;
            for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                if ((fieldItem.getFieldStringValue() != null && !"".equals(fieldItem.getFieldStringValue()))
                        || fieldItem.getFieldDateNonConvertedValue() != null || (fieldItem.getAttachments() != null && fieldItem.getAttachments().length > 0)
                        || (fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty())) {
                    isEmpty = false;
                    break;
                }
            }
            if (isEmpty) {
                return null;
            }
            EdsItemCustomFields productCustomFields = new EdsItemCustomFields();
            itemCFManager.create(productCustomFields);

            CustomFieldsUtils.setDomenObjectCustomFields(productCustomFields, customFieldItems);
            return productCustomFields;
        }
        return null;
    }

    private void applyProductWarehouseLocations(EdsItem product, EdsWarehouse warehouse, BigDecimal quantity) {
        List<EdsItemStock> itemStockList = new LinkedList<>();

        for (EdsItemStock itemStock : product.getItemStockList()) {
            if (INVENTORY_TRANSACTION.equals(itemStock.getTransaction().getKeyType())) {
                itemStockManager.delete(itemStock);
            }
        }

        if (warehouse != null && quantity != null && quantity.compareTo(BigDecimal.ZERO) > 0) {
            EdsItemStock itemStock = new EdsItemStock();
            itemStock.setQuantity(quantity);
            itemStock.setPrice(product.getUnitPrice());
            itemStock.setDate(product.getAsOf());
            itemStock.setTranDate(product.getAsOf());
            itemStock.setTranCode(TC_IN);
            itemStock.setTranValue(quantity.multiply(product.getUnitPrice()));
            itemStock.setItemId(product.getObjectID());
            itemStock.setWarehouse(warehouse);
            itemStockList.add(itemStock);
        }

        product.setItemStockList(itemStockList);
    }

    private void applyProductBatchWarehouseLocations(EdsItem
                                                             product, Map<EdsWarehouse, BigDecimal> warehouseQuantityMap) {
        final List<EdsItemStock> itemStockList = Lists.newLinkedList();
        int order = 0;

        for (EdsItemStock itemStock : product.getItemStockList()) {
            if (INVENTORY_TRANSACTION.equals(itemStock.getTransaction().getKeyType())) {
                itemStockManager.delete(itemStock);
            }
        }

        for (EdsWarehouse warehouse : warehouseQuantityMap.keySet()) {

            if (warehouseQuantityMap.get(warehouse).compareTo(BigDecimal.ZERO) <= 0) {
                continue;
            }
            final EdsItemStock itemStock = new EdsItemStock();

            itemStock.setQuantity(warehouseQuantityMap.get(warehouse));
            itemStock.setPrice(product.getUnitPrice());
            itemStock.setDate(product.getAsOf());
            itemStock.setTranDate(product.getAsOf());
            itemStock.setTranCode(TC_IN);
            itemStock.setTranValue(Optional.ofNullable(warehouseQuantityMap.get(warehouse)).orElse(BigDecimal.ZERO).multiply(product.getUnitPrice()));
            itemStock.setItemId(product.getObjectID());
            itemStock.setWarehouse(warehouse);
            itemStock.setOrder(order++);
            itemStockList.add(itemStock);
        }
        product.setItemStockList(itemStockList);
    }

    private void applyProductBatchPriceLevels(EdsItem product, Map<EdsPriceLevel, Double> map) {
        for (EdsPriceLevel edsPriceLevel : map.keySet()) {
            if (map.get(edsPriceLevel) != null && edsPriceLevel != null) {
                EdsPriceLevelPP pp = null;
                if (product.getObjectID() != null) {
                    pp = priceLevelPPManager.getByPriceLevelIdAndProductId(edsPriceLevel.getObjectID(), product.getObjectID());
                }
                if (pp == null) {
                    pp = new EdsPriceLevelPP();
                }
                pp.setProduct(product);
                pp.setPriceLevel(edsPriceLevel);
                pp.setCustomPrice(map.get(edsPriceLevel));
                product.transientPriceLevels.add(pp);
            }
        }
    }

