    @Override
    public void createOrUpdateAccountFromSaasu(AddAccountItem accountItem) {
        EdsUser user = userManager.getUser();
        EdsAccount account;
        boolean update = accountItem.getObjectId() != null;
        if (update) {
            account = accountingManager.get(accountItem.getObjectId());
        } else {
            account = new EdsAccount();
        }

        if (accountItem.getAccountTypeCode() != null && !accountItem.getAccountTypeCode().isEmpty()) {
            account.setAccountType(accountingManager.getAccountTypeByCode(accountItem.getAccountTypeCode()));
        }
        account.setName(accountItem.getName());
        if (accountItem.getObjectId() != null) {
            account.setAccountCode(accountItem.getCode());
            account.setCodeString(accountItem.getCode());
        } else {
            account.setAccountCode(getGeneratedAccountNumber(account.getAccountType().getObjectID()));
            account.setCodeString(account.getAccountCode());
        }
        account.setShowInExpense(accountItem.isShowInExpense());
        account.setEnablePayments(accountItem.isEnablePayments());
        account.setSaasuGUID(accountItem.getSaasuAccountID());
        account.setSasuuLastUpdatedTime(accountItem.getSasuuLastUpdatedDate());
        if (accountItem.isFromSaasu()) {
            account.setLastUpdatedDate(accountItem.getSasuuLastUpdatedDate());
        } else {
            account.setLastUpdatedDate(new Date());
        }
        if (update) {
            account.setUpdater(user);
            account.setLastUpdatedDate(new Date());
            accountingManager.update(account);
        } else {
            account.setCreator(user);
            account.setCreationTime(new Date());
            accountingManager.create(account);
        }

        try {
            chartOfAccountSolrComponent.index(account);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private BigDecimal applyAssemblySubItemToStock(BigDecimal qty, EdsInventoryTransaction transaction, Integer
            warehouseID, List<EdsTransactionItem> transactionItemList, EdsItem productItem, EdsAccount liabilityAccount) {
        BigDecimal COGS = BigDecimal.ZERO;

        if (productItem.getType().equals(INVENTORY_ITEM) || productItem.getType().equals(ASSEMBLY_ITEM)) {
            COGS = cogsServices.getService().getCOGSValue(productItem, qty, transaction, warehouseID, null);

            EdsTransactionItem transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(productItem.getAssetAccount());
            transactionItem.setCredit(COGS);
            transactionItem.setInventoryId(productItem.getObjectID());
            transactionItem.setCogsItem(true);

            transactionItemList.add(transactionItem);
        } else if (productItem.getType().equals(PRODUCT_KIT)) {
            List<EdsProductKitItems> pkItemList = productItem.getProductKitItems();

            if (pkItemList != null) {
                for (EdsProductKitItems pki : pkItemList) {
                    COGS = COGS.add(applyAssemblySubItemToStock(qty.multiply(pki.getQuantity()), transaction, warehouseID, transactionItemList, pki.getItem(), liabilityAccount));
                }
            }
        } else {
            COGS = COGS.add(Optional.ofNullable(productItem.getUnitPrice()).orElse(BigDecimal.ZERO).multiply(qty));
            EdsTransactionItem transactionItem = new EdsTransactionItem();
            transactionItem.setAccount(liabilityAccount);
            transactionItem.setCredit(COGS);
            transactionItem.setInventoryId(productItem.getObjectID());
            transactionItem.setCogsItem(true);
            transactionItemList.add(transactionItem);
        }

        try {
            productsServicesSolrComponent.index(productItem);
        } catch (Exception e) {
            e.printStackTrace();
        }

        return COGS;
    }

    @Override
    public boolean copyCustomFieldsToSubCategories(Integer objectID) {
        EdsProductCategory category = productCategoryManager.get(objectID);
        if (category != null) {
            List<CompanyCustomFieldItem> customFields = commonServiceLocal.getCompanyCustomFieldsByRelationship(ViewName.ProductCategory, category.getObjectID(), null);
            if (customFields != null && !customFields.isEmpty()) {
                copyCustomFieldsToSubCategories(category.getChildList(), customFields);
            }
        }

        return true;
    }

    private void copyCustomFieldsFromParent(EdsProductCategory category) {
        if (category.getParent() != null) {
            List<CompanyCustomFieldItem> parentCustomFields = commonServiceLocal.getCompanyCustomFieldsByRelationship(ViewName.ProductCategory, category.getParent().getObjectID(), null);

            List<EdsProductCategory> categories = new ArrayList<>();
            categories.add(category);

            if (parentCustomFields != null && !parentCustomFields.isEmpty()) {
                copyCustomFieldsToSubCategories(categories, parentCustomFields);
            }
        }
    }

    @Override
    public AccountTypeItem[] getAccountTypeItems() {
        List<EdsAccountType> list = accountTypeManager.getAccounTypeList();
        AccountTypeItem[] items = new AccountTypeItem[list.size()];

        int index = 0;
        for (EdsAccountType type : list) {
            items[index] = new AccountTypeItem();
            items[index].setObjectID(type.getObjectID());
            items[index].setName(accountingLocalizer.localize(type.getCode(), type.getName()));
            items[index].setCategory(accountingLocalizer.localize(type.getCategory()));
            items[index].setCode(type.getCode());

            EdsAccountNumberSettings numberSetting = accountTypeSettingManager.getNumberSetting(type.getObjectID());
            if (numberSetting != null) {
                items[index].setStart(numberSetting.getStart());
                items[index].setEnd(numberSetting.getEnd());
            }

            index++;
        }

        return items;
    }

    @Override
    public void saveAccountTypeNumbering(AccountTypeItem[] items) {
        if (items != null) {
            for (AccountTypeItem item : items) {
                EdsAccountNumberSettings numberSetting = accountTypeSettingManager.getNumberSetting(item.getObjectID());
                if (numberSetting != null) {
                    numberSetting.setStart(item.getStart());
                    numberSetting.setEnd(item.getEnd());
                    accountTypeSettingManager.update(numberSetting);
                }
            }
        }
    }

