    private EdsProductCategoryCustomFields saveCustomFields(EdsProductCategoryCustomFields
                                                                    edsProductCategoryCustomFields, List<CompanyCustomFieldItem> customFieldItems) {
        if (customFieldItems != null && !customFieldItems.isEmpty()) {
            if (edsProductCategoryCustomFields == null) {
                boolean isEmpty = true;
                for (CompanyCustomFieldItem fieldItem : customFieldItems) {
                    if ((fieldItem.getFieldStringValue() != null && !"".equals(fieldItem.getFieldStringValue()))
                            || fieldItem.getFieldDateNonConvertedValue() != null || (fieldItem.getAttachments() != null && fieldItem.getAttachments().length > 0)
                            || (fieldItem.getSelectItems() != null && !fieldItem.getSelectItems().isEmpty())) {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty) {
                    return null;
                }
                edsProductCategoryCustomFields = new EdsProductCategoryCustomFields();
                productCategoryCFManager.create(edsProductCategoryCustomFields);
            }
            CustomFieldsUtils.setDomenObjectCustomFields(edsProductCategoryCustomFields, customFieldItems);
            return edsProductCategoryCustomFields;
        }
        return null;
    }

    public void resaveCompanyAccountingSettings(Integer companyId,
                                                KeyValueStruct industry,
                                                String accounting_tool,
                                                Address billingAddress,
                                                AccountingSetupItem setupItem,
                                                boolean accountingSetup,
                                                String companyStripeAccount,
                                                String companyPaypalAccount) {

        EdsCompany company = companyManager.get(companyId);
        //Save Accounting Setup
        if (industry != null && industry.getValue() != null) {
            EdsCompanyPayrollSettings cps = companyPayrollSettingsManager.getCompanySettingValue(industry.getKey());

            if (cps == null) {
                cps = new EdsCompanyPayrollSettings();
            }
            cps.setKey(industry.getKey());
            cps.setValue(industry.getValue());
            companyPayrollSettingsManager.createOrUpdate(cps);
        }
        //Set Accounting Tool they used so far
        company.setAccountingTool(accounting_tool);

        //Set Billing && Mailing Addresses
        EdsAddress address = company.getBillingAddresses() == null || company.getBillingAddresses().isEmpty()
                ? new EdsAddress()
                : company.getBillingAddresses().get(0);
        address.setEntity(company);
        address.setRelationType(EdsAddress.BILLING_ADDRESS);
        if (billingAddress != null) {
            address.setAddress(billingAddress.getAddress());
            address.setAddressb(billingAddress.getAddressb());
            address.setZipCode(billingAddress.getZipCode());
            address.setCity(billingAddress.getCity());
        }

        address.setPrimary(true);

        if (billingAddress != null && billingAddress.getCountryId() != null) {
            EdsCountry country = countryManager.get(billingAddress.getCountryId());
            address.setCountry(country);
        } else {
            address.setCountry(null);
        }

        if (billingAddress != null && billingAddress.getStateId() != null) {
            EdsRegion state = regionManager.get(billingAddress.getStateId());
            if (state != null && state.getCountry().equals(address.getCountry())) {
                address.setState(state);
            } else {
                address.setState(null);
            }
        } else {
            address.setState(null);
        }

        if (company.getBillingAddresses() == null || company.getBillingAddresses().isEmpty()) {
            addressManager.create(address);
            List<EdsAddress> addresses = new ArrayList<>();
            addresses.add(address);
            company.setBillingAddresses(addresses);
        } else {
            addressManager.update(address);
        }

        //Set Conversion Date (Accounts start date)
        EdsFinancialSettings financialSettingsNew = financialSettingsManager.getFinancialSettings();
        if (financialSettingsNew == null) {
            financialSettingsNew = new EdsFinancialSettings();
        }
        financialSettingsNew.setConversionDate(setupItem.getConversionDate());
        financialSettingsNew.setTaxIdNumber(setupItem.getTaxIdNumber());
        financialSettingsNew.setTaxIdDisplayNumber(setupItem.getTaxDisplayName());
        financialSettingsNew.setTinDisplayName(setupItem.getTaxRegisterName());
        financialSettingsNew.setTinNumber(setupItem.getTaxRegisterNumber());
        financialSettingsNew.setShowVatNumberInInvoices(true);
        financialSettingsNew.setEnableContractOutsite(setupItem.isEnableContractOutsite());
        financialSettingsNew.setVatRegisteredOn(setupItem.getVatRegisteredOn());
        financialSettingsNew.setTaxGenerationDate(setupItem.getTaxGenerationDate());
        financialSettingsNew.setVatRegistered(setupItem.isTaxRegistered());
        financialSettingsManager.createOrUpdate(financialSettingsNew);

        if (financialSettingsNew.isEnableContractOutsite()) {
            genericSettingsManager.saveGenericSettings(null, GenericSettingsEnum.ACCOUNTING_IS_REVERSE_CHARGE, EdsGenericSettings.YES);
        }
        //Set Payment options
        if (StringUtils.isNotBlank(companyStripeAccount) || StringUtils.isNotBlank(companyPaypalAccount)) {
            EdsInvoicingSettings invoiceSettingsNew = invoicingSettingsManager.getInvoiceSettings(company);
            if (invoiceSettingsNew == null) {
                invoiceSettingsNew = new EdsInvoicingSettings();
            }
            if (StringUtils.isNotBlank(companyStripeAccount)) {
                invoiceSettingsNew.setStripeUserId(companyStripeAccount);
            }
            if (StringUtils.isNotBlank(companyPaypalAccount)) {
                invoiceSettingsNew.setPayPalAccount(companyPaypalAccount);
            }
            invoicingSettingsManager.createOrUpdate(invoiceSettingsNew);
        }

        //Save Taxes
        if (setupItem.getTaxes() != null) {
            setupItem.getTaxes().forEach(this::saveTaxRate);
        }
        company.setAccountingSetup(accountingSetup);
        //End Of Save Accounting Setup

        companyManager.update(company);
    }

    private void defaultFinancialSettings() {
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();
        if (financialSettings == null) {
            financialSettings = new EdsFinancialSettings();
        }

        Date endOfYear = ServerUtils.getYearEndDate(ServerUtils.getYear(new Date()));
        Date beginningOfYear = ServerUtils.getYearStartDate(ServerUtils.getYear(new Date()));

        financialSettings.setFinancialYearEnd(endOfYear);
        financialSettings.setConversionDate(beginningOfYear);

        financialSettingsManager.createOrUpdate(financialSettings);

        EdsCompany company = userManager.getUser().getCompany();
        company.setTestCompany(false);
        company.setAccountingSetup(true);
        companyManager.update(company);
    }

