    @Override
    public List<AddAccountItem> getInterCompanyTransactionAccounts(List<NewProduct> products) {
        List<AddAccountItem> accounts = new LinkedList<>();
        HashMap<Integer, Integer> accountIDsMap = new HashMap<>();
        if (products != null && !products.isEmpty()) {
            for (NewProduct pd : products) {
                if (pd.getAccountId() != null && !accountIDsMap.containsKey(pd.getAccountId())) {
                    AddAccountItem accountItem = getAccountForEdit(pd.getAccountId());
                    accounts.add(accountItem);
                    accountIDsMap.put(pd.getAccountId(), pd.getAccountId());
                }
                if (pd.getAssetAccountID() != null && !accountIDsMap.containsKey(pd.getAssetAccountID())) {
                    AddAccountItem accountItem = getAccountForEdit(pd.getAssetAccountID());
                    accounts.add(accountItem);
                    accountIDsMap.put(pd.getAssetAccountID(), pd.getAssetAccountID());
                }
                if (pd.getCogsAccountID() != null && !accountIDsMap.containsKey(pd.getCogsAccountID())) {
                    AddAccountItem accountItem = getAccountForEdit(pd.getCogsAccountID());
                    accounts.add(accountItem);
                    accountIDsMap.put(pd.getCogsAccountID(), pd.getCogsAccountID());
                }
            }
        }
        return accounts;
    }

    @Override
    public HashMap<Integer, Integer> convertInterCompanyAccounts(List<AddAccountItem> accounts) {
        HashMap<Integer, Integer> conversionIDSMap = new HashMap<>();
        if (accounts != null && !accounts.isEmpty()) {
            for (AddAccountItem acc : accounts) {
                Integer accountID = accountingManager.getAccountIDByNameAndAccountType(acc.getName(), acc.getAccountTypeId());
                if (accountID != null) {
                    conversionIDSMap.put(acc.getObjectId(), accountID);
                } else {
                    Integer externalAccountID = acc.getObjectId();
                    acc.setObjectId(null);
                    accountID = createAccount(acc).getId();
                    if (accountID != null && accountID > 0) {
                        conversionIDSMap.put(externalAccountID, accountID);
                    } else {
                        return null;
                    }
                }
            }
        }
        return conversionIDSMap;
    }

    public Transaction getTransaction(Integer transactionID) {

        EdsCusSuppPaymentTransaction edsTransaction = transactionManager.getTransaction(transactionID);
        Transaction transaction = new Transaction();
        transaction.setLayoutHtml(PathFinder.getLayoutHTML(LayoutRPC.TRANSACTION_ITEM_VIEW_FORM));
        if (edsTransaction == null) {
            return transaction;
        }

        transaction.setJournalName(edsTransaction.getName());
        transaction.setTransactionId(edsTransaction.getObjectID());
        transaction.setJournalDate(new DateNonConvertable(edsTransaction.getJournalDate()));
        transaction.setTotalCredit(edsTransaction.getCustomerSupplierPayment().getAmount());
        transaction.setReference(edsTransaction.getReference());

        return transaction;
    }

    public boolean deleteSupplierPayment(Integer transactionID) {
//        transactionManager.deleteTransactionItems(transactionID);
        EdsTransaction transaction = transactionManager.get(transactionID);
        transaction.setDeleted(true);

        if (transaction instanceof EdsCusSuppPaymentTransaction cspTransaction) {
            EdsCustomerSupplierPayment csPayment = cspTransaction.getCustomerSupplierPayment();
            csPayment.setDeleted(true);

            if (csPayment.getManualJournalId() == null) {
                if (transaction.getClient() != null) {
                    transaction.getClient().setPaid(false);
                } else if (transaction.getSupplier() != null) {
                    transaction.getSupplier().setPaid(false);
                }
            }

            //payment came from batch payment then update its batch payment object
            if (csPayment.getBatchPaymentID() != null) {
                BigDecimal total = invoicePaymentManager.getBatchPaymentItems(csPayment.getBatchPaymentID(), csPayment.getObjectID(), false);

                EdsBatchPayment batchPayment = batchPaymentManager.get(csPayment.getBatchPaymentID());

                if (total.compareTo(BigDecimal.ZERO) > 0) {
                    batchPayment.setTotalAmount(total);
                } else {
                    batchPayment.setDeleted(true);
                    String entityCode = Constants.RECEIVABLE.equals(batchPayment.getType())
                            ? AccountingConstants.RECEIVABLE_PREPAYMENT
                            : AccountingConstants.PAYABLE_SUPPLIER_CREDIT;
                    EdsSharedNumber sharedNumber = sharedNumberManager.getByEntityID(batchPayment.getObjectID(), entityCode);
                    if (sharedNumber != null) {
                        sharedNumber.setDeleted(true);
                        sharedNumberManager.update(sharedNumber);
                    }
                }
            }
        }

        return true;
    }


