    @Override
    public void changeTrashBinStatus(Integer objectID, String status) {
        EdsTrashBin trashBin = trashBinManager.get(objectID);
        if (TRASH_BIN_RESTORED.equals(status)) {
            Integer entityID = trashBin.getEntityID();
            String entityType = trashBin.getEntityType();
            if (SALE_QUOTE.equals(entityType) || SALE_ORDER.equals(entityType)) {
                EdsSaleQuote salesQuote = quoteManager.getSaleQuote(entityID);
                salesQuote.setDeleted(false);
                quoteManager.update(salesQuote);
                addSaleQuoteToSolr(salesQuote);
            } else if (SALE_INVOICE.equals(entityType)) {
                EdsSaleInvoice saleInvoice = invoiceManager.getSaleInvoice(entityID);
                saleInvoice.setDeleted(false);
                invoiceManager.update(saleInvoice);
                addSaleInvoiceToSolr(saleInvoice);
            } else if (RECURRING_INVOICE.equals(entityType)) {
                EdsRecurringInvoice recurringInvoice = (EdsRecurringInvoice) invoiceManager.get(entityID);
                recurringInvoice.setDeleted(false);
                invoiceManager.update(recurringInvoice);
            } else if (PURCHASE_ORDER.equals(entityType)) {
                EdsPurchaseOrder purchaseOrder = quoteManager.getPurchaseOrderByID(entityID);
                purchaseOrder.setDeleted(false);
                quoteManager.update(purchaseOrder);
                addPurchaseOrderToSolr(purchaseOrder);
            } else if (PURCHASE_INVOICE.equals(entityType)) {
                EdsPurchaseInvoice purchaseInvoice = invoiceManager.getPurchaseInvoice(entityID);
                purchaseInvoice.setDeleted(false);
                invoiceManager.update(purchaseInvoice);
                addPurchaseInvoiceToSolr(purchaseInvoice);
            }
        }
        trashBin.setStatus(status);
        trashBinManager.update(trashBin);
    }

