    @Override
    public Integer updateIncomeTaxData(DateNonConvertable fromDate, DateNonConvertable toDate) {
        EdsFinancialSettings financialSettings = financialSettingsManager.getFinancialSettings();

        EdsAccount incomeTaxAccount = financialSettings.getIncomeTaxAccount() != null
                ? accountingManager.get(financialSettings.getIncomeTaxAccount())
                : null;
        if (financialSettings.getIncomeTaxPeriod() != null && incomeTaxAccount != null
                && financialSettings.getIncomeTaxRate() != null && financialSettings.getIncomeTaxRate().compareTo(BigDecimal.ZERO) > 0) {
            Calendar startDateCal = new GregorianCalendar();
            Calendar endDateCal = new GregorianCalendar();
            startDateCal.setTime(fromDate.getNonConvertedDate());
            endDateCal.setTime(toDate.getNonConvertedDate());
            ServerUtils.setBeginningOfTheDay(startDateCal);
            ServerUtils.setBeginningOfTheDay(endDateCal);//Don't change to date end

            Calendar financialYearStart = new GregorianCalendar();
            financialYearStart.setTime(financialSettings.getFinancialYearEnd());
            financialYearStart.set(Calendar.DATE, financialYearStart.get(Calendar.DATE) + 1);
            ServerUtils.setBeginningOfTheDay(financialYearStart);


            //To Fix proper year
            if (financialYearStart.after(startDateCal)) {
                while (financialYearStart.after(startDateCal)) {
                    financialYearStart.set(Calendar.YEAR, financialYearStart.get(Calendar.YEAR) - 1);
                }
            } else {
                while (financialYearStart.before(startDateCal) || financialYearStart.equals(startDateCal)) {
                    financialYearStart.set(Calendar.YEAR, financialYearStart.get(Calendar.YEAR) + 1);
                }
                financialYearStart.set(Calendar.YEAR, financialYearStart.get(Calendar.YEAR) - 1);
            }

            ArrayList<Date[]> periodList = new ArrayList<>();

            String periodCode = financialSettings.getIncomeTaxPeriod().getCode();
            if (AccountingConstants.MONTHLY1.equals(periodCode)) {
                //To Fix Proper Month
                while (financialYearStart.before(startDateCal) || financialYearStart.equals(startDateCal)) {
                    financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) + 1);
                }
                financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) - 1);

                //Calculating Periods and add them to period list
                while (financialYearStart.before(endDateCal)) {
                    Date[] interval = new Date[2];
                    interval[0] = financialYearStart.getTime();

                    financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) + 1);

                    Calendar periodEndCal = new GregorianCalendar();
                    periodEndCal.setTime(financialYearStart.getTime());
                    periodEndCal.set(Calendar.DATE, periodEndCal.get(Calendar.DATE) - 1);
                    ServerUtils.setEndOfTheDay(periodEndCal);

                    interval[1] = periodEndCal.getTime();

                    periodList.add(interval);
                }
            } else if (AccountingConstants.QUARTERLY.equals(periodCode)) {
                //To Fix Proper Quarter
                while (financialYearStart.before(startDateCal) || financialYearStart.equals(startDateCal)) {
                    financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) + 3);
                }
                financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) - 3);

                //Calculating Periods and add them to period list
                while (financialYearStart.before(endDateCal)) {
                    Date[] interval = new Date[2];
                    interval[0] = financialYearStart.getTime();

                    financialYearStart.set(Calendar.MONTH, financialYearStart.get(Calendar.MONTH) + 3);

                    Calendar periodEndCal = new GregorianCalendar();
                    periodEndCal.setTime(financialYearStart.getTime());
                    periodEndCal.set(Calendar.DATE, periodEndCal.get(Calendar.DATE) - 1);
                    ServerUtils.setEndOfTheDay(periodEndCal);

                    interval[1] = periodEndCal.getTime();

                    periodList.add(interval);
                }
            } else if (AccountingConstants.ANNUAL.equals(periodCode)) {
                //Proper year is already fixed at the beginning of the method, so we don't need to fix year again
                //Calculating Periods and add them to period list
                while (financialYearStart.before(endDateCal)) {
                    Date[] interval = new Date[2];
                    interval[0] = financialYearStart.getTime();

                    financialYearStart.set(Calendar.YEAR, financialYearStart.get(Calendar.YEAR) + 1);

                    Calendar periodEndCal = new GregorianCalendar();
                    periodEndCal.setTime(financialYearStart.getTime());
                    periodEndCal.set(Calendar.DATE, periodEndCal.get(Calendar.DATE) - 1);
                    ServerUtils.setEndOfTheDay(periodEndCal);
                    interval[1] = periodEndCal.getTime();
                    periodList.add(interval);
                }
            }

            if (!periodList.isEmpty()) {
                Date commonPeriodStart = periodList.get(0)[0];
                Date commonPeriodEnd = periodList.get(periodList.size() - 1)[1];
                transactionManager.deleteIncomeTaxTransactionsByPeriod(commonPeriodStart, commonPeriodEnd);
            }

            EdsUser user = transactionManager.getUser();

            Integer calculationScale = financialSettings.getAccountingCalculationScale();

            for (Date[] period : periodList) {
                BigDecimal profit = transactionManager.getPNLProfitForIncomeTax(period[0], period[1]);
                if (profit.setScale(2, RoundingMode.HALF_UP).compareTo(BigDecimal.ZERO) > 0) {
                    Calendar journalDateCal = new GregorianCalendar();
                    journalDateCal.setTime(period[1]);
                    ServerUtils.setBeginningOfTheDay(journalDateCal);

                    EdsIncomeTaxTransaction incomeTaxTransaction = new EdsIncomeTaxTransaction();
                    incomeTaxTransaction.setName("Income Tax Transaction");
                    incomeTaxTransaction.setIncomeTaxPeriodType(periodCode);
                    incomeTaxTransaction.setJournalDate(journalDateCal.getTime());
                    incomeTaxTransaction.setJournalId(transactionManager.getCompanyLastTransactionOrderID(user.getCompany()) + 1);
                    incomeTaxTransaction.setPostedDate(user.getUserDate());
                    incomeTaxTransaction.setPostedBy(user);

                    BigDecimal incomeTaxAmount = profit.multiply(financialSettings.getIncomeTaxRate()).divide(new BigDecimal(100), calculationScale, RoundingMode.HALF_UP);

                    EdsTransactionItem transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(accountingManager.getAccountByKey(EdsAccount.INCOME_TAX_PAYABLE));
                    transactionItem.setCredit(incomeTaxAmount);
                    incomeTaxTransaction.addTransactionItem(transactionItem);

                    transactionItem = new EdsTransactionItem();
                    transactionItem.setAccount(accountingManager.get(financialSettings.getIncomeTaxAccount()));
                    transactionItem.setDebit(incomeTaxAmount);
                    incomeTaxTransaction.addTransactionItem(transactionItem);

                    transactionManager.create(incomeTaxTransaction);
                }
            }
            return 0;
        }
        return null;
    }

