    private BankTransferNumberData getBankTransferNumberData(Integer transferType) {
        BankTransferNumberData numberData = new BankTransferNumberData();
        EdsNumberingSettings settings = numberingSettingsManager.getNumberingSetting();
        Integer fourDigitNumber = null;

        if (Objects.equals(transferType, RECEIVE_MONEY)) {
            fourDigitNumber = sharedNumberManager.getLastIntNumber(EdsNumberingSettings.DEF_BANK_RECEIPT_PREFIX, BANK_TRANSFER);
        } else if (Objects.equals(transferType, SPEND_MONEY)) {
            fourDigitNumber = sharedNumberManager.getLastIntNumber(EdsNumberingSettings.DEF_BANK_PAYMENT_PREFIX, BANK_TRANSFER);
        } else if (Objects.equals(transferType, CASH_RECEIPT)) {
            fourDigitNumber = sharedNumberManager.getLastIntNumber(EdsNumberingSettings.DEF_CASH_RECEIPT_PREFIX, BANK_TRANSFER);
        } else if (Objects.equals(transferType, CASH_PAYMENT)) {
            fourDigitNumber = sharedNumberManager.getLastIntNumber(EdsNumberingSettings.DEF_CASH_PAYMENT_PREFIX, BANK_TRANSFER);
        }
        String numberFormat = null;
        if (settings != null) {
            numberFormat = (Objects.equals(transferType, SPEND_MONEY)
                    ? settings.getSmNumberingFormat()
                    : Objects.equals(transferType, RECEIVE_MONEY)
                    ? settings.getRmNumberingFormat()
                    : Objects.equals(transferType, CASH_RECEIPT)
                    ? settings.getCrNumberingFormat()
                    : settings.getCpNumberingFormat());
        }
        if (numberFormat == null) {
            numberFormat = (Objects.equals(transferType, SPEND_MONEY)
                    ? EdsNumberingSettings.DEF_BANK_PAYMENT_PREFIX
                    : Objects.equals(transferType, RECEIVE_MONEY)
                    ? EdsNumberingSettings.DEF_BANK_RECEIPT_PREFIX
                    : Objects.equals(transferType, CASH_RECEIPT)
                    ? EdsNumberingSettings.DEF_CASH_RECEIPT_PREFIX
                    : EdsNumberingSettings.DEF_CASH_PAYMENT_PREFIX);
        }

        parseNumber(numberFormat, numberData, fourDigitNumber);

        return numberData;
    }

    private void parseNumber(String numberFormat, BankTransferNumberData numberData, Integer fourDigitNumber) {
        String lastFourNumber = null;
        String[] partNumbers = numberFormat.split("_"); //CP_0001-date or CR_0001
        numberData.setPrefix(partNumbers[0]);
        if (partNumbers.length == 1) {
            lastFourNumber = "0";
        }
        if (partNumbers.length == 2 && !numberFormat.contains("date")) {
            lastFourNumber = partNumbers[1];
        }
        if (numberFormat.contains("date")) {
            numberData.setWithDate(true);
            numberData.setDate(ServerUtils.getBankTransferDateNumber(new Date()));
            lastFourNumber = numberFormat.substring(numberFormat.length() - 9, numberFormat.length() - 5);
        }

        int intLastFourNumber = 1;
        try {
            intLastFourNumber = Integer.parseInt(lastFourNumber);
        } catch (NumberFormatException ignored) {
        }
        DecimalFormat format = new DecimalFormat("0000");
        numberData.setFourDigitNumber((fourDigitNumber != null && fourDigitNumber.compareTo(intLastFourNumber) >= 0)
                ? format.format(fourDigitNumber + 1)
                : lastFourNumber);
    }

    private void parseBankTransferNumber(String numberFormat, BankTransferNumberData numberData, Integer
            fourDigitNumber) {
        String[] mainPartNumbers = numberFormat.split("_");  // e.g CP_0001-05/2015 or CR_0001-05/2015
        String[] datePartNumbers = mainPartNumbers[1].split("-");  // e.g 0001-05/2015 or 0001-05/2015

        numberData.setPrefix(mainPartNumbers[0]);
        numberData.setWithDate(datePartNumbers.length == 2);

        String lastFourNumber = datePartNumbers[0];

        DecimalFormat format = new DecimalFormat("0000");
        numberData.setFourDigitNumber(fourDigitNumber != null ? format.format(fourDigitNumber + 1) : lastFourNumber);
        if (numberData.isWithDate()) {
            numberData.setDate(ServerUtils.getBankTransferDateNumber(new Date()));
        }
    }

