    @Transactional
    public Boolean saveCsvTemplateData(Integer csvTemplateID, ArrayList<CsvTemplateItem> csvTemplateData) {
        EdsCsvTemplate csvTemplate = csvTemplateManager.get(csvTemplateID);
        if (csvTemplateData != null && !csvTemplateData.isEmpty()) {
            csvTemplateItemManager.deleteByTemplateId(csvTemplate.getObjectID());
            for (CsvTemplateItem item : csvTemplateData) {
                EdsCsvTemplateItem templateItem = new EdsCsvTemplateItem();
                templateItem.setCsvTemplate(csvTemplate);
                templateItem.setSystemField(item.getSystemField());
                templateItem.setValue(item.getValue());
                templateItem.setSystemValue(item.isSystemValue());
                csvTemplateItemManager.create(templateItem);
            }
            return true;
        }
        return false;
    }

    /**
     * This code will run only 1 time for clean the dirty data
     *
     * @param items
     * @param type
     */
    public void fixDoubleTransaction(List<Object> items, int type) {
        if (type == 1) {
            if (items != null && !items.isEmpty()) {
                for (Object item : items) {
                    Object[] it = (Object[]) item;

                    Integer invoiceID = (Integer) it[0];
                    Boolean isCreditNote = (Boolean) it[1];

                    EdsInvoice invoice = invoiceManager.get(invoiceID);

                    if (!isCreditNote) {
                        EdsInvoiceTransaction transaction = transactionManager.getTransactionByInvoice(invoice);
                        if (transaction != null) {
                            transactionManager.deleteTransactionItems(transaction.getObjectID());
                        }
                        createTransactionsForInvoice(invoice, invoice.getCreator());
                    } else {
                        createTransactionsForCreditNote(invoice, null);
                    }

                    invoiceManager.flushAndClear();

                }
            }
        }

        if (type == 2) {
            if (items != null && !items.isEmpty()) {
                for (Object item : items) {
                    Integer paymentID = (Integer) item;

                    EdsInvoicePayment payment = invoicePaymentManager.get(paymentID);
                    payment.setExchangeRate(payment.getInvoice().getExchangeRate());
                    payment.setBaseAmount(payment.getAmount().divide(payment.getExchangeRate(), 2, RoundingMode.HALF_UP));
                    invoicePaymentManager.update(payment);


                    createTransactionForPayment(payment);

                    invoicePaymentManager.flushAndClear();
                }
            }
        }

        if (type == 3) {
            if (items != null && !items.isEmpty()) {
                for (Object item : items) {
                    Integer cusSuppPayId = (Integer) item;

                    createClientSupplierPaymentTransaction(cusSuppPayId);
                }
            }
        }

        if (type == 4) {
            if (items != null && !items.isEmpty()) {
                for (Object item : items) {
                    Integer paymentID = (Integer) item;

                    EdsInvoicePayment payment = invoicePaymentManager.get(paymentID);
                    createTransactionForPayment(payment);

                    invoicePaymentManager.flushAndClear();
                }
            }
        }
    }

