    @Override
    public void runSpendReceivePostDatedTransactions(Integer companyID) {
        ServerSecurityContext.getInstance().setCompanyId(companyID);
        EdsCompany company = companyManager.get(companyID);

        try {
            Date companyTime = getCompanyCurrentDate(TimeZone.getTimeZone(company.getCountryZone().getZone().getZoneID()));
            List<EdsBankTransfer> postdatedtransactionList = spendReceiveMoneyManager.getPostDatedTransaction(companyTime);

            for (EdsBankTransfer postDatedTransaction : postdatedtransactionList) {
                Integer userId = postDatedTransaction.getCreator() != null
                        ? postDatedTransaction.getCreator().getObjectID()
                        : userManager.getAdmin(companyID).getObjectID();
                SecurityContext.getInstance().setStaticUserID(userId);
                postDatedTransaction.setPostDatedTransaction(false);
                Integer accountId = postDatedTransaction.getBankAccount() != null
                        ? postDatedTransaction.getBankAccount().getObjectID()
                        : postDatedTransaction.getCashAccount().getObjectID();
                postDatedTransaction.setBankTransferTransaction(saveBankTransferTransaction(getBankTransferData(postDatedTransaction.getObjectID(), accountId, postDatedTransaction.getTransferType()), postDatedTransaction));
            }
        } catch (Exception ex) {
            log.error("running Running SpendReceive Post Dated transaction failed for company " + companyID + "!!!", ex);
        }
    }

    @Override
    public ListResult<NewManualTransaction> getBankCashTransferList(ListingFilterParameter fp) {
        KpiLog kpiLog = SecurityContext.getInstance().getKpiLog();
        kpiLog.setEntityName(EdsBankTransfer.class.getSimpleName());
        kpiLog.setActionType(KpiLog.ActionType.LIST);
        ServerUtils.kpiLog(log, kpiLog, "Get Bank/Cash Transfer List");

        if (fp == null) {
            fp = new ListingFilterParameter();
        }
        ListPanelToolRpc panelTools = fp.getListPanelTool();
        fp.setCustomFieldsShown(true);
        if (panelTools != null && panelTools.isCustomFieldsShown()) {
            fp.setCustomFieldsShown(panelTools.isCustomFieldsShown());
            panelTools.setListViewCustomFields(commonService.getCompanyCustomFieldsForListView(ViewName.BankTransferList));
            fp.setColumnsOfListing(panelTools.getColumnCodeName());
        }

        if (fp.getStartDateNC() != null) {
            fp.setStartDate(ServerUtils.parseFilterParameterDate(fp.getStartDateNC()));
        }
        if (fp.getEndDateNC() != null) {
            fp.setEndDate(ServerUtils.parseFilterParameterDate(fp.getEndDateNC()));
        }

        ArrayList<NewManualTransaction> items = new ArrayList<>();
        List<NewManualTransaction> list = spendReceiveMoneyManager.list(fp);

        if (list != null && !list.isEmpty()) {
            if (fp.isFromExcelPDF()) {
                items = (ArrayList<NewManualTransaction>) list;
            } else {
                for (NewManualTransaction item : list) {
                    if (Constants.BANK_TRANSFER_TRANSACTION.equals(item.getTransactionType())) {
                        item.setUsed(spendReceiveMoneyManager.isUsedForPayment(item.getObjectId()));
                    }
                    EdsBankTransfer bankTransfer = spendReceiveMoneyManager.get(item.getObjectId());
                    if (bankTransfer != null && bankTransfer.getCustomFields() != null && fp.isCustomFieldsShown()) {
                        item.setCustomFields(CustomFieldsUtils.getRPCCustomFields(bankTransfer.getCustomFields(), fp.getColumnsOfListing()));
                    }
                    items.add(item);
                }
            }
        }

        return new ListResult<>(items, spendReceiveMoneyManager.listCount(fp));
    }

