    private Date getCompanyCurrentDate(TimeZone companyTimeZone) throws ParseException {
        Date currentServerTime = new Date();
        SimpleDateFormat companyTimeZoneDateFormat = new SimpleDateFormat();
        companyTimeZoneDateFormat.setTimeZone(companyTimeZone);
        String s = companyTimeZoneDateFormat.format(currentServerTime);
        SimpleDateFormat dateFormatForParse = new SimpleDateFormat();
        return dateFormatForParse.parse(s);
    }

    private QueryResponse getParentCompanyProductListFromSolr(Integer parentCompanyId) {
        StringBuilder solrQuery = new StringBuilder();
        solrQuery.append(SolrEventRepresenter.FIELD_COMPANY_ID).append(":").append(parentCompanyId);
        solrQuery.append(" AND " + SolrProductServiceRepresenter.FIELD_PRODUCT_ACTIVE).append(":true");

        SolrQuery query = new SolrQuery();
        query.setQuery(solrQuery.toString());
        query.setStart(0);
        query.setParam(CommonParams.ROWS, "1000");

        SolrClient server = WfmJpaTemplate.getSolrServerForCore(SOLR_PRODUCTS_SERVICES_CORE);
        QueryResponse resp = null;
        try {
            resp = server.query(query, SolrRequest.METHOD.POST);
        } catch (SolrServerException | IOException e) {
            e.printStackTrace();
        }

        return resp;
    }


