    public LinkedHashMap<String, BigDecimal> getTopExpensesMap(ListingFilterParameter fp) {
        HashMap<String, BigDecimal> expensesMap = new HashMap<>();
        List<Object[]> expenses = transactionManager.getBalanceDataByDateAndAccountCategory(fp.getAccountType(), fp.getStartDate(), fp.getEndDate(), null, null);

        for (Object[] objects : expenses) {

            BigDecimal debit = objects[0] != null ? (BigDecimal) objects[0] : BigDecimal.ZERO;
            BigDecimal credit = objects[1] != null ? (BigDecimal) objects[1] : BigDecimal.ZERO;

            if (debit.subtract(credit).abs().intValue() != 0) {
                expensesMap.put((String) objects[3], debit.subtract(credit));
            }
        }

        LinkedHashMap<String, BigDecimal> map = expensesMap.entrySet().stream()
                .sorted(Map.Entry.comparingByValue(Comparator.reverseOrder()))
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                        (oldValue, newValue) -> oldValue, LinkedHashMap::new));
        return map;
    }

