                epm = paymentMethodManager.get(pmi.getObjectID());
                epm.setName(pmi.getName());
                epm.setDescription(pmi.getDescription());
                epm.setCode(pmi.getCode());
                epm.setWeigth(pmi.getWeigth());
                epm.setSortOrder(pmi.getSortOrder());
