    @Override
    public void eventCorrectionAssemblyBuildTransaction(Integer assemblyTransactionId) {
        EdsTransaction transaction = transactionManager.get(assemblyTransactionId);

        if (transaction instanceof EdsInventoryTransaction inventoryTransaction && Constants.TT_BUILD_ASSEMBLY.equals(inventoryTransaction.getTransactionType())) {
            EdsItem item = inventoryTransaction.getInventory();
            Optional<EdsTransactionItem> optAssemblyTI = inventoryTransaction.getTransactionItems().stream().filter(ti -> ti.getAccount().getObjectID().equals(item.getAssetAccount().getObjectID()) && ti.getDebit() != null).findFirst();
            BigDecimal COGS = inventoryTransaction.getTransactionItems().stream().filter(ti -> ti.getCredit() != null).reduce(BigDecimal.ZERO, (substotal, ti) -> substotal.add(ti.getCredit()), BigDecimal::add);

            optAssemblyTI.ifPresent(ti -> ti.setDebit(COGS));

            List<EdsItemStock> assemblyStock = itemStockManager.getItemStockByTransaction(inventoryTransaction.getObjectID(), inventoryTransaction.getInventory().getObjectID());
            Optional<EdsItemStock> optStock = assemblyStock.stream().filter(stock -> TC_IN.equals(stock.getTranCode())).findAny();
            optStock.ifPresent(s -> {
                s.setTranValue(COGS);
                itemStockManager.update(s);
            });
        }
    }

