    @Override
    public Integer saveBudgetManager(BudgetManagerItem budgetsheetItem) {
        if (budgetsheetItem.getName() == null || budgetsheetItem.getType() == null) {
            return null;
        }

        String NAME = budgetsheetItem.getName().replace(" ", "_").toUpperCase();
        String BUDGET_NAME = NAME.toUpperCase() + "_BUDGET";

        EdsBudgetManager edsBudgetManager = this.budgetManager.get(budgetsheetItem.getObjectId());

        Integer result = budgetManager.isBudgetManagerAlreadyExists(edsBudgetManager != null ? edsBudgetManager.getCode() : BUDGET_NAME, budgetsheetItem.getName(), budgetsheetItem.getObjectId());

        if (result != 0) {
            return result;
        }
        if (edsBudgetManager == null) {
            edsBudgetManager = new EdsBudgetManager();
            edsBudgetManager.setCode(BUDGET_NAME);
        }
        edsBudgetManager.setName(budgetsheetItem.getName());
        edsBudgetManager.setType(budgetsheetItem.getType());
        edsBudgetManager.setScale(budgetsheetItem.getScale());

        if (budgetsheetItem.isDefaultBudget()) {
            budgetManager.updateBudgetsNotDefault();
        }
        edsBudgetManager.setDefaultBudget(budgetsheetItem.isDefaultBudget());

        edsBudgetManager.setGroupBy(budgetsheetItem.getGroupBy());
        if (budgetsheetItem.getColumns() != null) {
            Gson gson = new Gson();
            edsBudgetManager.setBudgetColumns(gson.toJson(budgetsheetItem.getColumns().toArray(new BudgetColumn[]{})));
        }
        budgetManager.createOrUpdate(edsBudgetManager);

        return edsBudgetManager.getObjectID();
    }

    @Override
    public void createBudgetManagerItem(AccountBudget budget) {
        EdsBudgetManager edsBudgetManager = budgetManager.get(budget.getBudgetManagerId());
        if (edsBudgetManager == null) {
            return;
        }
        EdsBudgetManagerItem budgetManagerItem;
        if (budget.getId() == null) {
            Calendar from = new GregorianCalendar();
            from.setTime(budget.getDate());
            from.set(Calendar.DAY_OF_MONTH, 1);
            ServerUtils.setBeginningOfTheDay(from);

            Calendar to = new GregorianCalendar();
            to.setTime(budget.getDate());
            to.set(Calendar.DAY_OF_MONTH, to.getActualMaximum(Calendar.DAY_OF_MONTH));
            ServerUtils.setEndOfTheDay(to);

            budgetManagerItem = budgetItemManager.findBudgetItem(budget.getEntityID(), budget.getGroupId(), budget.getColumnCode(), from.getTime(), to.getTime());

            if (budgetManagerItem == null) {
                budgetManagerItem = new EdsBudgetManagerItem();
            }
        } else {
            budgetManagerItem = budgetItemManager.get(budget.getId());
        }

        budgetManagerItem.setEntityId(budget.getEntityID());
        budgetManagerItem.setBudgetManager(edsBudgetManager);
        budgetManagerItem.setDepartment(budget.getDepartmentID() != null
                ? departmentManager.get(budget.getDepartmentID())
                : null);
        budgetManagerItem.setBudget(budget.getBudget());
        budgetManagerItem.setMonth(budget.getMonth());
        budgetManagerItem.setYear(budget.getYear());
        budgetManagerItem.setDate(budget.getDate());
        budgetManagerItem.setColumnCode(budget.getColumnCode());
        budgetManagerItem.setGroupId(budget.getGroupId());
        budgetItemManager.createOrUpdate(budgetManagerItem);
    }

    @Override
    public BudgetManagerItem getBudgetManagerData(Integer objectID) {

        BudgetManagerItem budgetManagerItem = new BudgetManagerItem();

        List<SelectItem> items = new ArrayList<>();
        SelectItem defaultBudget = null;
        List<EdsBudgetManager> budgetManagers = budgetManager.getBudgetManagerList();
        if (budgetManagers != null) {
            for (EdsBudgetManager budgetManager : budgetManagers) {
                SelectItem selectItem = budgetManager.toSelectItem();
                if (selectItem.isDefaultSelected()) {
                    defaultBudget = selectItem;
                }
                if (budgetManager.getType().contains("_FORM")) {
                    EdsCustomForm customForm = customFormManager.findByFormID(budgetManager.getType());
                    if (customForm != null) {
                        selectItem.setEntityId(customForm.getObjectID());
                    }
                }
                items.add(selectItem);
            }
        }
        budgetManagerItem.setBudgetManagers(items.toArray(new SelectItem[]{}));

        if (objectID != null) {
            EdsBudgetManager edsBudgetManager = budgetManager.get(objectID);
            if (edsBudgetManager != null) {
                budgetManagerItem.setObjectId(edsBudgetManager.getObjectID());
                budgetManagerItem.setName(edsBudgetManager.getName());
                budgetManagerItem.setType(edsBudgetManager.getType());
                budgetManagerItem.setDefaultBudget(edsBudgetManager.isDefaultBudget());
                budgetManagerItem.setScale(edsBudgetManager.getScale());
                budgetManagerItem.setGroupBy(edsBudgetManager.getGroupBy());

                if (edsBudgetManager.getBudgetColumns() != null) {

                    Gson gson = new Gson();
                    BudgetColumn[] columns = gson.fromJson(edsBudgetManager.getBudgetColumns(), BudgetColumn[].class);
                    if (columns != null) {
                        budgetManagerItem.setColumns(new LinkedList<>(Arrays.asList(columns)));
                    }
                }
                if (edsBudgetManager.getType() != null) {
                    budgetManagerItem.setGroupsByType((ArrayList<SelectItem>) getCustomfieldsByType(edsBudgetManager.getType()));
                }
            }
        } else {
            if (defaultBudget == null && items != null && !items.isEmpty()) {
                defaultBudget = items.get(0);
            }

            if (defaultBudget != null) {
                EdsBudgetManager defaultBudgetManger = budgetManager.get(defaultBudget.getId());

                if (defaultBudgetManger != null && defaultBudgetManger.getBudgetColumns() != null) {

                    Gson gson = new Gson();
                    BudgetColumn[] columns = gson.fromJson(defaultBudgetManger.getBudgetColumns(), BudgetColumn[].class);
                    if (columns != null) {
                        budgetManagerItem.setColumns(new LinkedList<>(Arrays.asList(columns)));
                    }
                }
                budgetManagerItem.setDefaultBudgetManager(defaultBudget);
            }
        }

        return budgetManagerItem;
    }

